CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_alerts" (
    "alert_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "beach_id" "uuid" NOT NULL,
    "local_date" "date" NOT NULL,
    "decision_id" "uuid",
    "alert_code" "text" NOT NULL,
    "separation_ft" numeric(8,4) NOT NULL,
    "primary_issue_id" "uuid",
    "conflicting_issue_id" "uuid",
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "build_key" "text" NOT NULL,
    "acknowledged" boolean DEFAULT false NOT NULL,
    "acknowledged_by" "text",
    "acknowledged_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_alerts_acknowledgement_check" CHECK (((("acknowledged" = false) AND ("acknowledged_by" IS NULL) AND ("acknowledged_at" IS NULL)) OR (("acknowledged" = true) AND ("acknowledged_by" IS NOT NULL) AND ("acknowledged_at" IS NOT NULL)))),
    CONSTRAINT "trusted_forecast_alerts_code_check" CHECK (("alert_code" = 'range_separation_exceeded'::"text")),
    CONSTRAINT "trusted_forecast_alerts_evidence_object_check" CHECK (("jsonb_typeof"("evidence") = 'object'::"text")),
    CONSTRAINT "trusted_forecast_alerts_separation_check" CHECK (("separation_ft" > 1.0))
);


ALTER TABLE "public"."trusted_forecast_alerts" OWNER TO "postgres";


COMMENT ON TABLE "public"."trusted_forecast_alerts" IS 'Immutable range-separation evidence. Only acknowledge_trusted_forecast_alert may change acknowledged, acknowledged_by, acknowledged_at (D-22).';



CREATE OR REPLACE FUNCTION "public"."acknowledge_trusted_forecast_alert"("p_acknowledgement" "jsonb") RETURNS SETOF "public"."trusted_forecast_alerts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_keys CONSTANT text[] := ARRAY['alertId', 'acknowledgedBy'];
  v_alert_id uuid;
  v_actor text;
  v_alert public.trusted_forecast_alerts%ROWTYPE;
BEGIN
  IF p_acknowledgement IS NULL
     OR jsonb_typeof(p_acknowledgement) <> 'object' THEN
    RAISE EXCEPTION 'alert acknowledgement must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_acknowledgement) AS supplied(key)
    WHERE supplied.key <> ALL (c_keys)
  ) OR EXISTS (
    SELECT 1
    FROM unnest(c_keys) AS required(key)
    WHERE NOT (p_acknowledgement ? required.key)
  ) THEN
    RAISE EXCEPTION 'alert acknowledgement has an invalid field set'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_acknowledgement -> 'acknowledgedBy') <> 'string'
     OR length(p_acknowledgement ->> 'acknowledgedBy') = 0 THEN
    RAISE EXCEPTION 'alert acknowledgement requires a non-empty actor'
      USING ERRCODE = '22023';
  END IF;

  v_alert_id := (p_acknowledgement ->> 'alertId')::uuid;
  v_actor := p_acknowledgement ->> 'acknowledgedBy';

  PERFORM set_config(
    'app.trusted_forecast_alert_acknowledgement',
    'on',
    true
  );

  UPDATE public.trusted_forecast_alerts
  SET acknowledged = true,
      acknowledged_by = v_actor,
      acknowledged_at = transaction_timestamp()
  WHERE alert_id = v_alert_id
    AND acknowledged = false
  RETURNING * INTO v_alert;

  PERFORM set_config(
    'app.trusted_forecast_alert_acknowledgement',
    'off',
    true
  );

  IF v_alert.alert_id IS NULL THEN
    SELECT *
    INTO v_alert
    FROM public.trusted_forecast_alerts
    WHERE alert_id = v_alert_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'trusted forecast alert % does not exist', v_alert_id
        USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN NEXT v_alert;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."acknowledge_trusted_forecast_alert"("p_acknowledgement" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acknowledge_trusted_forecast_alert"("p_acknowledgement" "jsonb") IS 'Service-role-only acknowledgement that may change only acknowledgement status, actor, and timestamp (D-22).';



