CREATE OR REPLACE FUNCTION "public"."admin_list_community_spot_photos_v1"("p_status" "text" DEFAULT 'all'::"text", "p_target_type" "text" DEFAULT NULL::"text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH page AS (
    SELECT
      p.*,
      NULLIF(btrim(pr.display_name), '') AS display_name,
      count(DISTINCT v.voter_id) FILTER (WHERE v.vote = 'up')::integer AS upvotes,
      count(DISTINCT v.voter_id) FILTER (WHERE v.vote = 'down')::integer AS downvotes,
      count(DISTINCT r.reporter_id) FILTER (
        WHERE r.reason IN ('explicit', 'privacy', 'safety')
      )::integer AS severe_reports,
      count(DISTINCT r.reporter_id) FILTER (
        WHERE r.reason IN ('wrong_spot', 'stale')
      )::integer AS quality_reports,
      count(DISTINCT r.reporter_id)::integer AS total_reports,
      EXISTS (
        SELECT 1 FROM public.community_photo_feature_pins pin
        WHERE pin.photo_id = p.id AND pin.revoked_at IS NULL
      ) AS is_pinned,
      (
        SELECT jsonb_build_object(
          'id', h.id, 'reason', h.reason, 'placedAt', h.placed_at
        )
        FROM public.community_photo_investigation_holds h
        WHERE h.photo_id = p.id AND h.released_at IS NULL
      ) AS hold,
      (
        SELECT jsonb_build_object(
          'reasonCode', cr.reason_code, 'restrictedUntil', cr.restricted_until
        )
        FROM public.community_photo_contributor_restrictions cr
        WHERE cr.contributor_id = p.uploader_id AND cr.lifted_at IS NULL
          AND (cr.restricted_until IS NULL OR cr.restricted_until > now())
      ) AS contributor_restriction
    FROM public.community_spot_photos p
    LEFT JOIN public.profiles pr ON pr.id = p.uploader_id
    LEFT JOIN public.community_photo_votes v ON v.photo_id = p.id
    LEFT JOIN public.community_photo_reports r ON r.photo_id = p.id
    WHERE (p_status = 'all'
      OR (p_status = 'visible' AND p.moderation_status = 'visible' AND p.lifecycle_status = 'active')
      OR (p_status = 'hidden' AND p.moderation_status = 'hidden' AND p.lifecycle_status = 'active')
      OR (p_status = 'removed' AND p.lifecycle_status = 'removed'))
      AND (p_target_type IS NULL OR p.target_type = p_target_type)
      AND (p_target_id IS NULL OR COALESCE(p.beach_id, p.custom_spot_id) = p_target_id)
      AND (p_before IS NULL OR p.created_at < p_before)
    GROUP BY p.id, pr.display_name
    ORDER BY p.created_at DESC, p.id ASC
    LIMIT LEAST(GREATEST(p_limit, 1), 100)
  )
  SELECT jsonb_build_object(
    'photos',
    COALESCE(jsonb_agg(jsonb_build_object(
      'id', id,
      'targetType', target_type,
      'targetId', COALESCE(beach_id, custom_spot_id),
      'imageUrl', '/api/community-photos/' || id || '/image',
      'visibility', visibility,
      'processingStatus', processing_status,
      'moderationStatus', moderation_status,
      'lifecycleStatus', lifecycle_status,
          'attribution', jsonb_build_object(
            'kind', CASE
              WHEN uploader_id IS NOT NULL AND display_name IS NOT NULL
                THEN 'profile'
              ELSE 'community'
            END,
            'displayName', COALESCE(display_name, 'Quiver community'),
            'profileId', CASE
              WHEN display_name IS NOT NULL THEN uploader_id
              ELSE NULL
            END
          ),
      'upvotes', upvotes,
      'downvotes', downvotes,
      'reportCounts', jsonb_build_object(
        'severe', severe_reports, 'quality', quality_reports, 'total', total_reports
      ),
      'isPinned', is_pinned,
      'hold', hold,
      'contributorRestriction', contributor_restriction,
      'createdAt', created_at,
      'removedAt', removed_at,
      'recoverableUntil', recoverable_until
    ) ORDER BY created_at DESC, id ASC), '[]'::jsonb),
    'nextCursor',
    CASE WHEN count(*) = LEAST(GREATEST(p_limit, 1), 100)
      THEN min(created_at)::text ELSE NULL END
  )
  FROM page
$$;


ALTER FUNCTION "public"."admin_list_community_spot_photos_v1"("p_status" "text", "p_target_type" "text", "p_target_id" "uuid", "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."experiment_assignments" (
    "experiment_key" "text" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "arm" smallint NOT NULL,
    "index_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "assignment_version" "text" DEFAULT 'v1'::"text" NOT NULL,
    "build" "text",
    "source" "text",
    "linked_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "experiment_assignments_arm_check" CHECK (("arm" = ANY (ARRAY[0, 1]))),
    CONSTRAINT "experiment_assignments_key_check" CHECK (("experiment_key" = ANY (ARRAY['t3-quicklog-v1'::"text", 't10-freegrowth-v1'::"text", 't2a-swellwatch-v1'::"text"]))),
    CONSTRAINT "experiment_assignments_linkage_pair_check" CHECK ((("build" IS NULL) = ("source" IS NULL))),
    CONSTRAINT "experiment_assignments_source_check" CHECK (("source" = ANY (ARRAY['native_app'::"text", 'web_oauth'::"text"])))
);


ALTER TABLE "public"."experiment_assignments" OWNER TO "postgres";


COMMENT ON TABLE "public"."experiment_assignments" IS 'W-ASSIGN ledger of record (plan 063 §5). Service-role only. arm 0=control 1=treatment. Rows are immutable except a single write-once (build, source) linkage. user_id intentionally has no auth.users foreign key so account deletion retains a detached pseudonymous ITT row.';



COMMENT ON COLUMN "public"."experiment_assignments"."index_at" IS 'Analysis anchor: auth.users.created_at for signup-hook rows (t3/t10); allocation time for batch-allocated rows (t2a). Frozen — 7-day-return windows are computed from this.';



COMMENT ON COLUMN "public"."experiment_assignments"."build" IS 'Write-once eligibility linkage; NULL = eligibility_unknown (reported as its own bucket, never defaulted).';



COMMENT ON COLUMN "public"."experiment_assignments"."source" IS 'Write-once eligibility linkage; NULL = eligibility_unknown (reported as its own bucket, never defaulted).';



CREATE OR REPLACE FUNCTION "public"."allocate_experiment_batch"("p_experiment_key" "text", "p_user_ids" "uuid"[], "p_index_at" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."experiment_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO public.experiment_assignments
    (experiment_key, user_id, arm, index_at, assignment_version)
  SELECT p_experiment_key, u, public.experiment_arm(u, p_experiment_key), p_index_at, 'v1'
  FROM unnest(p_user_ids) AS u
  ON CONFLICT (experiment_key, user_id) DO NOTHING;

  RETURN QUERY
  SELECT * FROM public.experiment_assignments
  WHERE experiment_key = p_experiment_key AND user_id = ANY(p_user_ids);
END;
$$;


ALTER FUNCTION "public"."allocate_experiment_batch"("p_experiment_key" "text", "p_user_ids" "uuid"[], "p_index_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anonymize_android_waitlist_for_account"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  DELETE FROM public.android_waitlist_source_links
  WHERE source_kind = 'profile_intent'
    AND source_id = NEW.id;

  UPDATE public.android_waitlist_entries
  SET user_id = NULL, normalized_email_sha256 = NULL, updated_at = now()
  WHERE user_id = NEW.id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."anonymize_android_waitlist_for_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anonymize_community_photos_before_account_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE public.community_photo_consents
  SET contributor_id = NULL
  WHERE contributor_id = OLD.id;
  UPDATE public.community_spot_photos
  SET uploader_id = NULL, updated_at = now()
  WHERE uploader_id = OLD.id;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."anonymize_community_photos_before_account_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regional_recommendation_hold_refs_are_safe"("p_refs" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_item jsonb;
  v_ref text;
  v_seen text[] := ARRAY[]::text[];
BEGIN
  IF p_refs IS NULL THEN
    RETURN false;
  END IF;

  IF jsonb_typeof(p_refs) <> 'array' THEN
    RETURN false;
  END IF;

  IF jsonb_array_length(p_refs) > 16 THEN
    RETURN false;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_refs) AS refs(value)
  LOOP
    IF jsonb_typeof(v_item) <> 'string' THEN
      RETURN false;
    END IF;

    v_ref := v_item #>> '{}';
    IF char_length(v_ref) NOT BETWEEN 1 AND 128
       OR v_ref !~ '^(official:rip_current_risks:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|qa:artifact:[A-Za-z0-9_-]{1,64})$'
       OR v_ref = ANY(v_seen) THEN
      RETURN false;
    END IF;

    v_seen := array_append(v_seen, v_ref);
  END LOOP;

  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."regional_recommendation_hold_refs_are_safe"("p_refs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regional_recommendation_hold_region_keys_are_safe"("p_region_keys" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_key text;
  v_seen text[] := ARRAY[]::text[];
BEGIN
  IF p_region_keys IS NULL OR cardinality(p_region_keys) > 64 THEN
    RETURN false;
  END IF;

  FOREACH v_key IN ARRAY p_region_keys
  LOOP
    IF v_key IS NULL
       OR v_key !~ '^[a-z0-9][a-z0-9_-]{0,63}$'
       OR v_key = ANY(v_seen) THEN
      RETURN false;
    END IF;

    v_seen := array_append(v_seen, v_key);
  END LOOP;

  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."regional_recommendation_hold_region_keys_are_safe"("p_region_keys" "text"[]) OWNER TO "postgres";


