    CONSTRAINT "regional_recommendation_hold_protected_alternative_beach__check" CHECK (("cardinality"("protected_alternative_beach_ids") <= 2000)),
    CONSTRAINT "regional_recommendation_holds_action_check" CHECK (("action" = ANY (ARRAY['suppress_positive'::"text", 'protected_alternatives_only'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_affected_cohorts_check" CHECK ((("cardinality"("affected_cohorts") > 0) AND ("affected_cohorts" <@ ARRAY['beginner'::"text", 'intermediate'::"text", 'advanced'::"text", 'expert'::"text", 'unknown'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_authorizing_actor_check" CHECK (("authorizing_actor" = ANY (ARRAY['admin_api'::"text", 'official_automation'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_automatic_policy_version_check" CHECK ((("automatic_policy_version" IS NULL) OR ("automatic_policy_version" ~ '^[a-z0-9._-]{1,64}$'::"text"))),
    CONSTRAINT "regional_recommendation_holds_check" CHECK (("valid_until" > "valid_from")),
    CONSTRAINT "regional_recommendation_holds_check1" CHECK ((("expires_at" > "effective_at") AND ("expires_at" <= ("effective_at" + '7 days'::interval)))),
    CONSTRAINT "regional_recommendation_holds_check2" CHECK (((("transition" = 'activation'::"text") AND ("version" = 1) AND ("supersedes_record_id" IS NULL)) OR (("transition" <> 'activation'::"text") AND ("version" > 1) AND ("supersedes_record_id" IS NOT NULL)))),
    CONSTRAINT "regional_recommendation_holds_check3" CHECK (((("transition" = 'cancellation'::"text") AND ("status" = 'cancelled'::"text")) OR (("transition" <> 'cancellation'::"text") AND ("status" = 'active'::"text")))),
    CONSTRAINT "regional_recommendation_holds_check4" CHECK (((("trigger_type" = 'manual_operator'::"text") AND ("authorizing_operator_ref" IS NOT NULL) AND ("automatic_policy_version" IS NULL)) OR (("trigger_type" = 'automatic_official'::"text") AND ("authorizing_operator_ref" IS NULL) AND ("automatic_policy_version" IS NOT NULL) AND ("jsonb_array_length"("supporting_evidence_refs") > 0)))),
    CONSTRAINT "regional_recommendation_holds_check5" CHECK ((("action" <> 'protected_alternatives_only'::"text") OR ("cardinality"("protected_alternative_beach_ids") > 0))),
    CONSTRAINT "regional_recommendation_holds_check6" CHECK ((("trigger_type" <> 'automatic_official'::"text") OR (("transition" = 'activation'::"text") AND ("action" = 'suppress_positive'::"text") AND ("affected_cohorts" = ARRAY['beginner'::"text", 'intermediate'::"text", 'unknown'::"text"]) AND ("cardinality"("scope_beach_ids") = 1) AND ("cardinality"("region_keys") = 0) AND ("cardinality"("scope_exposure_classes") = 0) AND ("cardinality"("protected_alternative_beach_ids") = 0) AND ("automatic_policy_version" = 'official-rip-high.v1'::"text") AND ("authorizing_actor" = 'official_automation'::"text") AND ("reason_code" = 'official_high_rip_current'::"text") AND ("jsonb_array_length"("supporting_evidence_refs") = 1)))),
    CONSTRAINT "regional_recommendation_holds_event_reference_check" CHECK ((("event_reference" IS NULL) OR ("event_reference" ~ '^(event|official|qa):[a-z0-9_]+:[A-Za-z0-9_-]{1,64}$'::"text"))),
    CONSTRAINT "regional_recommendation_holds_idempotency_key_check" CHECK (("idempotency_key" ~ '^[A-Za-z0-9:_-]{1,160}$'::"text")),
    CONSTRAINT "regional_recommendation_holds_payload_hash_check" CHECK (("payload_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "regional_recommendation_holds_reason_code_check" CHECK (("reason_code" = ANY (ARRAY['major_swell_manual_safety'::"text", 'official_high_rip_current'::"text", 'scope_correction'::"text", 'event_expired'::"text", 'operator_cancelled'::"text", 'policy_rollback'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_region_keys_check" CHECK ("public"."regional_recommendation_hold_region_keys_are_safe"("region_keys")),
    CONSTRAINT "regional_recommendation_holds_request_id_check" CHECK ((("request_id" IS NULL) OR ("request_id" ~ '^[A-Za-z0-9:_-]{1,96}$'::"text"))),
    CONSTRAINT "regional_recommendation_holds_scope_beach_ids_check" CHECK ((("cardinality"("scope_beach_ids") >= 1) AND ("cardinality"("scope_beach_ids") <= 2000))),
    CONSTRAINT "regional_recommendation_holds_scope_exposure_classes_check" CHECK (("scope_exposure_classes" <@ ARRAY['fully_exposed'::"text", 'partially_protected'::"text", 'protected'::"text", 'unknown'::"text"])),
    CONSTRAINT "regional_recommendation_holds_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_supporting_evidence_refs_check" CHECK ((("jsonb_typeof"("supporting_evidence_refs") = 'array'::"text") AND "public"."regional_recommendation_hold_refs_are_safe"("supporting_evidence_refs"))),
    CONSTRAINT "regional_recommendation_holds_transition_check" CHECK (("transition" = ANY (ARRAY['activation'::"text", 'extension'::"text", 'replacement'::"text", 'cancellation'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_trigger_type_check" CHECK (("trigger_type" = ANY (ARRAY['automatic_official'::"text", 'manual_operator'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_version_check" CHECK (("version" > 0))
);


ALTER TABLE "public"."regional_recommendation_holds" OWNER TO "postgres";


COMMENT ON TABLE "public"."regional_recommendation_holds" IS 'Append-only P0-A recommendation safety policy transitions. One row per audited transition.';



CREATE OR REPLACE FUNCTION "public"."append_regional_recommendation_hold_transition"("p_transition" "jsonb") RETURNS SETOF "public"."regional_recommendation_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_now timestamptz := transaction_timestamp();
  v_hold_id uuid;
  v_hold_id_text text;
  v_transition text;
  v_status text;
  v_trigger_type text;
  v_version integer;
  v_supersedes_record_id uuid;
  v_region_keys text[] := ARRAY[]::text[];
  v_scope_beach_ids uuid[] := ARRAY[]::uuid[];
  v_scope_exposure_classes text[] := ARRAY[]::text[];
  v_protected_alternative_beach_ids uuid[] := ARRAY[]::uuid[];
  v_event_reference text;
  v_valid_from timestamptz;
  v_valid_until timestamptz;
  v_affected_cohorts text[] := ARRAY[]::text[];
  v_action text;
  v_supporting_evidence_refs jsonb;
  v_automatic_policy_version text;
  v_authorizing_operator_ref uuid;
  v_authorizing_actor text;
  v_reason_code text;
  v_effective_at timestamptz;
  v_expires_at timestamptz;
  v_idempotency_key text;
  v_request_id text;
  v_operator_user_id uuid;
  v_operator_user_id_text text;
  v_operator_free_transition_text text;
  v_official_ref text;
  v_official_id uuid;
  v_risk_beach_id uuid;
  v_risk_valid_date date;
  v_risk_level text;
  v_risk_source text;
  v_risk_fetched_at timestamptz;
  v_beach_timezone text;
  v_local_today date;
  v_input_valid_from timestamptz;
  v_input_valid_until timestamptz;
  v_input_effective_at timestamptz;
  v_input_expires_at timestamptz;
  v_payload jsonb;
  v_payload_hash text;
  v_expected_input jsonb;
  v_key text;
  v_existing public.regional_recommendation_holds%ROWTYPE;
  v_previous public.regional_recommendation_holds%ROWTYPE;
  v_new public.regional_recommendation_holds%ROWTYPE;
BEGIN
  IF p_transition IS NULL OR jsonb_typeof(p_transition) <> 'object' THEN
    RAISE EXCEPTION 'hold transition must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_transition) AS supplied(key)
    WHERE supplied.key <> ALL (ARRAY[
      'holdId',
      'version',
      'transition',
      'regionKeys',
      'scopeBeachIds',
      'scopeExposureClasses',
      'protectedAlternativeBeachIds',
      'eventReference',
      'validFrom',
      'validUntil',
      'affectedCohorts',
      'action',
      'triggerType',
      'supportingEvidenceRefs',
      'automaticPolicyVersion',
      'operatorUserId',
      'authorizingActor',
      'reasonCode',
      'effectiveAt',
      'expiresAt',
      'supersedesRecordId',
      'idempotencyKey',
      'requestId'
    ]::text[])
  ) THEN
    RAISE EXCEPTION 'hold transition contains an unsupported field'
      USING ERRCODE = '22023';
  END IF;

  v_hold_id_text := p_transition ->> 'holdId';
  IF v_hold_id_text IS NULL
     OR v_hold_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'invalid hold id' USING ERRCODE = '22023';
  END IF;
  v_hold_id := v_hold_id_text::uuid;

  v_transition := p_transition ->> 'transition';
  IF v_transition IS NULL
     OR v_transition NOT IN (
       'activation','extension','replacement','cancellation'
     ) THEN
    RAISE EXCEPTION 'invalid hold transition' USING ERRCODE = '22023';
  END IF;

  v_trigger_type := p_transition ->> 'triggerType';
  IF v_trigger_type IS NULL
     OR v_trigger_type NOT IN ('automatic_official','manual_operator') THEN
    RAISE EXCEPTION 'invalid hold trigger type' USING ERRCODE = '22023';
  END IF;

  v_idempotency_key := p_transition ->> 'idempotencyKey';
  IF v_idempotency_key IS NULL
     OR v_idempotency_key !~ '^[A-Za-z0-9:_-]{1,160}$' THEN
    RAISE EXCEPTION 'invalid idempotency key' USING ERRCODE = '22023';
  END IF;

  v_request_id := p_transition ->> 'requestId';
  IF v_request_id IS NOT NULL
     AND v_request_id !~ '^[A-Za-z0-9:_-]{1,96}$' THEN
    RAISE EXCEPTION 'invalid request id' USING ERRCODE = '22023';
  END IF;

  v_supporting_evidence_refs := COALESCE(
    p_transition -> 'supportingEvidenceRefs',
    '[]'::jsonb
  );
  IF NOT public.regional_recommendation_hold_refs_are_safe(
    v_supporting_evidence_refs
  ) THEN
    RAISE EXCEPTION 'invalid supporting evidence references'
      USING ERRCODE = '22023';
  END IF;

  -- The idempotency-key lock is acquired before the hold lock everywhere.
  -- That fixed order prevents cross-hold retries from deadlocking.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('regional-hold-idempotency:' || v_idempotency_key, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('regional-hold:' || v_hold_id::text, 0)
  );

  SELECT *
  INTO v_existing
  FROM public.regional_recommendation_holds
  WHERE idempotency_key = v_idempotency_key;

  IF v_trigger_type = 'automatic_official' THEN
    IF v_transition <> 'activation'
       OR jsonb_array_length(v_supporting_evidence_refs) <> 1 THEN
      RAISE EXCEPTION 'automatic official holds require one activation reference'
        USING ERRCODE = '22023';
    END IF;

    v_official_ref := v_supporting_evidence_refs ->> 0;
    IF v_official_ref !~ '^official:rip_current_risks:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'automatic official reference is not eligible'
        USING ERRCODE = '22023';
    END IF;
    v_official_id := split_part(v_official_ref, ':', 3)::uuid;

    BEGIN
      IF p_transition ? 'validFrom' THEN
        v_input_valid_from := (p_transition ->> 'validFrom')::timestamptz;
      END IF;
      IF p_transition ? 'validUntil' THEN
        v_input_valid_until := (p_transition ->> 'validUntil')::timestamptz;
      END IF;
      IF p_transition ? 'effectiveAt' THEN
        v_input_effective_at := (p_transition ->> 'effectiveAt')::timestamptz;
      END IF;
      IF p_transition ? 'expiresAt' THEN
        v_input_expires_at := (p_transition ->> 'expiresAt')::timestamptz;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'automatic field conflicts with official evidence'
        USING ERRCODE = '22023';
    END;

    -- Exact retries return before clock-dependent normalization. Integrity is
    -- checked against the canonical stored tuple, not caller metadata.
    IF v_existing.record_id IS NOT NULL THEN
      v_new := v_existing;
      v_new.request_id := v_request_id;
      v_payload := public.regional_recommendation_hold_canonical_payload(
        v_new
      );
      v_payload_hash := encode(
        pg_catalog.sha256(convert_to(v_payload::text, 'UTF8')),
        'hex'
      );

      v_expected_input := jsonb_build_object(
        'holdId', v_existing.hold_id::text,
        'version', v_existing.version,
        'transition', v_existing.transition,
        'regionKeys', to_jsonb(v_existing.region_keys),
        'scopeBeachIds', to_jsonb(v_existing.scope_beach_ids),
        'scopeExposureClasses', to_jsonb(v_existing.scope_exposure_classes),
        'protectedAlternativeBeachIds',
          to_jsonb(v_existing.protected_alternative_beach_ids),
        'eventReference', v_existing.event_reference,
        'validFrom', v_existing.valid_from,
        'validUntil', v_existing.valid_until,
        'affectedCohorts', to_jsonb(v_existing.affected_cohorts),
        'action', v_existing.action,
        'triggerType', v_existing.trigger_type,
        'supportingEvidenceRefs', v_existing.supporting_evidence_refs,
        'automaticPolicyVersion', v_existing.automatic_policy_version,
        'authorizingActor', v_existing.authorizing_actor,
        'reasonCode', v_existing.reason_code,
        'effectiveAt', v_existing.effective_at,
        'expiresAt', v_existing.expires_at,
        'supersedesRecordId', v_existing.supersedes_record_id,
        'idempotencyKey', v_existing.idempotency_key,
        'requestId', v_existing.request_id
      );

      FOR v_key IN SELECT jsonb_object_keys(p_transition)
      LOOP
        IF v_key IN ('validFrom','validUntil','effectiveAt','expiresAt') THEN
          CONTINUE;
        END IF;

        IF (p_transition -> v_key) IS DISTINCT FROM (v_expected_input -> v_key) THEN
          RAISE EXCEPTION 'hold idempotency collision'
            USING ERRCODE = '23505';
        END IF;
      END LOOP;

      IF (p_transition ? 'validFrom'
          AND v_input_valid_from IS DISTINCT FROM v_existing.valid_from)
         OR (p_transition ? 'validUntil'
          AND v_input_valid_until IS DISTINCT FROM v_existing.valid_until)
         OR (p_transition ? 'effectiveAt'
          AND v_input_effective_at IS DISTINCT FROM v_existing.effective_at)
         OR (p_transition ? 'expiresAt'
          AND v_input_expires_at IS DISTINCT FROM v_existing.expires_at)
         OR v_request_id IS DISTINCT FROM v_existing.request_id
         OR v_existing.payload_hash <> v_payload_hash THEN
        RAISE EXCEPTION 'hold idempotency collision'
          USING ERRCODE = '23505';
      END IF;

      RETURN NEXT v_existing;
      RETURN;
    END IF;

    IF p_transition ? 'operatorUserId' THEN
      RAISE EXCEPTION 'automatic official holds cannot identify an operator'
        USING ERRCODE = '22023';
    END IF;

    SELECT
      r.beach_id,
      r.valid_date,
      r.risk_level,
      r.source,
      r.fetched_at,
      b.timezone
    INTO
      v_risk_beach_id,
      v_risk_valid_date,
      v_risk_level,
      v_risk_source,
      v_risk_fetched_at,
      v_beach_timezone
    FROM public.rip_current_risks AS r
    JOIN public.beaches AS b ON b.id = r.beach_id
    WHERE r.id = v_official_id
    FOR UPDATE OF r, b;

    IF NOT FOUND
       OR v_risk_level IS DISTINCT FROM 'high'
       OR (
         v_risk_source IS DISTINCT FROM 'srf'
         AND v_risk_source IS DISTINCT FROM 'alert'
       )
       OR v_risk_fetched_at IS NULL
       OR v_risk_fetched_at < transaction_timestamp() - interval '12 hours'
       OR v_risk_fetched_at > transaction_timestamp() + interval '5 minutes'
       OR v_beach_timezone IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM pg_catalog.pg_timezone_names AS zones
         WHERE zones.name = v_beach_timezone
       ) THEN
      RAISE EXCEPTION 'automatic official reference is not eligible'
        USING ERRCODE = '22023';
    END IF;

    v_local_today := (v_now AT TIME ZONE v_beach_timezone)::date;
    IF v_risk_valid_date IS NULL
       OR v_risk_valid_date < v_local_today
       OR v_risk_valid_date > v_local_today + 2 THEN
      RAISE EXCEPTION 'automatic official reference date is not eligible'
        USING ERRCODE = '22023';
    END IF;

    v_version := 1;
    v_status := 'active';
    v_region_keys := ARRAY[]::text[];
    v_scope_beach_ids := ARRAY[v_risk_beach_id];
    v_scope_exposure_classes := ARRAY[]::text[];
    v_protected_alternative_beach_ids := ARRAY[]::uuid[];
    v_event_reference := v_official_ref;
    v_valid_from := v_risk_valid_date::timestamp AT TIME ZONE v_beach_timezone;
    v_valid_until := (v_risk_valid_date + 1)::timestamp
      AT TIME ZONE v_beach_timezone;
    v_affected_cohorts := ARRAY[
      'beginner','intermediate','unknown'
    ]::text[];
    v_action := 'suppress_positive';
    v_automatic_policy_version := 'official-rip-high.v1';
    v_authorizing_operator_ref := NULL;
    v_authorizing_actor := 'official_automation';
    v_reason_code := 'official_high_rip_current';
    v_effective_at := GREATEST(v_now, v_valid_from);
    v_expires_at := v_valid_until;
    v_supersedes_record_id := NULL;

    v_expected_input := jsonb_build_object(
      'holdId', v_hold_id::text,
      'version', v_version,
      'transition', v_transition,
      'regionKeys', to_jsonb(v_region_keys),
      'scopeBeachIds', to_jsonb(v_scope_beach_ids),
      'scopeExposureClasses', to_jsonb(v_scope_exposure_classes),
      'protectedAlternativeBeachIds',
        to_jsonb(v_protected_alternative_beach_ids),
      'eventReference', v_event_reference,
      'validFrom', v_valid_from,
      'validUntil', v_valid_until,
      'affectedCohorts', to_jsonb(v_affected_cohorts),
      'action', v_action,
      'triggerType', v_trigger_type,
      'supportingEvidenceRefs', v_supporting_evidence_refs,
      'automaticPolicyVersion', v_automatic_policy_version,
      'authorizingActor', v_authorizing_actor,
      'reasonCode', v_reason_code,
      'effectiveAt', v_effective_at,
      'expiresAt', v_expires_at,
      'supersedesRecordId', v_supersedes_record_id,
      'idempotencyKey', v_idempotency_key,
      'requestId', v_request_id
    );

    FOR v_key IN SELECT jsonb_object_keys(p_transition)
    LOOP
      IF v_key IN ('validFrom','validUntil','effectiveAt','expiresAt') THEN
        CONTINUE;
      END IF;

      IF (p_transition -> v_key) IS DISTINCT FROM (v_expected_input -> v_key) THEN
        RAISE EXCEPTION 'automatic field conflicts with official evidence'
          USING ERRCODE = '22023';
      END IF;
    END LOOP;

    IF (p_transition ? 'validFrom'
        AND v_input_valid_from IS DISTINCT FROM v_valid_from)
       OR (p_transition ? 'validUntil'
        AND v_input_valid_until IS DISTINCT FROM v_valid_until)
       OR (p_transition ? 'effectiveAt'
        AND v_input_effective_at IS DISTINCT FROM v_effective_at)
       OR (p_transition ? 'expiresAt'
        AND v_input_expires_at IS DISTINCT FROM v_expires_at) THEN
      RAISE EXCEPTION 'automatic field conflicts with official evidence'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    IF (p_transition ->> 'authorizingActor') IS NOT NULL
       AND (p_transition ->> 'authorizingActor') <> 'admin_api' THEN
      RAISE EXCEPTION 'manual transition author is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF p_transition ? 'automaticPolicyVersion'
       AND p_transition -> 'automaticPolicyVersion' <> 'null'::jsonb THEN
      RAISE EXCEPTION 'manual transition cannot set automatic policy'
        USING ERRCODE = '22023';
    END IF;

    v_operator_user_id_text := p_transition ->> 'operatorUserId';
    IF v_operator_user_id_text IS NULL
       OR v_operator_user_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'manual transition requires an operator'
        USING ERRCODE = '22023';
    END IF;
    v_operator_user_id := v_operator_user_id_text::uuid;

    -- The auth UUID is transient authorization input. Reject it anywhere in
    -- the remaining body so it cannot be stored or enter the payload hash.
    v_operator_free_transition_text := lower(
      (p_transition - 'operatorUserId')::text
    );
    IF position(
         lower(v_operator_user_id::text)
         IN v_operator_free_transition_text
       ) > 0
       OR position(
         replace(lower(v_operator_user_id::text), '-', '')
         IN replace(v_operator_free_transition_text, '-', '')
       ) > 0 THEN
      RAISE EXCEPTION 'manual transition metadata cannot identify operator'
        USING ERRCODE = '22023';
    END IF;

    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'regional-hold-operator:' || v_operator_user_id::text,
        0
      )
    );

    IF EXISTS (
      SELECT 1
      FROM public.account_deletions
      WHERE user_id = v_operator_user_id
    ) THEN
      RAISE EXCEPTION 'manual transition operator is unavailable'
        USING ERRCODE = '22023';
    END IF;

    PERFORM 1
    FROM auth.users AS operator_user
    JOIN public.profiles AS operator_profile
      ON operator_profile.id = operator_user.id
    WHERE operator_user.id = v_operator_user_id
      AND operator_profile.deleted_at IS NULL
      AND (
        operator_user.banned_until IS NULL
        OR operator_user.banned_until <= v_now
      )
    FOR KEY SHARE OF operator_user, operator_profile;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'manual transition operator is unavailable'
        USING ERRCODE = '22023';
    END IF;

    SELECT operator_ref
    INTO v_authorizing_operator_ref
    FROM public.regional_recommendation_hold_operator_refs
    WHERE operator_user_id = v_operator_user_id;

    IF v_authorizing_operator_ref IS NULL
       AND v_existing.record_id IS NOT NULL THEN
      RAISE EXCEPTION 'hold idempotency collision'
        USING ERRCODE = '23505';
    END IF;

    IF v_authorizing_operator_ref IS NULL THEN
      INSERT INTO public.regional_recommendation_hold_operator_refs (
        operator_user_id
      )
      VALUES (v_operator_user_id)
      ON CONFLICT (operator_user_id) DO NOTHING;

      SELECT operator_ref
      INTO v_authorizing_operator_ref
      FROM public.regional_recommendation_hold_operator_refs
      WHERE operator_user_id = v_operator_user_id;
    END IF;

    IF v_authorizing_operator_ref IS NOT DISTINCT FROM v_operator_user_id THEN
      RAISE EXCEPTION 'manual transition operator reference is unavailable'
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_version := (p_transition ->> 'version')::integer;
      v_valid_from := (p_transition ->> 'validFrom')::timestamptz;
      v_valid_until := (p_transition ->> 'validUntil')::timestamptz;
      v_effective_at := (p_transition ->> 'effectiveAt')::timestamptz;
      v_expires_at := (p_transition ->> 'expiresAt')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'manual transition has invalid version or time fields'
        USING ERRCODE = '22023';
    END;

    IF v_version IS NULL
       OR v_valid_from IS NULL
       OR v_valid_until IS NULL
       OR v_effective_at IS NULL
       OR v_expires_at IS NULL
       OR v_valid_until <= v_valid_from
       OR v_expires_at <= v_effective_at
       OR v_expires_at > v_effective_at + interval '7 days' THEN
      RAISE EXCEPTION 'manual transition has invalid time bounds'
        USING ERRCODE = '22023';
    END IF;

    IF p_transition ->> 'supersedesRecordId' IS NOT NULL THEN
      IF (p_transition ->> 'supersedesRecordId')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'invalid superseded record id'
          USING ERRCODE = '22023';
      END IF;
      v_supersedes_record_id := (
        p_transition ->> 'supersedesRecordId'
      )::uuid;
    END IF;

    IF jsonb_typeof(COALESCE(p_transition -> 'regionKeys', '[]'::jsonb))
         <> 'array'
       OR jsonb_typeof(p_transition -> 'scopeBeachIds') <> 'array'
       OR jsonb_typeof(
         COALESCE(p_transition -> 'scopeExposureClasses', '[]'::jsonb)
       ) <> 'array'
       OR jsonb_typeof(
         COALESCE(
           p_transition -> 'protectedAlternativeBeachIds',
           '[]'::jsonb
         )
       ) <> 'array'
       OR jsonb_typeof(p_transition -> 'affectedCohorts') <> 'array' THEN
      RAISE EXCEPTION 'manual transition has invalid array fields'
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      SELECT COALESCE(
        array_agg(item.value ORDER BY item.ordinality),
        ARRAY[]::text[]
      )
      INTO v_region_keys
      FROM jsonb_array_elements_text(
        COALESCE(p_transition -> 'regionKeys', '[]'::jsonb)
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value::uuid ORDER BY item.ordinality),
        ARRAY[]::uuid[]
      )
      INTO v_scope_beach_ids
      FROM jsonb_array_elements_text(
        p_transition -> 'scopeBeachIds'
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value ORDER BY item.ordinality),
        ARRAY[]::text[]
      )
      INTO v_scope_exposure_classes
      FROM jsonb_array_elements_text(
        COALESCE(p_transition -> 'scopeExposureClasses', '[]'::jsonb)
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value::uuid ORDER BY item.ordinality),
        ARRAY[]::uuid[]
      )
      INTO v_protected_alternative_beach_ids
      FROM jsonb_array_elements_text(
        COALESCE(
          p_transition -> 'protectedAlternativeBeachIds',
          '[]'::jsonb
        )
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value ORDER BY item.ordinality),
        ARRAY[]::text[]
      )
      INTO v_affected_cohorts
      FROM jsonb_array_elements_text(
        p_transition -> 'affectedCohorts'
      ) WITH ORDINALITY AS item(value, ordinality);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'manual transition has invalid array values'
        USING ERRCODE = '22023';
    END;

    IF NOT public.regional_recommendation_hold_region_keys_are_safe(
      v_region_keys
    )
       OR cardinality(v_scope_beach_ids) NOT BETWEEN 1 AND 2000
       OR cardinality(v_scope_exposure_classes) > 4
       OR NOT v_scope_exposure_classes <@ ARRAY[
         'fully_exposed','partially_protected','protected','unknown'
       ]::text[]
       OR cardinality(v_protected_alternative_beach_ids) > 2000
       OR cardinality(v_affected_cohorts) = 0
       OR NOT v_affected_cohorts <@ ARRAY[
         'beginner','intermediate','advanced','expert','unknown'
       ]::text[]
       OR cardinality(v_scope_beach_ids) <> (
         SELECT count(DISTINCT beach_id)
         FROM unnest(v_scope_beach_ids) AS beaches(beach_id)
       )
       OR cardinality(v_scope_exposure_classes) <> (
         SELECT count(DISTINCT exposure_class)
         FROM unnest(v_scope_exposure_classes) AS exposures(exposure_class)
       )
       OR cardinality(v_protected_alternative_beach_ids) <> (
         SELECT count(DISTINCT beach_id)
         FROM unnest(v_protected_alternative_beach_ids) AS beaches(beach_id)
       )
       OR cardinality(v_affected_cohorts) <> (
         SELECT count(DISTINCT cohort)
         FROM unnest(v_affected_cohorts) AS cohorts(cohort)
       ) THEN
      RAISE EXCEPTION 'manual transition has invalid scope or cohort fields'
        USING ERRCODE = '22023';
    END IF;

    v_event_reference := p_transition ->> 'eventReference';
    IF v_event_reference IS NOT NULL
       AND v_event_reference
         !~ '^(event|official|qa):[a-z0-9_]+:[A-Za-z0-9_-]{1,64}$' THEN
      RAISE EXCEPTION 'manual transition has invalid event reference'
        USING ERRCODE = '22023';
    END IF;

    v_action := p_transition ->> 'action';
    IF v_action IS NULL
       OR v_action NOT IN (
         'suppress_positive','protected_alternatives_only'
       )
       OR (
         v_action = 'protected_alternatives_only'
         AND cardinality(v_protected_alternative_beach_ids) = 0
       ) THEN
      RAISE EXCEPTION 'manual transition has invalid action'
        USING ERRCODE = '22023';
    END IF;

    v_reason_code := p_transition ->> 'reasonCode';
    IF v_reason_code IS NULL
       OR v_reason_code NOT IN (
         'major_swell_manual_safety',
         'official_high_rip_current',
         'scope_correction',
         'event_expired',
         'operator_cancelled',
         'policy_rollback'
       ) THEN
      RAISE EXCEPTION 'manual transition has invalid reason code'
        USING ERRCODE = '22023';
    END IF;

    v_status := CASE
      WHEN v_transition = 'cancellation' THEN 'cancelled'
      ELSE 'active'
    END;
    v_automatic_policy_version := NULL;
    v_authorizing_actor := 'admin_api';
  END IF;

  v_new.hold_id := v_hold_id;
  v_new.version := v_version;
  v_new.transition := v_transition;
  v_new.status := v_status;
  v_new.region_keys := v_region_keys;
  v_new.scope_beach_ids := v_scope_beach_ids;
  v_new.scope_exposure_classes := v_scope_exposure_classes;
  v_new.protected_alternative_beach_ids :=
    v_protected_alternative_beach_ids;
  v_new.event_reference := v_event_reference;
  v_new.valid_from := v_valid_from;
  v_new.valid_until := v_valid_until;
  v_new.affected_cohorts := v_affected_cohorts;
  v_new.action := v_action;
  v_new.trigger_type := v_trigger_type;
  v_new.supporting_evidence_refs := v_supporting_evidence_refs;
  v_new.automatic_policy_version := v_automatic_policy_version;
  v_new.authorizing_operator_ref := v_authorizing_operator_ref;
  v_new.authorizing_actor := v_authorizing_actor;
  v_new.reason_code := v_reason_code;
  v_new.effective_at := v_effective_at;
  v_new.expires_at := v_expires_at;
  v_new.supersedes_record_id := v_supersedes_record_id;
  v_new.idempotency_key := v_idempotency_key;
  v_new.request_id := v_request_id;

  v_payload := public.regional_recommendation_hold_canonical_payload(v_new);
  v_payload_hash := encode(
    pg_catalog.sha256(convert_to(v_payload::text, 'UTF8')),
    'hex'
  );
  v_new.payload_hash := v_payload_hash;

  IF v_existing.record_id IS NOT NULL THEN
    IF v_existing.payload_hash <> v_payload_hash THEN
      RAISE EXCEPTION 'hold idempotency collision'
        USING ERRCODE = '23505';
    END IF;

    RETURN NEXT v_existing;
    RETURN;
  END IF;

  SELECT *
  INTO v_previous
  FROM public.regional_recommendation_holds
  WHERE hold_id = v_hold_id
  ORDER BY version DESC
  LIMIT 1
  FOR UPDATE;

  IF v_transition = 'activation' THEN
    IF v_version <> 1
       OR v_supersedes_record_id IS NOT NULL
       OR v_previous.record_id IS NOT NULL THEN
      RAISE EXCEPTION 'activation must start a new hold chain'
        USING ERRCODE = '22023';
    END IF;
  ELSIF v_previous.record_id IS NULL
        OR v_version <> v_previous.version + 1
        OR v_supersedes_record_id IS DISTINCT FROM v_previous.record_id THEN
    RAISE EXCEPTION 'transition must supersede the latest hold version'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.regional_recommendation_holds (
    hold_id,
    version,
    transition,
    status,
    region_keys,
    scope_beach_ids,
    scope_exposure_classes,
    protected_alternative_beach_ids,
    event_reference,
    valid_from,
    valid_until,
    affected_cohorts,
    action,
    trigger_type,
    supporting_evidence_refs,
    automatic_policy_version,
    authorizing_operator_ref,
    authorizing_actor,
    reason_code,
    effective_at,
    expires_at,
    supersedes_record_id,
    idempotency_key,
    payload_hash,
    request_id
  )
  VALUES (
    v_new.hold_id,
    v_new.version,
    v_new.transition,
    v_new.status,
    v_new.region_keys,
    v_new.scope_beach_ids,
    v_new.scope_exposure_classes,
    v_new.protected_alternative_beach_ids,
    v_new.event_reference,
    v_new.valid_from,
    v_new.valid_until,
    v_new.affected_cohorts,
    v_new.action,
    v_new.trigger_type,
    v_new.supporting_evidence_refs,
    v_new.automatic_policy_version,
    v_new.authorizing_operator_ref,
    v_new.authorizing_actor,
    v_new.reason_code,
    v_new.effective_at,
    v_new.expires_at,
    v_new.supersedes_record_id,
    v_new.idempotency_key,
    v_new.payload_hash,
    v_new.request_id
  )
  RETURNING * INTO v_new;

  RETURN NEXT v_new;
END;
$_$;


ALTER FUNCTION "public"."append_regional_recommendation_hold_transition"("p_transition" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."append_regional_recommendation_hold_transition"("p_transition" "jsonb") IS 'Only application write boundary for manual and database-verified official recommendation hold transitions.';



CREATE OR REPLACE FUNCTION "public"."apply_android_tester_roster_snapshot"("p_actor_user_id" "uuid", "p_claim_token" "uuid", "p_snapshot_complete" boolean, "p_observed_at" timestamp with time zone, "p_observations" "jsonb", "p_direct_user_count" integer, "p_failure_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  observation jsonb;
  v_entry_id uuid;
  v_claim_token uuid;
  v_sync_run_id uuid;
  v_changed integer := 0;
  v_added integer := 0;
  v_rejoined integer := 0;
  v_refreshed integer := 0;
  v_left integer := 0;
  v_purged integer := 0;
BEGIN
  SELECT claim.claim_token
  INTO v_claim_token
  FROM public.android_tester_roster_sync_claims AS claim
  WHERE claim.singleton
    AND claim.claim_token = p_claim_token
  FOR UPDATE;

  IF v_claim_token IS NULL THEN
    RAISE EXCEPTION 'Android tester roster sync claim unavailable';
  END IF;

  INSERT INTO public.android_tester_roster_sync_runs (
    source,
    complete,
    observed_at,
    direct_user_count,
    failure_code
  ) VALUES (
    'google_directory',
    p_snapshot_complete,
    p_observed_at,
    GREATEST(COALESCE(p_direct_user_count, 0), 0),
    p_failure_code
  )
  RETURNING id INTO v_sync_run_id;

  IF NOT p_snapshot_complete THEN
    INSERT INTO public.android_tester_roster_audit (
      actor_user_id,
      action,
      outcome,
      evidence
    ) VALUES (
      p_actor_user_id,
      'sync',
      'failed',
      jsonb_build_object('failureCode', COALESCE(p_failure_code, 'incomplete'))
    );
    DELETE FROM public.android_tester_roster_sync_claims
    WHERE singleton
      AND claim_token = p_claim_token;
    RETURN jsonb_build_object('complete', false);
  END IF;

  FOR observation IN
    SELECT value FROM jsonb_array_elements(COALESCE(p_observations, '[]'::jsonb))
  LOOP
    IF observation->>'kind' = 'new' THEN
      INSERT INTO public.android_tester_roster_entries (
        eligibility_status,
        group_membership_status,
        eligibility_source,
        eligibility_observed_at,
        eligibility_confidence
      ) VALUES (
        'eligible',
        'active',
        'google_directory',
        p_observed_at,
        'verified'
      )
      RETURNING id INTO v_entry_id;

      INSERT INTO public.android_tester_roster_identities (
        entry_id,
        key_version,
        iv,
        ciphertext,
        auth_tag
      ) VALUES (
        v_entry_id,
        (observation->>'keyVersion')::integer,
        observation->>'iv',
        observation->>'ciphertext',
        observation->>'authTag'
      );

      INSERT INTO public.android_tester_roster_stages (
        entry_id,
        stage,
        status,
        source,
        observed_at,
        confidence,
        evidence
      ) VALUES
        (
          v_entry_id,
          'play_opt_in',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        ),
        (
          v_entry_id,
          'install',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        ),
        (
          v_entry_id,
          'first_open',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        ),
        (
          v_entry_id,
          'account_join',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        );
      v_added := v_added + 1;
    ELSIF observation->>'kind' = 'seen' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_observed_at = p_observed_at,
        updated_at = now()
      WHERE id = v_entry_id
        AND eligibility_status = 'eligible';
    ELSIF observation->>'kind' = 'rejoined' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'eligible',
        group_membership_status = 'active',
        eligibility_observed_at = p_observed_at,
        eligibility_confidence = 'verified',
        purge_after = NULL,
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NULL;

      INSERT INTO public.android_tester_roster_identities (
        entry_id,
        key_version,
        iv,
        ciphertext,
        auth_tag
      )
      SELECT
        v_entry_id,
        (observation->>'keyVersion')::integer,
        observation->>'iv',
        observation->>'ciphertext',
        observation->>'authTag'
      WHERE EXISTS (
        SELECT 1
        FROM public.android_tester_roster_entries AS entry
        WHERE entry.id = v_entry_id
          AND entry.user_id IS NULL
      )
      ON CONFLICT (entry_id) DO UPDATE SET
        key_version = EXCLUDED.key_version,
        iv = EXCLUDED.iv,
        ciphertext = EXCLUDED.ciphertext,
        auth_tag = EXCLUDED.auth_tag,
        updated_at = now();
      v_rejoined := v_rejoined + 1;
    ELSIF observation->>'kind' = 'identity_refresh' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_observed_at = p_observed_at,
        updated_at = now()
      WHERE id = v_entry_id
        AND eligibility_status = 'eligible'
        AND user_id IS NULL;

      INSERT INTO public.android_tester_roster_identities (
        entry_id,
        key_version,
        iv,
        ciphertext,
        auth_tag
      )
      SELECT
        v_entry_id,
        (observation->>'keyVersion')::integer,
        observation->>'iv',
        observation->>'ciphertext',
        observation->>'authTag'
      WHERE EXISTS (
        SELECT 1
        FROM public.android_tester_roster_entries AS entry
        WHERE entry.id = v_entry_id
          AND entry.user_id IS NULL
      )
      ON CONFLICT (entry_id) DO UPDATE SET
        key_version = EXCLUDED.key_version,
        iv = EXCLUDED.iv,
        ciphertext = EXCLUDED.ciphertext,
        auth_tag = EXCLUDED.auth_tag,
        updated_at = now();
      GET DIAGNOSTICS v_changed = ROW_COUNT;
      v_refreshed := v_refreshed + v_changed;
    ELSIF observation->>'kind' = 'rejoined_linked' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'eligible',
        group_membership_status = 'active',
        eligibility_observed_at = p_observed_at,
        eligibility_confidence = 'verified',
        purge_after = NULL,
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NOT NULL;
      v_rejoined := v_rejoined + 1;
    ELSIF observation->>'kind' = 'left' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      PERFORM 1
      FROM public.android_tester_roster_entries AS entry
      WHERE entry.id = v_entry_id
      FOR UPDATE;

      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'ineligible',
        group_membership_status = 'left',
        eligibility_observed_at = p_observed_at,
        purge_after = p_observed_at + interval '30 days',
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NULL;
      GET DIAGNOSTICS v_changed = ROW_COUNT;
      v_left := v_left + v_changed;
      IF v_changed = 0 THEN
        CONTINUE;
      END IF;
    ELSIF observation->>'kind' = 'left_linked' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'ineligible',
        group_membership_status = 'left',
        eligibility_observed_at = p_observed_at,
        purge_after = NULL,
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NOT NULL;
      v_left := v_left + 1;
    ELSE
      RAISE EXCEPTION 'Unsupported roster observation';
    END IF;

    INSERT INTO public.android_tester_roster_stages (
      entry_id,
      stage,
      status,
      source,
      observed_at,
      confidence,
      evidence
    ) VALUES (
      v_entry_id,
      'group_eligibility',
      CASE
        WHEN observation->>'kind' IN ('left', 'left_linked')
          THEN 'ineligible'
        ELSE 'eligible'
      END,
      'google_directory',
      p_observed_at,
      'verified',
      '{}'::jsonb
    );
  END LOOP;

  DELETE FROM public.android_tester_roster_identities AS identity
  USING public.android_tester_roster_entries AS entry
  WHERE identity.entry_id = entry.id
    AND entry.user_id IS NULL
    AND entry.eligibility_status = 'ineligible'
    AND entry.purge_after <= p_observed_at;
  GET DIAGNOSTICS v_purged = ROW_COUNT;

  UPDATE public.android_tester_roster_sync_runs
  SET
    added_count = v_added,
    rejoined_count = v_rejoined,
    refreshed_count = v_refreshed,
    left_count = v_left,
    purged_count = v_purged
  WHERE id = v_sync_run_id;

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    action,
    outcome,
    evidence
  ) VALUES (
    p_actor_user_id,
    'sync',
    'succeeded',
    jsonb_build_object(
      'directUserCount', p_direct_user_count,
      'addedCount', v_added,
      'rejoinedCount', v_rejoined,
      'refreshedCount', v_refreshed,
      'leftCount', v_left,
      'purgedCount', v_purged
    )
  );

  DELETE FROM public.android_tester_roster_sync_claims
  WHERE singleton
    AND claim_token = p_claim_token;

  RETURN jsonb_build_object(
    'complete', true,
    'addedCount', v_added,
    'rejoinedCount', v_rejoined,
    'refreshedCount', v_refreshed,
    'leftCount', v_left,
    'purgedCount', v_purged
  );
END;
$$;


ALTER FUNCTION "public"."apply_android_tester_roster_snapshot"("p_actor_user_id" "uuid", "p_claim_token" "uuid", "p_snapshot_complete" boolean, "p_observed_at" timestamp with time zone, "p_observations" "jsonb", "p_direct_user_count" integer, "p_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_session_rip_current_risk"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  session_local_date DATE;
BEGIN
  NEW.rip_current_risk := NULL;

  IF NEW.beach_id IS NULL OR NEW.arrival_time IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT (NEW.arrival_time AT TIME ZONE b.timezone)::date
  INTO session_local_date
  FROM public.beaches b
  WHERE b.id = NEW.beach_id
    AND b.timezone IS NOT NULL;

  IF session_local_date IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT r.risk_level
  INTO NEW.rip_current_risk
  FROM public.rip_current_risks r
  WHERE r.beach_id = NEW.beach_id
    AND r.valid_date = session_local_date
  LIMIT 1;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_session_rip_current_risk"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_session_tide_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  snapshot RECORD;
  has_snapshot BOOLEAN := false;
  has_manual_tide BOOLEAN := false;
  should_recompute_tide BOOLEAN := false;
BEGIN
  IF NEW.beach_id IS NULL OR NEW.arrival_time IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT *
  INTO snapshot
  FROM public.compute_session_tide_snapshot(NEW.beach_id, NEW.arrival_time)
  LIMIT 1;
  has_snapshot := FOUND;

  should_recompute_tide :=
    TG_OP = 'UPDATE'
    AND (
      NEW.beach_id IS DISTINCT FROM OLD.beach_id
      OR NEW.arrival_time IS DISTINCT FROM OLD.arrival_time
    )
    AND COALESCE(NEW.tide_data_source, '') <> 'user';

  IF should_recompute_tide THEN
    IF has_snapshot THEN
      NEW.tide_height_ft := snapshot.tide_height_ft;
      NEW.tide_status := snapshot.tide_status;
      NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
      NEW.tide_data_source := snapshot.tide_data_source;
    ELSE
      NEW.tide_height_ft := NULL;
      NEW.tide_status := NULL;
      NEW.tide_rate_ft_per_hr := NULL;
      NEW.tide_data_source := NULL;
    END IF;

    RETURN NEW;
  END IF;

  has_manual_tide :=
    COALESCE(NEW.tide_data_source, '') = 'user'
    OR (
      TG_OP = 'INSERT'
      AND (
        NEW.tide_height_ft IS NOT NULL
        OR NEW.tide_status IS NOT NULL
      )
    )
    OR (
      TG_OP = 'UPDATE'
      AND (
        NEW.tide_height_ft IS DISTINCT FROM OLD.tide_height_ft
        OR NEW.tide_status IS DISTINCT FROM OLD.tide_status
      )
      AND (
        NEW.tide_height_ft IS NOT NULL
        OR NEW.tide_status IS NOT NULL
      )
    );

  IF has_manual_tide THEN
    NEW.tide_data_source := 'user';

    IF NEW.tide_rate_ft_per_hr IS NULL AND has_snapshot THEN
      NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
    END IF;

    RETURN NEW;
  END IF;

  IF has_snapshot THEN
    NEW.tide_height_ft := snapshot.tide_height_ft;
    NEW.tide_status := snapshot.tide_status;
    NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
    NEW.tide_data_source := snapshot.tide_data_source;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_session_tide_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assess_apple_identity_recovery"("p_canonical_user_id" "uuid", "p_apple_sub" "text", "p_apple_token_sha256" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $_$
DECLARE
  v_identity auth.identities%ROWTYPE;
  v_existing public.apple_identity_recovery_requests%ROWTYPE;
  v_dependency record;
  v_dependency_count bigint;
  v_data_counts jsonb := '{}'::jsonb;
  v_has_product_data boolean := false;
  v_recovery_id uuid;
  v_support_reference text;
  v_secondary_created_at timestamptz;
  v_expires_at timestamptz := clock_timestamp() + interval '10 minutes';
BEGIN
  IF p_canonical_user_id IS NULL
     OR length(p_apple_sub) = 0
     OR p_apple_token_sha256 !~ '^[0-9a-f]{64}$'
     OR length(p_idempotency_key) < 8
     OR length(p_idempotency_key) > 128 THEN
    RAISE EXCEPTION 'invalid apple recovery assessment input';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_constraint current_constraint
    JOIN pg_class source_table ON source_table.oid = current_constraint.conrelid
    JOIN pg_namespace source_ns ON source_ns.oid = source_table.relnamespace
    JOIN pg_class target_table ON target_table.oid = current_constraint.confrelid
    JOIN pg_namespace target_ns ON target_ns.oid = target_table.relnamespace
    WHERE current_constraint.contype = 'f'
      AND source_ns.nspname = 'public'
      AND current_constraint.confrelid IN ('auth.users'::regclass, 'public.profiles'::regclass)
      AND NOT EXISTS (
        SELECT 1
        FROM public.apple_recovery_dependency_registry registry
        WHERE registry.source_schema = source_ns.nspname
          AND registry.source_table = source_table.relname
          AND registry.constraint_name = current_constraint.conname
          AND registry.target_schema = target_ns.nspname
          AND registry.target_table = target_table.relname
      )
  ) THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type
    ) VALUES (
      p_canonical_user_id,
      'schema_coverage_incomplete'
    );
    RETURN jsonb_build_object('status', 'schema_coverage_incomplete');
  END IF;

  SELECT *
  INTO v_identity
  FROM auth.identities
  WHERE provider = 'apple'
    AND (
      provider_id = p_apple_sub
      OR identity_data->>'sub' = p_apple_sub
    )
  ORDER BY created_at
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type
    ) VALUES (
      p_canonical_user_id,
      'apple_identity_unclaimed'
    );
    RETURN jsonb_build_object('status', 'unclaimed');
  END IF;

  IF v_identity.user_id = p_canonical_user_id THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type
    ) VALUES (
      p_canonical_user_id,
      'apple_identity_already_linked'
    );
    RETURN jsonb_build_object('status', 'already_linked');
  END IF;

  SELECT *
  INTO v_existing
  FROM public.apple_identity_recovery_requests
  WHERE apple_token_sha256 = p_apple_token_sha256
     OR (
       canonical_user_id = p_canonical_user_id
       AND assessment_idempotency_key = p_idempotency_key
     )
  ORDER BY created_at DESC
  LIMIT 1;

  IF FOUND THEN
    IF v_existing.canonical_user_id <> p_canonical_user_id
       OR v_existing.assessment_idempotency_key <> p_idempotency_key THEN
      RETURN jsonb_build_object('status', 'replayed');
    END IF;

    RETURN jsonb_build_object(
      'status', v_existing.status,
      'recovery_id', v_existing.id,
      'expires_at', v_existing.expires_at,
      'support_reference', v_existing.support_reference,
      'secondary_created_at', (
        SELECT created_at FROM auth.users WHERE id = v_existing.secondary_user_id
      )
    );
  END IF;

  SELECT created_at
  INTO v_secondary_created_at
  FROM auth.users
  WHERE id = v_identity.user_id;

  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = v_identity.user_id) THEN
    v_has_product_data := true;
    v_data_counts := v_data_counts || jsonb_build_object('public.profiles', 1);
  END IF;

  FOR v_dependency IN
    SELECT *
    FROM public.apple_recovery_dependency_registry
    WHERE NOT (
      source_schema = 'public'
      AND source_table IN (
        'profiles',
        'apple_identity_recovery_requests',
        'apple_identity_recovery_audit'
      )
    )
  LOOP
    IF cardinality(v_dependency.source_columns) <> 1 THEN
      v_has_product_data := true;
      v_data_counts := v_data_counts || jsonb_build_object(
        format('%I.%I', v_dependency.source_schema, v_dependency.source_table),
        'unsupported_composite_fk'
      );
      CONTINUE;
    END IF;

    EXECUTE format(
      'SELECT count(*) FROM %I.%I WHERE %I = $1',
      v_dependency.source_schema,
      v_dependency.source_table,
      v_dependency.source_columns[1]
    )
    INTO v_dependency_count
    USING v_identity.user_id;

    IF v_dependency_count > 0 THEN
      v_has_product_data := true;
      v_data_counts := v_data_counts || jsonb_build_object(
        format('%I.%I', v_dependency.source_schema, v_dependency.source_table),
        v_dependency_count
      );
    END IF;
  END LOOP;

  v_recovery_id := gen_random_uuid();
  v_support_reference := 'AR-' || upper(substr(replace(v_recovery_id::text, '-', ''), 1, 8));

  INSERT INTO public.apple_identity_recovery_requests (
    id,
    canonical_user_id,
    secondary_user_id,
    apple_identity_id,
    apple_sub_sha256,
    apple_token_sha256,
    assessment_idempotency_key,
    status,
    eligibility_snapshot,
    support_reference,
    expires_at
  ) VALUES (
    v_recovery_id,
    p_canonical_user_id,
    v_identity.user_id,
    v_identity.id,
    encode(extensions.digest(p_apple_sub, 'sha256'), 'hex'),
    p_apple_token_sha256,
    p_idempotency_key,
    CASE WHEN v_has_product_data THEN 'support_required' ELSE 'eligible' END,
    jsonb_build_object(
      'schema_coverage_complete', true,
      'data_counts', v_data_counts,
      'assessed_at', clock_timestamp()
    ),
    v_support_reference,
    v_expires_at
  );

  INSERT INTO public.apple_identity_recovery_audit (
    recovery_id,
    canonical_user_id,
    event_type,
    event_details
  ) VALUES (
    v_recovery_id,
    p_canonical_user_id,
    CASE WHEN v_has_product_data THEN 'support_required' ELSE 'eligible' END,
    jsonb_build_object(
      'dependency_count',
      (SELECT count(*) FROM jsonb_object_keys(v_data_counts))
    )
  );

  IF v_has_product_data THEN
    RETURN jsonb_build_object(
      'status', 'support_required',
      'support_reference', v_support_reference
    );
  END IF;

  RETURN jsonb_build_object(
    'status', 'eligible',
    'recovery_id', v_recovery_id,
    'expires_at', v_expires_at,
    'secondary_created_at', v_secondary_created_at
  );
END;
$_$;


ALTER FUNCTION "public"."assess_apple_identity_recovery"("p_canonical_user_id" "uuid", "p_apple_sub" "text", "p_apple_token_sha256" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assess_apple_identity_recovery"("p_canonical_user_id" "uuid", "p_apple_sub" "text", "p_apple_token_sha256" "text", "p_idempotency_key" "text") IS 'Service-only Apple recovery assessment. Uses a verified stable Apple sub supplied by the API, inventories every registered public FK dependency, and fails closed on schema growth.';



CREATE OR REPLACE FUNCTION "public"."assign_experiment"("p_user_id" "uuid", "p_experiment_key" "text", "p_index_at" timestamp with time zone DEFAULT "now"()) RETURNS "public"."experiment_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_row public.experiment_assignments;
BEGIN
  INSERT INTO public.experiment_assignments
    (experiment_key, user_id, arm, index_at, assignment_version)
  VALUES
    (p_experiment_key, p_user_id,
     public.experiment_arm(p_user_id, p_experiment_key),
     p_index_at, 'v1')
  ON CONFLICT (experiment_key, user_id) DO NOTHING;

  SELECT * INTO STRICT v_row
  FROM public.experiment_assignments
  WHERE experiment_key = p_experiment_key AND user_id = p_user_id;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."assign_experiment"("p_user_id" "uuid", "p_experiment_key" "text", "p_index_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_nearest_beach_to_intel_post"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.beach_id IS NULL THEN
    NEW.beach_id := find_nearest_beach_id(NEW.latitude, NEW.longitude);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assign_nearest_beach_to_intel_post"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_nearest_beach_to_intel_post"() IS 'Trigger function that automatically assigns the nearest beach to intel posts on INSERT. Only assigns if beach_id is NULL (preserves explicit assignments). Uses SECURITY DEFINER to bypass RLS when reading beaches table.';



CREATE OR REPLACE FUNCTION "public"."assign_signup_experiments"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.assign_experiment(NEW.id, 't3-quicklog-v1', NEW.created_at);
  PERFORM public.assign_experiment(NEW.id, 't10-freegrowth-v1', NEW.created_at);
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- The exception savepoint rolls back both inserts, so this is both-or-neither.
    -- The deterministic hash makes any gap repairable from auth.users.created_at.
    RAISE WARNING 'assign_signup_experiments failed for %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assign_signup_experiments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_android_waitlist_entries"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_profile record;
  v_lead record;
  v_roster record;
BEGIN
  FOR v_profile IN
    SELECT
      p.id,
      p.android_waitlist_joined_at,
      p.android_waitlist_source,
      p.android_waitlist_surface,
      p.android_waitlist_placement,
      auth_user.email
    FROM public.profiles AS p
    JOIN auth.users AS auth_user ON auth_user.id = p.id
    WHERE p.wants_android_access
      AND p.android_waitlist_joined_at IS NOT NULL
    ORDER BY p.android_waitlist_joined_at, p.id
  LOOP
    PERFORM public.resolve_android_waitlist_entry(
      v_profile.id,
      CASE WHEN NULLIF(btrim(lower(v_profile.email)), '') IS NULL THEN NULL
        ELSE encode(
          extensions.digest(
            convert_to(btrim(lower(v_profile.email)), 'UTF8'),
            'sha256'
          ),
          'hex'
        )
      END,
      NULL,
      'profile_intent',
      v_profile.id,
      COALESCE(NULLIF(v_profile.android_waitlist_source, ''), 'legacy_profile'),
      COALESCE(NULLIF(v_profile.android_waitlist_surface, ''), 'profile'),
      COALESCE(NULLIF(v_profile.android_waitlist_placement, ''), 'unknown'),
      v_profile.android_waitlist_joined_at
    );
  END LOOP;

  FOR v_lead IN
    SELECT
      l.id,
      l.email,
      l.source,
      l.surface,
      l.placement,
      l.created_at
    FROM public.android_beta_leads AS l
    ORDER BY l.created_at, l.id
  LOOP
    PERFORM public.resolve_android_waitlist_entry(
      NULL,
      encode(
        extensions.digest(
          convert_to(btrim(lower(v_lead.email)), 'UTF8'),
          'sha256'
        ),
        'hex'
      ),
      NULL,
      'anonymous_lead',
      v_lead.id,
      v_lead.source,
      v_lead.surface,
      v_lead.placement,
      v_lead.created_at
    );
  END LOOP;

  FOR v_roster IN
    SELECT
      r.id,
      r.user_id,
      r.eligibility_observed_at,
      auth_user.email
    FROM public.android_tester_roster_entries AS r
    LEFT JOIN auth.users AS auth_user ON auth_user.id = r.user_id
    ORDER BY r.eligibility_observed_at, r.id
  LOOP
    PERFORM public.resolve_android_waitlist_entry(
      v_roster.user_id,
      CASE WHEN NULLIF(btrim(lower(v_roster.email)), '') IS NULL THEN NULL
        ELSE encode(
          extensions.digest(
            convert_to(btrim(lower(v_roster.email)), 'UTF8'),
            'sha256'
          ),
          'hex'
        )
      END,
      v_roster.id,
      'roster_evidence',
      v_roster.id,
      'google_directory',
      'android_tester_roster',
      'direct_group_membership',
      v_roster.eligibility_observed_at
    );
  END LOOP;

  RETURN jsonb_build_object(
    'entries', (SELECT count(*) FROM public.android_waitlist_entries),
    'sourceLinks', (
      SELECT count(*) FROM public.android_waitlist_source_links
    ),
    'joinedEvents', (
      SELECT count(*) FROM public.android_waitlist_events
      WHERE event_type = 'android_waitlist_joined'
    )
  );
END;
$$;


ALTER FUNCTION "public"."backfill_android_waitlist_entries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_ml_observations"("batch_size" integer DEFAULT 1000) RETURNS TABLE("processed" integer, "matched" integer, "no_match" integer, "elapsed_ms" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  start_time TIMESTAMPTZ := clock_timestamp();
  v_processed INT := 0;
  v_matched INT := 0;
  v_no_match INT := 0;
  cutoff TIMESTAMPTZ := NOW() - INTERVAL '2 hours';
  observation_window_start TIMESTAMPTZ := NOW() - INTERVAL '7 days';
  pred RECORD;
  obs RECORD;
BEGIN
  -- Get pending predictions for observable beaches
  FOR pred IN
    SELECT p.id, p.beach_id, p.predicted_at, p.raw_forecast_m, p.corrected_forecast_m
    FROM ml_predictions_log p
    INNER JOIN observable_beaches o ON p.beach_id = o.beach_id
    WHERE p.observed_m IS NULL
      AND p.predicted_at < cutoff
      AND p.predicted_at > observation_window_start
    ORDER BY p.predicted_at ASC
    LIMIT batch_size
  LOOP
    v_processed := v_processed + 1;
    
    -- Find nearest observation within 1 hour window
    SELECT mf.wave_height_m INTO obs
    FROM marine_forecasts mf
    WHERE mf.beach_id = pred.beach_id
      AND mf.is_observed = true
      AND mf.wave_height_m IS NOT NULL
      AND mf.ts >= pred.predicted_at - INTERVAL '1 hour'
      AND mf.ts <= pred.predicted_at + INTERVAL '1 hour'
    ORDER BY mf.ts ASC
    LIMIT 1;
    
    IF obs.wave_height_m IS NOT NULL THEN
      -- Update prediction with ground truth
      UPDATE ml_predictions_log
      SET 
        observed_m = obs.wave_height_m,
        raw_error_m = ABS(pred.raw_forecast_m - obs.wave_height_m),
        corrected_error_m = ABS(pred.corrected_forecast_m - obs.wave_height_m)
      WHERE id = pred.id;
      
      v_matched := v_matched + 1;
    ELSE
      v_no_match := v_no_match + 1;
    END IF;
  END LOOP;
  
  processed := v_processed;
  matched := v_matched;
  no_match := v_no_match;
  elapsed_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INT;
  
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."backfill_ml_observations"("batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_ml_observations"("batch_size" integer) IS 'Backfills ML predictions with ground truth observations. Run via pg_cron every 10 minutes.';



CREATE OR REPLACE FUNCTION "public"."backfill_ml_observations_batch"("batch_size" integer DEFAULT 10000) RETURNS TABLE("processed" integer, "matched" integer, "sentinel_marked" integer, "expired_deleted" integer, "elapsed_ms" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  start_ts TIMESTAMPTZ := clock_timestamp();
  v_matched INT := 0;
  v_sentinel INT := 0;
  v_expired INT := 0;
  cutoff TIMESTAMPTZ := NOW() - INTERVAL '12 hours';
  observation_window_start TIMESTAMPTZ := NOW() - INTERVAL '7 days';
BEGIN
  WITH matchable AS (
    SELECT DISTINCT ON (p.id)
      p.id,
      uwo.wave_height_m AS obs_height
    FROM ml_predictions_log p
    INNER JOIN observable_beaches ob ON ob.beach_id = p.beach_id
    INNER JOIN unified_wave_observations uwo
      ON uwo.nearest_beach_id = p.beach_id
      AND uwo.wave_height_m IS NOT NULL
      AND uwo.observed_at >= p.predicted_at - INTERVAL '12 hours'
      AND uwo.observed_at <= p.predicted_at + INTERVAL '12 hours'
    WHERE p.observed_m IS NULL
      AND p.predicted_at < cutoff
      AND p.predicted_at > observation_window_start
    ORDER BY p.id, ABS(EXTRACT(EPOCH FROM (uwo.observed_at - p.predicted_at)))
    LIMIT batch_size
  ),
  updated AS (
    UPDATE ml_predictions_log p
    SET
      observed_m = m.obs_height,
      raw_error_m = ABS(p.raw_forecast_m - m.obs_height),
      corrected_error_m = ABS(p.corrected_forecast_m - m.obs_height)
    FROM matchable m
    WHERE p.id = m.id
    RETURNING p.id
  )
  SELECT COUNT(*)::INT INTO v_matched FROM updated;

  WITH sentinel AS (
    UPDATE ml_predictions_log
    SET observed_m = -1
    WHERE observed_m IS NULL
      AND predicted_at < NOW() - INTERVAL '24 hours'
    RETURNING id
  )
  SELECT COUNT(*)::INT INTO v_sentinel FROM sentinel;

  WITH expired AS (
    DELETE FROM ml_predictions_log
    WHERE observed_m IS NULL
      AND predicted_at < NOW() - INTERVAL '72 hours'
    RETURNING id
  )
  SELECT COUNT(*)::INT INTO v_expired FROM expired;

  RETURN QUERY SELECT
    v_matched + v_sentinel + v_expired,
    v_matched,
    v_sentinel,
    v_expired,
    ROUND(EXTRACT(EPOCH FROM (clock_timestamp() - start_ts)) * 1000, 2);
END;
$$;


ALTER FUNCTION "public"."backfill_ml_observations_batch"("batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_ml_observations_batch"("batch_size" integer) IS 'JOIN-based ML ground truth matcher with expanded ±4h window.
   Step 1: Match predictions with observations via ±4h window (was ±2h).
   Step 2: Mark predictions >24h old as unmatchable (sentinel -1).
   Step 3: DELETE pending predictions >72h old (TTL cleanup).
   Returns: (processed, matched, sentinel_marked, expired_deleted, elapsed_ms).
   Updated Feb 2 2026: expanded matching window 2h→4h for better match rate.';



CREATE OR REPLACE FUNCTION "public"."bulk_update_hrrr_wind"("payload" "jsonb") RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH v AS (
    SELECT * FROM jsonb_to_recordset(payload) AS x(
      beach_id uuid,
      hour_start timestamptz,
      wind_speed text,
      wind_direction text,
      wind_direction_deg numeric
    )
  ), upd AS (
    UPDATE enhanced_forecasts ef
    SET wind_speed = v.wind_speed,
        wind_direction = v.wind_direction,
        wind_direction_deg = v.wind_direction_deg,
        wind_source = 'HRRR'
    FROM v
    WHERE ef.beach_id = v.beach_id
      AND ef.forecast_at >= v.hour_start
      AND ef.forecast_at < v.hour_start + INTERVAL '1 hour'
    RETURNING 1
  )
  SELECT count(*)::int FROM upd;
$$;


ALTER FUNCTION "public"."bulk_update_hrrr_wind"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bulk_update_hrrr_wind"("payload" "jsonb") IS 'Bulk-applies HRRR wind to enhanced_forecasts in one statement. Payload: array of {beach_id, hour_start, wind_speed, wind_direction, wind_direction_deg}. Returns rows updated.';



CREATE OR REPLACE FUNCTION "public"."can_view_surf_drop"("p_drop_id" "uuid", "p_viewer" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.surf_drops d
    WHERE d.id = p_drop_id
      AND p_viewer IS NOT NULL
      AND d.deleted_at IS NULL
      AND NOT public.has_user_block_between(p_viewer, d.user_id)
      AND (
        d.user_id = p_viewer
        OR EXISTS (
          SELECT 1
          FROM public.surf_drop_link_grants lg
          WHERE lg.drop_id = d.id
            AND lg.user_id = p_viewer
        )
        OR EXISTS (
          SELECT 1
          FROM public.surf_drop_participants p
          WHERE p.drop_id = d.id
            AND p.user_id = p_viewer
            AND p.left_at IS NULL
        )
        OR (
          d.audience IN ('mutuals', 'friends')
          AND public.is_mutual_follow(p_viewer, d.user_id)
        )
      )
  );
$$;


ALTER FUNCTION "public"."can_view_surf_drop"("p_drop_id" "uuid", "p_viewer" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_board_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Only capture if board_id is provided and snapshot is null
  IF NEW.board_id IS NOT NULL AND NEW.board_snapshot IS NULL THEN
    SELECT jsonb_build_object(
      'name', b.name,
      'board_type', b.board_type,
      'size', b.size,
      'volume', b.volume,
      'dimensions', b.dimensions
    ) INTO NEW.board_snapshot
    FROM boards b
    WHERE b.id = NEW.board_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."capture_board_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_database_health"() RETURNS TABLE("table_name" "text", "row_count" bigint, "table_size" "text", "last_analyzed" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        t.relname::TEXT,
        COALESCE(t.n_live_tup, 0) AS row_count,
        pg_size_pretty(pg_total_relation_size(t.schemaname||'.'||t.relname)) AS table_size,
        t.last_analyze
    FROM pg_stat_user_tables t
    WHERE t.schemaname = 'public' 
      AND t.relname IN ('enhanced_forecasts', 'buoys', 'beaches', 'spot_feedback')
    ORDER BY pg_total_relation_size(t.schemaname||'.'||t.relname) DESC;
END;
$$;


ALTER FUNCTION "public"."check_database_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_ml_drift"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_current_improvement NUMERIC;
  v_current_mae NUMERIC;
  v_previous_mae NUMERIC;
  v_mae_degradation_pct NUMERIC;
  v_current_model_version TEXT;
BEGIN
  SELECT
    pct_improved,
    avg_corrected_error_m,
    model_version
  INTO
    v_current_improvement,
    v_current_mae,
    v_current_model_version
  FROM get_ml_weekly_metrics()
  LIMIT 1;

  IF v_current_improvement IS NULL THEN
    RETURN false;
  END IF;

  IF v_current_improvement < 40 THEN
    RETURN true;
  END IF;

  SELECT
    ROUND(AVG(corrected_error_m)::numeric, 3)
  INTO v_previous_mae
  FROM ml_predictions_log
  WHERE model_version = v_current_model_version
    AND predicted_at > now() - interval '14 days'
    AND predicted_at <= now() - interval '7 days'
    AND observed_m > 0;

  IF v_previous_mae IS NOT NULL AND v_previous_mae > 0 THEN
    v_mae_degradation_pct := 100.0 * (v_current_mae - v_previous_mae) / v_previous_mae;

    IF v_mae_degradation_pct > 20 THEN
      RETURN true;
    END IF;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."check_ml_drift"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_ml_drift"() IS 'Detects ML model drift. Returns true if current week improvement <40% OR MAE degraded >20% vs previous week. Used by automated retraining pipeline.';



CREATE OR REPLACE FUNCTION "public"."check_ml_ground_truth_health"() RETURNS TABLE("metric" "text", "value" numeric, "status" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Check 1: Recent ground truth rate (last 24 hours, excluding recent 2 hours)
  RETURN QUERY
  WITH recent AS (
    SELECT
      COUNT(*) as total,
      COUNT(observed_m) as matched
    FROM ml_predictions_log
    WHERE predicted_at > NOW() - INTERVAL '24 hours'
      AND predicted_at < NOW() - INTERVAL '2 hours'
  )
  SELECT
    'ground_truth_rate_24h'::TEXT,
    ROUND(100.0 * matched / NULLIF(total, 0), 1),
    CASE
      WHEN matched * 100.0 / NULLIF(total, 0) >= 50 THEN 'ok'
      WHEN matched * 100.0 / NULLIF(total, 0) >= 20 THEN 'warning'
      ELSE 'critical'
    END,
    format('Matched %s of %s predictions', matched, total)
  FROM recent;

  -- Check 2: Backlog size (predictions waiting for ground truth)
  RETURN QUERY
  SELECT
    'backlog_size'::TEXT,
    COUNT(*)::NUMERIC,
    CASE
      WHEN COUNT(*) <= 20000 THEN 'ok'
      WHEN COUNT(*) <= 50000 THEN 'warning'
      ELSE 'critical'
    END,
    format('%s predictions waiting for ground truth', COUNT(*))
  FROM ml_predictions_log
  WHERE observed_m IS NULL
    AND predicted_at < NOW() - INTERVAL '2 hours'
    AND predicted_at > NOW() - INTERVAL '7 days';

  -- Check 3: Model improvement rate (from weekly metrics)
  RETURN QUERY
  WITH metrics AS (
    SELECT * FROM get_ml_weekly_metrics()
  )
  SELECT
    'improvement_rate_7d'::TEXT,
    pct_improved::NUMERIC,
    CASE
      WHEN pct_improved >= 55 THEN 'ok'
      WHEN pct_improved >= 45 THEN 'warning'
      ELSE 'critical'
    END,
    format('ML improved %s pct of forecasts', pct_improved)
  FROM metrics;

  -- Check 4: Observable beaches coverage
  RETURN QUERY
  SELECT
    'observable_beaches'::TEXT,
    COUNT(*)::NUMERIC,
    CASE
      WHEN COUNT(*) >= 80 THEN 'ok'
      WHEN COUNT(*) >= 50 THEN 'warning'
      ELSE 'critical'
    END,
    format('%s beaches have observation sources', COUNT(*))
  FROM observable_beaches;
END;
$$;


ALTER FUNCTION "public"."check_ml_ground_truth_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_ml_ground_truth_health"() IS 'Health checks for ML ground truth matching pipeline.
Returns metrics with status (ok/warning/critical) and human-readable messages.';



CREATE OR REPLACE FUNCTION "public"."claim_android_tester_roster_sync"("p_actor_user_id" "uuid", "p_observed_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_candidate_token uuid := gen_random_uuid();
  v_acquired_token uuid;
BEGIN
  INSERT INTO public.android_tester_roster_sync_claims (
    singleton,
    claim_token,
    claimed_at,
    claimed_by
  ) VALUES (
    true,
    v_candidate_token,
    p_observed_at,
    p_actor_user_id
  )
  ON CONFLICT (singleton) DO UPDATE SET
    claim_token = EXCLUDED.claim_token,
    claimed_at = EXCLUDED.claimed_at,
    claimed_by = EXCLUDED.claimed_by
  WHERE public.android_tester_roster_sync_claims.claimed_at
    <= p_observed_at - interval '15 minutes'
  RETURNING claim_token INTO v_acquired_token;

  RETURN v_acquired_token;
END;
$$;


