CREATE OR REPLACE FUNCTION "public"."cleanup_session_media_storage"("media_id" "uuid") RETURNS TABLE("success" boolean, "message" "text", "storage_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  media_record RECORD;
  v_is_admin BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_admin = true
  )
  INTO v_is_admin;

  SELECT sm.*, (sm.user_id = auth.uid() OR v_is_admin) AS can_delete
  INTO media_record
  FROM public.session_media sm
  WHERE sm.id = cleanup_session_media_storage.media_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Media not found'::TEXT, NULL::TEXT;
    RETURN;
  END IF;

  IF NOT media_record.can_delete THEN
    RETURN QUERY SELECT false, 'Unauthorized to delete this media'::TEXT, NULL::TEXT;
    RETURN;
  END IF;

  UPDATE public.session_media sm
  SET deleted_at = NOW()
  WHERE sm.id = media_record.id
    AND sm.deleted_at IS NULL;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Media already deleted'::TEXT, media_record.storage_path;
    RETURN;
  END IF;

  RETURN QUERY SELECT
    true,
    ('Media record soft-deleted. Storage cleanup required: ' || media_record.storage_path)::TEXT,
    media_record.storage_path;
END;
$$;


ALTER FUNCTION "public"."cleanup_session_media_storage"("media_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_session_media_storage"("media_id" "uuid") IS 'Soft deletes session media and returns storage path for cleanup. Caller must remove file from storage bucket separately.';



CREATE OR REPLACE FUNCTION "public"."cleanup_stale_enhanced_forecasts"("retention_days" integer DEFAULT 14) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    -- Delete enhanced forecasts older than retention period
    DELETE FROM public.enhanced_forecasts 
    WHERE forecast_date < CURRENT_DATE - (retention_days || ' days')::INTERVAL;
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    
    RAISE NOTICE 'Cleaned up % stale enhanced forecasts older than % days', 
        deleted_count, retention_days;
    
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_stale_enhanced_forecasts"("retention_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_photo_wilson_lower_bound"("p_upvotes" integer, "p_downvotes" integer) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  SELECT CASE
    WHEN (p_upvotes + p_downvotes) < 5 THEN 0::double precision
    ELSE (
      (
        p_upvotes::double precision / (p_upvotes + p_downvotes)
        + (1.959963984540054 * 1.959963984540054) / (2 * (p_upvotes + p_downvotes))
        - 1.959963984540054 * sqrt(
          (
            (p_upvotes::double precision / (p_upvotes + p_downvotes))
            * (1 - p_upvotes::double precision / (p_upvotes + p_downvotes))
            + (1.959963984540054 * 1.959963984540054) / (4 * (p_upvotes + p_downvotes))
          ) / (p_upvotes + p_downvotes)
        )
      )
      / (1 + (1.959963984540054 * 1.959963984540054) / (p_upvotes + p_downvotes))
    )
  END
$$;


ALTER FUNCTION "public"."community_photo_wilson_lower_bound"("p_upvotes" integer, "p_downvotes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_all_affinities_initial"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO user_beach_affinity (user_id, beach_id, session_count, last_surfed_at, affinity_score)
  SELECT
    user_id,
    beach_id,
    COUNT(*) as session_count,
    MAX(arrival_time) as last_surfed_at,
    compute_beach_affinity(user_id, beach_id) as affinity_score
  FROM sessions
  GROUP BY user_id, beach_id
  ON CONFLICT (user_id, beach_id) DO UPDATE SET
    session_count = EXCLUDED.session_count,
    last_surfed_at = EXCLUDED.last_surfed_at,
    affinity_score = EXCLUDED.affinity_score,
    computed_at = NOW();
END;
$$;


ALTER FUNCTION "public"."compute_all_affinities_initial"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_all_affinities_initial"() IS 'One-time bulk computation of beach affinities from existing session history. Idempotent - safe to run multiple times. Used by scripts/compute-initial-affinities.ts';



CREATE OR REPLACE FUNCTION "public"."compute_beach_affinity"("_user_id" "uuid", "_beach_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  session_count int;
  last_surfed timestamptz;
  days_since_last numeric;
  base_score numeric;
  recency_bonus numeric;
  frequency_bonus numeric;
  affinity numeric;
BEGIN
  -- Count sessions and get last surf date
  SELECT COUNT(*), MAX(arrival_time)
  INTO session_count, last_surfed
  FROM sessions
  WHERE user_id = _user_id AND beach_id = _beach_id;

  -- No sessions = 0 affinity
  IF session_count = 0 THEN
    RETURN 0;
  END IF;

  -- Base score: 10 points per session, capped at 50
  base_score := LEAST(session_count * 10, 50);

  -- Recency bonus: 30 points max, exponential decay over 180 days
  days_since_last := EXTRACT(DAY FROM (NOW() - last_surfed));
  recency_bonus := 30 * EXP(-days_since_last / 180.0);

  -- Frequency bonus: +20 if 5+ sessions
  frequency_bonus := CASE WHEN session_count >= 5 THEN 20 ELSE 0 END;

  -- Total affinity (capped at 100)
  affinity := base_score + recency_bonus + frequency_bonus;

  RETURN LEAST(100, affinity);
END;
$$;


ALTER FUNCTION "public"."compute_beach_affinity"("_user_id" "uuid", "_beach_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_beach_affinity"("_user_id" "uuid", "_beach_id" "uuid") IS 'Calculates beach affinity: base (10*sessions, max 50) + recency (30*exp(-days/180)) + frequency (+20 if 5+ sessions)';



CREATE OR REPLACE FUNCTION "public"."compute_implicit_preferences"("target_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  processed_count integer := 0;
BEGIN
  RAISE NOTICE 'compute_implicit_preferences: starting (target_user_id=%)', target_user_id;

  INSERT INTO public.user_implicit_preferences (
    user_id,
    inferred_wave_min_ft,
    inferred_wave_max_ft,
    break_type_weights,
    location_centroid_lat,
    location_centroid_lon,
    top_engaged_beach_ids,
    confidence,
    event_count,
    last_computed_at,
    computed_from,
    computed_to
  )
  WITH
    weighted_events AS MATERIALIZED (
      SELECT
        e.user_id,
        e.beach_id,
        e.event_type,
        e.created_at,
        e.metadata,
        COALESCE(
          ((regexp_match(e.metadata->>'wave_height_ft', '-?\d+(?:\.\d+)?'))[1])::numeric,
          ((regexp_match(e.metadata->>'forecast_wave_height_ft', '-?\d+(?:\.\d+)?'))[1])::numeric,
          ((regexp_match(e.metadata->>'wave_height', '-?\d+(?:\.\d+)?'))[1])::numeric,
          ((regexp_match(e.metadata->>'waveHeight', '-?\d+(?:\.\d+)?'))[1])::numeric,
          ((regexp_match(e.metadata->>'height_ft', '-?\d+(?:\.\d+)?'))[1])::numeric
        ) AS metadata_wave_ft,
        CASE e.event_type
          WHEN 'location_update' THEN 10.0
          WHEN 'discovery_click' THEN 3.0
          WHEN 'forecast_check' THEN 2.5
          WHEN 'beach_view' THEN 0.5
          WHEN 'discovery_skip' THEN -1.0
          ELSE 0
        END AS weight,
        GREATEST(
          0,
          1.0 - EXTRACT(EPOCH FROM (now() - e.created_at)) / (90 * 86400)
        ) AS recency_factor
      FROM public.user_events e
      JOIN public.profiles p
        ON p.id = e.user_id
       AND p.allow_implicit_tracking = true
      WHERE e.user_id IS NOT NULL
        AND e.created_at > now() - interval '90 days'
        AND e.event_type IN (
          'location_update',
          'discovery_click',
          'forecast_check',
          'beach_view',
          'discovery_skip'
        )
        AND (target_user_id IS NULL OR e.user_id = target_user_id)
    ),

    positive_weighted_events AS MATERIALIZED (
      SELECT *
      FROM weighted_events
      WHERE weight > 0
    ),

    event_wave_samples AS (
      SELECT samples.user_id, samples.wave_height_ft
      FROM (
        SELECT
          we.user_id,
          COALESCE(we.metadata_wave_ft, forecast_wave.wave_height_ft) AS wave_height_ft
        FROM positive_weighted_events we
        LEFT JOIN LATERAL (
          SELECT
            ((regexp_match(ef.wave_height::text, '-?\d+(?:\.\d+)?'))[1])::numeric AS wave_height_ft
          FROM public.enhanced_forecasts ef
          WHERE we.metadata_wave_ft IS NULL
            AND we.beach_id IS NOT NULL
            AND ef.beach_id = we.beach_id
            AND ef.forecast_at IS NOT NULL
            AND ef.forecast_at BETWEEN we.created_at - interval '6 hours'
                                  AND we.created_at + interval '6 hours'
          ORDER BY abs(EXTRACT(EPOCH FROM (ef.forecast_at - we.created_at))) ASC
          LIMIT 1
        ) forecast_wave ON true
      ) samples
      WHERE samples.wave_height_ft BETWEEN 0 AND 50
    ),

    wave_ranges AS (
      SELECT
        user_id,
        CASE
          WHEN count(*) >= 3 THEN round((percentile_cont(0.1) WITHIN GROUP (ORDER BY wave_height_ft))::numeric, 1)
          ELSE NULL::numeric
        END AS inferred_wave_min_ft,
        CASE
          WHEN count(*) >= 3 THEN round((percentile_cont(0.9) WITHIN GROUP (ORDER BY wave_height_ft))::numeric, 1)
          ELSE NULL::numeric
        END AS inferred_wave_max_ft
      FROM event_wave_samples
      GROUP BY user_id
    ),

    user_metrics AS (
      SELECT
        we.user_id,
        count(*) AS event_count,
        min(we.created_at) AS computed_from,
        max(we.created_at) AS computed_to,
        sum(abs(we.weight)) AS total_abs_weight
      FROM weighted_events we
      GROUP BY we.user_id
      HAVING count(*) >= 3
    ),

    positive_beach_metrics AS (
      SELECT
        we.user_id,
        we.beach_id,
        b.lat,
        b.lon,
        b.break_type,
        sum(we.weight * we.recency_factor) AS weighted_engagement
      FROM positive_weighted_events we
      LEFT JOIN public.beaches b ON b.id = we.beach_id
      WHERE we.beach_id IS NOT NULL
      GROUP BY we.user_id, we.beach_id, b.lat, b.lon, b.break_type
    ),

    break_type_weights AS (
      SELECT
        user_id,
        jsonb_object_agg(break_type, round(weight_pct::numeric, 2)) AS weights
      FROM (
        SELECT
          user_id,
          break_type,
          sum(weighted_engagement) /
            nullif(sum(sum(weighted_engagement)) OVER (PARTITION BY user_id), 0) AS weight_pct
        FROM positive_beach_metrics
        WHERE break_type IS NOT NULL
        GROUP BY user_id, break_type
      ) weighted_break_types
      WHERE weight_pct > 0
      GROUP BY user_id
    ),

    beach_centroids AS (
      SELECT
        user_id,
        round(
          (
            sum(lat * weighted_engagement) FILTER (WHERE lat IS NOT NULL) /
              nullif(sum(weighted_engagement) FILTER (WHERE lat IS NOT NULL), 0)
          )::numeric,
          6
        ) AS location_centroid_lat,
        round(
          (
            sum(lon * weighted_engagement) FILTER (WHERE lon IS NOT NULL) /
              nullif(sum(weighted_engagement) FILTER (WHERE lon IS NOT NULL), 0)
          )::numeric,
          6
        ) AS location_centroid_lon
      FROM positive_beach_metrics
      GROUP BY user_id
    ),

    top_beaches AS (
      SELECT user_id, array_agg(beach_id ORDER BY weighted_engagement DESC) AS top_engaged_beach_ids
      FROM (
        SELECT
          user_id,
          beach_id,
          sum(weighted_engagement) AS weighted_engagement,
          row_number() OVER (
            PARTITION BY user_id
            ORDER BY sum(weighted_engagement) DESC
          ) AS beach_rank
        FROM positive_beach_metrics
        GROUP BY user_id, beach_id
      ) ranked_beaches
      WHERE beach_rank <= 5
      GROUP BY user_id
    )

  SELECT
    um.user_id,
    wr.inferred_wave_min_ft,
    wr.inferred_wave_max_ft,
    COALESCE(btw.weights, '{}'::jsonb),
    bc.location_centroid_lat,
    bc.location_centroid_lon,
    COALESCE(tb.top_engaged_beach_ids, ARRAY[]::uuid[]),
    round(
      (1.0 / (1.0 + exp(-0.05 * (um.total_abs_weight - 20))))::numeric,
      2
    ),
    um.event_count::int,
    now(),
    um.computed_from,
    um.computed_to
  FROM user_metrics um
  LEFT JOIN wave_ranges wr ON wr.user_id = um.user_id
  LEFT JOIN break_type_weights btw ON btw.user_id = um.user_id
  LEFT JOIN beach_centroids bc ON bc.user_id = um.user_id
  LEFT JOIN top_beaches tb ON tb.user_id = um.user_id
  ON CONFLICT (user_id) DO UPDATE SET
    inferred_wave_min_ft = excluded.inferred_wave_min_ft,
    inferred_wave_max_ft = excluded.inferred_wave_max_ft,
    break_type_weights = excluded.break_type_weights,
    location_centroid_lat = excluded.location_centroid_lat,
    location_centroid_lon = excluded.location_centroid_lon,
    top_engaged_beach_ids = excluded.top_engaged_beach_ids,
    confidence = excluded.confidence,
    event_count = excluded.event_count,
    last_computed_at = now(),
    computed_from = excluded.computed_from,
    computed_to = excluded.computed_to;

  GET DIAGNOSTICS processed_count = ROW_COUNT;

  DELETE FROM public.user_implicit_preferences prefs
  WHERE (target_user_id IS NULL OR prefs.user_id = target_user_id)
    AND NOT EXISTS (
      SELECT 1
      FROM public.user_events e
      JOIN public.profiles p
        ON p.id = e.user_id
       AND p.allow_implicit_tracking = true
      WHERE e.user_id = prefs.user_id
        AND e.created_at > now() - interval '90 days'
        AND e.event_type IN (
          'location_update',
          'discovery_click',
          'forecast_check',
          'beach_view',
          'discovery_skip'
        )
      GROUP BY e.user_id
      HAVING count(*) >= 3
    );

  RAISE NOTICE 'compute_implicit_preferences: completed (processed_count=%)', processed_count;
  RETURN processed_count;
EXCEPTION
  WHEN others THEN
    RAISE NOTICE 'compute_implicit_preferences: error - % (%)', sqlerrm, sqlstate;
    RAISE;
END;
$$;


ALTER FUNCTION "public"."compute_implicit_preferences"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_implicit_preferences"("target_user_id" "uuid") IS 'Computes implicit preferences from opted-in user_events with weighted decay. Uses set-based beach aggregates and numeric centroid rounding to keep the nightly batch valid and within the database statement timeout. Pass NULL for batch processing all users, or user_id for single-user update.';



CREATE OR REPLACE FUNCTION "public"."compute_session_tide_snapshot"("p_beach_id" "uuid", "p_arrival_time" timestamp with time zone) RETURNS TABLE("tide_height_ft" numeric, "tide_status" "text", "tide_rate_ft_per_hr" numeric, "tide_data_source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH previous_point AS (
    SELECT
      tf.ts,
      COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) AS height_m,
      tf.source AS source_name
    FROM public.tide_forecasts tf
    WHERE tf.beach_id = p_beach_id
      AND tf.ts <= p_arrival_time
      AND tf.ts >= p_arrival_time - INTERVAL '4 hours'
      AND COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) IS NOT NULL
    ORDER BY tf.ts DESC
    LIMIT 1
  ),
  next_point AS (
    SELECT
      tf.ts,
      COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) AS height_m,
      tf.source AS source_name
    FROM public.tide_forecasts tf
    WHERE tf.beach_id = p_beach_id
      AND tf.ts > p_arrival_time
      AND tf.ts <= p_arrival_time + INTERVAL '4 hours'
      AND COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) IS NOT NULL
    ORDER BY tf.ts ASC
    LIMIT 1
  ),
  before_previous AS (
    SELECT
      tf.ts,
      COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) AS height_m
    FROM public.tide_forecasts tf
    CROSS JOIN previous_point pp
    WHERE tf.beach_id = p_beach_id
      AND tf.ts < pp.ts
      AND tf.ts >= p_arrival_time - INTERVAL '4 hours'
      AND COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) IS NOT NULL
    ORDER BY tf.ts DESC
    LIMIT 1
  ),
  after_next AS (
    SELECT
      tf.ts,
      COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) AS height_m
    FROM public.tide_forecasts tf
    CROSS JOIN next_point np
    WHERE tf.beach_id = p_beach_id
      AND tf.ts > np.ts
      AND tf.ts <= p_arrival_time + INTERVAL '4 hours'
      AND COALESCE(tf.tide_height_m, tf.tide_ft / 3.28084) IS NOT NULL
    ORDER BY tf.ts ASC
    LIMIT 1
  ),
  calculated AS (
    SELECT
      pp.ts AS previous_ts,
      np.ts AS next_ts,
      pp.height_m AS previous_height_m,
      np.height_m AS next_height_m,
      bp.ts AS before_ts,
      an.ts AS after_ts,
      bp.height_m AS before_height_m,
      an.height_m AS after_height_m,
      pp.source_name AS previous_source,
      np.source_name AS next_source,
      EXTRACT(EPOCH FROM (np.ts - pp.ts)) / 3600.0 AS span_hours,
      EXTRACT(EPOCH FROM (np.ts - bp.ts)) / 3600.0 AS central_span_hours,
      p_arrival_time = pp.ts AS exact_on_previous,
      GREATEST(
        0,
        LEAST(
          1,
          EXTRACT(EPOCH FROM (p_arrival_time - pp.ts))
            / NULLIF(EXTRACT(EPOCH FROM (np.ts - pp.ts)), 0)
        )
      ) AS interpolation_fraction
    FROM previous_point pp
    JOIN next_point np ON true
    LEFT JOIN before_previous bp ON true
    LEFT JOIN after_next an ON true
  ),
  derived AS (
    SELECT
      (
        previous_height_m
        + (next_height_m - previous_height_m)
          * ((1 - COS(PI() * interpolation_fraction)) / 2)
      ) * 3.28084 AS height_ft,
      CASE
        WHEN exact_on_previous
          AND before_height_m IS NOT NULL
          AND central_span_hours > 0
        THEN ((next_height_m - before_height_m) * 3.28084) / central_span_hours
        ELSE ((next_height_m - previous_height_m) * 3.28084) / span_hours
      END AS rate_ft_per_hr,
      (previous_height_m - COALESCE(before_height_m, previous_height_m)) AS slope_before,
      (next_height_m - previous_height_m) AS slope_between,
      (COALESCE(after_height_m, next_height_m) - next_height_m) AS slope_after,
      exact_on_previous,
      previous_source,
      next_source
    FROM calculated
    WHERE span_hours > 0
  )
  SELECT
    ROUND(height_ft::numeric, 2) AS tide_height_ft,
    CASE
      WHEN exact_on_previous AND slope_before > 0 AND slope_between < 0 THEN 'high'
      WHEN exact_on_previous AND slope_before < 0 AND slope_between > 0 THEN 'low'
      WHEN slope_before > 0 AND slope_after < 0 THEN 'high'
      WHEN slope_before < 0 AND slope_after > 0 THEN 'low'
      WHEN rate_ft_per_hr >= 0 THEN 'rising'
      ELSE 'falling'
    END AS tide_status,
    ROUND(rate_ft_per_hr::numeric, 2) AS tide_rate_ft_per_hr,
    CASE
      WHEN previous_source IN ('noaa', 'noaa_hilo_interpolated')
        OR next_source IN ('noaa', 'noaa_hilo_interpolated') THEN 'noaa'
      WHEN previous_source = 'open-meteo'
        OR next_source = 'open-meteo' THEN 'open-meteo'
      ELSE 'noaa'
    END AS tide_data_source
  FROM derived;
$$;


ALTER FUNCTION "public"."compute_session_tide_snapshot"("p_beach_id" "uuid", "p_arrival_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_user_match_score"("p_user_id" "uuid", "p_beach_id" "uuid", "p_wave_height" "text", "p_wave_period" "text", "p_wind_speed" "text", "p_wind_direction" "text", "p_tide_height" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text := COALESCE(auth.role(), 'anon');
  v_caller uuid := auth.uid();
  v_is_paid boolean := false;
  v_billing_issue boolean := false;
  v_expires_at timestamptz;
BEGIN
  IF v_role <> 'service_role' THEN
    IF v_caller IS NULL OR p_user_id <> v_caller THEN
      RETURN jsonb_build_object(
        'state', 'locked',
        'score', NULL,
        'fit_label', 'Personal match unlocks with your account',
        'reason_bullets', jsonb_build_array('Sign in with the matching account to use personal match.'),
        'session_count', 0,
        'sessions_needed', 5,
        'quality_band', 'locked',
        'lock_reason', 'forbidden'
      );
    END IF;

    SELECT
      COALESCE(ue.is_pro, false) OR COALESCE(ue.is_trialing, false),
      COALESCE(ue.billing_issue, false),
      ue.expires_at
    INTO v_is_paid, v_billing_issue, v_expires_at
    FROM public.user_entitlements ue
    WHERE ue.user_id = p_user_id
    LIMIT 1;

    IF v_billing_issue THEN
      RETURN jsonb_build_object(
        'state', 'locked',
        'score', NULL,
        'fit_label', 'Update payment to use personal match',
        'reason_bullets', jsonb_build_array('Your forecast is still here. Update your payment method to turn personal match back on.'),
        'session_count', 0,
        'sessions_needed', 5,
        'quality_band', 'locked',
        'lock_reason', 'billing_issue'
      );
    END IF;

    IF NOT COALESCE(v_is_paid, false) OR (v_expires_at IS NOT NULL AND v_expires_at < now()) THEN
      RETURN jsonb_build_object(
        'state', 'locked',
        'score', NULL,
        'fit_label', 'Personal match unlocks with Pro',
        'reason_bullets', jsonb_build_array('Forecasts stay free. Pro adds your fit, reasons, ranked windows, and personal alerts.'),
        'session_count', 0,
        'sessions_needed', 5,
        'quality_band', 'locked',
        'lock_reason', 'free'
      );
    END IF;
  END IF;

  RETURN public.compute_user_match_score_core(
    p_user_id,
    p_beach_id,
    p_wave_height,
    p_wave_period,
    p_wind_speed,
    p_wind_direction,
    p_tide_height
  );
END;
$$;


ALTER FUNCTION "public"."compute_user_match_score"("p_user_id" "uuid", "p_beach_id" "uuid", "p_wave_height" "text", "p_wave_period" "text", "p_wind_speed" "text", "p_wind_direction" "text", "p_tide_height" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_user_match_score_batch"("p_user_id" "uuid", "p_beach_id" "uuid", "p_slots" "jsonb") RETURNS TABLE("slot_idx" integer, "forecast_at" timestamp with time zone, "result" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$ DECLARE v_slot jsonb; v_idx int := 0; BEGIN IF p_slots IS NULL OR jsonb_typeof(p_slots) <> 'array' THEN RAISE EXCEPTION 'compute_user_match_score_batch: p_slots must be a jsonb array (got: %)', coalesce(jsonb_typeof(p_slots), '<null>'); END IF; FOR v_slot IN SELECT * FROM jsonb_array_elements(p_slots) LOOP slot_idx := v_idx; forecast_at := (v_slot->>'forecast_at')::timestamptz; result := public.compute_user_match_score(p_user_id, p_beach_id, v_slot->>'wave_height', v_slot->>'wave_period', v_slot->>'wind_speed', v_slot->>'wind_direction', v_slot->>'tide_height'); RETURN NEXT; v_idx := v_idx + 1; END LOOP; END; $$;


ALTER FUNCTION "public"."compute_user_match_score_batch"("p_user_id" "uuid", "p_beach_id" "uuid", "p_slots" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_user_match_score_batch"("p_user_id" "uuid", "p_beach_id" "uuid", "p_slots" "jsonb") IS 'Batched form of compute_user_match_score. Takes p_slots as a jsonb array of {forecast_at, wave_height, wave_period, wind_speed, wind_direction, tide_height} and returns one row per slot with (slot_idx, forecast_at, result). The result jsonb is the verbatim output of compute_user_match_score for that slot — preserving every possible shape (state=onboarding, state=ready, neutral fallback). Saves N-1 round-trips when scoring a forecast horizon. Declared VOLATILE to match the inner function''s default volatility — do not re-mark STABLE without first making compute_user_match_score STABLE-safe (its reads of sessions / session_forecast_snapshots / boards may not qualify under your data model).';



CREATE OR REPLACE FUNCTION "public"."compute_user_match_score_core"("p_user_id" "uuid", "p_beach_id" "uuid", "p_wave_height" "text", "p_wave_period" "text", "p_wind_speed" "text", "p_wind_direction" "text", "p_tide_height" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_session_count integer;
  v_forecast_wave numeric;
  v_forecast_period numeric;
  v_forecast_wind numeric;
  v_forecast_wind_dir numeric;
  v_forecast_tide numeric;

  v_pref_wave numeric;
  v_pref_period numeric;
  v_pref_wind numeric;
  v_pref_wind_dir numeric;
  v_pref_tide numeric;
  v_pref_count integer;

  v_av_wave numeric;
  v_av_period numeric;
  v_av_wind numeric;
  v_av_wind_dir numeric;
  v_av_tide numeric;
  v_av_count integer;

  v_wave_distance numeric;
  v_period_distance numeric;
  v_wind_distance numeric;
  v_wind_dir_distance numeric;
  v_tide_distance numeric;

  v_av_wave_distance numeric;
  v_av_period_distance numeric;
  v_av_wind_distance numeric;
  v_av_wind_dir_distance numeric;
  v_av_tide_distance numeric;

  v_base_distance numeric;
  v_base_score numeric;
  v_aversion_distance numeric;
  v_aversion_proximity numeric;
  v_aversion_penalty numeric;
  v_session_fit_adjustment numeric := 0;
  v_fit_signal_score numeric;
  v_fit_signal_sample_count integer := 0;
  v_fit_positive_count integer := 0;
  v_fit_negative_count integer := 0;
  v_cap_ceiling numeric;
  v_cap_sample integer := 0;
  v_skill_fit_net numeric;
  v_profile_skill text;
  v_resolved_skill text := 'intermediate';
  v_skill_source text := 'default';
  v_board_class text;
  v_skill_ideal_min numeric;
  v_skill_ideal_max numeric;
  v_skill_acceptable_min numeric;
  v_skill_acceptable_max numeric;
  v_board_shape_lo numeric;
  v_board_shape_hi numeric;
  v_board_ideal_min numeric;
  v_board_ideal_max numeric;
  v_board_acceptable_min numeric;
  v_board_acceptable_max numeric;
  v_board_band_adjustment numeric := 0;
  v_spot_swell_min_deg numeric;
  v_spot_swell_max_deg numeric;
  v_spot_wind_offshore_deg numeric;
  v_spot_wind_offshore_tol_deg numeric;
  v_spot_tide_min_ft numeric;
  v_spot_tide_max_ft numeric;
  v_prior_wave numeric;
  v_prior_wind_dir numeric;
  v_prior_tide numeric;
  v_prior_wave_distance numeric;
  v_prior_wind_dir_distance numeric;
  v_prior_tide_distance numeric;
  v_prior_weighted_distance numeric := 0;
  v_prior_weight_total numeric := 0;
  v_prior_score numeric;
  v_prior_dimensions jsonb := jsonb_build_array('skill_wave');
  v_prior_has_spot_profile boolean := false;
  v_blend_weight numeric;
  v_prior_fit_label text;
  v_prior_body text;
  v_score numeric;
  v_label text;
  v_confidence text;
  v_reason_bullets jsonb;
  v_board_tip text;
  v_beach_break_type text;

  c_aversion_scaling constant numeric := 3.0;
  c_fit_signal_scaling constant numeric := 1.0;
  c_capability_min_samples constant integer := 5;
  c_skill_fit_ceiling_weight constant numeric := 0.15;
BEGIN
  -- Gate: need >=5 sessions with rating + snapshot in the last 12 months.
  SELECT COUNT(*)::integer INTO v_session_count
  FROM public.sessions s
  JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
  WHERE s.user_id = p_user_id
    AND s.status = 'completed'
    AND s.rating IS NOT NULL
    AND s.arrival_time > now() - interval '12 months'
    AND s.deleted_at IS NULL
    AND sfs.forecast_snapshot IS NOT NULL;

  IF v_session_count < 5 THEN
    -- Starter prior: real forecast-sensitive score before the learned profile is ready.
    v_forecast_wave     := public.parse_numeric_from_text(p_wave_height);
    v_forecast_period   := public.parse_numeric_from_text(p_wave_period);
    v_forecast_wind     := public.parse_numeric_from_text(p_wind_speed);
    v_forecast_wind_dir := public.parse_numeric_from_text(p_wind_direction);
    v_forecast_tide     := public.parse_numeric_from_text(p_tide_height);

    SELECT
      b.break_type,
      b.swell_window_min_deg,
      b.swell_window_max_deg,
      b.wind_offshore_deg,
      b.wind_offshore_tol_deg,
      b.preferred_tide_ft_min,
      b.preferred_tide_ft_max
    INTO
      v_beach_break_type,
      v_spot_swell_min_deg,
      v_spot_swell_max_deg,
      v_spot_wind_offshore_deg,
      v_spot_wind_offshore_tol_deg,
      v_spot_tide_min_ft,
      v_spot_tide_max_ft
    FROM public.beaches b
    WHERE b.id = p_beach_id;

    SELECT lower(trim(p.experience_level))
    INTO v_profile_skill
    FROM public.profiles p
    WHERE p.id = p_user_id;

    v_profile_skill := NULLIF(v_profile_skill, '');

    WITH board_usage AS (
      SELECT
        COALESCE(s.board_id::text, s.board_snapshot->>'name', s.board_snapshot->>'board_type') AS board_key,
        COALESCE(s.board_snapshot->>'board_type', b.board_type) AS board_type,
        COALESCE(s.board_snapshot->>'name', b.name) AS name,
        COUNT(*)::integer AS use_count,
        MAX(s.arrival_time) AS last_used_at
      FROM public.sessions s
      LEFT JOIN public.boards b ON b.id = s.board_id
      JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
      WHERE s.user_id = p_user_id
        AND s.rating >= 4
        AND s.status = 'completed'
        AND s.arrival_time > now() - interval '12 months'
        AND s.deleted_at IS NULL
        AND sfs.forecast_snapshot IS NOT NULL
      GROUP BY
        COALESCE(s.board_id::text, s.board_snapshot->>'name', s.board_snapshot->>'board_type'),
        COALESCE(s.board_snapshot->>'board_type', b.board_type),
        COALESCE(s.board_snapshot->>'name', b.name)
    ),
    board_keys AS (
      SELECT
        board_key,
        use_count,
        last_used_at,
        0 AS source_priority,
        regexp_replace(
          regexp_replace(
            regexp_replace(lower(trim(COALESCE(board_type, ''))), '[[:space:]_]+', '-', 'g'),
            '-+',
            '-',
            'g'
          ),
          '(^-+|-+$)',
          '',
          'g'
        ) AS key
      FROM board_usage
      WHERE board_type IS NOT NULL AND trim(board_type) <> ''

      UNION ALL

      SELECT
        board_key,
        use_count,
        last_used_at,
        1 AS source_priority,
        regexp_replace(
          regexp_replace(
            regexp_replace(lower(trim(COALESCE(name, ''))), '[[:space:]_]+', '-', 'g'),
            '-+',
            '-',
            'g'
          ),
          '(^-+|-+$)',
          '',
          'g'
        ) AS key
      FROM board_usage
      WHERE name IS NOT NULL AND trim(name) <> ''
    ),
    board_classes AS (
      SELECT
        board_key,
        use_count,
        last_used_at,
        source_priority,
        CASE
          WHEN key IN ('foamie', 'foam', 'foamboard', 'foam-board', 'soft', 'softboard', 'soft-board', 'softtop', 'soft-top', 'softtopboard', 'soft-top-board')
            OR replace(key, '-', '') IN ('foamie', 'foam', 'foamboard', 'soft', 'softboard', 'softtop', 'softtopboard')
          THEN 'foamie'
          WHEN key IN ('longboard', 'long-board', 'log', 'longboard-single-fin', 'longboard-2-plus-1')
            OR replace(key, '-', '') IN ('longboard', 'longboard21')
          THEN 'longboard'
          WHEN key IN ('midlength', 'mid-length', 'mini-mid', 'egg')
            OR replace(key, '-', '') = 'midlength'
          THEN 'mid-length'
          WHEN key IN ('funboard', 'fun-board', 'mini', 'minimal', 'mini-mal', 'mini-simmons')
            OR replace(key, '-', '') IN ('funboard', 'minisimmons')
          THEN 'funboard'
          WHEN key IN ('fish', 'twin', 'twin-pin', 'groveler')
            OR replace(key, '-', '') = 'twinpin'
          THEN 'fish'
          WHEN key IN ('shortboard', 'short-board')
            OR replace(key, '-', '') = 'shortboard'
          THEN 'shortboard'
          WHEN key IN ('step-up', 'stepup')
            OR replace(key, '-', '') = 'stepup'
          THEN 'step-up'
          WHEN key = 'gun' THEN 'gun'
          WHEN key IN ('sup', 'standuppaddle', 'standuppaddleboard', 'stand-up-paddle', 'stand-up-paddleboard', 'paddleboard', 'paddle-board')
            OR replace(key, '-', '') IN ('sup', 'standuppaddle', 'standuppaddleboard', 'paddleboard')
          THEN 'sup'
          WHEN key = 'foil' THEN 'foil'
          WHEN key IN ('bodyboard', 'body-board', 'boogie', 'boogieboard', 'boogie-board')
            OR replace(key, '-', '') IN ('bodyboard', 'boogieboard')
          THEN 'bodyboard'
          ELSE NULL
        END AS board_class
      FROM board_keys
      WHERE key <> ''
    )
    SELECT board_class
    INTO v_board_class
    FROM board_classes
    WHERE board_class IS NOT NULL
    ORDER BY use_count DESC, last_used_at DESC NULLS LAST, source_priority ASC, board_key
    LIMIT 1;

    IF v_profile_skill IN ('beginner', 'intermediate', 'advanced', 'expert') THEN
      v_resolved_skill := v_profile_skill;
      v_skill_source := 'profile';
    ELSIF v_board_class IS NOT NULL THEN
      v_resolved_skill := CASE v_board_class
        WHEN 'foamie' THEN 'beginner'
        WHEN 'longboard' THEN 'beginner'
        WHEN 'sup' THEN 'beginner'
        WHEN 'foil' THEN 'beginner'
        WHEN 'funboard' THEN 'intermediate'
        WHEN 'fish' THEN 'intermediate'
        WHEN 'mid-length' THEN 'intermediate'
        WHEN 'bodyboard' THEN 'intermediate'
        WHEN 'shortboard' THEN 'intermediate'
        WHEN 'step-up' THEN 'advanced'
        WHEN 'gun' THEN 'advanced'
        ELSE 'intermediate'
      END;
      v_skill_source := 'board_prior';
    ELSE
      v_resolved_skill := 'intermediate';
      v_skill_source := 'default';
    END IF;

    v_prior_wave := CASE v_resolved_skill
      WHEN 'beginner' THEN 2.0
      WHEN 'intermediate' THEN 3.5
      WHEN 'advanced' THEN 5.5
      WHEN 'expert' THEN 8.0
      ELSE 3.5
    END;

    v_prior_wind_dir := v_spot_wind_offshore_deg;
    IF v_spot_tide_min_ft IS NOT NULL AND v_spot_tide_max_ft IS NOT NULL THEN
      v_prior_tide := (v_spot_tide_min_ft + v_spot_tide_max_ft) / 2.0;
    END IF;

    -- If a few positive sessions exist, shrink the prior toward the early learned peak.
    SELECT
      SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_height') * (s.rating - 3))
        / NULLIF(SUM(s.rating - 3), 0),
      SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_period') * (s.rating - 3))
        / NULLIF(SUM(s.rating - 3), 0),
      SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_speed') * (s.rating - 3))
        / NULLIF(SUM(s.rating - 3), 0),
      SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_direction_deg') * (s.rating - 3))
        / NULLIF(SUM(s.rating - 3), 0),
      SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'tide_height') * (s.rating - 3))
        / NULLIF(SUM(s.rating - 3), 0),
      COUNT(*)::integer
    INTO
      v_pref_wave, v_pref_period, v_pref_wind, v_pref_wind_dir, v_pref_tide, v_pref_count
    FROM public.sessions s
    JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
    LEFT JOIN public.beaches b ON b.id = s.beach_id
    WHERE s.user_id = p_user_id
      AND s.status = 'completed'
      AND s.rating >= 4
      AND s.arrival_time > now() - interval '12 months'
      AND s.deleted_at IS NULL
      AND sfs.forecast_snapshot IS NOT NULL
      AND (v_beach_break_type IS NULL OR b.break_type = v_beach_break_type OR b.break_type IS NULL);

    IF COALESCE(v_pref_count, 0) > 0 THEN
      v_blend_weight := v_session_count::numeric / (v_session_count::numeric + 5.0);

      IF v_pref_wave IS NOT NULL THEN
        v_prior_wave := v_blend_weight * v_pref_wave + (1.0 - v_blend_weight) * v_prior_wave;
      END IF;

      IF v_pref_wind_dir IS NOT NULL AND v_prior_wind_dir IS NOT NULL THEN
        IF ABS(v_pref_wind_dir - v_prior_wind_dir) > 180 THEN
          IF v_pref_wind_dir > v_prior_wind_dir THEN
            v_prior_wind_dir := v_prior_wind_dir + 360;
          ELSE
            v_pref_wind_dir := v_pref_wind_dir + 360;
          END IF;
        END IF;
        v_prior_wind_dir := mod(v_blend_weight * v_pref_wind_dir + (1.0 - v_blend_weight) * v_prior_wind_dir, 360);
      END IF;

      IF v_pref_tide IS NOT NULL AND v_prior_tide IS NOT NULL THEN
        v_prior_tide := v_blend_weight * v_pref_tide + (1.0 - v_blend_weight) * v_prior_tide;
      END IF;
    END IF;

    v_prior_wave_distance := LEAST(ABS(v_prior_wave - COALESCE(v_forecast_wave, v_prior_wave)) / GREATEST(v_prior_wave, 1), 1);
    v_prior_weighted_distance := v_prior_weighted_distance + 0.35 * v_prior_wave_distance;
    v_prior_weight_total := v_prior_weight_total + 0.35;

    IF v_prior_wind_dir IS NOT NULL AND v_forecast_wind_dir IS NOT NULL THEN
      v_prior_wind_dir_distance := LEAST(
        LEAST(ABS(v_prior_wind_dir - v_forecast_wind_dir), 360 - ABS(v_prior_wind_dir - v_forecast_wind_dir)) / 180,
        1
      );
      v_prior_weighted_distance := v_prior_weighted_distance + 0.10 * v_prior_wind_dir_distance;
      v_prior_weight_total := v_prior_weight_total + 0.10;
      v_prior_dimensions := v_prior_dimensions || jsonb_build_array('spot_wind_direction');
      v_prior_has_spot_profile := true;
    END IF;

    IF v_prior_tide IS NOT NULL AND v_forecast_tide IS NOT NULL THEN
      v_prior_tide_distance := LEAST(ABS(v_prior_tide - v_forecast_tide) / 3, 1);
      v_prior_weighted_distance := v_prior_weighted_distance + 0.10 * v_prior_tide_distance;
      v_prior_weight_total := v_prior_weight_total + 0.10;
      v_prior_dimensions := v_prior_dimensions || jsonb_build_array('spot_tide');
      v_prior_has_spot_profile := true;
    END IF;

    v_prior_score := GREATEST(
      0,
      LEAST(10, (1.0 - LEAST(v_prior_weighted_distance / NULLIF(v_prior_weight_total, 0), 1.0)) * 10.0)
    );
    v_prior_fit_label := CASE
      WHEN v_prior_has_spot_profile THEN 'Based on your skill + this spot'
      ELSE 'Based on your skill level'
    END;
    v_prior_body := 'A starter read from your skill'
      || CASE WHEN v_prior_has_spot_profile THEN ' and this spot''s setup' ELSE '' END
      || '. It gets more personal as you rate sessions.';

    RETURN jsonb_build_object(
      'state', 'starter',
      'score', round(v_prior_score::numeric, 1),
      'session_count', v_session_count,
      'sessions_needed', 5 - v_session_count,
      'fit_label', v_prior_fit_label,
      'body', v_prior_body,
      'quality_band', 'starter',
      'prior_dimensions', v_prior_dimensions,
      'skill_used', v_resolved_skill,
      'skill_source', v_skill_source,
      'board_class', v_board_class
    );
  END IF;

  -- Parse forecast inputs.
  v_forecast_wave     := public.parse_numeric_from_text(p_wave_height);
  v_forecast_period   := public.parse_numeric_from_text(p_wave_period);
  v_forecast_wind     := public.parse_numeric_from_text(p_wind_speed);
  v_forecast_wind_dir := public.parse_numeric_from_text(p_wind_direction);
  v_forecast_tide     := public.parse_numeric_from_text(p_tide_height);

  SELECT break_type INTO v_beach_break_type FROM public.beaches WHERE id = p_beach_id;

  SELECT lower(trim(p.experience_level))
  INTO v_profile_skill
  FROM public.profiles p
  WHERE p.id = p_user_id;

  v_profile_skill := NULLIF(v_profile_skill, '');

  WITH board_usage AS (
    SELECT
      COALESCE(s.board_id::text, s.board_snapshot->>'name', s.board_snapshot->>'board_type') AS board_key,
      COALESCE(s.board_snapshot->>'board_type', b.board_type) AS board_type,
      COALESCE(s.board_snapshot->>'name', b.name) AS name,
      COUNT(*)::integer AS use_count,
      MAX(s.arrival_time) AS last_used_at
    FROM public.sessions s
    LEFT JOIN public.boards b ON b.id = s.board_id
    JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
    WHERE s.user_id = p_user_id
      AND s.rating >= 4
      AND s.status = 'completed'
      AND s.arrival_time > now() - interval '12 months'
      AND s.deleted_at IS NULL
      AND sfs.forecast_snapshot IS NOT NULL
    GROUP BY
      COALESCE(s.board_id::text, s.board_snapshot->>'name', s.board_snapshot->>'board_type'),
      COALESCE(s.board_snapshot->>'board_type', b.board_type),
      COALESCE(s.board_snapshot->>'name', b.name)
  ),
  board_keys AS (
    SELECT
      board_key,
      use_count,
      last_used_at,
      0 AS source_priority,
      regexp_replace(
        regexp_replace(
          regexp_replace(lower(trim(COALESCE(board_type, ''))), '[[:space:]_]+', '-', 'g'),
          '-+',
          '-',
          'g'
        ),
        '(^-+|-+$)',
        '',
        'g'
      ) AS key
    FROM board_usage
    WHERE board_type IS NOT NULL AND trim(board_type) <> ''

    UNION ALL

    SELECT
      board_key,
      use_count,
      last_used_at,
      1 AS source_priority,
      regexp_replace(
        regexp_replace(
          regexp_replace(lower(trim(COALESCE(name, ''))), '[[:space:]_]+', '-', 'g'),
          '-+',
          '-',
          'g'
        ),
        '(^-+|-+$)',
        '',
        'g'
      ) AS key
    FROM board_usage
    WHERE name IS NOT NULL AND trim(name) <> ''
  ),
  board_classes AS (
    SELECT
      board_key,
      use_count,
      last_used_at,
      source_priority,
      CASE
        WHEN key IN ('foamie', 'foam', 'foamboard', 'foam-board', 'soft', 'softboard', 'soft-board', 'softtop', 'soft-top', 'softtopboard', 'soft-top-board')
          OR replace(key, '-', '') IN ('foamie', 'foam', 'foamboard', 'soft', 'softboard', 'softtop', 'softtopboard')
        THEN 'foamie'
        WHEN key IN ('longboard', 'long-board', 'log', 'longboard-single-fin', 'longboard-2-plus-1')
          OR replace(key, '-', '') IN ('longboard', 'longboard21')
        THEN 'longboard'
        WHEN key IN ('midlength', 'mid-length', 'mini-mid', 'egg')
          OR replace(key, '-', '') = 'midlength'
        THEN 'mid-length'
        WHEN key IN ('funboard', 'fun-board', 'mini', 'minimal', 'mini-mal', 'mini-simmons')
          OR replace(key, '-', '') IN ('funboard', 'minisimmons')
        THEN 'funboard'
        WHEN key IN ('fish', 'twin', 'twin-pin', 'groveler')
          OR replace(key, '-', '') = 'twinpin'
        THEN 'fish'
        WHEN key IN ('shortboard', 'short-board')
          OR replace(key, '-', '') = 'shortboard'
        THEN 'shortboard'
        WHEN key IN ('step-up', 'stepup')
          OR replace(key, '-', '') = 'stepup'
        THEN 'step-up'
        WHEN key = 'gun' THEN 'gun'
        WHEN key IN ('sup', 'standuppaddle', 'standuppaddleboard', 'stand-up-paddle', 'stand-up-paddleboard', 'paddleboard', 'paddle-board')
          OR replace(key, '-', '') IN ('sup', 'standuppaddle', 'standuppaddleboard', 'paddleboard')
        THEN 'sup'
        WHEN key = 'foil' THEN 'foil'
        WHEN key IN ('bodyboard', 'body-board', 'boogie', 'boogieboard', 'boogie-board')
          OR replace(key, '-', '') IN ('bodyboard', 'boogieboard')
        THEN 'bodyboard'
        ELSE NULL
      END AS board_class
    FROM board_keys
    WHERE key <> ''
  )
  SELECT board_class
  INTO v_board_class
  FROM board_classes
  WHERE board_class IS NOT NULL
  ORDER BY use_count DESC, last_used_at DESC NULLS LAST, source_priority ASC, board_key
  LIMIT 1;

  -- Capability ceiling: the size this user demonstrably rides well.
  -- Deliberately distinct from the weighted-mean preference peak below.
  SELECT
    percentile_cont(0.85) WITHIN GROUP (
      ORDER BY public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_height')
    )::numeric,
    COUNT(*)::integer,
    AVG(
      CASE s.session_skill_fit
        WHEN 'dialed' THEN 1.0
        WHEN 'under' THEN -0.5
        WHEN 'over_my_head' THEN -1.0
        ELSE 0
      END
    )
  INTO v_cap_ceiling, v_cap_sample, v_skill_fit_net
  FROM public.sessions s
  JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
  WHERE s.user_id = p_user_id
    AND s.status = 'completed'
    AND s.rating >= 4
    AND s.arrival_time > now() - interval '12 months'
    AND s.deleted_at IS NULL
    AND sfs.forecast_snapshot IS NOT NULL
    AND public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_height') IS NOT NULL;

  IF v_cap_ceiling IS NOT NULL THEN
    v_cap_ceiling := GREATEST(
      0.5,
      v_cap_ceiling * (1.0 + c_skill_fit_ceiling_weight * COALESCE(v_skill_fit_net, 0))
    );
  END IF;

  IF v_cap_sample >= c_capability_min_samples AND v_cap_ceiling IS NOT NULL THEN
    v_resolved_skill := CASE
      WHEN v_cap_ceiling <= 3 THEN 'beginner'
      WHEN v_cap_ceiling <= 5 THEN 'intermediate'
      WHEN v_cap_ceiling <= 8 THEN 'advanced'
      ELSE 'expert'
    END;
    v_skill_source := 'session_derived';
  ELSIF v_profile_skill IN ('beginner', 'intermediate', 'advanced', 'expert') THEN
    v_resolved_skill := v_profile_skill;
    v_skill_source := 'profile';
  ELSIF v_board_class IS NOT NULL THEN
    v_resolved_skill := CASE v_board_class
      WHEN 'foamie' THEN 'beginner'
      WHEN 'longboard' THEN 'beginner'
      WHEN 'sup' THEN 'beginner'
      WHEN 'foil' THEN 'beginner'
      WHEN 'funboard' THEN 'intermediate'
      WHEN 'fish' THEN 'intermediate'
      WHEN 'mid-length' THEN 'intermediate'
      WHEN 'bodyboard' THEN 'intermediate'
      WHEN 'shortboard' THEN 'intermediate'
      WHEN 'step-up' THEN 'advanced'
      WHEN 'gun' THEN 'advanced'
      ELSE 'intermediate'
    END;
    v_skill_source := 'board_prior';
  ELSE
    v_resolved_skill := 'intermediate';
    v_skill_source := 'default';
  END IF;

  -- Preference peak: weighted mean of conditions over sessions with rating >= 4.
  -- Weight = rating - 3 (1 for r=4, 2 for r=5). No contribution from r=3 or r<=2.
  SELECT
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_height') * (s.rating - 3))
      / NULLIF(SUM(s.rating - 3), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_period') * (s.rating - 3))
      / NULLIF(SUM(s.rating - 3), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_speed') * (s.rating - 3))
      / NULLIF(SUM(s.rating - 3), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_direction_deg') * (s.rating - 3))
      / NULLIF(SUM(s.rating - 3), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'tide_height') * (s.rating - 3))
      / NULLIF(SUM(s.rating - 3), 0),
    COUNT(*)::integer
  INTO
    v_pref_wave, v_pref_period, v_pref_wind, v_pref_wind_dir, v_pref_tide, v_pref_count
  FROM public.sessions s
  JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
  LEFT JOIN public.beaches b ON b.id = s.beach_id
  WHERE s.user_id = p_user_id
    AND s.status = 'completed'
    AND s.rating >= 4
    AND s.arrival_time > now() - interval '12 months'
    AND s.deleted_at IS NULL
    AND sfs.forecast_snapshot IS NOT NULL
    AND (v_beach_break_type IS NULL OR b.break_type = v_beach_break_type OR b.break_type IS NULL);

  -- Aversion peak: weighted mean of conditions over sessions with rating <= 2.
  -- Weight = 3 - rating (1 for r=2, 2 for r=1). No contribution from r=3 or r>=4.
  SELECT
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_height') * (3 - s.rating))
      / NULLIF(SUM(3 - s.rating), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_period') * (3 - s.rating))
      / NULLIF(SUM(3 - s.rating), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_speed') * (3 - s.rating))
      / NULLIF(SUM(3 - s.rating), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_direction_deg') * (3 - s.rating))
      / NULLIF(SUM(3 - s.rating), 0),
    SUM(public.parse_numeric_from_text(sfs.forecast_snapshot->>'tide_height') * (3 - s.rating))
      / NULLIF(SUM(3 - s.rating), 0),
    COUNT(*)::integer
  INTO
    v_av_wave, v_av_period, v_av_wind, v_av_wind_dir, v_av_tide, v_av_count
  FROM public.sessions s
  JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
  LEFT JOIN public.beaches b ON b.id = s.beach_id
  WHERE s.user_id = p_user_id
    AND s.status = 'completed'
    AND s.rating <= 2
    AND s.arrival_time > now() - interval '12 months'
    AND s.deleted_at IS NULL
    AND sfs.forecast_snapshot IS NOT NULL
    AND (v_beach_break_type IS NULL OR b.break_type = v_beach_break_type OR b.break_type IS NULL);

  -- Degenerate: all-negative profile (no rating >= 4 samples). Cannot anchor a preference.
  IF v_pref_count IS NULL OR v_pref_count = 0 THEN
    IF v_av_count IS NULL OR v_av_count = 0 THEN
      -- Also no aversion samples -> all rating = 3 sessions. Return honest avoidance-style learned state.
      RETURN jsonb_build_object(
        'state', 'avoidance_learned',
        'score', NULL,
        'fit_label', 'Need a few more ratings',
        'reason_bullets', jsonb_build_array(
          'We know what you tend to avoid. Rate a few good sessions to sharpen your match.'
        ),
        'board_tip', NULL,
        'sessions_in_profile', v_session_count,
        'profile_kind', 'neutral',
        'quality_band', 'mixed_signal'
      );
    END IF;

    -- Aversion only — we know what the user hates but not what they love. Can't score.
    RETURN jsonb_build_object(
      'state', 'avoidance_learned',
      'session_count', v_session_count,
      'sessions_needed', 0,
      'fit_label', 'Need a few more ratings',
      'reason_bullets', jsonb_build_array('We know what you tend to avoid. Rate a few good sessions to sharpen your match.'),
      'score', NULL,
      'quality_band', 'mixed_signal',
      'reason', 'no_positive_sessions'
    );
  END IF;

  -- Base distance (forecast vs preference peak).
  v_wave_distance     := LEAST(ABS(v_pref_wave - v_forecast_wave) / GREATEST(v_pref_wave, 1), 1);
  v_period_distance   := LEAST(ABS(v_pref_period - v_forecast_period) / GREATEST(v_pref_period, 1), 1);
  v_wind_distance     := LEAST(ABS(v_pref_wind - v_forecast_wind) / GREATEST(v_pref_wind, 5), 1);
  v_tide_distance     := LEAST(ABS(v_pref_tide - v_forecast_tide) / 3, 1);
  v_wind_dir_distance := LEAST(
    LEAST(ABS(v_pref_wind_dir - v_forecast_wind_dir), 360 - ABS(v_pref_wind_dir - v_forecast_wind_dir)) / 180,
    1
  );

  v_base_distance := LEAST(
    0.35 * v_wave_distance +
    0.25 * v_period_distance +
    0.20 * v_wind_distance +
    0.10 * v_tide_distance +
    0.10 * v_wind_dir_distance,
    1.0
  );
  v_base_score := (1.0 - v_base_distance) * 10.0;

  -- Aversion penalty (forecast vs aversion peak). Only when we have samples.
  IF v_av_count IS NOT NULL AND v_av_count > 0 THEN
    v_av_wave_distance     := LEAST(ABS(v_av_wave - v_forecast_wave) / GREATEST(v_av_wave, 1), 1);
    v_av_period_distance   := LEAST(ABS(v_av_period - v_forecast_period) / GREATEST(v_av_period, 1), 1);
    v_av_wind_distance     := LEAST(ABS(v_av_wind - v_forecast_wind) / GREATEST(v_av_wind, 5), 1);
    v_av_tide_distance     := LEAST(ABS(v_av_tide - v_forecast_tide) / 3, 1);
    v_av_wind_dir_distance := LEAST(
      LEAST(ABS(v_av_wind_dir - v_forecast_wind_dir), 360 - ABS(v_av_wind_dir - v_forecast_wind_dir)) / 180,
      1
    );

    v_aversion_distance := LEAST(
      0.35 * v_av_wave_distance +
      0.25 * v_av_period_distance +
      0.20 * v_av_wind_distance +
      0.10 * v_av_tide_distance +
      0.10 * v_av_wind_dir_distance,
      1.0
    );
    v_aversion_proximity := 1.0 - v_aversion_distance;
    v_aversion_penalty := v_aversion_proximity * c_aversion_scaling;
  ELSE
    v_aversion_penalty := 0;
  END IF;

  -- Fit-signal adjustment: explicit v1 picker feedback nudges nearby windows.
  -- It is bounded and only activates when categorical fit rows exist.
  WITH fit_samples AS (
    SELECT
      CASE
        WHEN s.session_skill_fit = 'dialed' THEN 1.0
        WHEN s.session_skill_fit = 'over_my_head' THEN -1.0
        WHEN s.session_skill_fit = 'under' THEN -0.5
        ELSE 0
      END
      +
      CASE
        WHEN s.session_board_fit = 'right' THEN 0.5
        WHEN s.session_board_fit IN ('too_small', 'too_much_board', 'wrong_type') THEN -0.5
        ELSE 0
      END AS fit_value,
      public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_height') AS sample_wave,
      public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_period') AS sample_period,
      public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_speed') AS sample_wind,
      public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_direction_deg') AS sample_wind_dir,
      public.parse_numeric_from_text(sfs.forecast_snapshot->>'tide_height') AS sample_tide
    FROM public.sessions s
    JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
    LEFT JOIN public.beaches b ON b.id = s.beach_id
    WHERE s.user_id = p_user_id
      AND s.status = 'completed'
      AND s.rating IS NOT NULL
      AND s.arrival_time > now() - interval '12 months'
      AND s.deleted_at IS NULL
      AND sfs.forecast_snapshot IS NOT NULL
      AND (s.session_skill_fit IS NOT NULL OR s.session_board_fit IS NOT NULL)
      AND (v_beach_break_type IS NULL OR b.break_type = v_beach_break_type OR b.break_type IS NULL)
  ),
  scored_fit_samples AS (
    SELECT
      fit_value,
      1.0 - LEAST(
        0.35 * LEAST(ABS(sample_wave - v_forecast_wave) / GREATEST(sample_wave, 1), 1) +
        0.25 * LEAST(ABS(sample_period - v_forecast_period) / GREATEST(sample_period, 1), 1) +
        0.20 * LEAST(ABS(sample_wind - v_forecast_wind) / GREATEST(sample_wind, 5), 1) +
        0.10 * LEAST(ABS(sample_tide - v_forecast_tide) / 3, 1) +
        0.10 * LEAST(
          LEAST(ABS(sample_wind_dir - v_forecast_wind_dir), 360 - ABS(sample_wind_dir - v_forecast_wind_dir)) / 180,
          1
        ),
        1.0
      ) AS fit_proximity
    FROM fit_samples
    WHERE sample_wave IS NOT NULL
      AND sample_period IS NOT NULL
      AND sample_wind IS NOT NULL
      AND sample_wind_dir IS NOT NULL
      AND sample_tide IS NOT NULL
      AND fit_value <> 0
  )
  SELECT
    SUM(fit_value * fit_proximity) / NULLIF(SUM(fit_proximity), 0),
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE fit_value > 0)::integer,
    COUNT(*) FILTER (WHERE fit_value < 0)::integer
  INTO
    v_fit_signal_score,
    v_fit_signal_sample_count,
    v_fit_positive_count,
    v_fit_negative_count
  FROM scored_fit_samples
  WHERE fit_proximity > 0.15;

  IF COALESCE(v_fit_signal_sample_count, 0) > 0 THEN
    v_session_fit_adjustment := GREATEST(
      -1.0,
      LEAST(1.0, COALESCE(v_fit_signal_score, 0) * c_fit_signal_scaling)
    );
  ELSE
    v_session_fit_adjustment := 0;
  END IF;

  SELECT
    CASE v_resolved_skill
      WHEN 'intermediate' THEN 2.0
      WHEN 'advanced' THEN 3.0
      WHEN 'expert' THEN 4.0
      ELSE 1.0
    END,
    CASE v_resolved_skill
      WHEN 'intermediate' THEN 5.0
      WHEN 'advanced' THEN 8.0
      WHEN 'expert' THEN 12.0
      ELSE 3.0
    END,
    CASE v_resolved_skill
      WHEN 'intermediate' THEN 1.0
      WHEN 'advanced' THEN 2.0
      WHEN 'expert' THEN 2.0
      ELSE 0.5
    END,
    CASE v_resolved_skill
      WHEN 'intermediate' THEN 6.0
      WHEN 'advanced' THEN 12.0
      WHEN 'expert' THEN 20.0
      ELSE 4.0
    END
  INTO
    v_skill_ideal_min,
    v_skill_ideal_max,
    v_skill_acceptable_min,
    v_skill_acceptable_max;

  SELECT
    CASE v_board_class
      WHEN 'foamie' THEN 0.5
      WHEN 'longboard' THEN 0.5
      WHEN 'mid-length' THEN 0.7
      WHEN 'funboard' THEN 0.6
      WHEN 'fish' THEN 0.85
      WHEN 'shortboard' THEN 1.15
      WHEN 'step-up' THEN 1.4
      WHEN 'gun' THEN 1.6
      WHEN 'sup' THEN 0.4
      WHEN 'foil' THEN 0.2
      WHEN 'bodyboard' THEN 1.0
      ELSE NULL
    END,
    CASE v_board_class
      WHEN 'foamie' THEN 0.6
      WHEN 'longboard' THEN 0.7
      WHEN 'mid-length' THEN 0.85
      WHEN 'funboard' THEN 0.8
      WHEN 'fish' THEN 0.95
      WHEN 'shortboard' THEN 1.05
      WHEN 'step-up' THEN 1.15
      WHEN 'gun' THEN 1.2
      WHEN 'sup' THEN 0.6
      WHEN 'foil' THEN 0.5
      WHEN 'bodyboard' THEN 1.0
      ELSE NULL
    END
  INTO v_board_shape_lo, v_board_shape_hi;

  IF v_board_class IS NOT NULL
    AND v_board_shape_lo IS NOT NULL
    AND v_board_shape_hi IS NOT NULL
    AND v_forecast_wave IS NOT NULL
  THEN
    v_board_ideal_min := GREATEST(0.3, round((v_skill_ideal_min * v_board_shape_lo)::numeric, 1));
    v_board_ideal_max := GREATEST(v_board_ideal_min + 0.5, round((v_skill_ideal_max * v_board_shape_hi)::numeric, 1));
    v_board_acceptable_min := GREATEST(0.3, round((v_skill_acceptable_min * v_board_shape_lo)::numeric, 1));
    v_board_acceptable_max := GREATEST(v_board_acceptable_min + 0.5, round((v_skill_acceptable_max * v_board_shape_hi)::numeric, 1));

    IF v_forecast_wave >= v_board_ideal_min AND v_forecast_wave <= v_board_ideal_max THEN
      v_board_band_adjustment := 0.5;
    ELSIF v_forecast_wave < v_board_acceptable_min THEN
      v_board_band_adjustment := -LEAST(
        1.0,
        GREATEST(0.5, round(((v_board_acceptable_min - v_forecast_wave) * 0.5)::numeric, 2))
      );
    ELSIF v_forecast_wave > v_board_acceptable_max THEN
      v_board_band_adjustment := -LEAST(
        1.0,
        GREATEST(0.5, round(((v_forecast_wave - v_board_acceptable_max) * 0.5)::numeric, 2))
      );
    ELSE
      v_board_band_adjustment := 0;
    END IF;
  ELSE
    v_board_band_adjustment := 0;
  END IF;

  v_score := GREATEST(
    0,
    LEAST(
      10,
      v_base_score - v_aversion_penalty + v_session_fit_adjustment + v_board_band_adjustment
    )
  );

  v_label := CASE
    WHEN v_score >= 8.5 THEN 'EPIC'
    WHEN v_score >= 7.0 THEN 'GOOD'
    WHEN v_score >= 5.5 THEN 'FAIR'
    WHEN v_score >= 3.5 THEN 'RIDEABLE'
    ELSE 'MEH'
  END;

  v_confidence := CASE
    WHEN v_session_count >= 25 THEN 'high'
    WHEN v_session_count >= 10 THEN 'medium'
    ELSE 'low'
  END;

  v_reason_bullets := jsonb_build_array(
    format('Wave height %s ft — profile peak %s ft', round(v_forecast_wave::numeric, 1), round(v_pref_wave::numeric, 1)),
    format('Period %s s — profile peak %s s', round(v_forecast_period::numeric, 0), round(v_pref_period::numeric, 0)),
    format('Wind %s mph — profile peak %s mph', round(v_forecast_wind::numeric, 0), round(v_pref_wind::numeric, 0))
  );

  IF COALESCE(v_fit_signal_sample_count, 0) > 0 THEN
    v_reason_bullets := v_reason_bullets || jsonb_build_array(
      CASE
        WHEN v_session_fit_adjustment > 0.15 THEN 'Your session fit feedback lifts this window.'
        WHEN v_session_fit_adjustment < -0.15 THEN 'Similar sessions were flagged as a skill or board mismatch.'
        ELSE 'Your session fit feedback is neutral for this window.'
      END
    );
  END IF;

  IF v_board_class IS NOT NULL AND ABS(v_board_band_adjustment) >= 0.15 THEN
    v_reason_bullets := v_reason_bullets || jsonb_build_array(
      CASE
        WHEN v_board_band_adjustment > 0 THEN format('Your %s band fits this wave height.', v_board_class)
        ELSE format('This wave height is outside your usual %s band.', v_board_class)
      END
    );
  END IF;

  -- Board tip: most-used board at rating >=4 sessions with nearby wave height.
  SELECT
    CASE
      WHEN b.dimensions IS NOT NULL AND b.dimensions <> '' THEN b.name || ' ' || b.dimensions
      ELSE b.name
    END
  INTO v_board_tip
  FROM public.sessions s
  JOIN public.boards b ON b.id = s.board_id
  WHERE s.user_id = p_user_id
    AND s.rating >= 4
    AND s.status = 'completed'
    AND ABS(public.parse_numeric_from_text((SELECT forecast_snapshot->>'wave_height' FROM public.session_forecast_snapshots WHERE session_id = s.id)) - v_forecast_wave) < 1.5
  GROUP BY b.id, b.name, b.dimensions
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'state', 'learned',
    'score', round(v_score::numeric, 1),
    'label', v_label,
    'reason_bullets', v_reason_bullets,
    'board_tip', v_board_tip,
    'confidence', v_confidence,
    'sessions_in_profile', v_session_count,
    'profile_kind', CASE WHEN v_av_count IS NOT NULL AND v_av_count > 0 THEN 'two_sided' ELSE 'preference_only' END,
    'quality_band', CASE WHEN v_session_count >= 15 THEN 'dense_signal' ELSE 'session_backed' END,
    'base_score', round(v_base_score::numeric, 2),
    'aversion_penalty', round(v_aversion_penalty::numeric, 2),
    'aversion_sample_count', COALESCE(v_av_count, 0),
    'fit_signal_adjustment', round(v_session_fit_adjustment::numeric, 2),
    'fit_signal_sample_count', COALESCE(v_fit_signal_sample_count, 0),
    'fit_signal_positive_count', COALESCE(v_fit_positive_count, 0),
    'fit_signal_negative_count', COALESCE(v_fit_negative_count, 0),
    'skill_used', v_resolved_skill,
    'skill_source', v_skill_source,
    'board_class', v_board_class,
    'board_band_adjustment', round(v_board_band_adjustment::numeric, 2),
    'board_ideal_wave_min_ft', v_board_ideal_min,
    'board_ideal_wave_max_ft', v_board_ideal_max
  );
END;
$_$;


ALTER FUNCTION "public"."compute_user_match_score_core"("p_user_id" "uuid", "p_beach_id" "uuid", "p_wave_height" "text", "p_wave_period" "text", "p_wind_speed" "text", "p_wind_direction" "text", "p_tide_height" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."concat_text_array"("vals" "text"[]) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  select array_to_string(vals, ' ');
$$;


ALTER FUNCTION "public"."concat_text_array"("vals" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_apple_identity_recovery"("p_canonical_user_id" "uuid", "p_recovery_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_request public.apple_identity_recovery_requests%ROWTYPE;
BEGIN
  IF p_canonical_user_id IS NULL
     OR p_recovery_id IS NULL
     OR length(p_idempotency_key) < 8
     OR length(p_idempotency_key) > 128 THEN
    RAISE EXCEPTION 'invalid apple recovery confirmation input';
  END IF;

  SELECT *
  INTO v_request
  FROM public.apple_identity_recovery_requests
  WHERE id = p_recovery_id
    AND canonical_user_id = p_canonical_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'expired');
  END IF;

  IF v_request.status = 'completed' THEN
    RETURN jsonb_build_object(
      'status', 'already_recovered',
      'rollback_until', v_request.rollback_until
    );
  END IF;

  IF v_request.status = 'support_required' THEN
    RETURN jsonb_build_object(
      'status', 'support_required',
      'support_reference', v_request.support_reference
    );
  END IF;

  IF v_request.expires_at <= clock_timestamp() THEN
    UPDATE public.apple_identity_recovery_requests
    SET status = 'expired', updated_at = clock_timestamp()
    WHERE id = v_request.id;
    RETURN jsonb_build_object('status', 'expired');
  END IF;

  IF v_request.confirmation_idempotency_key IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'identity_transfer_not_supported',
      'support_reference', v_request.support_reference
    );
  END IF;

  UPDATE public.apple_identity_recovery_requests
  SET
    confirmation_idempotency_key = p_idempotency_key,
    confirmed_at = clock_timestamp(),
    status = 'operator_pending',
    updated_at = clock_timestamp()
  WHERE id = v_request.id;

  INSERT INTO public.apple_identity_recovery_audit (
    recovery_id,
    canonical_user_id,
    event_type
  ) VALUES (
    v_request.id,
    p_canonical_user_id,
    'canonical_account_confirmed'
  );

  -- Supabase Auth exposes no supported API for transactionally reassigning an
  -- auth.identities row. This function deliberately stops after durable
  -- confirmation rather than writing GoTrue-owned tables directly.
  RETURN jsonb_build_object(
    'status', 'identity_transfer_not_supported',
    'support_reference', v_request.support_reference
  );
END;
$$;


ALTER FUNCTION "public"."confirm_apple_identity_recovery"("p_canonical_user_id" "uuid", "p_recovery_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_apple_identity_recovery"("p_canonical_user_id" "uuid", "p_recovery_id" "uuid", "p_idempotency_key" "text") IS 'Service-only explicit canonical-account confirmation. Records operator-pending state and intentionally does not mutate GoTrue-owned auth tables.';



CREATE OR REPLACE FUNCTION "public"."count_auth_apple_orphan_users"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT COUNT(*)::integer
  FROM auth.users u
  WHERE u.raw_user_meta_data->>'iss' LIKE '%appleid%'
    AND NOT EXISTS (
      SELECT 1
      FROM auth.identities i
      WHERE i.user_id = u.id
    );
$$;


ALTER FUNCTION "public"."count_auth_apple_orphan_users"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."count_auth_apple_orphan_users"() IS 'Release audit gate: counts Apple OIDC auth.users rows with no auth.identities row. Expected value before mobile release: 0. Service-role only; returns no PII.';



CREATE OR REPLACE FUNCTION "public"."create_activity"("p_user_id" "uuid", "p_activity_type" character varying, "p_entity_type" character varying, "p_entity_id" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  activity_id uuid;
begin
  insert into public.user_activities (user_id, activity_type, entity_type, entity_id, metadata)
  values (p_user_id, p_activity_type, p_entity_type, p_entity_id, p_metadata)
  returning id into activity_id;
  
  return activity_id;
end;
$$;


ALTER FUNCTION "public"."create_activity"("p_user_id" "uuid", "p_activity_type" character varying, "p_entity_type" character varying, "p_entity_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_custom_spot_guarded"("p_name" "text", "p_lat" double precision, "p_lon" double precision, "p_break_type" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'private'::"text", "p_facing_direction_deg" numeric DEFAULT NULL::numeric, "p_swell_window_min_deg" numeric DEFAULT NULL::numeric, "p_swell_window_max_deg" numeric DEFAULT NULL::numeric, "p_offshore_direction_deg" numeric DEFAULT NULL::numeric, "p_exposure_level" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "user_id" "uuid", "name" "text", "lat" numeric, "lon" numeric, "break_type" "text", "visibility" "text", "nearest_beach_id" "uuid", "nearest_beach_distance_mi" numeric, "deleted_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "facing_direction_deg" numeric, "swell_window_min_deg" numeric, "swell_window_max_deg" numeric, "offshore_direction_deg" numeric, "exposure_level" "text", "fingerprint_confidence" "text", "fingerprint_updated_at" timestamp with time zone, "favorite_id" "uuid", "favorite_rank" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  current_user_id uuid := auth.uid();
  trimmed_name text := btrim(p_name);
  nearest_id uuid;
  nearest_distance_miles numeric(5,2);
  favorite_count integer;
  next_rank integer;
  has_unlimited_favorites boolean;
  inserted_spot public.custom_spots%ROWTYPE;
  has_fingerprint boolean := (
    p_facing_direction_deg IS NOT NULL
    OR p_swell_window_min_deg IS NOT NULL
    OR p_swell_window_max_deg IS NOT NULL
    OR p_offshore_direction_deg IS NOT NULL
    OR p_exposure_level IS NOT NULL
  );
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF trimmed_name IS NULL OR char_length(trimmed_name) < 1 OR char_length(trimmed_name) > 60 THEN
    RAISE EXCEPTION 'invalid_custom_spot_name'
      USING DETAIL = 'name_length_1_60_required';
  END IF;

  IF p_lat IS NULL OR p_lon IS NULL
     OR p_lat < -90 OR p_lat > 90
     OR p_lon < -180 OR p_lon > 180 THEN
    RAISE EXCEPTION 'invalid_custom_spot_coordinates'
      USING DETAIL = 'lat_lon_out_of_range';
  END IF;

  IF p_break_type IS NOT NULL
     AND p_break_type <> ALL (ARRAY['reef','point','beach','rivermouth','jetty']) THEN
    RAISE EXCEPTION 'invalid_custom_spot_break_type'
      USING DETAIL = 'unsupported_break_type';
  END IF;

  IF p_exposure_level IS NOT NULL
     AND p_exposure_level <> ALL (ARRAY['sheltered','mixed','exposed']) THEN
    RAISE EXCEPTION 'invalid_custom_spot_exposure'
      USING DETAIL = 'unsupported_exposure_level';
  END IF;

  IF p_facing_direction_deg IS NOT NULL
     AND (p_facing_direction_deg < 0 OR p_facing_direction_deg >= 360) THEN
    RAISE EXCEPTION 'invalid_custom_spot_facing_direction'
      USING DETAIL = 'degree_out_of_range';
  END IF;

  IF p_swell_window_min_deg IS NOT NULL
     AND (p_swell_window_min_deg < 0 OR p_swell_window_min_deg >= 360) THEN
    RAISE EXCEPTION 'invalid_custom_spot_swell_min'
      USING DETAIL = 'degree_out_of_range';
  END IF;

  IF p_swell_window_max_deg IS NOT NULL
     AND (p_swell_window_max_deg < 0 OR p_swell_window_max_deg >= 360) THEN
    RAISE EXCEPTION 'invalid_custom_spot_swell_max'
      USING DETAIL = 'degree_out_of_range';
  END IF;

  IF p_offshore_direction_deg IS NOT NULL
     AND (p_offshore_direction_deg < 0 OR p_offshore_direction_deg >= 360) THEN
    RAISE EXCEPTION 'invalid_custom_spot_offshore_direction'
      USING DETAIL = 'degree_out_of_range';
  END IF;

  nearest_id := public.find_nearest_beach_id(
    p_lat::decimal,
    p_lon::decimal,
    241401.6
  );

  IF nearest_id IS NULL THEN
    RAISE EXCEPTION 'custom_spot_out_of_coverage'
      USING DETAIL = 'nearest_beach_required';
  END IF;

  SELECT round((ST_Distance(
    b.geog,
    ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326)::geography
  ) / 1609.344)::numeric, 2)::numeric(5,2)
  INTO nearest_distance_miles
  FROM public.beaches b
  WHERE b.id = nearest_id;

  IF nearest_distance_miles IS NULL THEN
    RAISE EXCEPTION 'custom_spot_out_of_coverage'
      USING DETAIL = 'nearest_beach_distance_required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(current_user_id::text)::bigint);

  SELECT EXISTS (
    SELECT 1
    FROM public.user_entitlements ue
    WHERE ue.user_id = current_user_id
      AND (ue.is_pro = true OR ue.is_trialing = true)
      AND (
        ue.expires_at IS NULL
        OR ue.expires_at > now()
        OR ue.billing_issue = true
      )
  ) INTO has_unlimited_favorites;

  SELECT count(*) INTO favorite_count
  FROM public.favorite_beaches fb
  WHERE fb.user_id = current_user_id;

  IF NOT has_unlimited_favorites AND favorite_count >= 3 THEN
    RAISE EXCEPTION 'favorite_quota_exceeded'
      USING DETAIL = 'free_favorites_limit';
  END IF;

  SELECT COALESCE(max(fb.rank), 0) + 1 INTO next_rank
  FROM public.favorite_beaches fb
  WHERE fb.user_id = current_user_id;

  INSERT INTO public.custom_spots (
    user_id,
    name,
    lat,
    lon,
    break_type,
    visibility,
    nearest_beach_id,
    nearest_beach_distance_mi,
    facing_direction_deg,
    swell_window_min_deg,
    swell_window_max_deg,
    offshore_direction_deg,
    exposure_level,
    fingerprint_confidence,
    fingerprint_updated_at
  )
  VALUES (
    current_user_id,
    trimmed_name,
    p_lat,
    p_lon,
    p_break_type,
    'private',
    nearest_id,
    nearest_distance_miles,
    p_facing_direction_deg,
    p_swell_window_min_deg,
    p_swell_window_max_deg,
    p_offshore_direction_deg,
    p_exposure_level,
    CASE WHEN has_fingerprint THEN 'user_set' ELSE 'unset' END,
    CASE WHEN has_fingerprint THEN now() ELSE NULL END
  )
  RETURNING * INTO inserted_spot;

  INSERT INTO public.favorite_beaches (
    user_id,
    beach_id,
    custom_spot_id,
    rank,
    alerts_enabled
  )
  VALUES (
    current_user_id,
    NULL,
    inserted_spot.id,
    next_rank,
    false
  )
  RETURNING favorite_beaches.id, favorite_beaches.rank
  INTO favorite_id, favorite_rank;

  id := inserted_spot.id;
  user_id := inserted_spot.user_id;
  name := inserted_spot.name;
  lat := inserted_spot.lat;
  lon := inserted_spot.lon;
  break_type := inserted_spot.break_type;
  visibility := inserted_spot.visibility;
  nearest_beach_id := inserted_spot.nearest_beach_id;
  nearest_beach_distance_mi := inserted_spot.nearest_beach_distance_mi;
  deleted_at := inserted_spot.deleted_at;
  created_at := inserted_spot.created_at;
  updated_at := inserted_spot.updated_at;
  facing_direction_deg := inserted_spot.facing_direction_deg;
  swell_window_min_deg := inserted_spot.swell_window_min_deg;
  swell_window_max_deg := inserted_spot.swell_window_max_deg;
  offshore_direction_deg := inserted_spot.offshore_direction_deg;
  exposure_level := inserted_spot.exposure_level;
  fingerprint_confidence := inserted_spot.fingerprint_confidence;
  fingerprint_updated_at := inserted_spot.fingerprint_updated_at;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."create_custom_spot_guarded"("p_name" "text", "p_lat" double precision, "p_lon" double precision, "p_break_type" "text", "p_visibility" "text", "p_facing_direction_deg" numeric, "p_swell_window_min_deg" numeric, "p_swell_window_max_deg" numeric, "p_offshore_direction_deg" numeric, "p_exposure_level" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_session_forecast_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  forecast_data jsonb;
  conditions_data jsonb;
  forecast_vs_actual_data jsonb := '{}'::jsonb;
  snapshot_exists boolean;
  should_rematch_forecast boolean := false;
  forecast_wave_height numeric;
  forecast_wind_speed numeric;
  forecast_tide_height numeric;
BEGIN
  PERFORM public.sync_session_wave_observation_candidate(
    new.id,
    new.user_id,
    new.beach_id::uuid,
    new.arrival_time,
    new.status,
    new.wave_height_ft,
    'trigger'
  );

  IF new.status IS DISTINCT FROM 'completed' THEN
    RETURN new;
  END IF;

  conditions_data := jsonb_build_object(
    'wave_quality', new.wave_quality,
    'water_temp', new.water_temp,
    'crowd_level', new.crowd_level,
    'parking_ease', new.parking_ease,
    'rating', new.rating,
    'notes', new.notes,
    'duration_minutes', new.duration_minutes,
    'arrival_time', new.arrival_time,
    'wave_height_ft', new.wave_height_ft,
    'wind_speed_mph', new.wind_speed_mph,
    'wind_direction', new.wind_direction,
    'forecast_accuracy', new.forecast_accuracy,
    'tide_height_ft', new.tide_height_ft,
    'tide_status', new.tide_status
  );

  IF tg_op = 'UPDATE' THEN
    should_rematch_forecast :=
      old.status = 'completed'
      AND (
        old.arrival_time IS DISTINCT FROM new.arrival_time
        OR old.beach_id IS DISTINCT FROM new.beach_id
      );
  END IF;

  IF tg_op = 'UPDATE' THEN
    IF old.status = 'completed' THEN
      SELECT sfs.forecast_snapshot
      INTO forecast_data
      FROM public.session_forecast_snapshots sfs
      WHERE sfs.session_id = new.id;

      IF forecast_data IS NOT NULL AND NOT should_rematch_forecast THEN
        IF forecast_data->>'wave_height' IS NOT NULL AND new.wave_height_ft IS NOT NULL THEN
          BEGIN
            forecast_wave_height := (forecast_data->>'wave_height')::numeric;
            IF forecast_wave_height IS DISTINCT FROM new.wave_height_ft THEN
              forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
                'wave_height_ft', jsonb_build_object(
                  'forecast', forecast_wave_height,
                  'actual', new.wave_height_ft,
                  'diff', new.wave_height_ft - forecast_wave_height
                )
              );
            END IF;
          EXCEPTION WHEN others THEN NULL;
          END;
        END IF;

        IF forecast_data->>'wind_speed_mph' IS NOT NULL AND new.wind_speed_mph IS NOT NULL THEN
          BEGIN
            forecast_wind_speed := (forecast_data->>'wind_speed_mph')::numeric;
            IF forecast_wind_speed IS DISTINCT FROM new.wind_speed_mph THEN
              forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
                'wind_speed_mph', jsonb_build_object(
                  'forecast', forecast_wind_speed,
                  'actual', new.wind_speed_mph,
                  'diff', new.wind_speed_mph - forecast_wind_speed
                )
              );
            END IF;
          EXCEPTION WHEN others THEN NULL;
          END;
        END IF;

        IF forecast_data->>'wind_direction' IS NOT NULL AND new.wind_direction IS NOT NULL THEN
          IF forecast_data->>'wind_direction' <> new.wind_direction THEN
            forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
              'wind_direction', jsonb_build_object(
                'forecast', forecast_data->>'wind_direction',
                'actual', new.wind_direction
              )
            );
          END IF;
        END IF;

        IF forecast_data->>'tide_height' IS NOT NULL AND new.tide_height_ft IS NOT NULL THEN
          BEGIN
            forecast_tide_height := (forecast_data->>'tide_height')::numeric;
            IF forecast_tide_height IS DISTINCT FROM new.tide_height_ft THEN
              forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
                'tide_height_ft', jsonb_build_object(
                  'forecast', forecast_tide_height,
                  'actual', new.tide_height_ft,
                  'diff', new.tide_height_ft - forecast_tide_height
                )
              );
            END IF;
          EXCEPTION WHEN others THEN NULL;
          END;
        END IF;

        IF forecast_data->>'tide_status' IS NOT NULL AND new.tide_status IS NOT NULL THEN
          IF forecast_data->>'tide_status' <> new.tide_status THEN
            forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
              'tide_status', jsonb_build_object(
                'forecast', forecast_data->>'tide_status',
                'actual', new.tide_status
              )
            );
          END IF;
        END IF;

        UPDATE public.session_forecast_snapshots
        SET
          actual_conditions = coalesce(actual_conditions, '{}'::jsonb) || conditions_data,
          forecast_vs_actual = forecast_vs_actual_data,
          session_date = new.arrival_time::date,
          updated_at = now()
        WHERE session_id = new.id;

        RETURN new;
      END IF;
    END IF;
  END IF;

  SELECT exists(
    SELECT 1
    FROM public.session_forecast_snapshots
    WHERE session_id = new.id
  ) INTO snapshot_exists;

  IF snapshot_exists AND NOT should_rematch_forecast THEN
    RETURN new;
  END IF;

  SELECT to_jsonb(ef.*)
  INTO forecast_data
  FROM public.enhanced_forecasts ef
  WHERE ef.beach_id::uuid = new.beach_id::uuid
    AND ef.forecast_at IS NOT NULL
    AND ef.forecast_at BETWEEN new.arrival_time - interval '6 hours'
                          AND new.arrival_time + interval '6 hours'
  ORDER BY abs(EXTRACT(EPOCH FROM (ef.forecast_at - new.arrival_time))) ASC
  LIMIT 1;

  IF forecast_data IS NOT NULL THEN
    forecast_vs_actual_data := '{}'::jsonb;

    IF forecast_data->>'wave_height' IS NOT NULL AND new.wave_height_ft IS NOT NULL THEN
      BEGIN
        forecast_wave_height := (forecast_data->>'wave_height')::numeric;
        IF forecast_wave_height IS DISTINCT FROM new.wave_height_ft THEN
          forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
            'wave_height_ft', jsonb_build_object(
              'forecast', forecast_wave_height,
              'actual', new.wave_height_ft,
              'diff', new.wave_height_ft - forecast_wave_height
            )
          );
        END IF;
      EXCEPTION WHEN others THEN NULL;
      END;
    END IF;

    IF forecast_data->>'wind_speed_mph' IS NOT NULL AND new.wind_speed_mph IS NOT NULL THEN
      BEGIN
        forecast_wind_speed := (forecast_data->>'wind_speed_mph')::numeric;
        IF forecast_wind_speed IS DISTINCT FROM new.wind_speed_mph THEN
          forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
            'wind_speed_mph', jsonb_build_object(
              'forecast', forecast_wind_speed,
              'actual', new.wind_speed_mph,
              'diff', new.wind_speed_mph - forecast_wind_speed
            )
          );
        END IF;
      EXCEPTION WHEN others THEN NULL;
      END;
    END IF;

    IF forecast_data->>'wind_direction' IS NOT NULL AND new.wind_direction IS NOT NULL THEN
      IF forecast_data->>'wind_direction' <> new.wind_direction THEN
        forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
          'wind_direction', jsonb_build_object(
            'forecast', forecast_data->>'wind_direction',
            'actual', new.wind_direction
          )
        );
      END IF;
    END IF;

    IF forecast_data->>'tide_height' IS NOT NULL AND new.tide_height_ft IS NOT NULL THEN
      BEGIN
        forecast_tide_height := (forecast_data->>'tide_height')::numeric;
        IF forecast_tide_height IS DISTINCT FROM new.tide_height_ft THEN
          forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
            'tide_height_ft', jsonb_build_object(
              'forecast', forecast_tide_height,
              'actual', new.tide_height_ft,
              'diff', new.tide_height_ft - forecast_tide_height
            )
          );
        END IF;
      EXCEPTION WHEN others THEN NULL;
      END;
    END IF;

    IF forecast_data->>'tide_status' IS NOT NULL AND new.tide_status IS NOT NULL THEN
      IF forecast_data->>'tide_status' <> new.tide_status THEN
        forecast_vs_actual_data := forecast_vs_actual_data || jsonb_build_object(
          'tide_status', jsonb_build_object(
            'forecast', forecast_data->>'tide_status',
            'actual', new.tide_status
          )
        );
      END IF;
    END IF;

    IF snapshot_exists THEN
      UPDATE public.session_forecast_snapshots
      SET
        beach_id = new.beach_id::uuid,
        forecast_snapshot = forecast_data,
        actual_conditions = coalesce(actual_conditions, '{}'::jsonb) || conditions_data,
        forecast_vs_actual = forecast_vs_actual_data,
        forecast_confidence_score = (forecast_data->>'confidence_score')::integer,
        data_source = forecast_data->>'data_source',
        session_date = new.arrival_time::date,
        updated_at = now()
      WHERE session_id = new.id;
    ELSE
      BEGIN
        INSERT INTO public.session_forecast_snapshots (
          session_id, user_id, beach_id, forecast_snapshot, actual_conditions,
          forecast_vs_actual, forecast_confidence_score, data_source, session_date
        ) VALUES (
          new.id, new.user_id, new.beach_id::uuid, forecast_data, conditions_data,
          forecast_vs_actual_data, (forecast_data->>'confidence_score')::integer,
          forecast_data->>'data_source', new.arrival_time::date
        );
      EXCEPTION
        WHEN unique_violation THEN NULL;
        WHEN others THEN RAISE WARNING 'Failed to create forecast snapshot for session %: %', new.id, sqlerrm;
      END;
    END IF;
  ELSIF snapshot_exists AND should_rematch_forecast THEN
    DELETE FROM public.session_forecast_snapshots
    WHERE session_id = new.id;
  END IF;

  RETURN new;
END;
$$;


ALTER FUNCTION "public"."create_session_forecast_snapshot"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_session_forecast_snapshot"() IS 'Creates session forecast snapshots and keeps actual_conditions synced. Forecast rows are matched by nearest enhanced_forecasts.forecast_at within +/- 6 hours of session arrival_time.';



CREATE OR REPLACE FUNCTION "public"."custom_spots_lock_user_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'custom_spots.user_id is immutable after insert';
  END IF;
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."custom_spots_lock_user_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_session_share_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  UPDATE sessions
  SET share_count = GREATEST(0, share_count - 1)
  WHERE id = OLD.session_id;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."decrement_session_share_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_android_tester_roster_for_account"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE public.android_tester_roster_audit
  SET
    actor_user_id = NULL,
    evidence = '{}'::jsonb
  WHERE actor_user_id = NEW.id
    OR entry_id IN (
      SELECT entry.id
      FROM public.android_tester_roster_entries AS entry
      WHERE entry.user_id = NEW.id
    );

  DELETE FROM public.android_tester_roster_entries
  WHERE user_id = NEW.id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."delete_android_tester_roster_for_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_user_account"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_audit_id uuid;
  v_sessions_soft_deleted int := 0;
  v_comments_anonymized int := 0;
  v_personal_rows_deleted int := 0;
  v_count int;
BEGIN
  INSERT INTO account_deletions (user_id)
  VALUES (p_user_id)
  RETURNING id INTO v_audit_id;

  UPDATE sessions
  SET deleted_at = now(),
      notes = NULL,
      description = NULL,
      image_url = NULL,
      board_snapshot = NULL,
      muted = true
  WHERE user_id = p_user_id AND deleted_at IS NULL;
  GET DIAGNOSTICS v_sessions_soft_deleted = ROW_COUNT;

  UPDATE comments
  SET content = '[deleted]',
      updated_at = now()
  WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_comments_anonymized = ROW_COUNT;

  UPDATE beach_reviews
  SET title = '[deleted]',
      content = '[deleted]',
      deleted_at = now(),
      updated_at = now()
  WHERE user_id = p_user_id AND deleted_at IS NULL;

  UPDATE intel_posts
  SET is_active = false,
      title = '[deleted]',
      description = '[deleted]',
      photo_url = NULL,
      photo_storage_path = NULL,
      vibe = NULL,
      updated_at = now()
  WHERE user_id = p_user_id;

  DELETE FROM intel_reports WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_email_prefs WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_surf_preferences WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_implicit_preferences WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_beach_affinity WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM favorite_beaches WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_devices WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_badges WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_xp WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM xp_events WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_activities WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_events WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM personalization_milestones WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM saved_windows WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM session_invitations
  WHERE inviter_id = p_user_id OR invitee_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM boards WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM session_logs WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  UPDATE session_media
  SET deleted_at = now(),
      caption = NULL
  WHERE user_id = p_user_id AND deleted_at IS NULL;

  DELETE FROM session_forecast_snapshots WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM spot_feedback WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM notifications WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM forecast_alert_deliveries WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM user_follows
  WHERE follower_id = p_user_id OR following_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM beach_review_likes WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM session_likes WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM session_shares WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM forecast_accuracy_votes WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM intel_votes WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  DELETE FROM intel_post_confirmations WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_personal_rows_deleted := v_personal_rows_deleted + v_count;

  PERFORM public.erase_regional_recommendation_hold_operator_v1(p_user_id);

  UPDATE profiles
  SET deleted_at = now(),
      full_name = 'Deleted surfer',
      avatar_url = NULL,
      bio = NULL,
      location = NULL,
      instagram = NULL,
      home_beach_id = NULL,
      experience_level = NULL,
      preferred_session_time = NULL,
      surf_styles = NULL,
      followers_count = 0,
      following_count = 0,
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE account_deletions
  SET completed_at = now(),
      sessions_soft_deleted = v_sessions_soft_deleted,
      comments_anonymized = v_comments_anonymized,
      personal_rows_deleted = v_personal_rows_deleted
  WHERE id = v_audit_id;

  RETURN jsonb_build_object(
    'audit_id', v_audit_id,
    'sessions_soft_deleted', v_sessions_soft_deleted,
    'comments_anonymized', v_comments_anonymized,
    'personal_rows_deleted', v_personal_rows_deleted
  );
EXCEPTION WHEN OTHERS THEN
  UPDATE account_deletions
  SET error = SQLERRM
  WHERE id = v_audit_id;
  RAISE;
END;
$$;


