COMMENT ON FUNCTION "public"."delete_user_account"("p_user_id" "uuid") IS 'Atomic soft-delete of a user account. Service role only. Called from the delete-account Edge Function after verifying the caller JWT.';



CREATE OR REPLACE FUNCTION "public"."detect_apple_orphan_after_sign_in"("p_current_user_id" "uuid", "p_apple_sub" "text", "p_native_install_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_current_created_at timestamptz;
  v_current_name text;
  v_candidate_user_id uuid;
  v_candidate_count integer;
  v_pair_key text;
BEGIN
  IF p_current_user_id IS NULL
     OR length(p_apple_sub) = 0
     OR p_native_install_id IS NULL
     OR length(p_idempotency_key) < 8
     OR length(p_idempotency_key) > 128 THEN
    RAISE EXCEPTION 'invalid apple orphan detection input';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_constraint current_constraint
    JOIN pg_class source_table ON source_table.oid = current_constraint.conrelid
    JOIN pg_namespace source_ns ON source_ns.oid = source_table.relnamespace
    JOIN pg_class target_table ON target_table.oid = current_constraint.confrelid
    JOIN pg_namespace target_ns ON target_ns.oid = target_table.relnamespace
    WHERE current_constraint.contype = 'f'
      AND source_ns.nspname = 'public'
      AND current_constraint.confrelid IN (
        'auth.users'::regclass,
        'public.profiles'::regclass
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.apple_recovery_dependency_registry registry
        WHERE registry.source_schema = source_ns.nspname
          AND registry.source_table = source_table.relname
          AND registry.constraint_name = current_constraint.conname
          AND registry.target_schema = target_ns.nspname
          AND registry.target_table = target_table.relname
      )
  ) THEN
    RETURN jsonb_build_object('status', 'schema_coverage_incomplete');
  END IF;

  SELECT
    signed_in_user.created_at,
    lower(
      regexp_replace(
        trim(
          coalesce(
            nullif(current_profile.full_name, ''),
            nullif(current_profile.display_name, ''),
            nullif(signed_in_user.raw_user_meta_data->>'full_name', ''),
            nullif(signed_in_user.raw_user_meta_data->>'name', ''),
            nullif(
              concat_ws(
                ' ',
                signed_in_user.raw_user_meta_data->>'given_name',
                signed_in_user.raw_user_meta_data->>'family_name'
              ),
              ''
            )
          )
        ),
        '[^[:alnum:]]+',
        '',
        'g'
      )
    )
  INTO v_current_created_at, v_current_name
  FROM auth.users signed_in_user
  LEFT JOIN public.profiles current_profile
    ON current_profile.id = signed_in_user.id
   AND current_profile.deleted_at IS NULL
  WHERE signed_in_user.id = p_current_user_id
    AND signed_in_user.deleted_at IS NULL;

  IF NOT FOUND
     OR v_current_name IS NULL
     OR v_current_name = ''
     OR v_current_created_at < clock_timestamp() - interval '15 minutes'
     OR v_current_created_at > clock_timestamp() + interval '30 seconds' THEN
    RETURN jsonb_build_object('status', 'no_match');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM auth.identities identity_row
    WHERE identity_row.user_id = p_current_user_id
      AND identity_row.provider = 'apple'
      AND (
        identity_row.provider_id = p_apple_sub
        OR identity_row.identity_data->>'sub' = p_apple_sub
      )
  ) THEN
    RETURN jsonb_build_object('status', 'no_match');
  END IF;

  WITH candidate_users AS MATERIALIZED (
    SELECT DISTINCT event_row.user_id
    FROM public.user_events event_row
    WHERE event_row.user_id IS NOT NULL
      AND event_row.user_id <> p_current_user_id
      AND event_row.metadata->>'native_install_id' = p_native_install_id::text
  ),
  named_candidates AS (
    SELECT candidate_user.id
    FROM candidate_users candidate
    JOIN auth.users candidate_user ON candidate_user.id = candidate.user_id
    LEFT JOIN public.profiles candidate_profile
      ON candidate_profile.id = candidate_user.id
     AND candidate_profile.deleted_at IS NULL
    WHERE candidate_user.deleted_at IS NULL
      AND candidate_user.created_at < v_current_created_at
      AND lower(
        regexp_replace(
          trim(
            coalesce(
              nullif(candidate_profile.full_name, ''),
              nullif(candidate_profile.display_name, ''),
              nullif(candidate_user.raw_user_meta_data->>'full_name', ''),
              nullif(candidate_user.raw_user_meta_data->>'name', ''),
              nullif(
                concat_ws(
                  ' ',
                  candidate_user.raw_user_meta_data->>'given_name',
                  candidate_user.raw_user_meta_data->>'family_name'
                ),
                ''
              )
            )
          ),
          '[^[:alnum:]]+',
          '',
          'g'
        )
      ) = v_current_name
  )
  SELECT count(*), (array_agg(id ORDER BY id))[1]
  INTO v_candidate_count, v_candidate_user_id
  FROM named_candidates;

  IF v_candidate_count <> 1 OR v_candidate_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'no_match');
  END IF;

  v_pair_key := v_candidate_user_id::text || ':' || p_current_user_id::text;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_pair_key, 0));

  IF EXISTS (
    SELECT 1
    FROM public.apple_identity_recovery_audit audit_row
    WHERE audit_row.canonical_user_id = v_candidate_user_id
      AND audit_row.event_type = 'post_sign_in_orphan_flagged'
      AND audit_row.event_details->>'secondary_user_id' = p_current_user_id::text
  ) THEN
    RETURN jsonb_build_object('status', 'flagged');
  END IF;

  INSERT INTO public.apple_identity_recovery_audit (
    canonical_user_id,
    event_type,
    event_details
  ) VALUES (
    v_candidate_user_id,
    'post_sign_in_orphan_flagged',
    jsonb_build_object(
      'secondary_user_id', p_current_user_id,
      'evidence', jsonb_build_array('native_install_id', 'normalized_name'),
      'idempotency_key_sha256',
        encode(extensions.digest(p_idempotency_key, 'sha256'), 'hex')
    )
  );

  INSERT INTO public.user_events (
    user_id,
    event_type,
    metadata
  ) VALUES (
    p_current_user_id,
    'apple_orphan_recovery_flagged',
    jsonb_build_object(
      'detection_surface', 'apple_sign_in',
      'evidence', jsonb_build_array('native_install_id', 'normalized_name'),
      'probable_canonical_user_id', v_candidate_user_id,
      'event_id', 'apple-orphan:' || v_pair_key
    )
  );

  RETURN jsonb_build_object('status', 'flagged');
END;
$$;


ALTER FUNCTION "public"."detect_apple_orphan_after_sign_in"("p_current_user_id" "uuid", "p_apple_sub" "text", "p_native_install_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."detect_apple_orphan_after_sign_in"("p_current_user_id" "uuid", "p_apple_sub" "text", "p_native_install_id" "uuid", "p_idempotency_key" "text") IS 'Service-only post-sign-in detector. Flags one older same-install, exact-name account pair without blocking authentication or mutating auth identities.';



CREATE OR REPLACE FUNCTION "public"."detect_apple_orphan_before_sign_in"("p_apple_sub" "text", "p_native_install_id" "uuid", "p_full_name" "text", "p_token_issued_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_normalized_name text;
  v_candidate_user_id uuid;
  v_candidate_count integer;
  v_apple_sub_sha256 text;
  v_audit_key text;
BEGIN
  IF p_apple_sub IS NULL
     OR length(p_apple_sub) = 0
     OR p_native_install_id IS NULL
     OR p_token_issued_at IS NULL
     OR p_token_issued_at < clock_timestamp() - interval '5 minutes'
     OR p_token_issued_at > clock_timestamp() + interval '30 seconds' THEN
    RAISE EXCEPTION 'invalid apple orphan precheck input';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_constraint current_constraint
    JOIN pg_class source_table ON source_table.oid = current_constraint.conrelid
    JOIN pg_namespace source_ns ON source_ns.oid = source_table.relnamespace
    JOIN pg_class target_table ON target_table.oid = current_constraint.confrelid
    JOIN pg_namespace target_ns ON target_ns.oid = target_table.relnamespace
    WHERE current_constraint.contype = 'f'
      AND source_ns.nspname = 'public'
      AND current_constraint.confrelid IN (
        'auth.users'::regclass,
        'public.profiles'::regclass
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.apple_recovery_dependency_registry registry
        WHERE registry.source_schema = source_ns.nspname
          AND registry.source_table = source_table.relname
          AND registry.constraint_name = current_constraint.conname
          AND registry.target_schema = target_ns.nspname
          AND registry.target_table = target_table.relname
      )
  ) THEN
    RETURN jsonb_build_object('status', 'schema_coverage_incomplete');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM auth.identities identity_row
    JOIN auth.users identity_user ON identity_user.id = identity_row.user_id
    WHERE identity_row.provider = 'apple'
      AND identity_user.deleted_at IS NULL
      AND (
        identity_row.provider_id = p_apple_sub
        OR identity_row.identity_data->>'sub' = p_apple_sub
      )
  ) THEN
    RETURN jsonb_build_object('status', 'apple_sub_claimed');
  END IF;

  v_normalized_name := lower(
    regexp_replace(trim(coalesce(p_full_name, '')), '[^[:alnum:]]+', '', 'g')
  );
  IF v_normalized_name = '' THEN
    RETURN jsonb_build_object('status', 'unclaimed_no_match');
  END IF;

  WITH candidate_users AS MATERIALIZED (
    SELECT DISTINCT event_row.user_id
    FROM public.user_events event_row
    WHERE event_row.user_id IS NOT NULL
      AND event_row.metadata->>'native_install_id' = p_native_install_id::text
  ),
  named_candidates AS (
    SELECT candidate_user.id
    FROM candidate_users candidate
    JOIN auth.users candidate_user ON candidate_user.id = candidate.user_id
    LEFT JOIN public.profiles candidate_profile
      ON candidate_profile.id = candidate_user.id
     AND candidate_profile.deleted_at IS NULL
    WHERE candidate_user.deleted_at IS NULL
      AND candidate_user.created_at < p_token_issued_at
      AND lower(
        regexp_replace(
          trim(
            coalesce(
              nullif(candidate_profile.full_name, ''),
              nullif(candidate_profile.display_name, ''),
              nullif(candidate_user.raw_user_meta_data->>'full_name', ''),
              nullif(candidate_user.raw_user_meta_data->>'name', ''),
              nullif(
                concat_ws(
                  ' ',
                  candidate_user.raw_user_meta_data->>'given_name',
                  candidate_user.raw_user_meta_data->>'family_name'
                ),
                ''
              )
            )
          ),
          '[^[:alnum:]]+',
          '',
          'g'
        )
      ) = v_normalized_name
  )
  SELECT count(*), (array_agg(id ORDER BY id))[1]
  INTO v_candidate_count, v_candidate_user_id
  FROM named_candidates;

  IF v_candidate_count <> 1 OR v_candidate_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'unclaimed_no_match');
  END IF;

  v_apple_sub_sha256 := encode(
    extensions.digest(p_apple_sub, 'sha256'),
    'hex'
  );
  v_audit_key := v_candidate_user_id::text || ':' || v_apple_sub_sha256;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_audit_key, 0));

  IF NOT EXISTS (
    SELECT 1
    FROM public.apple_identity_recovery_audit audit_row
    WHERE audit_row.canonical_user_id = v_candidate_user_id
      AND audit_row.event_type = 'pre_sign_in_orphan_prevented'
      AND audit_row.event_details->>'apple_sub_sha256' = v_apple_sub_sha256
  ) THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type,
      event_details
    ) VALUES (
      v_candidate_user_id,
      'pre_sign_in_orphan_prevented',
      jsonb_build_object(
        'apple_sub_sha256', v_apple_sub_sha256,
        'evidence', jsonb_build_array('native_install_id', 'normalized_name')
      )
    );
  END IF;

  RETURN jsonb_build_object('status', 'prevent');
END;
$$;


ALTER FUNCTION "public"."detect_apple_orphan_before_sign_in"("p_apple_sub" "text", "p_native_install_id" "uuid", "p_full_name" "text", "p_token_issued_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."detect_apple_orphan_before_sign_in"("p_apple_sub" "text", "p_native_install_id" "uuid", "p_full_name" "text", "p_token_issued_at" timestamp with time zone) IS 'Service-only pre-sign-in detector. A stable native install ID is expected to survive app updates and relaunches but may reset on uninstall/reinstall, which weakens prevention to the post-sign-in backstop.';



CREATE OR REPLACE FUNCTION "public"."dev_log_session_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_pid_info record;
BEGIN
  v_user_id := COALESCE(NEW.user_id, OLD.user_id);
  IF v_user_id <> '73040cff-afe9-4fa0-a874-2016203fc015'::uuid THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT application_name, client_addr, query
    INTO v_pid_info
    FROM pg_stat_activity
   WHERE pid = pg_backend_pid();

  INSERT INTO public.dev_session_mutation_audit
    (op, user_id, session_id, old_row, new_row,
     application_name, client_addr, current_user_role, session_user_role,
     current_query)
  VALUES
    (TG_OP, v_user_id, COALESCE(NEW.id, OLD.id),
     to_jsonb(OLD), to_jsonb(NEW),
     v_pid_info.application_name, v_pid_info.client_addr,
     current_user::name, session_user::name,
     v_pid_info.query);

  RETURN COALESCE(NEW, OLD);
END
$$;


ALTER FUNCTION "public"."dev_log_session_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_experiment_assignment_write_once"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.experiment_key IS DISTINCT FROM OLD.experiment_key
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.arm IS DISTINCT FROM OLD.arm
     OR NEW.index_at IS DISTINCT FROM OLD.index_at
     OR NEW.assignment_version IS DISTINCT FROM OLD.assignment_version
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'experiment_assignments core columns are immutable';
  END IF;
  IF OLD.build IS NOT NULL AND NEW.build IS DISTINCT FROM OLD.build THEN
    RAISE EXCEPTION 'experiment_assignments.build is write-once';
  END IF;
  IF OLD.source IS NOT NULL AND NEW.source IS DISTINCT FROM OLD.source THEN
    RAISE EXCEPTION 'experiment_assignments.source is write-once';
  END IF;
  IF OLD.linked_at IS NOT NULL AND NEW.linked_at IS DISTINCT FROM OLD.linked_at THEN
    RAISE EXCEPTION 'experiment_assignments.linked_at is write-once';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_experiment_assignment_write_once"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_user_xp"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'ensure_user_xp: p_user_id is required';
  END IF;

  IF auth.uid() IS NULL THEN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
      RAISE EXCEPTION 'ensure_user_xp: caller must be authenticated';
    END IF;
  ELSIF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ensure_user_xp: caller may only initialize XP for self';
  END IF;

  INSERT INTO public.user_xp (user_id, xp_total, level)
  VALUES (p_user_id, 0, 1)
  ON CONFLICT (user_id) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."ensure_user_xp"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_user_xp"("p_user_id" "uuid") IS 'Idempotent SECURITY DEFINER initializer for user_xp zero rows; authenticated users may initialize only themselves.';



CREATE OR REPLACE FUNCTION "public"."erase_regional_recommendation_hold_operator_v1"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted integer := 0;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'operator erasure requires a user id'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('regional-hold-operator:' || p_user_id::text, 0)
  );

  DELETE FROM public.regional_recommendation_hold_operator_refs
  WHERE operator_user_id = p_user_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object('mapping_deleted', v_deleted > 0);
END;
$$;


ALTER FUNCTION "public"."erase_regional_recommendation_hold_operator_v1"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."experiment_arm"("p_user_id" "uuid", "p_experiment_key" "text") RETURNS smallint
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT (get_byte(
    digest(convert_to(p_user_id::text || ':' || p_experiment_key, 'UTF8'), 'sha256'),
    0
  ) % 2)::smallint;
$$;


ALTER FUNCTION "public"."experiment_arm"("p_user_id" "uuid", "p_experiment_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."export_android_tester_roster_non_pii"() RETURNS TABLE("entry_id" "uuid", "eligibility_status" "text", "group_membership_status" "text", "eligibility_source" "text", "eligibility_observed_at" timestamp with time zone, "eligibility_confidence" "text", "purge_after" timestamp with time zone, "linked" boolean, "stage" "text", "stage_status" "text", "stage_source" "text", "stage_observed_at" timestamp with time zone, "stage_confidence" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    entry.id,
    entry.eligibility_status,
    entry.group_membership_status,
    entry.eligibility_source,
    entry.eligibility_observed_at,
    entry.eligibility_confidence,
    entry.purge_after,
    entry.user_id IS NOT NULL,
    stage.stage,
    stage.status,
    stage.source,
    stage.observed_at,
    stage.confidence
  FROM public.android_tester_roster_entries AS entry
  LEFT JOIN public.android_tester_roster_stages AS stage
    ON stage.entry_id = entry.id
  ORDER BY entry.created_at, stage.observed_at;
$$;


ALTER FUNCTION "public"."export_android_tester_roster_non_pii"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_community_spot_photo_upload_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_reason_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  upload_key uuid;
BEGIN
  SELECT idempotency_key INTO upload_key
  FROM public.community_spot_photos
  WHERE id = p_photo_id AND uploader_id = p_uploader_id
  FOR UPDATE;
  IF upload_key IS NULL THEN
    RETURN false;
  END IF;
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  ) VALUES (
    p_photo_id, p_uploader_id, 'upload_failed', 'failed',
    left(p_reason_code, 64), upload_key
  )
  ON CONFLICT (actor_id, action, idempotency_key) DO UPDATE
  SET photo_id = EXCLUDED.photo_id,
      outcome = EXCLUDED.outcome,
      reason_code = EXCLUDED.reason_code;
  DELETE FROM public.community_spot_photos
  WHERE id = p_photo_id AND uploader_id = p_uploader_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fail_community_spot_photo_upload_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_anon_alert_capture"("p_user_id" "uuid", "p_email" "text") RETURNS TABLE("capture_id" "uuid", "beach_id" "uuid", "preset_type" "text", "return_path" "text", "captured_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimed_captures AS (
    UPDATE public.pending_alert_captures AS pac
    SET
      consumed_at = NOW(),
      consumed_user_id = p_user_id
    WHERE pac.email = lower(p_email)
      AND pac.consumed_at IS NULL
      AND pac.expires_at > NOW()
    RETURNING
      pac.id AS capture_id,
      pac.beach_id,
      pac.preset_type,
      pac.return_path,
      pac.captured_at
  ),
  inserted_rules AS (
    INSERT INTO public.alert_rules (
      user_id,
      beach_id,
      name,
      preset_type,
      conditions,
      notify_email,
      notify_push,
      enabled
    )
    SELECT
      p_user_id,
      cc.beach_id,
      public.preset_default_name(cc.preset_type, cc.beach_id),
      cc.preset_type,
      public.preset_default_conditions(cc.preset_type, cc.beach_id),
      true,
      false,
      true
    FROM claimed_captures cc
    RETURNING public.alert_rules.id
  ),
  first_claim AS (
    SELECT cc.beach_id
    FROM claimed_captures cc
    ORDER BY cc.captured_at ASC
    LIMIT 1
  ),
  updated_profile AS (
    UPDATE public.profiles p
    SET
      home_beach_id = COALESCE(p.home_beach_id, fc.beach_id),
      signup_context = jsonb_set(
        COALESCE(p.signup_context, '{}'::jsonb),
        '{entrypoint}',
        '"anon_alert_capture"'::jsonb
      )
    FROM first_claim fc
    WHERE p.id = p_user_id
    RETURNING p.id
  )
  SELECT
    cc.capture_id,
    cc.beach_id,
    cc.preset_type,
    cc.return_path,
    cc.captured_at
  FROM claimed_captures cc
  ORDER BY cc.captured_at ASC;
END;
$$;


ALTER FUNCTION "public"."finalize_anon_alert_capture"("p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_width" integer, "p_height" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  changed integer;
BEGIN
  UPDATE public.community_spot_photos
  SET processing_status = 'ready',
      moderation_status = 'visible',
      width = p_width,
      height = p_height,
      updated_at = now()
  WHERE id = p_photo_id
    AND uploader_id = p_uploader_id
    AND processing_status = 'processing'
    AND lifecycle_status = 'active';
  GET DIAGNOSTICS changed = ROW_COUNT;
  IF changed = 1 AND NOT EXISTS (
    SELECT 1 FROM public.community_photo_action_events
    WHERE photo_id = p_photo_id AND action = 'upload_ready'
  ) THEN
    INSERT INTO public.community_photo_action_events (
      photo_id, actor_id, action, outcome, reason_code, idempotency_key
    )
    SELECT id, uploader_id, 'upload_ready', 'accepted', 'published', idempotency_key
    FROM public.community_spot_photos WHERE id = p_photo_id;
  END IF;
  RETURN changed = 1;
END;
$$;


ALTER FUNCTION "public"."finalize_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_width" integer, "p_height" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_purged_community_spot_photos_v1"("p_photo_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  )
  SELECT p.id, NULL, 'purge', 'accepted', 'retention_expired', gen_random_uuid()
  FROM public.community_spot_photos p
  WHERE p.id = ANY(p_photo_ids)
    AND p.lifecycle_status = 'purging'
    AND NOT EXISTS (
      SELECT 1 FROM public.community_photo_investigation_holds h
      WHERE h.photo_id = p.id AND h.released_at IS NULL
    );
  DELETE FROM public.community_spot_photos p
  WHERE p.id = ANY(p_photo_ids)
    AND p.lifecycle_status = 'purging'
    AND NOT EXISTS (
      SELECT 1 FROM public.community_photo_investigation_holds h
      WHERE h.photo_id = p.id AND h.released_at IS NULL
    );
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."finalize_purged_community_spot_photos_v1"("p_photo_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_stuck_community_spot_photo_uploads_v1"("p_photo_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  )
  SELECT
    p.id, p.uploader_id, 'upload_failed', 'failed', 'stuck_processing',
    p.idempotency_key
  FROM public.community_spot_photos p
  WHERE p.id = ANY(p_photo_ids) AND p.processing_status = 'cleanup'
  ON CONFLICT (actor_id, action, idempotency_key) DO NOTHING;
  DELETE FROM public.community_spot_photos p
  WHERE p.id = ANY(p_photo_ids) AND p.processing_status = 'cleanup';
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."finalize_stuck_community_spot_photo_uploads_v1"("p_photo_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_cities_by_pattern"("search_pattern" "text", "state_filter" "text" DEFAULT NULL::"text") RETURNS TABLE("city" "text", "state" "text", "beach_count" bigint, "is_exact_match" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    b.city,
    b.state,
    COUNT(*)::BIGINT as beach_count,
    -- Exact match: normalized city equals normalized search pattern
    (unaccent(lower(b.city)) = unaccent(lower(search_pattern)) OR
     unaccent(lower(replace(b.city, '-', ' '))) = unaccent(lower(search_pattern))) as is_exact_match
  FROM beaches b
  WHERE (b.is_private IS NULL OR b.is_private = false)
    AND (state_filter IS NULL OR b.state = state_filter)
    AND (
      -- Match with unaccent (handles Rincon vs rincon)
      unaccent(lower(b.city)) ILIKE '%' || unaccent(lower(search_pattern)) || '%'
      OR
      -- Match with hyphen normalization (handles Cardiff-by-the-Sea vs cardiff by the sea)
      unaccent(lower(replace(b.city, '-', ' '))) ILIKE '%' || unaccent(lower(search_pattern)) || '%'
    )
  GROUP BY b.city, b.state
  ORDER BY
    -- Exact matches first
    (unaccent(lower(b.city)) = unaccent(lower(search_pattern)) OR
     unaccent(lower(replace(b.city, '-', ' '))) = unaccent(lower(search_pattern))) DESC,
    -- Then by beach count (more beaches = more popular)
    COUNT(*) DESC;
END;
$$;


ALTER FUNCTION "public"."find_cities_by_pattern"("search_pattern" "text", "state_filter" "text") OWNER TO "postgres";


