CREATE OR REPLACE FUNCTION "public"."find_nearest_beach_id"("post_lat" numeric, "post_lon" numeric, "max_distance_meters" double precision DEFAULT 3218.69) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  nearest_id UUID;
BEGIN
  IF post_lat IS NULL OR post_lon IS NULL
     OR post_lat = 0 OR post_lon = 0
     OR post_lat < -90 OR post_lat > 90
     OR post_lon < -180 OR post_lon > 180 THEN
    RETURN NULL;
  END IF;

  SELECT b.id INTO nearest_id
  FROM public.beaches b
  WHERE b.geog IS NOT NULL
    AND ST_DWithin(
      b.geog,
      ST_SetSRID(ST_MakePoint(post_lon, post_lat), 4326)::geography,
      max_distance_meters
    )
  ORDER BY ST_Distance(
    b.geog,
    ST_SetSRID(ST_MakePoint(post_lon, post_lat), 4326)::geography
  )
  LIMIT 1;

  RETURN nearest_id;
END;
$$;


ALTER FUNCTION "public"."find_nearest_beach_id"("post_lat" numeric, "post_lon" numeric, "max_distance_meters" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_nearest_beach_id"("post_lat" numeric, "post_lon" numeric, "max_distance_meters" double precision) IS 'Finds the nearest beach within a given radius of the specified coordinates. Uses the pre-computed geog column with GiST index for optimal performance. Default radius is 2 miles (3218.69 meters).';



CREATE OR REPLACE FUNCTION "public"."find_orphaned_session_media"() RETURNS TABLE("storage_path" "text", "media_id" "uuid", "deleted_at" timestamp with time zone, "days_since_deletion" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- Only admins can run this query
    IF NOT public.is_admin_user() THEN
        RAISE EXCEPTION 'Only administrators can query orphaned media';
    END IF;

    RETURN QUERY
    SELECT
        sm.storage_path,
        sm.id as media_id,
        sm.deleted_at,
        EXTRACT(DAY FROM (NOW() - sm.deleted_at))::INTEGER as days_since_deletion
    FROM public.session_media sm
    WHERE sm.deleted_at IS NOT NULL
    AND sm.deleted_at < NOW() - INTERVAL '7 days'  -- Grace period
    ORDER BY sm.deleted_at ASC;
END;
$$;


ALTER FUNCTION "public"."find_orphaned_session_media"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_orphaned_session_media"() IS 'Admin function to find soft-deleted media records older than 7 days.
These records indicate storage files that should be cleaned up.
Returns storage paths for bulk cleanup operations.';



CREATE OR REPLACE FUNCTION "public"."follow_user_with_notification"("p_target_user_id" "uuid", "p_actor_id" "uuid", "p_dedupe_key" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_event_id uuid;
  v_dedup_collision boolean := false;
  v_existing_id uuid;
BEGIN
  IF p_actor_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'actor_id mismatch: must match auth.uid()';
  END IF;

  IF p_actor_id = p_target_user_id THEN
    RAISE EXCEPTION 'cannot follow yourself';
  END IF;

  SELECT id INTO v_existing_id
    FROM user_follows
    WHERE follower_id = p_actor_id AND following_id = p_target_user_id;

  IF v_existing_id IS NOT NULL THEN
    RETURN json_build_object(
      'followed', true,
      'was_existing', true,
      'event_id', null,
      'notification_dedup_collision', false
    );
  END IF;

  INSERT INTO user_follows (follower_id, following_id)
    VALUES (p_actor_id, p_target_user_id);

  BEGIN
    INSERT INTO notification_events (
      recipient_user_id, actor_user_id, type,
      entity_type, entity_id, payload, dedupe_key
    ) VALUES (
      p_target_user_id, p_actor_id, 'follow',
      'user', p_target_user_id,
      '{}'::jsonb,
      p_dedupe_key
    )
    RETURNING id INTO v_event_id;
  EXCEPTION WHEN unique_violation THEN
    v_dedup_collision := true;
    v_event_id := null;
  END;

  RETURN json_build_object(
    'followed', true,
    'was_existing', false,
    'event_id', v_event_id,
    'notification_dedup_collision', v_dedup_collision
  );
END;
$$;


ALTER FUNCTION "public"."follow_user_with_notification"("p_target_user_id" "uuid", "p_actor_id" "uuid", "p_dedupe_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_referral_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    new_code TEXT;
    code_exists BOOLEAN;
    max_attempts INTEGER := 10;
    attempt INTEGER := 0;
BEGIN
    -- Try to generate a unique code (max 10 attempts to avoid infinite loops)
    LOOP
        -- Generate 6-character alphanumeric code
        new_code := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 6));

        -- Check if code already exists (case-insensitive)
        SELECT EXISTS (
            SELECT 1 FROM public.profiles
            WHERE LOWER(referral_code) = LOWER(new_code)
        ) INTO code_exists;

        -- Exit if unique code found
        EXIT WHEN NOT code_exists;

        -- Increment attempt counter
        attempt := attempt + 1;

        -- Raise exception if max attempts reached
        IF attempt >= max_attempts THEN
            RAISE EXCEPTION 'Failed to generate unique referral code after % attempts', max_attempts;
        END IF;
    END LOOP;

    RETURN new_code;
END;
$$;


ALTER FUNCTION "public"."generate_referral_code"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_referral_code"() IS 'Generates a unique 6-character alphanumeric referral code (case-insensitive uniqueness check)';



CREATE OR REPLACE FUNCTION "public"."generate_surf_drop_slug"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  alphabet text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  bytes bytea := gen_random_bytes(10);
  result text := '';
  i integer;
BEGIN
  FOR i IN 0..9 LOOP
    result := result || substr(alphabet, (get_byte(bytes, i) % length(alphabet)) + 1, 1);
  END LOOP;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."generate_surf_drop_slug"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_community_spot_photo_image_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_audit_id" "uuid") RETURNS TABLE("storage_path" "text", "content_type" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  resolved_storage_path text;
  resolved_content_type text;
  previous_photo_id uuid;
  previous_action text;
BEGIN
  SELECT e.photo_id, e.action INTO previous_photo_id, previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_audit_id;
  IF previous_action IS NOT NULL AND (
    previous_action <> 'admin_view_hidden' OR previous_photo_id <> p_photo_id
  ) THEN
    RAISE EXCEPTION 'idempotency_conflict';
  END IF;

  SELECT p.storage_path, p.content_type
    INTO resolved_storage_path, resolved_content_type
  FROM public.community_spot_photos p
  WHERE p.id = p_photo_id
    AND p.processing_status = 'ready'
    AND p.moderation_status = 'hidden'
    AND p.lifecycle_status IN ('active', 'removed')
  FOR SHARE;
  IF resolved_storage_path IS NULL THEN
    RAISE EXCEPTION 'photo_not_found';
  END IF;

  IF previous_action IS NULL THEN
    INSERT INTO public.community_photo_moderation_events (
      photo_id, actor_id, action, reason, idempotency_key
    ) VALUES (
      p_photo_id, p_actor_id, 'admin_view_hidden', 'hidden_media_view',
      p_audit_id
    );
  END IF;
  RETURN QUERY SELECT resolved_storage_path, resolved_content_type;
END;
$$;


ALTER FUNCTION "public"."get_admin_community_spot_photo_image_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_audit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_beach_locations"() RETURNS TABLE("country" "text", "state" "text", "city" "text", "beach_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    b.country,
    b.state,
    b.city,
    COUNT(*) as beach_count
  FROM beaches b
  WHERE b.is_private = false
    AND b.city IS NOT NULL
    AND b.state IS NOT NULL
    AND b.country IS NOT NULL
  GROUP BY b.country, b.state, b.city
  HAVING COUNT(*) >= 1
  ORDER BY beach_count DESC, b.country, b.state, b.city;
END;
$$;


ALTER FUNCTION "public"."get_all_beach_locations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_all_beach_locations"() IS 'Returns all unique location combinations (city, state, country) with at least 1 beach.
Used for Next.js static generation of location pages and sitemaps.';



CREATE OR REPLACE FUNCTION "public"."get_android_tester_roster_join_context"("p_user_id" "uuid", "p_idempotency_key_hash" "text") RETURNS TABLE("snapshot_complete" boolean, "already_linked" boolean, "candidates" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_snapshot_complete boolean := false;
  v_already_linked boolean := false;
  v_linked_entry_id uuid;
  v_candidates jsonb := '[]'::jsonb;
BEGIN
  IF p_idempotency_key_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN;
  END IF;

  SELECT run.complete
  INTO v_snapshot_complete
  FROM public.android_tester_roster_sync_runs AS run
  ORDER BY run.observed_at DESC, run.created_at DESC
  LIMIT 1;

  SELECT join_evidence.entry_id
  INTO v_linked_entry_id
  FROM public.android_tester_roster_join_evidence AS join_evidence
  WHERE join_evidence.user_id = p_user_id
    AND join_evidence.idempotency_key_hash = p_idempotency_key_hash
  LIMIT 1;

  v_already_linked := v_linked_entry_id IS NOT NULL;
  IF v_already_linked THEN
    INSERT INTO public.android_tester_roster_audit (
      actor_user_id,
      entry_id,
      action,
      outcome
    ) VALUES (
      NULL,
      v_linked_entry_id,
      'join',
      'same_key_retry'
    );
  END IF;

  IF COALESCE(v_snapshot_complete, false) AND NOT v_already_linked THEN
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'entry_id', entry.id,
          'key_version', identity.key_version,
          'iv', identity.iv,
          'ciphertext', identity.ciphertext,
          'auth_tag', identity.auth_tag
        )
        ORDER BY entry.created_at
      ),
      '[]'::jsonb
    )
    INTO v_candidates
    FROM public.android_tester_roster_entries AS entry
    JOIN public.android_tester_roster_identities AS identity
      ON identity.entry_id = entry.id
    WHERE entry.eligibility_status = 'eligible'
      AND entry.group_membership_status = 'active'
      AND entry.user_id IS NULL;
  END IF;

  RETURN QUERY SELECT
    COALESCE(v_snapshot_complete, false),
    v_already_linked,
    v_candidates;
END;
$_$;


ALTER FUNCTION "public"."get_android_tester_roster_join_context"("p_user_id" "uuid", "p_idempotency_key_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_android_tester_roster_summary"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH latest_stage AS (
    SELECT DISTINCT ON (entry_id, stage)
      entry_id,
      stage,
      status
    FROM public.android_tester_roster_stages
    ORDER BY entry_id, stage, observed_at DESC, id DESC
  )
  SELECT jsonb_build_object(
    'eligible', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE eligibility_status = 'eligible'
    ),
    'ineligible', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE eligibility_status = 'ineligible'
    ),
    'linkedAccounts', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE user_id IS NOT NULL
    ),
    'unjoinedIdentities', (
      SELECT count(*)
      FROM public.android_tester_roster_entries AS entry
      WHERE entry.user_id IS NULL
        AND EXISTS (
          SELECT 1
          FROM public.android_tester_roster_identities AS identity
          WHERE identity.entry_id = entry.id
        )
    ),
    'purgeScheduled', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE purge_after IS NOT NULL
    ),
    'stageCounts', jsonb_build_object(
      'group_eligibility', jsonb_build_object(
        'eligible', count(*) FILTER (
          WHERE stage = 'group_eligibility' AND status = 'eligible'
        ),
        'ineligible', count(*) FILTER (
          WHERE stage = 'group_eligibility' AND status = 'ineligible'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'group_eligibility' AND status = 'unknown'
        )
      ),
      'play_opt_in', jsonb_build_object(
        'observed', count(*) FILTER (
          WHERE stage = 'play_opt_in' AND status = 'observed'
        ),
        'notObserved', count(*) FILTER (
          WHERE stage = 'play_opt_in' AND status = 'not_observed'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'play_opt_in' AND status = 'unknown'
        )
      ),
      'install', jsonb_build_object(
        'observed', count(*) FILTER (
          WHERE stage = 'install' AND status = 'observed'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'install' AND status = 'unknown'
        )
      ),
      'first_open', jsonb_build_object(
        'observed', count(*) FILTER (
          WHERE stage = 'first_open' AND status = 'observed'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'first_open' AND status = 'unknown'
        )
      ),
      'account_join', jsonb_build_object(
        'linked', count(*) FILTER (
          WHERE stage = 'account_join' AND status = 'linked'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'account_join' AND status = 'unknown'
        )
      )
    )
  )
  FROM latest_stage;
$$;


