COMMENT ON FUNCTION "public"."get_beaches_by_metro_with_scores"("p_cities" "text"[], "p_state" "text", "p_country" "text") IS 'Retrieves beaches across multiple cities in a metro area with composite scores.
Useful for aggregate views like "San Diego Area" which includes La Jolla, Pacific Beach, etc.
Uses lat/lon columns (not latitude/longitude).';



CREATE OR REPLACE FUNCTION "public"."get_beaches_near"("_lat" double precision, "_lon" double precision, "_radius_km" double precision DEFAULT 25) RETURNS TABLE("id" "uuid", "name" "text", "lat" double precision, "lon" double precision, "break_type" "text", "aspect_deg" integer, "wind_offshore_deg" integer, "swell_window_center_deg" integer, "swell_window_halfwidth_deg" integer, "preferred_tide_ft_min" numeric, "preferred_tide_ft_max" numeric, "wind_cross_shore_ok_kt" integer, "wind_onshore_bad_kt" integer, "dist_km" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT
      b.id,
      b.name,
      b.lat,  -- FIXED: was b.latitude AS lat
      b.lon,  -- FIXED: was b.longitude AS lon
      b.break_type,
      b.aspect_deg,
      b.wind_offshore_deg,  -- FIXED: was offshore_deg
      b.swell_window_center_deg,
      b.swell_window_halfwidth_deg,
      b.preferred_tide_ft_min,  -- FIXED: was tide_min_ft
      b.preferred_tide_ft_max,  -- FIXED: was tide_max_ft
      b.wind_cross_shore_ok_kt,  -- FIXED: was wind_cross_ok_kts
      b.wind_onshore_bad_kt,  -- FIXED: was wind_onshore_bad_kts
      -- Haversine (spherical law of cosines) with clamped argument
      6371 * acos(
        LEAST(1.0, GREATEST(-1.0,
          cos(radians(_lat)) * cos(radians(b.lat)) * cos(radians(b.lon) - radians(_lon))  -- FIXED: was b.latitude and b.longitude
          + sin(radians(_lat)) * sin(radians(b.lat))  -- FIXED: was b.latitude
        ))
      ) AS dist_km
    FROM public.beaches b
    WHERE b.lat IS NOT NULL AND b.lon IS NOT NULL  -- FIXED: was b.latitude and b.longitude
  )
  SELECT *
  FROM base
  WHERE dist_km <= _radius_km
  ORDER BY dist_km
  LIMIT 12;
$$;


ALTER FUNCTION "public"."get_beaches_near"("_lat" double precision, "_lon" double precision, "_radius_km" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_best_times"("p_beach" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_limit" integer DEFAULT 6) RETURNS TABLE("start_ts" timestamp with time zone, "end_ts" timestamp with time zone, "label" "text", "score" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
WITH params AS (
  SELECT 
    b.id AS beach_id,
    b.wind_offshore_deg,
    b.wind_cross_shore_ok_kt,
    b.preferred_tide_ft_min,
    b.preferred_tide_ft_max,
    ((b.swell_window_max_deg - b.swell_window_min_deg + 360) % 360) AS swell_span,
    b.swell_window_min_deg AS swell_min
  FROM public.beaches b
  WHERE b.id = p_beach
),
hrs AS (
  SELECT generate_series(
           date_trunc('hour', p_start),
           date_trunc('hour', p_end),
           interval '1 hour'
         ) AS ts_utc
),
nearest AS (
  SELECT
    h.ts_utc,
    -- nearest marine within ±6 hours
    (
      SELECT m.ts FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS m_ts,
    (
      SELECT m.wave_height_m FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wave_height_m,
    (
      SELECT m.wave_period_s FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wave_period_s,
    (
      SELECT m.wave_direction_deg FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wave_direction_deg,
    (
      SELECT m.wind_speed_ms FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wind_speed_ms,
    (
      SELECT m.wind_direction_deg FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wind_direction_deg,
    -- nearest tide within ±90 minutes
    (
      SELECT t.tide_height_m FROM public.tide_forecasts t
      WHERE t.beach_id = p_beach
        AND t.ts BETWEEN h.ts_utc - interval '90 minutes' AND h.ts_utc + interval '90 minutes'
      ORDER BY ABS(EXTRACT(EPOCH FROM (t.ts - h.ts_utc)))
      LIMIT 1
    ) AS tide_height_m
  FROM hrs h
),
scored AS (
  SELECT
    n.ts_utc,
    -- Wind score
    GREATEST(
      0,
      (1 + COS(RADIANS(ABS(MOD(((n.wind_direction_deg)::int - p.wind_offshore_deg + 540),360) - 180))))/2
      * (1 - GREATEST(0, ((COALESCE(n.wind_speed_ms,0) * 1.94384449) - p.wind_cross_shore_ok_kt)::float / 10.0))
    ) AS wind_score,
    -- Tide score (ft band triangle)
    COALESCE(
      GREATEST(
        0,
        1 - ABS(((n.tide_height_m * 3.28084)) - ((p.preferred_tide_ft_min + p.preferred_tide_ft_max)/2.0))
              / NULLIF((p.preferred_tide_ft_max - p.preferred_tide_ft_min)/2.0,0)
      ), 0
    )::numeric AS tide_score,
    -- Swell direction score
    GREATEST(
      0,
      1 - GREATEST(
            0,
            ABS(MOD(((n.wave_direction_deg)::int - ((p.swell_min + p.swell_span/2.0)) + 540)::int, 360) - 180) - (p.swell_span/2.0)
          )::float / 30.0
    ) AS swell_dir_score,
    0.0 AS period_score,
    0.0 AS height_score,
    -- Total score
    ROUND(
      100 * GREATEST(
        0,
        (0.4 * GREATEST(0,
          (1 + COS(RADIANS(ABS(MOD(((n.wind_direction_deg)::int - p.wind_offshore_deg + 540),360) - 180))))/2
          * (1 - GREATEST(0, ((COALESCE(n.wind_speed_ms,0) * 1.94384449) - p.wind_cross_shore_ok_kt)::float / 10.0))
        ))
        + (0.2 * COALESCE(
          GREATEST(
            0,
            1 - ABS(((n.tide_height_m * 3.28084)) - ((p.preferred_tide_ft_min + p.preferred_tide_ft_max)/2.0))
                  / NULLIF((p.preferred_tide_ft_max - p.preferred_tide_ft_min)/2.0,0)
          ), 0
        ))
        + (0.4 * GREATEST(
          0,
          1 - GREATEST(0, ABS(MOD(((n.wave_direction_deg)::int - ((p.swell_min + p.swell_span/2.0)) + 540)::int, 360) - 180) - (p.swell_span/2.0))::float / 30.0
        ))
      )
    )::int AS score_0_100
  FROM nearest n
  JOIN params p ON TRUE
  WHERE n.m_ts IS NOT NULL -- require a marine reference within window
),
win AS (
  SELECT
    h1.ts_utc                       AS start_ts,
    h1.ts_utc + interval '2 hour'   AS end_ts,
    round(avg(h2.score_0_100))::int AS score
  FROM scored h1
  JOIN scored h2
    ON h2.ts_utc BETWEEN h1.ts_utc AND h1.ts_utc + interval '1 hour'
  GROUP BY h1.ts_utc
),
ranked AS (
  SELECT
    w.*,
    CASE
      WHEN w.score >= 85 THEN 'epic'
      WHEN w.score >= 70 THEN 'good'
      WHEN w.score >= 55 THEN 'fair'
      ELSE 'poor'
    END AS grade
  FROM win w
  WHERE w.score >= 55
)
SELECT
  r.start_ts,
  r.end_ts,
  (r.grade || ' (' || r.score || ')')::text AS label,
  r.score
FROM ranked r
ORDER BY r.score DESC, r.start_ts
LIMIT p_limit;
$$;


ALTER FUNCTION "public"."get_best_times"("p_beach" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bulk_current_forecasts"("p_beach_ids" "uuid"[], "p_target_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("beach_id" "uuid", "wave_height" "text", "forecast_date" "date", "forecast_time" time without time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH ranked AS (
    SELECT
      ef.beach_id,
      ef.wave_height,
      ef.forecast_date,
      ef.forecast_time,
      ROW_NUMBER() OVER (
        PARTITION BY ef.beach_id
        ORDER BY
          CASE
            WHEN ef.forecast_date = p_target_date
                 AND ef.forecast_time >= CURRENT_TIME THEN 1
            WHEN ef.forecast_date = p_target_date + 1 THEN 2
            ELSE 3
          END ASC,
          CASE
            WHEN ef.forecast_date = p_target_date
                 AND ef.forecast_time < CURRENT_TIME
            THEN -EXTRACT(EPOCH FROM ef.forecast_time)
            ELSE  EXTRACT(EPOCH FROM ef.forecast_time)
          END ASC
      ) AS rn
    FROM enhanced_forecasts ef
    WHERE ef.beach_id = ANY(p_beach_ids)
      AND ef.forecast_date IN (p_target_date, p_target_date + 1)
  )
  SELECT r.beach_id, r.wave_height, r.forecast_date, r.forecast_time
  FROM ranked r
  WHERE r.rn = 1;
$$;


ALTER FUNCTION "public"."get_bulk_current_forecasts"("p_beach_ids" "uuid"[], "p_target_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_bulk_current_forecasts"("p_beach_ids" "uuid"[], "p_target_date" "date") IS 'Returns the current/next forecast wave_height for each beach. wave_height is the per-beach face-Hs from the transformer (lib/utils/wave-height-transformer.ts). Used by /api/forecasts/bulk to avoid PostgREST row-limit truncation.';



CREATE OR REPLACE FUNCTION "public"."get_cities_with_beach_skills"("min_beaches" integer DEFAULT 1) RETURNS TABLE("city" "text", "state" "text", "country" "text", "beach_count" bigint, "has_beginner" boolean, "has_advanced" boolean, "has_editorial" boolean, "has_least_crowded" boolean, "has_tide_data" boolean, "has_water_temp_data" boolean)
    LANGUAGE "sql" STABLE
    AS $_$
  SELECT
    b.city,
    b.state,
    COALESCE(b.country, 'USA') as country,
    COUNT(*) as beach_count,
    bool_or(
      LOWER(COALESCE(b.skill_level, '')) LIKE '%beginner%'
      OR LOWER(COALESCE(b.skill_level, '')) LIKE '%longboard%'
    ) as has_beginner,
    bool_or(
      LOWER(COALESCE(b.skill_level, '')) LIKE '%advanced%'
      OR LOWER(COALESCE(b.skill_level, '')) LIKE '%expert%'
    ) as has_advanced,
    COUNT(*) FILTER (
      WHERE COALESCE(b.description, '') <> ''
      AND (
        COALESCE(b.crowd_tips, '') <> ''
        OR COALESCE(b.wave_tips, '') <> ''
        OR COALESCE(b.best_conditions_prose, '') <> ''
      )
    ) >= 2 as has_editorial,
    bool_or(
      LOWER(COALESCE(b.crowd_level, '')) IN ('light', 'moderate')
    ) as has_least_crowded,
    bool_or(
      EXISTS (
        SELECT 1
        FROM enhanced_forecasts ef
        WHERE ef.beach_id = b.id
          AND ef.forecast_at >= date_trunc('day', now())
          AND ef.forecast_at < date_trunc('day', now()) + interval '1 day'
          AND (
            CASE
              WHEN jsonb_typeof(ef.raw_forecast -> 'tide_schedule') = 'array'
              THEN jsonb_array_length(ef.raw_forecast -> 'tide_schedule') >= 2
              ELSE false
            END
            OR ef.tide_status IS NOT NULL
            OR ef.tide_height IS NOT NULL
            OR ef.next_tide_time IS NOT NULL
            OR ef.next_tide_type IS NOT NULL
            OR ef.next_tide_height IS NOT NULL
          )
        LIMIT 1
      )
    ) as has_tide_data,
    bool_or(
      EXISTS (
        SELECT 1
        FROM enhanced_forecasts ef
        WHERE ef.beach_id = b.id
          AND ef.forecast_at >= now() - interval '7 days'
          AND ef.water_temp IS NOT NULL
          AND CASE
            WHEN regexp_replace(ef.water_temp::text, '[°Ff[:space:]]', '', 'g') ~ '^[0-9]+(\.[0-9]+)?$'
            THEN regexp_replace(ef.water_temp::text, '[°Ff[:space:]]', '', 'g')::numeric BETWEEN 30 AND 90
            ELSE false
          END
        LIMIT 1
      )
    ) as has_water_temp_data
  FROM beaches b
  WHERE (b.is_private IS NULL OR b.is_private = false)
    AND b.city IS NOT NULL
    AND b.state IS NOT NULL
    AND b.deleted_at IS NULL
  GROUP BY b.city, b.state, b.country
  HAVING COUNT(*) >= min_beaches
  ORDER BY b.city ASC
$_$;


ALTER FUNCTION "public"."get_cities_with_beach_skills"("min_beaches" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_cities_with_beach_skills"("min_beaches" integer) IS 'Returns cities with at least min_beaches beaches, including skill level, editorial, crowd, and data-backed intent availability flags.
has_beginner includes beginner and longboard skill levels (not lower-intermediate).
has_advanced includes advanced and expert skill levels.
has_editorial is true when >= 2 beaches have description AND at least one of crowd_tips/wave_tips/best_conditions_prose.
has_least_crowded is true when at least one beach has crowd_level of light or moderate.
has_tide_data is true when a city has a current-day enhanced forecast row with tide fields or a tide schedule.
has_water_temp_data is true when a city has water temperature data in enhanced forecasts from the last 7 days.
Used by sitemap generation and intent page static params.';



CREATE TABLE IF NOT EXISTS "public"."city_editorial_content" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "city_slug" "text" NOT NULL,
    "state_slug" "text" DEFAULT 'ca'::"text" NOT NULL,
    "country_slug" "text" DEFAULT 'usa'::"text" NOT NULL,
    "city_name" "text" NOT NULL,
    "region_label" "text" NOT NULL,
    "description" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "session_timing" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "quick_links" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "featured_intents" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "planning_checklist" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "intent" "text",
    "seo_indexable" boolean DEFAULT false NOT NULL,
    "editorial_reviewed_at" timestamp with time zone,
    "editorial_sources" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "seo_intro" "text",
    "seo_local_guidance" "text",
    CONSTRAINT "city_editorial_content_intent_check" CHECK ((("intent" IS NULL) OR ("intent" = ANY (ARRAY['beginner'::"text", 'tide'::"text", 'water-temp'::"text", 'general'::"text", 'least-crowded'::"text", 'longboard'::"text", 'dawn-patrol'::"text", 'sunset'::"text", 'best-time'::"text"])))),
    CONSTRAINT "city_editorial_content_sources_array_check" CHECK (("jsonb_typeof"("editorial_sources") = 'array'::"text"))
);


ALTER TABLE "public"."city_editorial_content" OWNER TO "postgres";


COMMENT ON TABLE "public"."city_editorial_content" IS 'Stores curated editorial content for city landing pages including session timing modules,
quick action links, about section paragraphs, and planning checklists.
This content is shown on /beaches/[country]/[state]/[city] pages when available.
To add editorial content for a new city, insert a row into this table.';



COMMENT ON COLUMN "public"."city_editorial_content"."seo_indexable" IS 'Set true only after human review of the matching city intent content.';



CREATE OR REPLACE FUNCTION "public"."get_city_editorial"("p_city" "text", "p_state" "text" DEFAULT 'ca'::"text", "p_country" "text" DEFAULT 'usa'::"text", "p_intent" "text" DEFAULT NULL::"text") RETURNS "public"."city_editorial_content"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT c.*
  FROM public.city_editorial_content c
  WHERE lower(c.city_slug) = lower(p_city)
    AND lower(c.state_slug) = lower(p_state)
    AND lower(c.country_slug) = lower(p_country)
    AND (
      (p_intent IS NULL AND (c.intent IS NULL OR c.intent = 'general'))
      OR (p_intent IS NOT NULL AND c.intent IS NOT DISTINCT FROM p_intent)
    )
  ORDER BY
    CASE WHEN c.editorial_reviewed_at IS NULL THEN 1 ELSE 0 END,
    c.editorial_reviewed_at DESC NULLS LAST,
    c.updated_at DESC NULLS LAST,
    CASE WHEN c.intent IS NULL THEN 0 ELSE 1 END
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_city_editorial"("p_city" "text", "p_state" "text", "p_country" "text", "p_intent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_coach_picks"("_beach_id" "uuid", "_radius_km" numeric DEFAULT 80) RETURNS TABLE("pick_rank" integer, "beach_id" "uuid", "name" "text", "distance_km" numeric, "score" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  WITH origin AS (
    SELECT b.lat, b.lon
    FROM public.beaches b
    WHERE b.id = _beach_id
      AND b.deleted_at IS NULL
      AND NOT b.is_private
  ),
  candidate_distances AS (
    SELECT
      b.id,
      b.name,
      (
        6371.0088 * 2 * asin(
          least(
            1.0,
            sqrt(
              power(sin(radians((b.lat - o.lat) / 2.0)), 2) +
              cos(radians(o.lat)) * cos(radians(b.lat)) *
              power(sin(radians((b.lon - o.lon) / 2.0)), 2)
            )
          )
        )
      )::numeric AS distance_km
    FROM public.beaches b
    CROSS JOIN origin o
    WHERE b.id <> _beach_id
      AND b.deleted_at IS NULL
      AND NOT b.is_private
  ),
  scored_candidates AS (
    SELECT
      candidate.id,
      candidate.name,
      candidate.distance_km,
      coalesce(latest_intel.conditions_score, 0)::int AS score
    FROM candidate_distances candidate
    LEFT JOIN LATERAL (
      SELECT intel.conditions_score
      FROM public.beach_daily_intel intel
      WHERE intel.beach_id = candidate.id
      ORDER BY intel.forecast_date DESC, intel.generated_at DESC
      LIMIT 1
    ) latest_intel ON true
    WHERE candidate.distance_km <= _radius_km
  )
  SELECT
    row_number() OVER (
      ORDER BY candidate.score DESC, candidate.distance_km ASC, candidate.id
    )::int AS pick_rank,
    candidate.id AS beach_id,
    candidate.name,
    candidate.distance_km,
    candidate.score
  FROM scored_candidates candidate
  ORDER BY pick_rank
  LIMIT 3;
$$;


ALTER FUNCTION "public"."get_coach_picks"("_beach_id" "uuid", "_radius_km" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_coach_picks"("_beach_id" "uuid", "_radius_km" numeric) IS 'Returns the top three public beaches within a strict radius, ranked by each beach''s latest daily conditions score.';



CREATE OR REPLACE FUNCTION "public"."get_community_photo_monitoring_v1"("p_since" timestamp with time zone DEFAULT ("now"() - '24:00:00'::interval)) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_build_object(
    'since', p_since,
    'uploadsReserved', count(*) FILTER (
      WHERE e.action = 'upload_reserved' AND e.outcome = 'accepted'
    ),
    'uploadsReady', count(*) FILTER (
      WHERE e.action = 'upload_ready' AND e.outcome = 'accepted'
    ),
    'uploadsFailed', count(*) FILTER (
      WHERE e.action = 'upload_failed'
    ),
    'reportsAccepted', count(*) FILTER (
      WHERE e.action = 'report' AND e.outcome = 'accepted'
    ),
    'purgesCompleted', count(*) FILTER (
      WHERE e.action = 'purge' AND e.outcome = 'accepted'
    ),
    'processingStuck', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.processing_status = 'processing'
        AND p.updated_at < now() - interval '15 minutes'
    ),
    'processingCleanup', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.processing_status = 'cleanup'
    ),
    'orphanObjects', (
      SELECT count(*) FROM storage.objects o
      WHERE o.bucket_id = 'community-spot-photos'
        AND o.created_at < now() - interval '15 minutes'
        AND NOT EXISTS (
          SELECT 1 FROM public.community_spot_photos p
          WHERE p.storage_path = o.name
        )
    ),
    'hiddenActive', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.lifecycle_status = 'active' AND p.moderation_status = 'hidden'
    ),
    'expiredRemovalBacklog', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.lifecycle_status = 'removed' AND p.recoverable_until <= now()
        AND NOT EXISTS (
          SELECT 1 FROM public.community_photo_investigation_holds h
          WHERE h.photo_id = p.id AND h.released_at IS NULL
        )
    ),
    'activeHolds', (
      SELECT count(*) FROM public.community_photo_investigation_holds h
      WHERE h.released_at IS NULL
    )
  )
  FROM public.community_photo_action_events e
  WHERE e.created_at >= p_since
$$;


ALTER FUNCTION "public"."get_community_photo_monitoring_v1"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_community_spot_photo_image_v1"("p_photo_id" "uuid", "p_viewer_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("storage_path" "text", "content_type" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT p.storage_path, p.content_type
  FROM public.community_spot_photos p
  WHERE p.id = p_photo_id
    AND p.processing_status = 'ready'
    AND EXISTS (
      SELECT 1 FROM public.community_photo_feature_config config
      WHERE config.singleton AND config.read_enabled
    )
    AND (
      (
        p.lifecycle_status = 'active'
        AND p.moderation_status = 'visible'
        AND p.target_type = 'beach'
        AND p.visibility = 'public'
        AND EXISTS (
          SELECT 1 FROM public.beaches b
          WHERE b.id = p.beach_id
            AND COALESCE(b.is_private, false) = false
        )
      )
      OR (
        p.lifecycle_status = 'active'
        AND p.moderation_status = 'visible'
        AND p.target_type = 'custom_spot'
        AND EXISTS (
          SELECT 1 FROM public.custom_spots cs
          WHERE cs.id = p.custom_spot_id
            AND cs.deleted_at IS NULL
            AND (
              (p.visibility = 'public' AND cs.visibility = 'public')
              OR (
                p.visibility = 'private'
                AND cs.user_id = p_viewer_id
                AND p.uploader_id = p_viewer_id
              )
            )
        )
      )
      OR (
        p.lifecycle_status = 'removed'
        AND p.recoverable_until > now()
        AND p.uploader_id IS NOT NULL
        AND p.uploader_id = p_viewer_id
      )
    )
$$;


ALTER FUNCTION "public"."get_community_spot_photo_image_v1"("p_photo_id" "uuid", "p_viewer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_conditions_alert_candidates"("p_min_score" integer DEFAULT 7) RETURNS TABLE("user_id" "uuid", "email" "text", "display_name" "text", "experience_level" "text", "home_beach_id" "uuid", "beach_name" "text", "beach_slug" "text", "beach_state" "text", "beach_city" "text", "conditions_score" integer, "surf_description" "text", "wind_description" "text", "best_window_start" time without time zone, "best_window_end" time without time zone, "recommendation" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH eligible_users AS (
    SELECT
      p.id,
      p.email,
      p.display_name,
      p.experience_level,
      p.home_beach_id
    FROM profiles p
    WHERE p.home_beach_id IS NOT NULL
      AND p.email IS NOT NULL
      AND p.notif_email_enabled = true
      AND p.notif_forecast_alerts = true
      AND COALESCE(p.is_mock, false) = false
  ),
  users_with_beach AS (
    SELECT
      eu.id,
      eu.email,
      eu.display_name,
      eu.experience_level,
      eu.home_beach_id,
      COALESCE(b.timezone, 'America/Los_Angeles') AS beach_tz
    FROM eligible_users eu
    INNER JOIN beaches b ON b.id = eu.home_beach_id
  ),
  latest_intel AS (
    SELECT DISTINCT ON (bdi.beach_id)
      bdi.beach_id,
      bdi.conditions_score,
      bdi.surf_description,
      bdi.wind_description,
      bdi.best_window_start,
      bdi.best_window_end,
      bdi.recommendation
    FROM beach_daily_intel bdi
    INNER JOIN users_with_beach uwb ON uwb.home_beach_id = bdi.beach_id
    WHERE bdi.forecast_date = (CURRENT_TIMESTAMP AT TIME ZONE uwb.beach_tz)::date
      AND bdi.conditions_score >= p_min_score
    ORDER BY bdi.beach_id, bdi.generated_at DESC
  ),
  active_today_filter AS (
    SELECT
      uwb.id,
      uwb.email,
      uwb.display_name,
      uwb.experience_level,
      uwb.home_beach_id,
      uwb.beach_tz
    FROM users_with_beach uwb
    WHERE NOT EXISTS (
      SELECT 1
      FROM user_events ue
      WHERE ue.user_id = uwb.id
        AND ue.created_at >= (CURRENT_TIMESTAMP AT TIME ZONE uwb.beach_tz)::date AT TIME ZONE uwb.beach_tz
    )
  ),
  email_dedup AS (
    SELECT
      atf.id,
      atf.email,
      atf.display_name,
      atf.experience_level,
      atf.home_beach_id
    FROM active_today_filter atf
    WHERE NOT EXISTS (
      SELECT 1
      FROM email_send_log esl
      WHERE esl.user_id = atf.id
        AND esl.sent_at >= (CURRENT_TIMESTAMP AT TIME ZONE atf.beach_tz)::date AT TIME ZONE atf.beach_tz
    )
  )
  SELECT
    ed.id AS user_id,
    ed.email,
    ed.display_name,
    ed.experience_level,
    ed.home_beach_id,
    b.name AS beach_name,
    b.slug AS beach_slug,
    b.state AS beach_state,
    b.city AS beach_city,
    li.conditions_score,
    li.surf_description,
    li.wind_description,
    li.best_window_start,
    li.best_window_end,
    li.recommendation
  FROM email_dedup ed
  INNER JOIN beaches b ON b.id = ed.home_beach_id
  INNER JOIN latest_intel li ON li.beach_id = ed.home_beach_id;
END;
$$;


