COMMENT ON FUNCTION "public"."get_entity_history"("table_name" "text", "entity_id" "uuid", "limit_rows" integer) IS 'Retrieve audit history for a specific entity. Returns up to limit_rows most recent changes.';



CREATE OR REPLACE FUNCTION "public"."get_forecast_accuracy_horizon_metrics"("p_start" timestamp with time zone DEFAULT ("now"() - '7 days'::interval), "p_end" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("horizon_bucket" "text", "baseline" "text", "sample_count" bigint, "mae_m" numeric, "bias_m" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH eligible AS (
    SELECT
      COALESCE(
        p.forecast_horizon_bucket,
        CASE
        WHEN p.forecast_horizon_hours BETWEEN 0 AND 24 THEN '0-24h'
        WHEN p.forecast_horizon_hours BETWEEN 25 AND 72 THEN '25-72h'
        WHEN p.forecast_horizon_hours >= 73 THEN '73h+'
        ELSE NULL
        END
      ) AS horizon_bucket,
      p.observed_m,
      p.raw_display_height_m,
      p.offset_corrected_display_height_m,
      p.wave_height_om,
      p.v5_shadow_height_m
    FROM public.ml_predictions_log p
    WHERE p.predicted_at >= p_start
      AND p.predicted_at < p_end
      AND p.observed_m > 0
      AND p.display_source = 'face-Hs-transformer-v1'
      AND (
        p.forecast_horizon_bucket IS NOT NULL
        OR p.forecast_horizon_hours IS NOT NULL
      )
  ),
  expanded AS (
    SELECT
      e.horizon_bucket,
      v.baseline,
      (v.predicted_m - e.observed_m) AS signed_error
    FROM eligible e
    CROSS JOIN LATERAL (
      VALUES
        ('current_display'::text, e.offset_corrected_display_height_m),
        ('raw_display'::text, e.raw_display_height_m),
        ('raw_om'::text, e.wave_height_om),
        ('v5_shadow'::text, e.v5_shadow_height_m)
    ) AS v(baseline, predicted_m)
    WHERE e.horizon_bucket IS NOT NULL
      AND v.predicted_m IS NOT NULL
      AND v.predicted_m >= 0
  )
  SELECT
    expanded.horizon_bucket,
    expanded.baseline,
    COUNT(*)::bigint AS sample_count,
    ROUND(AVG(ABS(expanded.signed_error))::numeric, 3) AS mae_m,
    ROUND(AVG(expanded.signed_error)::numeric, 3) AS bias_m
  FROM expanded
  GROUP BY expanded.horizon_bucket, expanded.baseline
  ORDER BY
    CASE expanded.horizon_bucket
      WHEN '0-24h' THEN 1
      WHEN '25-72h' THEN 2
      WHEN '73h+' THEN 3
      ELSE 4
    END,
    CASE expanded.baseline
      WHEN 'current_display' THEN 1
      WHEN 'raw_display' THEN 2
      WHEN 'raw_om' THEN 3
      WHEN 'v5_shadow' THEN 4
      ELSE 5
    END;
$$;


ALTER FUNCTION "public"."get_forecast_accuracy_horizon_metrics"("p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_forecast_accuracy_horizon_metrics"("p_start" timestamp with time zone, "p_end" timestamp with time zone) IS 'Phase 0 canonical face-height accuracy metric. Returns MAE and signed bias vs observed_m split by horizon bucket (0-24h, 25-72h, 73h+) and baseline (current display, raw display, raw OM, v5 shadow).';



CREATE OR REPLACE FUNCTION "public"."get_forecast_vs_observation_pairs"("p_days_back" integer DEFAULT 7, "p_max_distance_km" numeric DEFAULT 100) RETURNS TABLE("beach_id" "uuid", "observation_time" timestamp with time zone, "observed_wave_height_m" numeric, "observed_wave_period_s" numeric, "forecast_wave_height" "text", "forecast_period" "text", "observation_source" "text", "station_id" "text", "distance_km" numeric, "forecast_age_hours" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT DISTINCT ON (o.observed_at, o.station_id)
    o.nearest_beach_id AS beach_id,
    o.observed_at AS observation_time,
    o.wave_height_m AS observed_wave_height_m,
    o.wave_period_s AS observed_wave_period_s,
    f.wave_height AS forecast_wave_height,
    f.wave_period AS forecast_period,
    o.source AS observation_source,
    o.station_id,
    o.distance_to_beach_km AS distance_km,
    EXTRACT(EPOCH FROM (o.observed_at - (f.forecast_date + f.forecast_time)::TIMESTAMPTZ)) / 3600 AS forecast_age_hours
  FROM unified_wave_observations o
  JOIN enhanced_forecasts f
    ON o.nearest_beach_id = f.beach_id
    AND o.observed_at BETWEEN (f.forecast_date + f.forecast_time)::TIMESTAMPTZ - INTERVAL '1 hour'
                          AND (f.forecast_date + f.forecast_time)::TIMESTAMPTZ + INTERVAL '1 hour'
  WHERE o.observed_at >= NOW() - (p_days_back || ' days')::INTERVAL
    AND o.distance_to_beach_km <= p_max_distance_km
    AND f.wave_height IS NOT NULL
  ORDER BY o.observed_at, o.station_id, ABS(EXTRACT(EPOCH FROM (o.observed_at - (f.forecast_date + f.forecast_time)::TIMESTAMPTZ)));
$$;


ALTER FUNCTION "public"."get_forecast_vs_observation_pairs"("p_days_back" integer, "p_max_distance_km" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_forecast_vs_observation_pairs"("p_days_back" integer, "p_max_distance_km" numeric) IS 'Returns forecast vs observation pairs for ML training - matches forecasts to nearby observations within 1 hour window';



