COMMENT ON FUNCTION "public"."get_metro_stats"("p_cities" "text"[], "p_state" "text", "p_country" "text") IS 'Returns aggregate statistics for a metro area spanning multiple cities.';



CREATE OR REPLACE FUNCTION "public"."get_ml_health_metrics"() RETURNS TABLE("total_predictions" bigint, "pending_observations" bigint, "pending_12_24h" bigint, "pending_gt_24h" bigint, "sentinel_marked" bigint, "matched_last_24h" bigint, "total_observable_24h" bigint, "match_rate_24h" numeric, "avg_raw_error_24h" numeric, "avg_corrected_error_24h" numeric, "improvement_pct_24h" numeric, "oldest_pending_age_hours" numeric, "observable_beaches_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '4 hours'
          AND p.predicted_at > now() - interval '7 days'
          AND ob.beach_id IS NOT NULL
      ) AS pending,
      COUNT(*) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '12 hours'
          AND p.predicted_at >= now() - interval '24 hours'
          AND ob.beach_id IS NOT NULL
      ) AS pending_12_24h,
      COUNT(*) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '24 hours'
          AND ob.beach_id IS NOT NULL
      ) AS pending_gt_24h,
      COUNT(*) FILTER (
        WHERE p.observed_m = -1
      ) AS sentinel,
      COUNT(*) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.predicted_at < now() - interval '4 hours'
          AND ob.beach_id IS NOT NULL
      ) AS total_24h,
      COUNT(*) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.observed_m > 0
          AND ob.beach_id IS NOT NULL
      ) AS matched_24h,
      AVG(ABS(p.raw_display_height_m - p.observed_m)) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.observed_m > 0
          AND p.raw_display_height_m IS NOT NULL
          AND ob.beach_id IS NOT NULL
      ) AS avg_raw_display_24h,
      AVG(ABS(p.offset_corrected_display_height_m - p.observed_m)) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.observed_m > 0
          AND p.offset_corrected_display_height_m IS NOT NULL
          AND ob.beach_id IS NOT NULL
      ) AS avg_current_display_24h,
      EXTRACT(EPOCH FROM (now() - MIN(p.predicted_at) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '4 hours'
          AND p.predicted_at > now() - interval '7 days'
          AND ob.beach_id IS NOT NULL
      ))) / 3600 AS oldest_pending_hours
    FROM public.ml_predictions_log p
    LEFT JOIN public.observable_beaches ob ON ob.beach_id = p.beach_id
    WHERE p.predicted_at > now() - interval '30 days'
      AND p.display_source = 'face-Hs-transformer-v1'
  ),
  beach_count AS (
    SELECT COUNT(*) AS cnt FROM public.observable_beaches
  )
  SELECT
    s.total::bigint,
    s.pending::bigint,
    s.pending_12_24h::bigint,
    s.pending_gt_24h::bigint,
    s.sentinel::bigint,
    s.matched_24h::bigint,
    s.total_24h::bigint,
    ROUND(100.0 * s.matched_24h / NULLIF(s.total_24h, 0), 1),
    ROUND(s.avg_raw_display_24h::numeric, 3),
    ROUND(s.avg_current_display_24h::numeric, 3),
    ROUND(
      100.0 * (s.avg_raw_display_24h - s.avg_current_display_24h) /
      NULLIF(s.avg_raw_display_24h, 0),
      1
    ),
    ROUND(s.oldest_pending_hours, 1),
    b.cnt::bigint
  FROM stats s, beach_count b;
END;
$$;


ALTER FUNCTION "public"."get_ml_health_metrics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ml_health_metrics"() IS 'Returns ML pipeline health metrics. Phase 0 repointed 24h MAE from retired raw/corrected error columns to live raw_display_height_m and offset_corrected_display_height_m vs observed_m.';



CREATE OR REPLACE FUNCTION "public"."get_ml_weekly_metrics"() RETURNS TABLE("model_version" "text", "predictions" bigint, "with_ground_truth" bigint, "avg_raw_error_m" numeric, "avg_corrected_error_m" numeric, "avg_improvement_m" numeric, "pct_improved" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH weekly AS (
    SELECT
      p.model_version,
      p.observed_m,
      p.raw_display_height_m,
      p.offset_corrected_display_height_m,
      CASE
        WHEN p.observed_m > 0 AND p.raw_display_height_m IS NOT NULL
        THEN ABS(p.raw_display_height_m - p.observed_m)
        ELSE NULL
      END AS raw_display_error_m,
      CASE
        WHEN p.observed_m > 0 AND p.offset_corrected_display_height_m IS NOT NULL
        THEN ABS(p.offset_corrected_display_height_m - p.observed_m)
        ELSE NULL
      END AS current_display_error_m
    FROM public.ml_predictions_log p
    WHERE p.predicted_at > now() - interval '7 days'
      AND p.display_source = 'face-Hs-transformer-v1'
  )
  SELECT
    weekly.model_version,
    COUNT(*)::bigint AS predictions,
    COUNT(*) FILTER (WHERE weekly.observed_m > 0)::bigint AS with_ground_truth,
    ROUND(AVG(weekly.raw_display_error_m)::numeric, 3) AS avg_raw_error_m,
    ROUND(AVG(weekly.current_display_error_m)::numeric, 3) AS avg_corrected_error_m,
    ROUND(AVG(weekly.raw_display_error_m - weekly.current_display_error_m)::numeric, 3) AS avg_improvement_m,
    ROUND(
      100.0 * COUNT(*) FILTER (
        WHERE weekly.current_display_error_m < weekly.raw_display_error_m
      ) / NULLIF(
        COUNT(*) FILTER (
          WHERE weekly.current_display_error_m IS NOT NULL
            AND weekly.raw_display_error_m IS NOT NULL
        ),
        0
      ),
      1
    ) AS pct_improved
  FROM weekly
  GROUP BY weekly.model_version
  ORDER BY weekly.model_version DESC;
$$;


ALTER FUNCTION "public"."get_ml_weekly_metrics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ml_weekly_metrics"() IS 'Compatibility weekly metrics for scripts/ml-stats. Phase 0 repointed MAE from retired corrected_forecast_m/raw_error_m fields to live display snapshot columns vs observed_m.';



CREATE OR REPLACE FUNCTION "public"."get_most_visited_beach"("user_id" "uuid") RETURNS TABLE("beach_id" "uuid", "visit_count" bigint, "beach_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.beach_id,
    COUNT(s.id)::BIGINT AS visit_count,
    b.name              AS beach_name
  FROM sessions s
  JOIN beaches b ON b.id = s.beach_id
  WHERE s.user_id = get_most_visited_beach.user_id
    AND s.deleted_at IS NULL
  GROUP BY s.beach_id, b.name
  ORDER BY visit_count DESC
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_most_visited_beach"("user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_most_visited_beach"("user_id" "uuid") IS 'Returns the beach a user has visited most frequently. Recreated with a user_id parameter after the global version was dropped in remote_commit migration. SECURITY DEFINER with search_path protection.';



CREATE OR REPLACE FUNCTION "public"."get_my_analytics_tracking_allowed"("p_expected_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT CASE
    WHEN (SELECT auth.uid()) IS NULL
      OR (SELECT auth.uid()) <> p_expected_user_id
      THEN false
    ELSE COALESCE(
      (
        SELECT p.allow_implicit_tracking
        FROM public.profiles AS p
        WHERE p.id = (SELECT auth.uid())
          AND p.id = p_expected_user_id
      ),
      true
    )
  END;
$$;


ALTER FUNCTION "public"."get_my_analytics_tracking_allowed"("p_expected_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_analytics_tracking_allowed"("p_expected_user_id" "uuid") IS 'Returns analytics consent only for the authenticated profile selected by auth.uid(); defaults to the schema default when the profile is still bootstrapping.';



CREATE OR REPLACE FUNCTION "public"."get_nearby_beaches"("input_lat" double precision, "input_lng" double precision, "max_distance_meters" integer DEFAULT 80467, "limit_count" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "name" "text", "location" "text", "lat" double precision, "lon" double precision, "is_private" boolean, "distance_meters" double precision, "slug" "text", "city" "text", "state" "text", "skill_level" "text", "break_type" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    target_lat DOUBLE PRECISION := input_lat;
    target_lng DOUBLE PRECISION := input_lng;
    -- Ceilings bound the scan without clipping any real caller. 160934 m is
    -- what native's use-nearest-beach and web's candidate-pool outer tier both
    -- already request; clamping to 50 mi would silently return nothing for
    -- users further than that from a break, in binaries already shipped.
    -- 100 rows clears discovery's CANDIDATE_POOL_LIMIT of 60.
    capped_distance INTEGER := LEAST(GREATEST(max_distance_meters, 0), 160934);
    capped_limit INTEGER := LEAST(GREATEST(limit_count, 1), 100);
BEGIN
    RETURN QUERY
    SELECT
        b.id,
        b.name,
        CASE
            WHEN b.city IS NOT NULL AND b.state IS NOT NULL
                THEN b.city || ', ' || b.state
            WHEN b.city IS NOT NULL THEN b.city
            WHEN b.state IS NOT NULL THEN b.state
            ELSE 'Unknown'
        END AS location,
        b.lat,
        b.lon,
        b.is_private,
        ST_Distance(
            b.geog,
            ST_SetSRID(ST_MakePoint(target_lng, target_lat), 4326)::geography
        ) AS distance_meters,
        b.slug,
        b.city,
        b.state,
        b.skill_level,
        b.break_type
    FROM public.beaches b
    WHERE b.lat IS NOT NULL
      AND b.lon IS NOT NULL
      AND COALESCE(b.is_private, false) = false
      AND b.deleted_at IS NULL
      AND ST_DWithin(
          b.geog,
          ST_SetSRID(ST_MakePoint(target_lng, target_lat), 4326)::geography,
          capped_distance
      )
    ORDER BY distance_meters ASC
    LIMIT capped_limit;
END;
$$;


ALTER FUNCTION "public"."get_nearby_beaches"("input_lat" double precision, "input_lng" double precision, "max_distance_meters" integer, "limit_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_nearby_beaches"("input_lat" double precision, "input_lng" double precision, "max_distance_meters" integer, "limit_count" integer) IS 'Returns at most 100 public, non-deleted beaches within at most 100 miles of the supplied coordinates. Defaults to 50 miles / 50 rows when the caller omits them.';



CREATE OR REPLACE FUNCTION "public"."get_nearby_buoys"("target_lat" double precision, "target_lng" double precision, "max_distance_m" integer DEFAULT 100000, "result_limit" integer DEFAULT 4) RETURNS TABLE("buoy_uuid" "text", "buoy_name" "text", "active" boolean, "coordinates" "extensions"."geometry", "water_temperature" numeric, "air_temperature" numeric, "wave_height" numeric, "wave_period" numeric, "wind_speed" numeric, "wind_gust" numeric, "wind_direction" numeric, "tides" "jsonb", "updated_at" timestamp with time zone, "distance_meters" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        b.buoy_uuid,
        b.buoy_name,
        b.active,
        b.coordinates,
        b.water_temperature,
        b.air_temperature,
        b.wave_height,
        b.wave_period,
        b.wind_speed,
        b.wind_gust,
        b.wind_direction,
        b.tides,
        b.updated_at,
        ST_Distance(
            b.coordinates,
            ST_SetSRID(ST_MakePoint(target_lng, target_lat), 4326)::geography
        ) AS distance_meters
    FROM public.buoys b
    WHERE b.active = true
      AND b.coordinates IS NOT NULL
      AND ST_DWithin(
          b.coordinates,
          ST_SetSRID(ST_MakePoint(target_lng, target_lat), 4326)::geography,
          max_distance_m
      )
    ORDER BY distance_meters ASC
    LIMIT result_limit;
END;
$$;


ALTER FUNCTION "public"."get_nearby_buoys"("target_lat" double precision, "target_lng" double precision, "max_distance_m" integer, "result_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearby_intel_posts"("center_lat" double precision, "center_lng" double precision, "limit_count" integer DEFAULT 50, "radius_miles" double precision DEFAULT 25.0, "tag_filter" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "user_id" "uuid", "beach_id" "uuid", "latitude" numeric, "longitude" numeric, "tag" "public"."intel_post_tag", "title" "text", "description" "text", "photo_url" "text", "confirmations_count" integer, "is_active" boolean, "surf_conditions" "jsonb", "expires_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "distance_miles" double precision, "user_name" "text", "beach_name" "text", "helpful_count" integer, "off_count" integer, "confirmed_count" integer, "rank_score" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ip.id,
        ip.user_id,
        ip.beach_id,
        ip.latitude,
        ip.longitude,
        ip.tag,
        ip.title,
        ip.description,
        ip.photo_url,
        ip.confirmations_count,
        ip.is_active,
        ip.surf_conditions,
        ip.expires_at,
        ip.created_at,
        ip.updated_at,
        (public.ST_Distance(
            public.ST_SetSRID(public.ST_MakePoint(ip.longitude, ip.latitude), 4326)::public.geography,
            public.ST_SetSRID(public.ST_MakePoint(center_lng, center_lat), 4326)::public.geography
        ) / 1609.34) AS distance_miles,
        p.full_name AS user_name,
        COALESCE(b.name, 'Unknown Beach') AS beach_name,
        ip.helpful_count,
        ip.off_count,
        ip.confirmed_count,
        (
            GREATEST(0, (ip.helpful_count - ip.off_count + ip.confirmed_count * 2)::DOUBLE PRECISION)
            * (1.0 / (1.0 + EXTRACT(EPOCH FROM (NOW() - ip.created_at)) / 3600.0 / 8.0))
        ) AS rank_score
    FROM public.intel_posts ip
    LEFT JOIN public.profiles p ON p.id = ip.user_id
    LEFT JOIN public.beaches b ON b.id = ip.beach_id
    WHERE ip.is_active = true
      AND (ip.expires_at IS NULL OR ip.expires_at > NOW())
      AND public.ST_DWithin(
          public.ST_SetSRID(public.ST_MakePoint(ip.longitude, ip.latitude), 4326)::public.geography,
          public.ST_SetSRID(public.ST_MakePoint(center_lng, center_lat), 4326)::public.geography,
          radius_miles * 1609.34
      )
      AND (tag_filter IS NULL OR ip.tag::TEXT = tag_filter)
    ORDER BY
        rank_score DESC,
        ip.created_at DESC
    LIMIT limit_count;
END;
$$;


ALTER FUNCTION "public"."get_nearby_intel_posts"("center_lat" double precision, "center_lng" double precision, "limit_count" integer, "radius_miles" double precision, "tag_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearest_buoy_with_conditions"("target_lat" double precision, "target_lng" double precision, "max_distance_m" integer DEFAULT 100000) RETURNS TABLE("buoy_uuid" "text", "buoy_name" "text", "active" boolean, "coordinates" "extensions"."geometry", "water_temperature" numeric, "air_temperature" numeric, "wave_height" numeric, "wave_period" numeric, "wind_speed" numeric, "wind_gust" numeric, "wind_direction" numeric, "tides" "jsonb", "updated_at" timestamp with time zone, "distance_meters" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        b.buoy_uuid,
        b.buoy_name,
        b.active,
        b.coordinates,
        b.water_temperature,
        b.air_temperature,
        b.wave_height,
        b.wave_period,
        b.wind_speed,
        b.wind_gust,
        b.wind_direction,
        b.tides,
        b.updated_at,
        ST_Distance(
            b.coordinates,
            ST_SetSRID(ST_MakePoint(target_lng, target_lat), 4326)::geography
        ) AS distance_meters
    FROM public.buoys b
    WHERE b.active = true
      AND b.coordinates IS NOT NULL
      AND (b.water_temperature IS NOT NULL 
           OR b.air_temperature IS NOT NULL 
           OR b.wave_height IS NOT NULL)
      AND ST_DWithin(
          b.coordinates,
          ST_SetSRID(ST_MakePoint(target_lng, target_lat), 4326)::geography,
          max_distance_m
      )
    ORDER BY 
        b.updated_at DESC,
        distance_meters ASC
    LIMIT 1;
END;
$$;


