COMMENT ON TABLE "public"."trusted_forecast_build_receipts" IS 'Immutable build receipts with the database-computed canonical SHA-256 and exact durable counts (D-19, D-20).';



CREATE OR REPLACE FUNCTION "public"."get_trusted_forecast_build_receipt"("p_build_key" "text") RETURNS SETOF "public"."trusted_forecast_build_receipts"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT *
  FROM public.trusted_forecast_build_receipts
  WHERE build_key = p_build_key;
$$;


