CREATE OR REPLACE FUNCTION "public"."like_session_with_notification"("p_session_id" "uuid", "p_actor_id" "uuid", "p_dedupe_key" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_session_owner_id uuid;
  v_beach_name text;
  v_event_id uuid;
  v_dedup_collision boolean := false;
  v_existing_id uuid;
BEGIN
  IF p_actor_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'actor_id mismatch: must match auth.uid()';
  END IF;

  SELECT id INTO v_existing_id
    FROM session_likes
    WHERE session_id = p_session_id AND user_id = p_actor_id;

  IF v_existing_id IS NOT NULL THEN
    RETURN json_build_object(
      'liked', true,
      'was_existing', true,
      'event_id', null,
      'notification_dedup_collision', false
    );
  END IF;

  INSERT INTO session_likes (session_id, user_id)
    VALUES (p_session_id, p_actor_id);

  SELECT user_id, beach_name INTO v_session_owner_id, v_beach_name
    FROM sessions
    WHERE id = p_session_id;

  IF v_session_owner_id IS NULL OR v_session_owner_id = p_actor_id THEN
    RETURN json_build_object(
      'liked', true,
      'was_existing', false,
      'event_id', null,
      'notification_dedup_collision', false
    );
  END IF;

  BEGIN
    INSERT INTO notification_events (
      recipient_user_id, actor_user_id, type,
      entity_type, entity_id, payload, dedupe_key
    ) VALUES (
      v_session_owner_id, p_actor_id, 'like',
      'session', p_session_id,
      jsonb_build_object(
        'session_id', p_session_id::text,
        'beach_name', v_beach_name
      ),
      p_dedupe_key
    )
    RETURNING id INTO v_event_id;
  EXCEPTION WHEN unique_violation THEN
    v_dedup_collision := true;
    v_event_id := null;
  END;

  RETURN json_build_object(
    'liked', true,
    'was_existing', false,
    'event_id', v_event_id,
    'notification_dedup_collision', v_dedup_collision
  );
END;
$$;


ALTER FUNCTION "public"."like_session_with_notification"("p_session_id" "uuid", "p_actor_id" "uuid", "p_dedupe_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_android_tester_roster_account"("p_entry_id" "uuid", "p_user_id" "uuid", "p_native_install_id" "uuid", "p_idempotency_key_hash" "text") RETURNS TABLE("outcome" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_entry public.android_tester_roster_entries%ROWTYPE;
BEGIN
  IF p_idempotency_key_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN QUERY SELECT 'terminal_invalid'::text;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_join_evidence AS join_evidence
    WHERE join_evidence.user_id = p_user_id
      AND join_evidence.idempotency_key_hash = p_idempotency_key_hash
  ) THEN
    INSERT INTO public.android_tester_roster_audit (
      actor_user_id,
      entry_id,
      action,
      outcome
    ) VALUES (
      NULL,
      p_entry_id,
      'join',
      'same_key_retry'
    );
    RETURN QUERY SELECT 'same_key_retry'::text;
    RETURN;
  END IF;

  SELECT entry.*
  INTO v_entry
  FROM public.android_tester_roster_entries AS entry
  WHERE entry.id = p_entry_id
  FOR UPDATE;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_join_evidence AS join_evidence
    WHERE join_evidence.user_id = p_user_id
      AND join_evidence.idempotency_key_hash = p_idempotency_key_hash
  ) THEN
    INSERT INTO public.android_tester_roster_audit (
      actor_user_id,
      entry_id,
      action,
      outcome
    ) VALUES (
      NULL,
      p_entry_id,
      'join',
      'same_key_retry'
    );
    RETURN QUERY SELECT 'same_key_retry'::text;
    RETURN;
  END IF;

  IF v_entry.id IS NULL
     OR v_entry.eligibility_status <> 'eligible'
     OR v_entry.group_membership_status <> 'active'
     OR (v_entry.user_id IS NOT NULL AND v_entry.user_id <> p_user_id)
     OR NOT EXISTS (
       SELECT 1
       FROM public.android_tester_roster_identities AS identity
       WHERE identity.entry_id = p_entry_id
     ) THEN
    RETURN QUERY SELECT 'pending_retryable'::text;
    RETURN;
  END IF;

  UPDATE public.android_tester_roster_entries
  SET
    user_id = p_user_id,
    linked_at = COALESCE(linked_at, now()),
    purge_after = NULL,
    updated_at = now()
  WHERE id = p_entry_id;

  INSERT INTO public.android_tester_roster_join_evidence (
    entry_id,
    user_id,
    native_install_id,
    idempotency_key_hash
  ) VALUES (
    p_entry_id,
    p_user_id,
    p_native_install_id,
    p_idempotency_key_hash
  );

  INSERT INTO public.android_tester_roster_stages (
    entry_id,
    stage,
    status,
    source,
    observed_at,
    confidence,
    evidence
  ) VALUES (
    p_entry_id,
    'account_join',
    'linked',
    'authenticated_roster_join',
    now(),
    'verified',
    '{}'::jsonb
  );

  DELETE FROM public.android_tester_roster_identities
  WHERE entry_id = p_entry_id;

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    entry_id,
    action,
    outcome,
    evidence
  ) VALUES (
    NULL,
    p_entry_id,
    'join',
    'linked',
    '{}'::jsonb
  );

  RETURN QUERY SELECT 'linked'::text;
END;
$_$;


ALTER FUNCTION "public"."link_android_tester_roster_account"("p_entry_id" "uuid", "p_user_id" "uuid", "p_native_install_id" "uuid", "p_idempotency_key_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_anonymous_events"("p_session_id" "uuid", "p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  linked_count integer;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id cannot be null';
  END IF;

  UPDATE public.user_events
  SET user_id = p_user_id
  WHERE session_id = p_session_id
    AND user_id IS NULL
    AND created_at > now() - interval '30 days';

  GET DIAGNOSTICS linked_count = ROW_COUNT;
  RETURN linked_count;
END;
$$;


ALTER FUNCTION "public"."link_anonymous_events"("p_session_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."link_anonymous_events"("p_session_id" "uuid", "p_user_id" "uuid") IS 'Links anonymous events to an authenticated user after sign-up. Called via service role from /api/events/link endpoint. Limited to events from the last 30 days.';



CREATE OR REPLACE FUNCTION "public"."link_anonymous_events_v2"("p_session_id" "uuid", "p_user_id" "uuid", "p_signup_context" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_linked_count integer := 0;
  v_profile_created_at timestamptz;
  v_existing_context jsonb := '{}'::jsonb;
  v_existing_surface text;
  v_candidate_context jsonb;
  v_merged_context jsonb;
  v_evidence_source text := 'none';
  v_attribution_outcome text := 'no_evidence';
  v_signup_surface text := 'unknown';
  v_event_metadata jsonb;
  v_event_created_at timestamptz;
  v_native_platform text;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id cannot be null';
  END IF;

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id cannot be null';
  END IF;

  UPDATE public.user_events
  SET user_id = p_user_id
  WHERE session_id = p_session_id
    AND user_id IS NULL
    AND created_at > now() - interval '30 days';

  GET DIAGNOSTICS v_linked_count = ROW_COUNT;

  SELECT
    p.created_at,
    jsonb_strip_nulls(COALESCE(p.signup_context, '{}'::jsonb))
  INTO
    v_profile_created_at,
    v_existing_context
  FROM public.profiles p
  WHERE p.id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'linked', v_linked_count,
      'attribution_outcome', 'no_profile',
      'signup_surface', 'unknown',
      'evidence_source', 'none'
    );
  END IF;

  v_existing_surface := NULLIF(v_existing_context->>'signup_surface', '');
  v_signup_surface := COALESCE(v_existing_surface, 'unknown');

  IF v_profile_created_at < now() - interval '24 hours' THEN
    RETURN jsonb_build_object(
      'linked', v_linked_count,
      'attribution_outcome', 'not_recent',
      'signup_surface', v_signup_surface,
      'evidence_source',
        CASE
          WHEN v_existing_context <> '{}'::jsonb
            THEN 'existing_profile_context'
          ELSE 'none'
        END
    );
  END IF;

  -- Evidence precedence 1: request_signup_context.
  IF p_signup_context IS NOT NULL
     AND jsonb_typeof(p_signup_context) = 'object'
     AND p_signup_context->>'schema_version' = '2'
     AND p_signup_context->>'signup_surface' IN (
       'web',
       'native_ios',
       'native_android',
       'unknown'
     )
     AND p_signup_context->>'method' IN (
       'email',
       'google',
       'apple',
       'unknown'
     )
     AND NULLIF(p_signup_context->>'entrypoint', '') IS NOT NULL
     AND p_signup_context->>'source_capture_status' IN ('captured', 'missing')
     AND NULLIF(p_signup_context->>'captured_at', '') IS NOT NULL THEN
    v_candidate_context := jsonb_strip_nulls(p_signup_context);
    v_evidence_source := 'request_signup_context';
  END IF;

  -- Evidence precedence 2: linked_web_signup_event.
  IF v_candidate_context IS NULL THEN
    SELECT
      ue.metadata,
      ue.created_at
    INTO
      v_event_metadata,
      v_event_created_at
    FROM public.user_events ue
    WHERE ue.user_id = p_user_id
      AND ue.event_type = 'signup_success'
      AND ue.created_at >= v_profile_created_at - interval '24 hours'
      AND ue.created_at < v_profile_created_at + interval '24 hours'
      AND COALESCE(ue.bot_flagged, false) = false
      AND COALESCE(ue.metadata->>'is_test', 'false') NOT IN ('true', '1')
      AND COALESCE(
        ue.metadata->>'platform',
        ue.metadata->>'_platform',
        'web'
      ) NOT IN ('ios', 'android', 'native-ios', 'native-android')
    ORDER BY
      ABS(EXTRACT(EPOCH FROM (ue.created_at - v_profile_created_at))),
      ue.created_at
    LIMIT 1;

    IF FOUND THEN
      v_candidate_context := jsonb_strip_nulls(
        jsonb_build_object(
          'schema_version', 2,
          'signup_surface', 'web',
          'method',
            CASE
              WHEN v_event_metadata->>'method' IN (
                'email',
                'google',
                'apple'
              )
                THEN v_event_metadata->>'method'
              ELSE 'unknown'
            END,
          'entrypoint',
            COALESCE(
              NULLIF(v_event_metadata->>'entrypoint', ''),
              NULLIF(v_event_metadata->>'source', ''),
              'unknown'
            ),
          'landing_path',
            COALESCE(
              NULLIF(v_event_metadata->>'landing_path', ''),
              NULLIF(v_event_metadata->>'landing_page', '')
            ),
          'referrer_domain',
            NULLIF(v_event_metadata->>'referrer_domain', ''),
          'referrer',
            CASE
              WHEN v_event_metadata->>'referrer' = 'direct' THEN 'direct'
              ELSE NULL
            END,
          'utm',
            jsonb_strip_nulls(
              jsonb_build_object(
                'source', NULLIF(v_event_metadata->>'utm_source', ''),
                'medium', NULLIF(v_event_metadata->>'utm_medium', ''),
                'campaign', NULLIF(v_event_metadata->>'utm_campaign', ''),
                'content', NULLIF(v_event_metadata->>'utm_content', ''),
                'term', NULLIF(v_event_metadata->>'utm_term', '')
              )
            ),
          'source_capture_status',
            CASE
              WHEN COALESCE(
                NULLIF(v_event_metadata->>'referrer_domain', ''),
                CASE
                  WHEN v_event_metadata->>'referrer' = 'direct' THEN 'direct'
                  ELSE NULL
                END,
                NULLIF(v_event_metadata->>'utm_source', ''),
                NULLIF(v_event_metadata->>'utm_medium', ''),
                NULLIF(v_event_metadata->>'utm_campaign', ''),
                NULLIF(v_event_metadata->>'partner', ''),
                NULLIF(v_event_metadata->>'referral_code', '')
              ) IS NOT NULL
                THEN 'captured'
              ELSE 'missing'
            END,
          'captured_at', to_char(
            v_event_created_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
          )
        )
      );
      v_evidence_source := 'linked_web_signup_event';
    END IF;
  END IF;

  -- Evidence precedence 3: linked_native_first_open_event.
  IF v_candidate_context IS NULL THEN
    SELECT
      ue.metadata,
      ue.created_at,
      COALESCE(ue.metadata->>'platform', ue.metadata->>'_platform')
    INTO
      v_event_metadata,
      v_event_created_at,
      v_native_platform
    FROM public.user_events ue
    WHERE ue.user_id = p_user_id
      AND ue.event_type = 'native_app_first_open'
      AND ue.created_at >= v_profile_created_at - interval '24 hours'
      AND ue.created_at < v_profile_created_at + interval '24 hours'
      AND COALESCE(ue.bot_flagged, false) = false
      AND COALESCE(ue.metadata->>'is_emulator', 'false') NOT IN ('true', '1')
      AND COALESCE(ue.metadata->>'is_test', 'false') NOT IN ('true', '1')
      AND COALESCE(ue.metadata->>'_is_test', 'false') NOT IN ('true', '1')
      AND COALESCE(ue.metadata->>'platform', ue.metadata->>'_platform') IN (
        'ios',
        'android',
        'native-ios',
        'native-android'
      )
    ORDER BY
      ABS(EXTRACT(EPOCH FROM (ue.created_at - v_profile_created_at))),
      ue.created_at
    LIMIT 1;

    IF FOUND THEN
      v_candidate_context := jsonb_build_object(
        'schema_version', 2,
        'signup_surface',
          CASE
            WHEN v_native_platform IN ('ios', 'native-ios')
              THEN 'native_ios'
            ELSE 'native_android'
          END,
        'method', 'unknown',
        'entrypoint',
          COALESCE(NULLIF(v_event_metadata->>'source', ''), 'native_app'),
        'source_capture_status', 'missing',
        'captured_at', to_char(
          v_event_created_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
        )
      );
      v_evidence_source := 'linked_native_first_open_event';
    END IF;
  END IF;

  IF v_candidate_context IS NULL THEN
    IF v_existing_context <> '{}'::jsonb THEN
      v_attribution_outcome := 'preserved';
      v_evidence_source := 'existing_profile_context';
    END IF;

    RETURN jsonb_build_object(
      'linked', v_linked_count,
      'attribution_outcome', v_attribution_outcome,
      'signup_surface', v_signup_surface,
      'evidence_source', v_evidence_source
    );
  END IF;

  -- Existing values win. Candidate values fill only missing keys.
  v_merged_context := v_candidate_context || v_existing_context;

  IF jsonb_typeof(v_candidate_context->'utm') = 'object'
     OR jsonb_typeof(v_existing_context->'utm') = 'object' THEN
    v_merged_context := jsonb_set(
      v_merged_context,
      '{utm}',
      COALESCE(v_candidate_context->'utm', '{}'::jsonb)
        || COALESCE(v_existing_context->'utm', '{}'::jsonb),
      true
    );
  END IF;

  IF v_merged_context IS DISTINCT FROM v_existing_context THEN
    UPDATE public.profiles
    SET
      signup_context = v_merged_context,
      updated_at = now()
    WHERE id = p_user_id;
  END IF;

  v_signup_surface := COALESCE(
    NULLIF(v_merged_context->>'signup_surface', ''),
    'unknown'
  );

  IF v_existing_surface IS NOT NULL THEN
    v_attribution_outcome := 'preserved';
  ELSE
    v_attribution_outcome := 'materialized';
  END IF;

  RETURN jsonb_build_object(
    'linked', v_linked_count,
    'attribution_outcome', v_attribution_outcome,
    'signup_surface', v_signup_surface,
    'evidence_source', v_evidence_source
  );
END;
$$;


ALTER FUNCTION "public"."link_anonymous_events_v2"("p_session_id" "uuid", "p_user_id" "uuid", "p_signup_context" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."link_anonymous_events_v2"("p_session_id" "uuid", "p_user_id" "uuid", "p_signup_context" "jsonb") IS 'Links anonymous events from the prior 30 days and fills missing acquisition context for profiles created in the prior 24 hours. Existing first-touch values always win. Service-role only.';



CREATE OR REPLACE FUNCTION "public"."link_experiment_eligibility"("p_user_id" "uuid", "p_build" "text", "p_source" "text") RETURNS TABLE("rows_linked" integer, "already_linked" boolean, "existing_build" "text", "existing_source" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_build text;
  v_source text;
BEGIN
  IF p_source NOT IN ('native_app', 'web_oauth') THEN
    RAISE EXCEPTION 'invalid source %', p_source;
  END IF;

  UPDATE public.experiment_assignments
  SET build = p_build, source = p_source, linked_at = now()
  WHERE user_id = p_user_id AND build IS NULL AND source IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  SELECT ea.build, ea.source INTO v_build, v_source
  FROM public.experiment_assignments ea
  WHERE ea.user_id = p_user_id
  LIMIT 1;

  RETURN QUERY SELECT v_count, (v_count = 0 AND v_build IS NOT NULL), v_build, v_source;
END;
$$;


ALTER FUNCTION "public"."link_experiment_eligibility"("p_user_id" "uuid", "p_build" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_orphan_community_photo_objects_v1"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 100) RETURNS TABLE("storage_path" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT o.name
  FROM storage.objects o
  WHERE o.bucket_id = 'community-spot-photos'
    AND o.created_at <= p_now - interval '15 minutes'
    AND NOT EXISTS (
      SELECT 1 FROM public.community_spot_photos p
      WHERE p.storage_path = o.name
    )
  ORDER BY o.created_at ASC, o.name ASC
  LIMIT LEAST(GREATEST(p_limit, 1), 500)
$$;


ALTER FUNCTION "public"."list_orphan_community_photo_objects_v1"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_owned_removed_community_spot_photos_v1"("p_uploader_id" "uuid") RETURNS TABLE("photo_id" "uuid", "target_type" "text", "target_id" "uuid", "recoverable_until" timestamp with time zone, "moderation_status" "text", "has_active_hold" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    p.id,
    p.target_type,
    COALESCE(p.beach_id, p.custom_spot_id),
    p.recoverable_until,
    p.moderation_status,
    EXISTS (
      SELECT 1 FROM public.community_photo_investigation_holds h
      WHERE h.photo_id = p.id AND h.released_at IS NULL
    )
  FROM public.community_spot_photos p
  WHERE p.uploader_id = p_uploader_id
    AND p.lifecycle_status = 'removed'
    AND p.processing_status = 'ready'
    AND p.recoverable_until > now()
    AND EXISTS (
      SELECT 1 FROM public.community_photo_feature_config config
      WHERE config.singleton AND config.read_enabled
    )
  ORDER BY p.recoverable_until ASC, p.id ASC
  LIMIT 100
$$;


ALTER FUNCTION "public"."list_owned_removed_community_spot_photos_v1"("p_uploader_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    history_table_name TEXT;
    change_type_value TEXT;
    changed_by_id UUID;
    insert_query TEXT;
    column_list TEXT;
    value_list TEXT;
BEGIN
    -- Determine history table name
    history_table_name := TG_TABLE_NAME || '_history';

    -- Determine change type
    IF TG_OP = 'DELETE' THEN
        change_type_value := 'DELETE';
    ELSIF TG_OP = 'UPDATE' THEN
        change_type_value := 'UPDATE';
    ELSE
        -- This trigger should only fire on UPDATE or DELETE
        RETURN OLD;
    END IF;

    -- Get the current user ID from auth context (if available)
    BEGIN
        changed_by_id := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        changed_by_id := NULL;
    END;

    -- Build column list from OLD record
    -- We'll use a dynamic approach to capture all columns
    SELECT
        string_agg(column_name, ', ' ORDER BY ordinal_position),
        string_agg('($1).' || column_name, ', ' ORDER BY ordinal_position)
    INTO column_list, value_list
    FROM information_schema.columns
    WHERE table_schema = TG_TABLE_SCHEMA
    AND table_name = TG_TABLE_NAME
    AND column_name NOT IN ('changed_at', 'changed_by', 'change_type', 'history_id');

    -- Build and execute dynamic insert query
    insert_query := format(
        'INSERT INTO %I.%I (%s, changed_at, changed_by, change_type) VALUES (%s, NOW(), $2, $3)',
        TG_TABLE_SCHEMA,
        history_table_name,
        column_list,
        value_list
    );

    -- Execute the insert
    EXECUTE insert_query USING OLD, changed_by_id, change_type_value;

    -- Return the appropriate record
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;

EXCEPTION WHEN OTHERS THEN
    -- Log error but don't fail the operation
    RAISE WARNING 'Failed to log revision for %.%: %', TG_TABLE_SCHEMA, TG_TABLE_NAME, SQLERRM;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$_$;


ALTER FUNCTION "public"."log_revision"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_revision"() IS 'Trigger function that automatically logs row changes to corresponding history tables. Fires BEFORE UPDATE OR DELETE.';



CREATE OR REPLACE FUNCTION "public"."maintain_board_session_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$ BEGIN IF TG_OP = 'INSERT' THEN IF NEW.board_id IS NOT NULL THEN UPDATE boards SET session_count = COALESCE(session_count, 0) + 1 WHERE id = NEW.board_id; END IF; RETURN NEW; ELSIF TG_OP = 'DELETE' THEN IF OLD.board_id IS NOT NULL THEN UPDATE boards SET session_count = GREATEST(COALESCE(session_count, 0) - 1, 0) WHERE id = OLD.board_id; END IF; RETURN OLD; ELSIF TG_OP = 'UPDATE' THEN IF OLD.board_id IS DISTINCT FROM NEW.board_id THEN IF OLD.board_id IS NOT NULL THEN UPDATE boards SET session_count = GREATEST(COALESCE(session_count, 0) - 1, 0) WHERE id = OLD.board_id; END IF; IF NEW.board_id IS NOT NULL THEN UPDATE boards SET session_count = COALESCE(session_count, 0) + 1 WHERE id = NEW.board_id; END IF; END IF; RETURN NEW; END IF; RETURN NULL; END; $$;


ALTER FUNCTION "public"."maintain_board_session_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."moderate_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_action" "text", "p_reason" "text", "p_idempotency_key" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  new_status text;
  changed integer;
  previous_action text;
BEGIN
  IF p_action = 'hide' THEN
    new_status := 'hidden';
  ELSIF p_action = 'restore' THEN
    new_status := 'visible';
  ELSE
    RAISE EXCEPTION 'invalid_moderation_action';
  END IF;
  SELECT e.action INTO previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_idempotency_key;
  IF previous_action IS NOT NULL THEN
    IF previous_action <> (
      CASE WHEN p_action = 'hide' THEN 'admin_hide' ELSE 'admin_restore' END
    ) THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    RETURN new_status;
  END IF;
  UPDATE public.community_spot_photos
  SET moderation_status = new_status,
      hidden_reason = CASE WHEN new_status = 'hidden' THEN left(p_reason, 280) END,
      updated_at = now()
  WHERE id = p_photo_id AND lifecycle_status = 'active'
    AND processing_status = 'ready';
  GET DIAGNOSTICS changed = ROW_COUNT;
  IF changed <> 1 THEN RAISE EXCEPTION 'photo_not_found'; END IF;
  INSERT INTO public.community_photo_moderation_events (
    photo_id, actor_id, action, reason, idempotency_key
  ) VALUES (
    p_photo_id, p_actor_id,
    CASE WHEN p_action = 'hide' THEN 'admin_hide' ELSE 'admin_restore' END,
    left(p_reason, 280), p_idempotency_key
  );
  RETURN new_status;
END;
$$;


ALTER FUNCTION "public"."moderate_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_action" "text", "p_reason" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nightly_forecast_maintenance"() RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    refresh_result JSON;
    cleanup_count INTEGER;
    final_result JSON;
    start_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- Refresh enhanced forecasts
    refresh_result := refresh_enhanced_forecasts_for_active_beaches();
    
    -- Cleanup stale forecasts
    cleanup_count := cleanup_stale_enhanced_forecasts(14);
    
    -- Update table statistics
    ANALYZE public.enhanced_forecasts;
    ANALYZE public.beaches;
    
    -- Build final result
    final_result := jsonb_build_object(
        'operation', 'nightly_forecast_maintenance',
        'started_at', start_time,
        'completed_at', NOW(),
        'duration_seconds', EXTRACT(EPOCH FROM (NOW() - start_time)),
        'refresh_summary', refresh_result,
        'stale_forecasts_cleaned', cleanup_count,
        'statistics_updated', true
    );
    
    RETURN final_result;
END;
$$;


ALTER FUNCTION "public"."nightly_forecast_maintenance"() OWNER TO "postgres";


