CREATE OR REPLACE FUNCTION "public"."prevent_delete_on_protected"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Allow ephemeral-smoke-test users to be deleted regardless of the
  -- destructive flag. Marker is server-only (app_metadata).
  IF TG_TABLE_SCHEMA = 'auth' AND TG_TABLE_NAME = 'users' THEN
    IF (OLD.raw_app_meta_data->>'is_ephemeral_smoke_test')::boolean IS TRUE THEN
      RETURN OLD;
    END IF;
  ELSIF TG_TABLE_SCHEMA = 'public' AND TG_TABLE_NAME = 'profiles' THEN
    -- Orphan profiles (auth.users row already deleted) are always safe.
    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = OLD.id) THEN
      RETURN OLD;
    END IF;
  END IF;

  -- Existing escape hatch: explicit DBA flag inside a transaction.
  IF current_setting('app.allow_destructive', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'DELETE blocked on % (user=%). Set app.allow_destructive=on inside a transaction if you truly need to proceed.',
      TG_TABLE_NAME, current_user;
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."prevent_delete_on_protected"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_forecasts_retention"("keep_days_raw" integer DEFAULT 90, "keep_days_enhanced" integer DEFAULT 14, "batch_size" integer DEFAULT 25000) RETURNS TABLE("marine_deleted" bigint, "tide_deleted" bigint, "enhanced_deleted" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  cutoff_ts_raw timestamptz := now() - make_interval(days => keep_days_raw);
  cutoff_date_enhanced date := current_date - keep_days_enhanced;
  v_deleted int;
BEGIN
  marine_deleted := 0;
  tide_deleted := 0;
  enhanced_deleted := 0;

  -- Delete old marine_forecasts (90 day retention for ML training data)
  LOOP
    DELETE FROM public.marine_forecasts
    WHERE ctid IN (
      SELECT ctid FROM public.marine_forecasts WHERE ts < cutoff_ts_raw LIMIT batch_size
    );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    marine_deleted := marine_deleted + v_deleted;
    EXIT WHEN v_deleted = 0;
  END LOOP;

  -- Delete old tide_forecasts (90 day retention)
  LOOP
    DELETE FROM public.tide_forecasts
    WHERE ctid IN (
      SELECT ctid FROM public.tide_forecasts WHERE ts < cutoff_ts_raw LIMIT batch_size
    );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    tide_deleted := tide_deleted + v_deleted;
    EXIT WHEN v_deleted = 0;
  END LOOP;

  -- Delete old enhanced_forecasts (14 day retention)
  LOOP
    DELETE FROM public.enhanced_forecasts
    WHERE ctid IN (
      SELECT ctid FROM public.enhanced_forecasts WHERE forecast_date::date < cutoff_date_enhanced LIMIT batch_size
    );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    enhanced_deleted := enhanced_deleted + v_deleted;
    EXIT WHEN v_deleted = 0;
  END LOOP;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."prune_forecasts_retention"("keep_days_raw" integer, "keep_days_enhanced" integer, "batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prune_forecasts_retention"("keep_days_raw" integer, "keep_days_enhanced" integer, "batch_size" integer) IS 'Prunes old forecast data. Retention: 90 days marine/tide (for ML training), 14 days enhanced.
Updated 2026-01-20 to support ML bias correction model training.
Runs daily at 5am via pg_cron. Est. storage: ~1.2 GB for 90 days.';



CREATE OR REPLACE FUNCTION "public"."purge_android_tester_roster_identities"("p_actor_user_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_purged integer;
BEGIN
  DELETE FROM public.android_tester_roster_identities AS identity
  USING public.android_tester_roster_entries AS entry
  WHERE identity.entry_id = entry.id
    AND entry.user_id IS NULL
    AND entry.eligibility_status = 'ineligible'
    AND entry.purge_after <= p_now;
  GET DIAGNOSTICS v_purged = ROW_COUNT;

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    action,
    outcome,
    evidence
  ) VALUES (
    p_actor_user_id,
    'purge',
    'succeeded',
    jsonb_build_object('purgedCount', v_purged)
  );

  RETURN v_purged;
END;
$$;


ALTER FUNCTION "public"."purge_android_tester_roster_identities"("p_actor_user_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_expired_regional_recommendation_holds_v1"() RETURNS TABLE("chains_deleted" bigint, "rows_deleted" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := transaction_timestamp();
  v_candidate_hold_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_hold_id uuid;
  v_hold_ids uuid[] := ARRAY[]::uuid[];
  v_chain_count bigint := 0;
  v_row_count bigint := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('regional-recommendation-hold-retention-v1', 0)
  );

  WITH latest AS (
    SELECT DISTINCT ON (hold_id)
      hold_id,
      status,
      expires_at
    FROM public.regional_recommendation_holds
    ORDER BY hold_id, version DESC
  )
  SELECT COALESCE(
    array_agg(latest.hold_id ORDER BY latest.hold_id),
    ARRAY[]::uuid[]
  )
  INTO v_candidate_hold_ids
  FROM latest
  WHERE (latest.status = 'cancelled' OR latest.expires_at <= v_now)
    AND NOT EXISTS (
      SELECT 1
      FROM public.regional_recommendation_holds AS future_version
      WHERE future_version.hold_id = latest.hold_id
        AND future_version.effective_at > v_now
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.regional_recommendation_holds AS retained_version
      WHERE retained_version.hold_id = latest.hold_id
        AND retained_version.expires_at >= v_now - interval '13 months'
    );

  IF cardinality(v_candidate_hold_ids) = 0 THEN
    RETURN QUERY SELECT 0::bigint, 0::bigint;
    RETURN;
  END IF;

  -- Append takes this same per-hold lock. Lock candidates in UUID order, then
  -- re-evaluate them under lock so a row committed while purge was waiting can
  -- never be swept into the whole-chain DELETE.
  FOREACH v_candidate_hold_id IN ARRAY v_candidate_hold_ids
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'regional-hold:' || v_candidate_hold_id::text,
        0
      )
    );
  END LOOP;

  WITH latest AS (
    SELECT DISTINCT ON (hold_id)
      hold_id,
      status,
      expires_at
    FROM public.regional_recommendation_holds
    ORDER BY hold_id, version DESC
  )
  SELECT COALESCE(
    array_agg(latest.hold_id ORDER BY latest.hold_id),
    ARRAY[]::uuid[]
  )
  INTO v_hold_ids
  FROM latest
  WHERE latest.hold_id = ANY(v_candidate_hold_ids)
    AND (latest.status = 'cancelled' OR latest.expires_at <= v_now)
    AND NOT EXISTS (
      SELECT 1
      FROM public.regional_recommendation_holds AS future_version
      WHERE future_version.hold_id = latest.hold_id
        AND future_version.effective_at > v_now
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.regional_recommendation_holds AS retained_version
      WHERE retained_version.hold_id = latest.hold_id
        AND retained_version.expires_at >= v_now - interval '13 months'
    );

  v_chain_count := cardinality(v_hold_ids);
  IF v_chain_count = 0 THEN
    RETURN QUERY SELECT 0::bigint, 0::bigint;
    RETURN;
  END IF;

  PERFORM set_config(
    'app.regional_recommendation_hold_retention_purge',
    'on',
    true
  );

  DELETE FROM public.regional_recommendation_holds
  WHERE hold_id = ANY(v_hold_ids);
  GET DIAGNOSTICS v_row_count = ROW_COUNT;

  PERFORM set_config(
    'app.regional_recommendation_hold_retention_purge',
    'off',
    true
  );

  RETURN QUERY SELECT v_chain_count, v_row_count;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.regional_recommendation_hold_retention_purge',
    'off',
    true
  );
  RAISE;
END;
$$;


ALTER FUNCTION "public"."purge_expired_regional_recommendation_holds_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_expired_regional_recommendation_holds_v1"() IS 'Deletes only complete terminal hold chains after every row is older than 13 months.';



CREATE OR REPLACE FUNCTION "public"."purge_implicit_history"("target_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  current_user_id uuid;
  is_service_role boolean;
begin
  -- Acquire advisory lock on user_id to prevent concurrent purge operations
  -- This ensures the auth check and deletion are atomic
  -- Using xact-level lock that auto-releases on transaction end
  perform pg_advisory_xact_lock(hashtext('purge_implicit_history'), hashtext(target_user_id::text));

  -- Get current user info
  current_user_id := auth.uid();
  is_service_role := (
    current_setting('role', true) = 'service_role' or
    current_setting('request.jwt.claims', true)::json->>'role' = 'service_role'
  );

  -- Security check: user can only purge their own data
  -- Service role bypasses this check and can purge any user
  -- IMPORTANT: This check happens INSIDE the lock to prevent race conditions
  if target_user_id != current_user_id and not is_service_role then
    raise exception 'Unauthorized: Cannot purge another user''s data';
  end if;

  -- Delete all events for this user
  delete from public.user_events
  where user_id = target_user_id;

  -- Delete implicit preferences for this user
  delete from public.user_implicit_preferences
  where user_id = target_user_id;

  -- Log the purge action for audit trail (optional but recommended)
  -- Note: This could be expanded to write to an audit_log table
  raise notice 'Purged implicit history for user %', target_user_id;

  -- Note: Does NOT change profiles.allow_implicit_tracking
  -- User can disable tracking separately via settings
end;
$$;


ALTER FUNCTION "public"."purge_implicit_history"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_implicit_history"("target_user_id" "uuid") IS 'Deletes all implicit preference data for a user. Uses advisory lock to prevent race conditions. User can only purge their own data unless service_role.';



CREATE OR REPLACE FUNCTION "public"."purge_removed_community_spot_photos_v1"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 100) RETURNS TABLE("photo_id" "uuid", "storage_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH candidates AS (
    SELECT p.id, p.storage_path
    FROM public.community_spot_photos p
    WHERE (
        (p.lifecycle_status = 'removed' AND p.recoverable_until <= p_now)
        OR
        (
          p.lifecycle_status = 'purging'
          AND p.updated_at <= p_now - interval '15 minutes'
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.community_photo_investigation_holds h
        WHERE h.photo_id = p.id AND h.released_at IS NULL
      )
    ORDER BY p.recoverable_until ASC, p.id ASC
    LIMIT LEAST(GREATEST(p_limit, 1), 500)
    FOR UPDATE SKIP LOCKED
  ),
  claimed AS (
    UPDATE public.community_spot_photos p
    SET lifecycle_status = 'purging', updated_at = now()
    FROM candidates c
    WHERE p.id = c.id
      AND NOT EXISTS (
        SELECT 1 FROM public.community_photo_investigation_holds h
        WHERE h.photo_id = p.id AND h.released_at IS NULL
      )
    RETURNING p.id, p.storage_path
  )
  SELECT c.id, c.storage_path FROM claimed c;
END;
$$;


ALTER FUNCTION "public"."purge_removed_community_spot_photos_v1"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_android_tester_roster_audit"("p_actor_user_id" "uuid", "p_entry_id" "uuid", "p_action" "text", "p_outcome" "text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id bigint;
BEGIN
  IF p_evidence ?| ARRAY[
      'email',
      'memberId',
      'member_id',
      'externalMemberId',
      'external_member_id',
      'ciphertext'
    ]
    OR p_evidence::text ~ '@' THEN
    RAISE EXCEPTION 'PII is not permitted in roster audit evidence';
  END IF;

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    entry_id,
    action,
    outcome,
    evidence
  ) VALUES (
    p_actor_user_id,
    p_entry_id,
    p_action,
    p_outcome,
    COALESCE(p_evidence, '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_android_tester_roster_audit"("p_actor_user_id" "uuid", "p_entry_id" "uuid", "p_action" "text", "p_outcome" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_android_tester_roster_first_open"("p_user_id" "uuid", "p_native_install_id" "uuid", "p_idempotency_key_hash" "text") RETURNS TABLE("outcome" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_entry_id uuid;
BEGIN
  IF p_idempotency_key_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN QUERY SELECT 'terminal_invalid'::text;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_first_open_evidence AS first_open
    WHERE first_open.user_id = p_user_id
      AND first_open.idempotency_key_hash = p_idempotency_key_hash
  ) THEN
    RETURN QUERY SELECT 'same_key_retry'::text;
    RETURN;
  END IF;

  SELECT entry.id
  INTO v_entry_id
  FROM public.android_tester_roster_entries AS entry
  WHERE entry.user_id = p_user_id
  FOR UPDATE;

  IF v_entry_id IS NULL THEN
    RETURN QUERY SELECT 'pending_retryable'::text;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_first_open_evidence AS first_open
    WHERE first_open.user_id = p_user_id
      AND first_open.idempotency_key_hash = p_idempotency_key_hash
  ) THEN
    RETURN QUERY SELECT 'same_key_retry'::text;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_first_open_evidence AS first_open
    WHERE first_open.entry_id = v_entry_id
      AND first_open.native_install_id = p_native_install_id
  ) THEN
    RETURN QUERY SELECT 'terminal_invalid'::text;
    RETURN;
  END IF;

  INSERT INTO public.android_tester_roster_first_open_evidence (
    entry_id,
    user_id,
    native_install_id,
    idempotency_key_hash
  ) VALUES (
    v_entry_id,
    p_user_id,
    p_native_install_id,
    p_idempotency_key_hash
  );

  INSERT INTO public.android_tester_roster_stages (
    entry_id,
    stage,
    status,
    source,
    observed_at,
    confidence,
    evidence
  ) VALUES (
    v_entry_id,
    'first_open',
    'observed',
    'native_first_open_explicit',
    now(),
    'verified',
    '{}'::jsonb
  );

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    entry_id,
    action,
    outcome,
    evidence
  ) VALUES (
    NULL,
    v_entry_id,
    'record_first_open',
    'succeeded',
    '{}'::jsonb
  );

  RETURN QUERY SELECT 'observed'::text;
END;
$_$;


ALTER FUNCTION "public"."record_android_tester_roster_first_open"("p_user_id" "uuid", "p_native_install_id" "uuid", "p_idempotency_key_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_android_tester_roster_install"("p_user_id" "uuid", "p_native_install_id" "uuid", "p_idempotency_key_hash" "text", "p_source" "text", "p_surface" "text", "p_placement" "text", "p_campaign" "text", "p_created_on" "date", "p_expires_on" "date") RETURNS TABLE("outcome" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_entry_id uuid;
BEGIN
  IF p_idempotency_key_hash !~ '^[a-f0-9]{64}$'
     OR p_expires_on < p_created_on
     OR p_expires_on > p_created_on + 30 THEN
    RETURN QUERY SELECT 'terminal_invalid'::text;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_install_evidence AS install
    WHERE install.user_id = p_user_id
      AND install.idempotency_key_hash = p_idempotency_key_hash
  ) THEN
    RETURN QUERY SELECT 'same_key_retry'::text;
    RETURN;
  END IF;

  SELECT entry.id
  INTO v_entry_id
  FROM public.android_tester_roster_entries AS entry
  WHERE entry.user_id = p_user_id
  FOR UPDATE;

  IF v_entry_id IS NULL THEN
    RETURN QUERY SELECT 'pending_retryable'::text;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_install_evidence AS install
    WHERE install.user_id = p_user_id
      AND install.idempotency_key_hash = p_idempotency_key_hash
  ) THEN
    RETURN QUERY SELECT 'same_key_retry'::text;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.android_tester_roster_install_evidence AS install
    WHERE install.entry_id = v_entry_id
      AND install.native_install_id = p_native_install_id
  ) THEN
    RETURN QUERY SELECT 'terminal_invalid'::text;
    RETURN;
  END IF;

  INSERT INTO public.android_tester_roster_install_evidence (
    entry_id,
    user_id,
    native_install_id,
    idempotency_key_hash,
    source,
    surface,
    placement,
    campaign,
    created_on,
    expires_on
  ) VALUES (
    v_entry_id,
    p_user_id,
    p_native_install_id,
    p_idempotency_key_hash,
    p_source,
    p_surface,
    p_placement,
    p_campaign,
    p_created_on,
    p_expires_on
  );

  INSERT INTO public.android_tester_roster_stages (
    entry_id,
    stage,
    status,
    source,
    observed_at,
    confidence,
    evidence
  ) VALUES (
    v_entry_id,
    'install',
    'observed',
    'bounded_install_attribution',
    now(),
    'attributed',
    jsonb_build_object(
      'source', p_source,
      'surface', p_surface,
      'placement', p_placement,
      'campaign', p_campaign,
      'createdOn', p_created_on,
      'expiresOn', p_expires_on
    )
  );

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    entry_id,
    action,
    outcome,
    evidence
  ) VALUES (
    NULL,
    v_entry_id,
    'record_install_evidence',
    'succeeded',
    '{}'::jsonb
  );

  RETURN QUERY SELECT 'observed'::text;
END;
$_$;


ALTER FUNCTION "public"."record_android_tester_roster_install"("p_user_id" "uuid", "p_native_install_id" "uuid", "p_idempotency_key_hash" "text", "p_source" "text", "p_surface" "text", "p_placement" "text", "p_campaign" "text", "p_created_on" "date", "p_expires_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_android_tester_roster_stage"("p_actor_user_id" "uuid", "p_entry_id" "uuid", "p_stage" "text", "p_status" "text", "p_source" "text", "p_observed_at" timestamp with time zone, "p_confidence" "text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_stage_id bigint;
BEGIN
  IF p_stage <> 'play_opt_in'
     OR p_status NOT IN ('observed', 'not_observed')
     OR p_source <> 'manual_google_play_console'
     OR p_confidence <> 'manual'
     OR jsonb_typeof(COALESCE(p_evidence, 'null'::jsonb)) <> 'object'
     OR NOT p_evidence ? 'code'
     OR NOT p_evidence ? 'referenceId'
     OR p_evidence - ARRAY['code', 'referenceId'] <> '{}'::jsonb
     OR p_evidence->>'code' <> 'play_console_membership_review'
     OR COALESCE(p_evidence->>'referenceId', '') !~
       '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'Invalid Play evidence';
  END IF;

  INSERT INTO public.android_tester_roster_stages (
    entry_id,
    stage,
    status,
    source,
    observed_at,
    confidence,
    evidence
  ) VALUES (
    p_entry_id,
    p_stage,
    p_status,
    p_source,
    p_observed_at,
    p_confidence,
    COALESCE(p_evidence, '{}'::jsonb)
  )
  RETURNING id INTO v_stage_id;

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    entry_id,
    action,
    outcome,
    evidence
  ) VALUES (
    p_actor_user_id,
    p_entry_id,
    'record_play_evidence',
    'succeeded',
    jsonb_build_object('stageId', v_stage_id)
  );

  RETURN v_stage_id;
END;
$_$;


ALTER FUNCTION "public"."record_android_tester_roster_stage"("p_actor_user_id" "uuid", "p_entry_id" "uuid", "p_stage" "text", "p_status" "text", "p_source" "text", "p_observed_at" timestamp with time zone, "p_confidence" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_referral_attribution"("referrer" "uuid", "referee" "uuid", "source" "text", "referral_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_referrer_code text;
  v_attribution_code text;
  v_inserted_id uuid;
  v_existing_id uuid;
BEGIN
  IF auth.uid() IS DISTINCT FROM $2 THEN
    RAISE EXCEPTION 'referee mismatch: must match auth.uid()'
      USING ERRCODE = '42501';
  END IF;

  IF $1 IS NULL OR $2 IS NULL THEN
    RAISE EXCEPTION 'referrer and referee are required'
      USING ERRCODE = '22023';
  END IF;

  IF $1 = $2 THEN
    RAISE EXCEPTION 'cannot refer yourself'
      USING ERRCODE = '22023';
  END IF;

  IF $3 NOT IN ('referral_code', 'invite_token') THEN
    RAISE EXCEPTION 'invalid referral source: %', $3
      USING ERRCODE = '22023';
  END IF;

  SELECT p.referral_code
    INTO v_referrer_code
    FROM public.profiles p
    WHERE p.id = $1
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'referrer profile not found'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_referrer_code IS NULL THEN
    v_referrer_code := public.generate_referral_code();

    UPDATE public.profiles p
      SET referral_code = v_referrer_code
      WHERE p.id = $1
        AND p.referral_code IS NULL
      RETURNING p.referral_code
      INTO v_referrer_code;
  END IF;

  v_attribution_code := COALESCE(NULLIF(upper(trim($4)), ''), v_referrer_code);

  INSERT INTO public.referrals (
    referrer_id,
    referee_id,
    referral_code,
    status,
    source
  ) VALUES (
    $1,
    $2,
    v_attribution_code,
    'pending',
    $3
  )
  ON CONFLICT (referee_id) DO NOTHING
  RETURNING id INTO v_inserted_id;

  IF v_inserted_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'created', true,
      'existing', false,
      'referral_id', v_inserted_id,
      'source', $3
    );
  END IF;

  SELECT r.id
    INTO v_existing_id
    FROM public.referrals r
    WHERE r.referee_id = $2;

  RETURN jsonb_build_object(
    'created', false,
    'existing', true,
    'referral_id', v_existing_id,
    'source', $3
  );
END;
$_$;


ALTER FUNCTION "public"."record_referral_attribution"("referrer" "uuid", "referee" "uuid", "source" "text", "referral_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_referral_attribution"("referrer" "uuid", "referee" "uuid", "source" "text", "referral_code" "text") IS 'Creates one idempotent referral attribution row for the authenticated referee.';



CREATE OR REPLACE FUNCTION "public"."recover_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  changed integer;
  previous_action text;
BEGIN
  SELECT e.action INTO previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_idempotency_key;
  IF previous_action IS NOT NULL THEN
    IF previous_action <> 'admin_recover' THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
    RETURN true;
  END IF;
  UPDATE public.community_spot_photos p
  SET lifecycle_status = 'active', removed_at = NULL, recoverable_until = NULL,
      updated_at = now()
  WHERE p.id = p_photo_id
    AND p.lifecycle_status = 'removed'
    AND p.recoverable_until > now();
  GET DIAGNOSTICS changed = ROW_COUNT;
  IF changed <> 1 THEN RAISE EXCEPTION 'photo_not_recoverable'; END IF;
  INSERT INTO public.community_photo_moderation_events (
    photo_id, actor_id, action, reason, idempotency_key
  ) VALUES (p_photo_id, p_actor_id, 'admin_recover', 'manual_recovery', p_idempotency_key);
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  ) VALUES (p_photo_id, p_actor_id, 'recover', 'accepted', 'admin_recovered', p_idempotency_key);
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."recover_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_owned_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_idempotency_key" "uuid") RETURNS TABLE("photo_id" "uuid", "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  previous_photo_id uuid;
  locked_photo_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.community_photo_feature_config
    WHERE singleton AND read_enabled AND writes_enabled
  ) THEN
    RAISE EXCEPTION 'feature_disabled';
  END IF;
  SELECT e.photo_id INTO previous_photo_id
  FROM public.community_photo_action_events e
  WHERE e.actor_id = p_uploader_id
    AND e.action = 'recover'
    AND e.idempotency_key = p_idempotency_key;
  IF previous_photo_id IS NOT NULL THEN
    IF previous_photo_id <> p_photo_id THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    RETURN QUERY SELECT p_photo_id, 'active'::text;
    RETURN;
  END IF;

  SELECT p.id INTO locked_photo_id
  FROM public.community_spot_photos p
  WHERE p.id = p_photo_id
    AND p.uploader_id = p_uploader_id
    AND p.lifecycle_status = 'removed'
    AND p.processing_status = 'ready'
    AND p.moderation_status = 'visible'
    AND p.recoverable_until > now()
    AND (
      (
        p.target_type = 'beach'
        AND p.visibility = 'public'
        AND EXISTS (
          SELECT 1 FROM public.beaches b
          WHERE b.id = p.beach_id AND COALESCE(b.is_private, false) = false
        )
      )
      OR (
        p.target_type = 'custom_spot'
        AND EXISTS (
          SELECT 1 FROM public.custom_spots cs
          WHERE cs.id = p.custom_spot_id
            AND cs.deleted_at IS NULL
            AND (
              (p.visibility = 'public' AND cs.visibility = 'public')
              OR (
                p.visibility = 'private'
                AND cs.user_id = p_uploader_id
              )
            )
        )
      )
    )
  FOR UPDATE;
  IF locked_photo_id IS NULL OR EXISTS (
    SELECT 1 FROM public.community_photo_investigation_holds h
    WHERE h.photo_id = p_photo_id AND h.released_at IS NULL
  ) THEN
    RAISE EXCEPTION 'photo_not_recoverable';
  END IF;

  UPDATE public.community_spot_photos
  SET lifecycle_status = 'active',
      removed_at = NULL,
      recoverable_until = NULL,
      updated_at = now()
  WHERE id = locked_photo_id;
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  ) VALUES (
    p_photo_id, p_uploader_id, 'recover', 'accepted', 'owner_recovered',
    p_idempotency_key
  );
  RETURN QUERY SELECT p_photo_id, 'active'::text;
END;
$$;


ALTER FUNCTION "public"."recover_owned_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redeem_install_attribution_token"("p_token_hash" "text", "p_redemption_key_hash" "text") RETURNS TABLE("source" "text", "surface" "text", "placement" "text", "campaign" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  matched_rows integer;
BEGIN
  IF p_token_hash !~ '^[a-f0-9]{64}$'
     OR p_redemption_key_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN;
  END IF;

  RETURN QUERY
  UPDATE public.install_attribution_tokens AS token
  SET
    consumed_at = now(),
    redemption_key_hash = p_redemption_key_hash
  WHERE token.token_hash = p_token_hash
    AND token.consumed_at IS NULL
    AND token.expires_at > now()
  RETURNING
    token.source,
    token.surface,
    token.placement,
    token.campaign,
    token.created_at,
    token.expires_at;

  GET DIAGNOSTICS matched_rows = ROW_COUNT;
  IF matched_rows > 0 THEN
    INSERT INTO public.install_attribution_audit (
      token_hash_prefix,
      action,
      outcome
    ) VALUES (
      left(p_token_hash, 12),
      'redeem',
      'redeemed'
    );
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    token.source,
    token.surface,
    token.placement,
    token.campaign,
    token.created_at,
    token.expires_at
  FROM public.install_attribution_tokens AS token
  WHERE token.token_hash = p_token_hash
    AND token.consumed_at IS NOT NULL
    AND token.redemption_key_hash = p_redemption_key_hash
    AND token.expires_at > now();

  GET DIAGNOSTICS matched_rows = ROW_COUNT;
  INSERT INTO public.install_attribution_audit (
    token_hash_prefix,
    action,
    outcome
  ) VALUES (
    left(p_token_hash, 12),
    'redeem',
    CASE WHEN matched_rows > 0 THEN 'same_key_retry' ELSE 'unavailable' END
  );
END;
$_$;


ALTER FUNCTION "public"."redeem_install_attribution_token"("p_token_hash" "text", "p_redemption_key_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redeem_install_attribution_token"("p_token_hash" "text", "p_redemption_key_hash" "text") IS 'Atomically consumes a valid token and lets the same hashed retry key recover a lost HTTP response.';



