    ),
    'expires_at', to_char(
      p_row.expires_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    ),
    'supersedes_record_id', p_row.supersedes_record_id,
