CREATE OR REPLACE FUNCTION "public"."remove_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_idempotency_key" "uuid") RETURNS TABLE("photo_id" "uuid", "status" "text", "recoverable_until" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  recovery_at timestamptz;
  previous_event boolean;
BEGIN
  SELECT true INTO previous_event
  FROM public.community_photo_action_events e
  WHERE e.actor_id = p_uploader_id
    AND e.action = 'remove'
    AND e.idempotency_key = p_idempotency_key;
  IF previous_event THEN
    SELECT p.recoverable_until INTO recovery_at
    FROM public.community_spot_photos p
    WHERE p.id = p_photo_id AND p.uploader_id = p_uploader_id;
    IF recovery_at IS NULL THEN RAISE EXCEPTION 'photo_not_found'; END IF;
    RETURN QUERY SELECT p_photo_id, 'removed'::text, recovery_at;
    RETURN;
  END IF;
  UPDATE public.community_spot_photos
  SET lifecycle_status = 'removed',
      removed_at = now(),
      recoverable_until = now() + interval '30 days',
      updated_at = now()
  WHERE id = p_photo_id AND uploader_id = p_uploader_id
    AND lifecycle_status = 'active'
  RETURNING community_spot_photos.recoverable_until INTO recovery_at;
  IF recovery_at IS NULL THEN
    RAISE EXCEPTION 'photo_not_found';
  END IF;
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  ) VALUES (
    p_photo_id, p_uploader_id, 'remove', 'accepted', 'contributor_removed',
    p_idempotency_key
  )
  ON CONFLICT (actor_id, action, idempotency_key) DO NOTHING;
  RETURN QUERY SELECT p_photo_id, 'removed'::text, recovery_at;
END;
$$;


ALTER FUNCTION "public"."remove_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_custom_spot_favorite_on_soft_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    DELETE FROM public.favorite_beaches
    WHERE custom_spot_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."remove_custom_spot_favorite_on_soft_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repair_strict_session_snapshots"("p_limit" integer DEFAULT 100, "p_apply" boolean DEFAULT false) RETURNS TABLE("session_id" "uuid", "user_id" "uuid", "beach_id" "uuid", "forecast_at" timestamp with time zone, "delta_minutes" numeric, "repaired" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT p_apply THEN
    RETURN QUERY
    SELECT
      c.session_id,
      c.user_id,
      c.beach_id,
      c.forecast_at,
      c.delta_minutes,
      false AS repaired
    FROM public.strict_session_snapshot_repair_candidates(p_limit) c;
    RETURN;
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT * FROM public.strict_session_snapshot_repair_candidates(p_limit)
  ),
  source_rows AS (
    SELECT
      c.session_id,
      c.user_id,
      c.beach_id,
      c.forecast_at,
      c.delta_minutes,
      s.arrival_time,
      s.rating,
      s.wave_quality,
      s.wave_height_ft,
      s.crowd_level,
      s.duration_minutes,
      to_jsonb(ef) AS forecast_snapshot,
      ef.confidence_score,
      ef.data_source
    FROM candidates c
    JOIN public.sessions s ON s.id = c.session_id
    JOIN public.enhanced_forecasts ef
      ON ef.beach_id = c.beach_id
      AND ef.forecast_at = c.forecast_at
  ),
  inserted AS (
    INSERT INTO public.session_forecast_snapshots (
      session_id,
      user_id,
      beach_id,
      forecast_snapshot,
      actual_conditions,
      forecast_confidence_score,
      data_source,
      session_date
    )
    SELECT
      sr.session_id,
      sr.user_id,
      sr.beach_id,
      sr.forecast_snapshot,
      jsonb_build_object(
        'arrival_time', sr.arrival_time,
        'rating', sr.rating,
        'wave_quality', sr.wave_quality,
        'wave_height_ft', sr.wave_height_ft,
        'crowd_level', sr.crowd_level,
        'duration_minutes', sr.duration_minutes
      ),
      sr.confidence_score,
      sr.data_source,
      sr.arrival_time::date
    FROM source_rows sr
    ON CONFLICT ON CONSTRAINT unique_session_forecast_snapshot DO NOTHING
    RETURNING public.session_forecast_snapshots.session_id AS inserted_session_id
  )
  SELECT
    sr.session_id,
    sr.user_id,
    sr.beach_id,
    sr.forecast_at,
    sr.delta_minutes,
    inserted.inserted_session_id IS NOT NULL AS repaired
  FROM source_rows sr
  LEFT JOIN inserted ON inserted.inserted_session_id = sr.session_id;
END;
$$;


ALTER FUNCTION "public"."repair_strict_session_snapshots"("p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."repair_strict_session_snapshots"("p_limit" integer, "p_apply" boolean) IS 'Strict same-beach +/-90 minute session snapshot repair. p_apply=false previews only; production apply requires explicit approval.';



CREATE OR REPLACE FUNCTION "public"."report_community_spot_photo_v1"("p_photo_id" "uuid", "p_reporter_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid") RETURNS TABLE("photo_id" "uuid", "status" "text", "report_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  owner_id uuid;
  photo_visibility text;
  quality_reports integer;
  all_reports integer;
  should_hide boolean;
  previous_reason text;
  current_status text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.community_photo_feature_config
    WHERE singleton AND read_enabled AND writes_enabled
  ) THEN
    RAISE EXCEPTION 'feature_disabled';
  END IF;
  IF p_reason NOT IN ('explicit', 'privacy', 'safety', 'wrong_spot', 'stale') THEN
    RAISE EXCEPTION 'invalid_report';
  END IF;
  SELECT e.reason_code INTO previous_reason
  FROM public.community_photo_action_events e
  WHERE e.actor_id = p_reporter_id
    AND e.action = 'report'
    AND e.idempotency_key = p_idempotency_key;
  IF previous_reason IS NOT NULL THEN
    IF previous_reason <> p_reason THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
    SELECT
      CASE WHEN p.moderation_status = 'hidden' THEN 'hidden' ELSE 'visible' END
    INTO current_status
    FROM public.community_spot_photos p WHERE p.id = p_photo_id;
    IF current_status IS NULL THEN RAISE EXCEPTION 'photo_not_found'; END IF;
    SELECT count(*)::integer INTO all_reports
    FROM public.community_photo_reports reports
    WHERE reports.photo_id = p_photo_id;
    RETURN QUERY SELECT p_photo_id, current_status, all_reports;
    RETURN;
  END IF;
  SELECT uploader_id, visibility INTO owner_id, photo_visibility
  FROM public.community_spot_photos
  WHERE id = p_photo_id AND visibility = 'public'
    AND processing_status = 'ready'
    AND moderation_status = 'visible'
    AND lifecycle_status = 'active'
  FOR UPDATE;
  IF photo_visibility IS NULL THEN
    RAISE EXCEPTION 'photo_not_found';
  END IF;
  IF owner_id IS NOT NULL AND owner_id = p_reporter_id THEN
    RAISE EXCEPTION 'photo_owner_cannot_report';
  END IF;
  INSERT INTO public.community_photo_reports (photo_id, reporter_id, reason)
  VALUES (p_photo_id, p_reporter_id, p_reason)
  ON CONFLICT ON CONSTRAINT community_photo_reports_pkey DO UPDATE
  SET reason = EXCLUDED.reason, updated_at = now();
  SELECT
    count(*) FILTER (WHERE reports.reason IN ('wrong_spot', 'stale'))::integer,
    count(*)::integer
  INTO quality_reports, all_reports
  FROM public.community_photo_reports reports
  WHERE reports.photo_id = p_photo_id;
  should_hide := p_reason IN ('explicit', 'privacy', 'safety') OR quality_reports >= 3;
  IF should_hide THEN
    UPDATE public.community_spot_photos
    SET moderation_status = 'hidden',
        hidden_reason = CASE
          WHEN p_reason IN ('explicit', 'privacy', 'safety') THEN p_reason
          ELSE 'quality_reports'
        END,
        updated_at = now()
    WHERE id = p_photo_id;
    INSERT INTO public.community_photo_moderation_events (
      photo_id, actor_id, action, reason, idempotency_key
    ) VALUES (
      p_photo_id, NULL, 'auto_hide',
      CASE WHEN p_reason IN ('explicit', 'privacy', 'safety')
        THEN p_reason ELSE 'three_unique_quality_reporters' END,
      p_idempotency_key
    )
    ON CONFLICT (actor_id, idempotency_key) DO NOTHING;
  END IF;
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  ) VALUES (
    p_photo_id, p_reporter_id, 'report', 'accepted', p_reason, p_idempotency_key
  )
  ON CONFLICT (actor_id, action, idempotency_key) DO NOTHING;
  RETURN QUERY SELECT p_photo_id, CASE WHEN should_hide THEN 'hidden' ELSE 'visible' END, all_reports;
END;
$$;


ALTER FUNCTION "public"."report_community_spot_photo_v1"("p_photo_id" "uuid", "p_reporter_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_target_type" "text", "p_target_id" "uuid", "p_visibility" "text", "p_storage_path" "text", "p_terms_version" "text", "p_rights_confirmed" boolean, "p_idempotency_key" "uuid") RETURNS TABLE("photo_id" "uuid", "storage_path" "text", "replay" boolean, "processing_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  existing_id uuid;
  existing_storage_path text;
  existing_status text;
  active_count integer;
  rolling_count integer;
  custom_owner uuid;
  custom_visibility text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_uploader_id::text, 35));

  SELECT p.id, p.storage_path, p.processing_status
    INTO existing_id, existing_storage_path, existing_status
  FROM public.community_spot_photos p
  WHERE p.uploader_id = p_uploader_id
    AND p.idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF existing_id IS NOT NULL THEN
    RETURN QUERY SELECT
      existing_id,
      existing_storage_path,
      true,
      existing_status;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.community_photo_action_events e
    WHERE e.actor_id = p_uploader_id
      AND e.action = 'upload_failed'
      AND e.outcome = 'failed'
      AND e.idempotency_key = p_idempotency_key
  ) THEN
    RAISE EXCEPTION 'upload_attempt_failed';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.community_photo_action_events e
    WHERE e.actor_id = p_uploader_id
      AND e.action = 'upload_reserved'
      AND e.outcome = 'accepted'
      AND e.idempotency_key = p_idempotency_key
  ) THEN
    RAISE EXCEPTION 'idempotency_conflict';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.community_photo_feature_config
    WHERE singleton AND read_enabled AND writes_enabled
      AND terms_version = p_terms_version
  ) THEN
    RAISE EXCEPTION 'feature_disabled';
  END IF;
  IF p_terms_version <> '2026-07-25' OR NOT p_rights_confirmed THEN
    RAISE EXCEPTION 'consent_required';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.community_photo_contributor_restrictions r
    WHERE r.contributor_id = p_uploader_id
      AND r.lifted_at IS NULL
      AND (r.restricted_until IS NULL OR r.restricted_until > now())
  ) THEN
    RAISE EXCEPTION 'contributor_restricted';
  END IF;

  IF p_target_type = 'beach' THEN
    IF p_visibility <> 'public' OR NOT EXISTS (
      SELECT 1 FROM public.beaches b
      WHERE b.id = p_target_id AND COALESCE(b.is_private, false) = false
    ) THEN
      RAISE EXCEPTION 'invalid_target';
    END IF;
  ELSIF p_target_type = 'custom_spot' THEN
    SELECT c.user_id, c.visibility
      INTO custom_owner, custom_visibility
    FROM public.custom_spots c
    WHERE c.id = p_target_id AND c.deleted_at IS NULL;
    IF custom_owner IS NULL THEN
      RAISE EXCEPTION 'invalid_target';
    END IF;
    IF p_visibility = 'private' AND custom_owner <> p_uploader_id THEN
      RAISE EXCEPTION 'private_target_forbidden';
    END IF;
    IF p_visibility = 'public' AND custom_visibility <> 'public' THEN
      RAISE EXCEPTION 'private_target_forbidden';
    END IF;
  ELSE
    RAISE EXCEPTION 'invalid_target';
  END IF;

  SELECT count(*) INTO active_count
  FROM public.community_spot_photos p
  WHERE p.uploader_id = p_uploader_id
    AND p.lifecycle_status = 'active'
    AND (
      (p_target_type = 'beach' AND p.beach_id = p_target_id)
      OR (p_target_type = 'custom_spot' AND p.custom_spot_id = p_target_id)
    );
  -- 3 active photos per contributor and target.
  IF active_count >= 3 THEN
    RAISE EXCEPTION 'target_active_limit';
  END IF;

  SELECT count(*) INTO rolling_count
  FROM public.community_photo_action_events e
  WHERE e.actor_id = p_uploader_id
    AND e.action = 'upload_reserved'
    AND e.outcome = 'accepted'
    AND e.created_at > now() - interval '24 hours';
  -- 5 rolling uploads per 24 hours across all targets.
  IF rolling_count >= 5 THEN
    RAISE EXCEPTION 'rolling_upload_limit';
  END IF;

  INSERT INTO public.community_spot_photos (
    id, uploader_id, target_type, beach_id, custom_spot_id, visibility,
    storage_path, idempotency_key
  )
  VALUES (
    p_photo_id,
    p_uploader_id,
    p_target_type,
    CASE WHEN p_target_type = 'beach' THEN p_target_id END,
    CASE WHEN p_target_type = 'custom_spot' THEN p_target_id END,
    p_visibility,
    p_storage_path,
    p_idempotency_key
  );
  INSERT INTO public.community_photo_consents (
    photo_id, contributor_id, terms_version, rights_confirmed
  ) VALUES (p_photo_id, p_uploader_id, p_terms_version, p_rights_confirmed);
  INSERT INTO public.community_photo_action_events (
    photo_id, actor_id, action, outcome, reason_code, idempotency_key
  ) VALUES (
    p_photo_id, p_uploader_id, 'upload_reserved', 'accepted', 'reserved',
    p_idempotency_key
  );
  RETURN QUERY SELECT p_photo_id, p_storage_path, false, 'processing';
END;
$$;


ALTER FUNCTION "public"."reserve_community_spot_photo_v1"("p_photo_id" "uuid", "p_uploader_id" "uuid", "p_target_type" "text", "p_target_id" "uuid", "p_visibility" "text", "p_storage_path" "text", "p_terms_version" "text", "p_rights_confirmed" boolean, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_active_regional_recommendation_holds"("p_as_of" timestamp with time zone, "p_beach_ids" "uuid"[], "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone) RETURNS SETOF "public"."regional_recommendation_holds"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH effective_versions AS (
    SELECT *
    FROM public.regional_recommendation_holds
    WHERE effective_at <= p_as_of
  ), latest AS (
    SELECT DISTINCT ON (hold_id) *
    FROM effective_versions
    ORDER BY hold_id, version DESC
  )
  SELECT latest.*
  FROM latest
  WHERE status = 'active'
    AND expires_at > p_as_of
    AND valid_from < p_window_end
    AND valid_until > p_window_start
    AND scope_beach_ids && p_beach_ids;
$$;


ALTER FUNCTION "public"."resolve_active_regional_recommendation_holds"("p_as_of" timestamp with time zone, "p_beach_ids" "uuid"[], "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_android_waitlist_entry"("p_user_id" "uuid", "p_normalized_email_sha256" "text", "p_roster_entry_id" "uuid", "p_source_kind" "text", "p_source_id" "uuid", "p_source" "text", "p_surface" "text", "p_placement" "text", "p_observed_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_user_entry_id uuid;
  v_email_entry_id uuid;
  v_roster_entry_id uuid;
  v_source_entry_id uuid;
  v_entry_id uuid;
  v_merge_entry_id uuid;
  v_existing_user_id uuid;
  v_existing_email_sha256 text;
  v_merge_user_id uuid;
  v_merge_email_sha256 text;
  v_merge_first_joined_at timestamptz;
  v_merge_last_joined_at timestamptz;
  v_link_entry_id uuid;
BEGIN
  IF p_source_kind NOT IN (
      'anonymous_lead',
      'profile_intent',
      'roster_evidence'
    )
    OR p_source_id IS NULL
    OR p_observed_at IS NULL
    OR char_length(COALESCE(p_source, '')) NOT BETWEEN 1 AND 120
    OR char_length(COALESCE(p_surface, '')) NOT BETWEEN 1 AND 80
    OR char_length(COALESCE(p_placement, '')) NOT BETWEEN 1 AND 80
    OR (
      p_normalized_email_sha256 IS NOT NULL
      AND p_normalized_email_sha256 !~ '^[a-f0-9]{64}$'
    )
    OR (
      p_source_kind = 'roster_evidence'
      AND p_roster_entry_id IS NULL
    )
    OR (
      p_source_kind <> 'roster_evidence'
      AND p_roster_entry_id IS NOT NULL
    ) THEN
    RAISE EXCEPTION 'Invalid canonical Android waitlist source';
  END IF;

  -- Low-volume global serialization makes precedence deterministic under
  -- concurrent exact lead/profile/roster observations.
  PERFORM pg_catalog.pg_advisory_xact_lock(20560726);

  IF p_user_id IS NOT NULL THEN
    SELECT entry.id
    INTO v_user_entry_id
    FROM public.android_waitlist_entries AS entry
    WHERE entry.user_id = p_user_id;
  END IF;

  IF p_normalized_email_sha256 IS NOT NULL THEN
    SELECT entry.id
    INTO v_email_entry_id
    FROM public.android_waitlist_entries AS entry
    WHERE entry.normalized_email_sha256 = p_normalized_email_sha256;
  END IF;

  IF p_roster_entry_id IS NOT NULL THEN
    SELECT link.entry_id
    INTO v_roster_entry_id
    FROM public.android_waitlist_source_links AS link
    WHERE link.roster_entry_id = p_roster_entry_id;
  END IF;

  SELECT link.entry_id
  INTO v_source_entry_id
  FROM public.android_waitlist_source_links AS link
  WHERE link.source_kind = p_source_kind
    AND link.source_id = p_source_id;

  v_entry_id := COALESCE(
    v_user_entry_id,
    v_email_entry_id,
    v_roster_entry_id,
    v_source_entry_id
  );

  IF v_entry_id IS NULL THEN
    INSERT INTO public.android_waitlist_entries (
      user_id,
      normalized_email_sha256,
      first_joined_at,
      last_joined_at
    )
    SELECT
      p_user_id,
      p_normalized_email_sha256,
      p_observed_at,
      p_observed_at
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.android_waitlist_entries AS entry
      WHERE (p_user_id IS NOT NULL AND entry.user_id = p_user_id)
        OR (
          p_normalized_email_sha256 IS NOT NULL
          AND entry.normalized_email_sha256 = p_normalized_email_sha256
        )
    )
    RETURNING id INTO v_entry_id;
  END IF;

  IF v_entry_id IS NULL THEN
    RAISE EXCEPTION 'Canonical Android waitlist identity changed concurrently';
  END IF;

  FOR v_merge_entry_id IN
    SELECT DISTINCT candidate.entry_id
    FROM unnest(ARRAY[
      v_user_entry_id,
      v_email_entry_id,
      v_roster_entry_id,
      v_source_entry_id
    ]) AS candidate(entry_id)
    WHERE candidate.entry_id IS NOT NULL
      AND candidate.entry_id <> v_entry_id
  LOOP
    SELECT entry.user_id, entry.normalized_email_sha256
    INTO v_existing_user_id, v_existing_email_sha256
    FROM public.android_waitlist_entries AS entry
    WHERE entry.id = v_entry_id
    FOR UPDATE;

    SELECT
      merge_entry.user_id,
      merge_entry.normalized_email_sha256,
      merge_entry.first_joined_at,
      merge_entry.last_joined_at
    INTO
      v_merge_user_id,
      v_merge_email_sha256,
      v_merge_first_joined_at,
      v_merge_last_joined_at
    FROM public.android_waitlist_entries AS merge_entry
    WHERE merge_entry.id = v_merge_entry_id
    FOR UPDATE;

    IF (
      v_existing_user_id IS NOT NULL
      AND v_merge_user_id IS NOT NULL
      AND v_merge_user_id <> v_existing_user_id
    ) OR (
      v_existing_email_sha256 IS NOT NULL
      AND v_merge_email_sha256 IS NOT NULL
      AND v_merge_email_sha256 <> v_existing_email_sha256
    ) THEN
      RAISE EXCEPTION 'Conflicting exact Android waitlist identities';
    END IF;

    UPDATE public.android_waitlist_entries
    SET
      user_id = NULL,
      normalized_email_sha256 = NULL
    WHERE id = v_merge_entry_id;

    UPDATE public.android_waitlist_entries
    SET
      user_id = COALESCE(user_id, v_merge_user_id),
      normalized_email_sha256 = COALESCE(
        normalized_email_sha256,
        v_merge_email_sha256
      ),
      first_joined_at = LEAST(
        first_joined_at,
        v_merge_first_joined_at
      ),
      last_joined_at = GREATEST(
        last_joined_at,
        v_merge_last_joined_at
      ),
      updated_at = now()
    WHERE id = v_entry_id;

    UPDATE public.android_waitlist_source_links
    SET entry_id = v_entry_id, updated_at = now()
    WHERE entry_id = v_merge_entry_id;

    IF EXISTS (
      SELECT 1
      FROM public.android_waitlist_events
      WHERE entry_id = v_entry_id
        AND event_type = 'android_waitlist_joined'
    ) THEN
      DELETE FROM public.android_waitlist_events
      WHERE entry_id = v_merge_entry_id
        AND event_type = 'android_waitlist_joined';
    ELSE
      UPDATE public.android_waitlist_events
      SET entry_id = v_entry_id
      WHERE entry_id = v_merge_entry_id
        AND event_type = 'android_waitlist_joined';
    END IF;

    DELETE FROM public.android_waitlist_entries
    WHERE id = v_merge_entry_id;
  END LOOP;

  SELECT entry.user_id, entry.normalized_email_sha256
  INTO v_existing_user_id, v_existing_email_sha256
  FROM public.android_waitlist_entries AS entry
  WHERE entry.id = v_entry_id
  FOR UPDATE;

  IF (v_existing_user_id IS NOT NULL
      AND p_user_id IS NOT NULL
      AND v_existing_user_id <> p_user_id)
    OR (
      v_existing_email_sha256 IS NOT NULL
      AND p_normalized_email_sha256 IS NOT NULL
      AND v_existing_email_sha256 <> p_normalized_email_sha256
    ) THEN
    RAISE EXCEPTION 'Conflicting exact Android waitlist identity';
  END IF;

  UPDATE public.android_waitlist_entries
  SET
    user_id = COALESCE(user_id, p_user_id),
    normalized_email_sha256 = COALESCE(
      normalized_email_sha256,
      p_normalized_email_sha256
    ),
    first_joined_at = LEAST(first_joined_at, p_observed_at),
    last_joined_at = GREATEST(last_joined_at, p_observed_at),
    updated_at = now()
  WHERE id = v_entry_id;

  INSERT INTO public.android_waitlist_source_links (
    entry_id,
    source_kind,
    source_id,
    roster_entry_id,
    source,
    surface,
    placement,
    first_observed_at,
    last_observed_at
  )
  SELECT
    v_entry_id,
    p_source_kind,
    p_source_id,
    p_roster_entry_id,
    p_source,
    p_surface,
    p_placement,
    p_observed_at,
    p_observed_at
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.android_waitlist_source_links AS link
    WHERE link.source_kind = p_source_kind
      AND link.source_id = p_source_id
  );

  UPDATE public.android_waitlist_source_links
  SET
    roster_entry_id = COALESCE(roster_entry_id, p_roster_entry_id),
    last_observed_at = GREATEST(last_observed_at, p_observed_at),
    updated_at = now()
  WHERE source_kind = p_source_kind
    AND source_id = p_source_id
  RETURNING entry_id INTO v_link_entry_id;

  IF v_link_entry_id <> v_entry_id THEN
    RAISE EXCEPTION 'Canonical Android waitlist source conflict';
  END IF;

  INSERT INTO public.android_waitlist_events (
    entry_id,
    event_type,
    source_kind,
    observed_at
  )
  SELECT
    v_entry_id,
    'android_waitlist_joined',
    p_source_kind,
    p_observed_at
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.android_waitlist_events AS event
    WHERE event.entry_id = v_entry_id
      AND event.event_type = 'android_waitlist_joined'
  );

  RETURN v_entry_id;
END;
$_$;


ALTER FUNCTION "public"."resolve_android_waitlist_entry"("p_user_id" "uuid", "p_normalized_email_sha256" "text", "p_roster_entry_id" "uuid", "p_source_kind" "text", "p_source_id" "uuid", "p_source" "text", "p_surface" "text", "p_placement" "text", "p_observed_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_android_waitlist_entry"("p_user_id" "uuid", "p_normalized_email_sha256" "text", "p_roster_entry_id" "uuid", "p_source_kind" "text", "p_source_id" "uuid", "p_source" "text", "p_surface" "text", "p_placement" "text", "p_observed_at" timestamp with time zone) IS 'Resolves exact identity precedence: user ID, normalized contact SHA-256, roster identity link, source tuple, then new entry.';



CREATE OR REPLACE FUNCTION "public"."resolve_community_spot_photo_batch_v1"("p_targets" "jsonb", "p_viewer_id" "uuid" DEFAULT NULL::"uuid", "p_limit_per_target" integer DEFAULT 6) RETURNS TABLE("photo_id" "uuid", "target_type" "text", "target_id" "uuid", "visibility" "text", "width" integer, "height" integer, "uploader_id" "uuid", "display_name" "text", "upvotes" integer, "downvotes" integer, "viewer_vote" "text", "wilson_score" double precision, "is_pinned" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT resolved.*
  FROM jsonb_to_recordset(p_targets) AS target(target_type text, target_id uuid)
  CROSS JOIN LATERAL public.resolve_community_spot_photos_v1(
    target.target_type,
    target.target_id,
    p_viewer_id,
    LEAST(GREATEST(p_limit_per_target, 1), 20)
  ) resolved
$$;


ALTER FUNCTION "public"."resolve_community_spot_photo_batch_v1"("p_targets" "jsonb", "p_viewer_id" "uuid", "p_limit_per_target" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_community_spot_photo_by_id_v1"("p_photo_id" "uuid", "p_viewer_id" "uuid") RETURNS TABLE("photo_id" "uuid", "target_type" "text", "target_id" "uuid", "visibility" "text", "width" integer, "height" integer, "uploader_id" "uuid", "display_name" "text", "upvotes" integer, "downvotes" integer, "viewer_vote" "text", "wilson_score" double precision, "is_pinned" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    p.id,
    p.target_type,
    COALESCE(p.beach_id, p.custom_spot_id),
    p.visibility,
    p.width,
    p.height,
    p.uploader_id,
    NULLIF(btrim(pr.display_name), ''),
    counts.upvotes,
    counts.downvotes,
    (
      SELECT v.vote
      FROM public.community_photo_votes v
      WHERE v.photo_id = p.id AND v.voter_id = p_viewer_id
    ),
    public.community_photo_wilson_lower_bound(
      counts.upvotes,
      counts.downvotes
    ),
    EXISTS (
      SELECT 1 FROM public.community_photo_feature_pins pin
      WHERE pin.photo_id = p.id AND pin.revoked_at IS NULL
    ),
    p.created_at
  FROM public.community_spot_photos p
  LEFT JOIN public.profiles pr ON pr.id = p.uploader_id
  CROSS JOIN LATERAL (
    SELECT
      count(*) FILTER (WHERE v.vote = 'up')::integer AS upvotes,
      count(*) FILTER (WHERE v.vote = 'down')::integer AS downvotes
    FROM public.community_photo_votes v
    WHERE v.photo_id = p.id
  ) counts
  WHERE p.id = p_photo_id
    AND p.processing_status = 'ready'
    AND p.moderation_status = 'visible'
    AND p.lifecycle_status = 'active'
    AND EXISTS (
      SELECT 1 FROM public.community_photo_feature_config config
      WHERE config.singleton AND config.read_enabled
    )
    AND (
      (
        p.target_type = 'beach'
        AND p.visibility = 'public'
        AND EXISTS (
          SELECT 1 FROM public.beaches b
          WHERE b.id = p.beach_id AND COALESCE(b.is_private, false) = false
        )
      )
      OR
      (
        p.target_type = 'custom_spot'
        AND EXISTS (
          SELECT 1 FROM public.custom_spots cs
          WHERE cs.id = p.custom_spot_id
            AND cs.deleted_at IS NULL
            AND (
              (p.visibility = 'public' AND cs.visibility = 'public')
              OR (
                p.visibility = 'private'
                AND cs.user_id = p_viewer_id
                AND p.uploader_id = p_viewer_id
              )
            )
        )
      )
    )
$$;


ALTER FUNCTION "public"."resolve_community_spot_photo_by_id_v1"("p_photo_id" "uuid", "p_viewer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_community_spot_photos_v1"("p_target_type" "text", "p_target_id" "uuid", "p_viewer_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("photo_id" "uuid", "target_type" "text", "target_id" "uuid", "visibility" "text", "width" integer, "height" integer, "uploader_id" "uuid", "display_name" "text", "upvotes" integer, "downvotes" integer, "viewer_vote" "text", "wilson_score" double precision, "is_pinned" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH candidates AS (
    SELECT
      p.id AS photo_id,
      p.target_type,
      COALESCE(p.beach_id, p.custom_spot_id) AS target_id,
      p.visibility,
      p.width,
      p.height,
      p.uploader_id,
      NULLIF(btrim(pr.display_name), '') AS display_name,
      count(*) FILTER (WHERE v.vote = 'up')::integer AS upvotes,
      count(*) FILTER (WHERE v.vote = 'down')::integer AS downvotes,
      max(v.vote) FILTER (WHERE v.voter_id = p_viewer_id) AS viewer_vote,
      EXISTS (
        SELECT 1 FROM public.community_photo_feature_pins pin
        WHERE pin.photo_id = p.id AND pin.revoked_at IS NULL
      ) AS is_pinned,
      p.created_at
    FROM public.community_spot_photos p
    LEFT JOIN public.profiles pr ON pr.id = p.uploader_id
    LEFT JOIN public.community_photo_votes v ON v.photo_id = p.id
    WHERE p.processing_status = 'ready'
      AND p.moderation_status = 'visible'
      AND p.lifecycle_status = 'active'
      AND EXISTS (
        SELECT 1 FROM public.community_photo_feature_config config
        WHERE config.singleton AND config.read_enabled
      )
      AND p.target_type = p_target_type
      AND COALESCE(p.beach_id, p.custom_spot_id) = p_target_id
      AND (
        (
          p.target_type = 'beach'
          AND p.visibility = 'public'
          AND EXISTS (
            SELECT 1 FROM public.beaches b
            WHERE b.id = p.beach_id AND COALESCE(b.is_private, false) = false
          )
        )
        OR
        (
          p.target_type = 'custom_spot'
          AND EXISTS (
            SELECT 1 FROM public.custom_spots cs
            WHERE cs.id = p.custom_spot_id
              AND cs.deleted_at IS NULL
              AND (
                (p.visibility = 'public' AND cs.visibility = 'public')
                OR
                (
                  p.visibility = 'private'
                  AND cs.user_id = p_viewer_id
                  AND p.uploader_id = p_viewer_id
                )
              )
          )
        )
      )
    GROUP BY p.id, pr.display_name
  )
  SELECT
    c.photo_id, c.target_type, c.target_id, c.visibility, c.width, c.height,
    c.uploader_id, c.display_name, c.upvotes, c.downvotes, c.viewer_vote,
    public.community_photo_wilson_lower_bound(c.upvotes, c.downvotes) AS wilson_score,
    c.is_pinned, c.created_at
  FROM candidates c
  ORDER BY
    c.is_pinned DESC,
    wilson_score DESC,
    (c.upvotes + c.downvotes) DESC,
    c.photo_id ASC
  LIMIT LEAST(GREATEST(p_limit, 1), 100)
$$;


ALTER FUNCTION "public"."resolve_community_spot_photos_v1"("p_target_type" "text", "p_target_id" "uuid", "p_viewer_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_entity"("table_name" "text", "entity_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    sql_query TEXT;
    rows_affected INTEGER;
BEGIN
    -- Validate table name to prevent SQL injection
    IF table_name NOT IN ('beaches', 'sessions', 'beach_reviews', 'beach_photos', 'session_media') THEN
        RAISE EXCEPTION 'Invalid table name: %', table_name;
    END IF;

    -- Build and execute restore query
    sql_query := format(
        'UPDATE public.%I SET deleted_at = NULL WHERE id = $1 AND deleted_at IS NOT NULL',
        table_name
    );

    EXECUTE sql_query USING entity_id;
    GET DIAGNOSTICS rows_affected = ROW_COUNT;

    RETURN rows_affected > 0;
END;
$_$;


ALTER FUNCTION "public"."restore_entity"("table_name" "text", "entity_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_entity"("table_name" "text", "entity_id" "uuid") IS 'Helper function to restore soft-deleted entities. Returns true if entity was restored, false if not deleted or not found.';



CREATE OR REPLACE FUNCTION "public"."restrict_community_photo_contributor_v1"("p_contributor_id" "uuid", "p_actor_id" "uuid", "p_reason_code" "text", "p_restricted_until" timestamp with time zone, "p_idempotency_key" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  previous_action text;
BEGIN
  SELECT e.action INTO previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_idempotency_key;
  IF previous_action IS NOT NULL THEN
    IF previous_action <> 'admin_restrict_contributor' THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    RETURN true;
  END IF;
  IF char_length(p_reason_code) NOT BETWEEN 1 AND 64 THEN
    RAISE EXCEPTION 'invalid_request';
  END IF;
  INSERT INTO public.community_photo_contributor_restrictions (
    contributor_id, restricted_until, reason_code, applied_by,
    applied_at, lifted_at, lifted_by
  ) VALUES (
    p_contributor_id, p_restricted_until, p_reason_code, p_actor_id,
    now(), NULL, NULL
  )
  ON CONFLICT (contributor_id) DO UPDATE SET
    restricted_until = EXCLUDED.restricted_until,
    reason_code = EXCLUDED.reason_code,
    applied_by = EXCLUDED.applied_by,
    applied_at = now(),
    lifted_at = NULL,
    lifted_by = NULL;
  INSERT INTO public.community_photo_moderation_events (
    subject_user_id, actor_id, action, reason, idempotency_key
  ) VALUES (
    p_contributor_id, p_actor_id, 'admin_restrict_contributor',
    p_reason_code, p_idempotency_key
  );
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."restrict_community_photo_contributor_v1"("p_contributor_id" "uuid", "p_actor_id" "uuid", "p_reason_code" "text", "p_restricted_until" timestamp with time zone, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_database_maintenance"("cleanup_forecasts" boolean DEFAULT true, "cleanup_buoys" boolean DEFAULT true, "update_stats" boolean DEFAULT true, "forecast_retention_days" integer DEFAULT 30, "buoy_inactive_days" integer DEFAULT 7) RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
  forecasts_cleaned INTEGER := 0;
  buoys_cleaned INTEGER := 0;
  start_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
  result := jsonb_build_object(
    'maintenance_started', start_time,
    'operations', '[]'::jsonb
  );

  IF cleanup_forecasts THEN
    forecasts_cleaned := public.cleanup_old_forecasts(forecast_retention_days);
    result := jsonb_set(
      result,
      '{operations}',
      result->'operations' || jsonb_build_object(
        'operation', 'forecast_cleanup',
        'records_affected', forecasts_cleaned,
        'retention_days', forecast_retention_days
      )
    );
  END IF;

  IF cleanup_buoys THEN
    buoys_cleaned := public.cleanup_inactive_buoys(buoy_inactive_days);
    result := jsonb_set(
      result,
      '{operations}',
      result->'operations' || jsonb_build_object(
        'operation', 'buoy_cleanup',
        'records_affected', buoys_cleaned,
        'inactive_days', buoy_inactive_days
      )
    );
  END IF;

  IF update_stats THEN
    PERFORM public.update_forecast_table_stats();
    result := jsonb_set(
      result,
      '{operations}',
      result->'operations' || jsonb_build_object(
        'operation', 'statistics_update',
        'completed', true
      )
    );
  END IF;

  result := jsonb_set(result, '{maintenance_completed}', to_jsonb(NOW()));
  result := jsonb_set(
    result,
    '{duration_seconds}',
    to_jsonb(EXTRACT(EPOCH FROM (NOW() - start_time)))
  );

  RETURN result::JSON;
END;
$$;


ALTER FUNCTION "public"."run_database_maintenance"("cleanup_forecasts" boolean, "cleanup_buoys" boolean, "update_stats" boolean, "forecast_retention_days" integer, "buoy_inactive_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_audit_triggers_enabled"("enabled" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    trigger_state TEXT;
    result_message TEXT;
BEGIN
    -- Only admins can disable audit triggers
    IF NOT EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid() AND is_admin = true
    ) THEN
        RAISE EXCEPTION 'Only administrators can modify audit trigger state';
    END IF;

    IF enabled THEN
        trigger_state := 'ENABLE';
        result_message := 'Audit triggers enabled';
    ELSE
        trigger_state := 'DISABLE';
        result_message := 'Audit triggers disabled (WARNING: Changes will not be logged!)';
    END IF;

    -- Enable/disable triggers on all tracked tables
    EXECUTE format('ALTER TABLE public.beach_reviews %s TRIGGER log_beach_reviews_changes', trigger_state);

    -- Handle beach_photos if it exists
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public'
        AND table_name = 'beach_photos'
    ) THEN
        EXECUTE format('ALTER TABLE public.beach_photos %s TRIGGER log_beach_photos_changes', trigger_state);
    END IF;

    -- Handle session_media if it exists
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public'
        AND table_name = 'session_media'
    ) THEN
        EXECUTE format('ALTER TABLE public.session_media %s TRIGGER log_session_media_changes', trigger_state);
    END IF;

    RETURN result_message;
END;
$$;


ALTER FUNCTION "public"."set_audit_triggers_enabled"("enabled" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_audit_triggers_enabled"("enabled" boolean) IS 'Enable or disable audit triggers. Only admins can call this function. Use with caution - disabling triggers means changes will not be logged.';



CREATE OR REPLACE FUNCTION "public"."set_profile_analytics_real_user_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  normalized_email text;
BEGIN
  normalized_email := lower(coalesce(NEW.email, ''));

  IF coalesce(NEW.is_mock, false) THEN
    NEW.analytics_is_real_user := false;
    NEW.analytics_exclusion_reason := 'mock_profile';
  ELSIF NEW.email IS NOT NULL AND normalized_email LIKE '%@local.test' THEN
    NEW.analytics_is_real_user := false;
    NEW.analytics_exclusion_reason := 'local_test_email';
  ELSIF NEW.email IS NOT NULL AND normalized_email LIKE '%@example.invalid' THEN
    NEW.analytics_is_real_user := false;
    NEW.analytics_exclusion_reason := 'example_invalid_email';
  ELSIF NEW.email IS NOT NULL AND normalized_email LIKE '%test%' THEN
    NEW.analytics_is_real_user := false;
    NEW.analytics_exclusion_reason := 'test_email';
  ELSE
    NEW.analytics_is_real_user := true;
    NEW.analytics_exclusion_reason := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_profile_analytics_real_user_fields"() OWNER TO "postgres";


