    'beachId', p_row -> 'beachId',
    'localDate', p_row -> 'localDate',
    'localTimezone', p_row -> 'localTimezone',
    'primaryIssueId', p_row -> 'primaryIssueId',
    'signedGapFt', public.trusted_forecast_canonical_number(
      p_row -> 'signedGapFt'
    ),
    'status', p_row -> 'status',
    'trustedMaxFaceFt', public.trusted_forecast_canonical_number(
      p_row -> 'trustedMaxFaceFt'
    ),
    'trustedMinFaceFt', public.trusted_forecast_canonical_number(
      p_row -> 'trustedMinFaceFt'
    )
  );
$$;


ALTER FUNCTION "public"."trusted_forecast_canonical_decision"("p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trusted_forecast_canonical_number"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_value IS NULL OR jsonb_typeof(p_value) = 'null' THEN 'null'::jsonb
    ELSE to_jsonb(
      to_char((p_value #>> '{}')::numeric, 'FM9999999990.0000')
    )
  END;
$$;


ALTER FUNCTION "public"."trusted_forecast_canonical_number"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trusted_forecast_canonical_snapshot"("p_row" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(
    jsonb_object_agg(
      column_name,
      CASE
        WHEN column_name = 'predicted_at'
          THEN public.trusted_forecast_canonical_timestamp(p_row -> column_name)
        WHEN jsonb_typeof(p_row -> column_name) = 'number'
          THEN public.trusted_forecast_canonical_number(p_row -> column_name)
        ELSE coalesce(p_row -> column_name, 'null'::jsonb)
      END
    ),
    '{}'::jsonb
  )
  FROM unnest(public.trusted_forecast_snapshot_columns()) AS column_name;
$$;


ALTER FUNCTION "public"."trusted_forecast_canonical_snapshot"("p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trusted_forecast_canonical_timestamp"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_value IS NULL OR jsonb_typeof(p_value) = 'null' THEN 'null'::jsonb
    ELSE to_jsonb(
      to_char(
        (p_value #>> '{}')::timestamptz AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    )
  END;
$$;


ALTER FUNCTION "public"."trusted_forecast_canonical_timestamp"("p_value" "jsonb") OWNER TO "postgres";


