    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT ARRAY[
    'beach_id',
    'predicted_at',
    'forecast_horizon_hours',
    'forecast_horizon_bucket',
    'raw_display_height_m',
    'offset_corrected_display_height_m',
    'height_offset_m',
    'height_offset_sample_count',
    'feedback_height_calibration_candidate_id',
    'feedback_height_offset_ft',
    'feedback_height_calibration_applied',
    'display_source',
    'display_wave_source',
    'display_raw_input_height_m',
    'model_version',
    'wave_height_om',
    'noaa_swell_1_height_m',
    'noaa_swell_1_period_s',
    'noaa_swell_1_direction_deg',
    'noaa_swell_2_height_m',
    'noaa_swell_2_period_s',
    'noaa_swell_2_direction_deg',
    'noaa_wind_wave_height_m',
    'noaa_wind_wave_period_s',
    'noaa_wind_wave_direction_deg',
    'wave_period_s',
    'wave_direction_deg',
    'wave_period_om',
    'wave_direction_om',
    'wave_peak_period_om',
    'swell_height_om',
    'swell_period_om',
    'swell_direction_om',
    'swell_wave_peak_period_om',
    'wind_wave_height_om',
    'wind_wave_period_om',
    'wind_wave_direction_om',
    'wind_wave_peak_period_om',
    'secondary_swell_height_om',
    'secondary_swell_period_om',
    'secondary_swell_direction_om',
    'tertiary_swell_height_om',
    'tertiary_swell_period_om',
    'tertiary_swell_direction_om',
    'om_wind_wave_missing',
    'om_primary_swell_missing',
    'om_secondary_swell_missing',
    'om_tertiary_swell_missing',
    'om_partition_schema_version',
    'wind_speed_ms',
    'wind_direction_deg',
    'v5_shadow_height_m',
    'v5_model_version',
    'direction_bucket',
    'om_bucket'
  ]::text[];
$$;


ALTER FUNCTION "public"."trusted_forecast_snapshot_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."try_insert_similarity_alert"("p_user_id" "uuid", "p_rule_id" "uuid", "p_beach_id" "uuid", "p_alert_date" "date", "p_send_at" timestamp with time zone, "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_best_hour" timestamp with time zone, "p_conditions_snapshot" "jsonb") RETURNS TABLE("inserted" boolean, "alert_queue_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_verdict text;
BEGIN
  IF (p_conditions_snapshot ->> 'alert_type') IS DISTINCT FROM 'similarity_match' THEN
    RAISE EXCEPTION
      'try_insert_similarity_alert requires conditions_snapshot.alert_type = similarity_match (got: %)',
      coalesce(p_conditions_snapshot ->> 'alert_type', '<null>');
  END IF;

  v_verdict := CASE
    WHEN p_conditions_snapshot ? 'session_decision'
      THEN p_conditions_snapshot -> 'session_decision' ->> 'verdict'
    ELSE 'go'
  END;
  IF v_verdict IS NULL OR v_verdict NOT IN ('go', 'maybe', 'no') THEN
    RAISE EXCEPTION
      'try_insert_similarity_alert requires a canonical session_decision.verdict (got: %)',
      coalesce(v_verdict, '<null>');
  END IF;

  INSERT INTO public.alert_queue (
    user_id,
    rule_id,
    beach_id,
    alert_date,
    send_at,
    window_start,
    window_end,
    best_hour,
    conditions_snapshot,
    sent
  ) VALUES (
    p_user_id,
    p_rule_id,
    p_beach_id,
    p_alert_date,
    p_send_at,
    p_window_start,
    p_window_end,
    p_best_hour,
    p_conditions_snapshot,
    false
  )
  ON CONFLICT (
    user_id,
    beach_id,
    window_start,
    (
      CASE
        WHEN conditions_snapshot ? 'session_decision'
          THEN conditions_snapshot -> 'session_decision' ->> 'verdict'
        ELSE 'go'
      END
    )
  )
  WHERE (conditions_snapshot ->> 'alert_type') = 'similarity_match'
  DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RETURN QUERY SELECT false, NULL::uuid;
  ELSE
    RETURN QUERY SELECT true, v_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."try_insert_similarity_alert"("p_user_id" "uuid", "p_rule_id" "uuid", "p_beach_id" "uuid", "p_alert_date" "date", "p_send_at" timestamp with time zone, "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_best_hour" timestamp with time zone, "p_conditions_snapshot" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."try_insert_similarity_alert"("p_user_id" "uuid", "p_rule_id" "uuid", "p_beach_id" "uuid", "p_alert_date" "date", "p_send_at" timestamp with time zone, "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_best_hour" timestamp with time zone, "p_conditions_snapshot" "jsonb") IS 'Idempotently queues a similarity alert by user, beach, window, and canonical verdict; legacy missing verdicts are treated as go.';



CREATE OR REPLACE FUNCTION "public"."unpin_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  changed integer;
  previous_action text;
BEGIN
  SELECT e.action INTO previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_idempotency_key;
  IF previous_action IS NOT NULL THEN
    IF previous_action <> 'admin_unpin' THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
    RETURN true;
  END IF;
  UPDATE public.community_photo_feature_pins
  SET revoked_at = now(), revoked_by = p_actor_id
  WHERE photo_id = p_photo_id AND revoked_at IS NULL;
  GET DIAGNOSTICS changed = ROW_COUNT;
  IF changed = 0 THEN RAISE EXCEPTION 'pin_not_found'; END IF;
  INSERT INTO public.community_photo_moderation_events (
    photo_id, actor_id, action, reason, idempotency_key
  ) VALUES (p_photo_id, p_actor_id, 'admin_unpin', 'manual_unfeature', p_idempotency_key);
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."unpin_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unrestrict_community_photo_contributor_v1"("p_contributor_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  changed integer;
  previous_action text;
BEGIN
  SELECT e.action INTO previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_idempotency_key;
  IF previous_action IS NOT NULL THEN
    IF previous_action <> 'admin_unrestrict_contributor' THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    RETURN true;
  END IF;
  UPDATE public.community_photo_contributor_restrictions
  SET lifted_at = now(), lifted_by = p_actor_id
  WHERE contributor_id = p_contributor_id AND lifted_at IS NULL;
  GET DIAGNOSTICS changed = ROW_COUNT;
  IF changed = 0 THEN RAISE EXCEPTION 'restriction_not_found'; END IF;
  INSERT INTO public.community_photo_moderation_events (
    subject_user_id, actor_id, action, reason, idempotency_key
  ) VALUES (
    p_contributor_id, p_actor_id, 'admin_unrestrict_contributor',
    'manual_release', p_idempotency_key
  );
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."unrestrict_community_photo_contributor_v1"("p_contributor_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_beach_affinity_on_session_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    INSERT INTO user_beach_affinity (user_id, beach_id, session_count, last_surfed_at, affinity_score)
    SELECT
      NEW.user_id,
      NEW.beach_id,
      COUNT(*),
      MAX(arrival_time),
      compute_beach_affinity(NEW.user_id, NEW.beach_id)
    FROM sessions
    WHERE user_id = NEW.user_id AND beach_id = NEW.beach_id
    GROUP BY user_id, beach_id
    ON CONFLICT (user_id, beach_id) DO UPDATE SET
      session_count = EXCLUDED.session_count,
      last_surfed_at = EXCLUDED.last_surfed_at,
      affinity_score = EXCLUDED.affinity_score,
      computed_at = NOW();
  END IF;

  IF TG_OP = 'DELETE' THEN
    DELETE FROM user_beach_affinity
    WHERE user_id = OLD.user_id AND beach_id = OLD.beach_id
    AND NOT EXISTS (
      SELECT 1 FROM sessions
      WHERE user_id = OLD.user_id AND beach_id = OLD.beach_id
    );
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."update_beach_affinity_on_session_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_beach_affinity_on_session_change"() IS 'Trigger function that automatically updates beach affinity when sessions are added, modified, or deleted. Uses SECURITY DEFINER to bypass RLS.';



