    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "best_score" numeric DEFAULT 0 NOT NULL,
    "delivery_shadow_outcome" "jsonb"
);


ALTER TABLE "public"."alert_queue" OWNER TO "postgres";


COMMENT ON COLUMN "public"."alert_queue"."best_score" IS 'Best matched alert-window score used to order consolidated alert emails.';



COMMENT ON COLUMN "public"."alert_queue"."delivery_shadow_outcome" IS 'Snapshot recorded when forecast alert delivery is shadowed: status, canonical verdict/reason, preset type, and channels that reached the send boundary.';



CREATE TABLE IF NOT EXISTS "public"."alert_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "beach_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "preset_type" "text",
    "conditions" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "notify_email" boolean DEFAULT true NOT NULL,
    "notify_push" boolean DEFAULT true NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "last_matched_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "auto_created_at" timestamp with time zone,
    CONSTRAINT "alert_rules_preset_type_check" CHECK (("preset_type" = ANY (ARRAY['glass_off'::"text", 'big_day'::"text", 'clean_groundswell'::"text", 'mellow_session'::"text", 'tide_window'::"text", 'dawn_patrol'::"text", 'epic_conditions'::"text", 'similarity_alert'::"text", 'similarity_match'::"text", 'daily_check_in'::"text", 'weekend_warrior'::"text", 'after_work'::"text"])))
);


ALTER TABLE "public"."alert_rules" OWNER TO "postgres";


COMMENT ON COLUMN "public"."alert_rules"."auto_created_at" IS 'Non-null when this rule was system-created (e.g., similarity_match auto-enable for Pro/trial users). Null = user-created. Used to distinguish auto-seeded rows from manual rules in audit/analytics.';



CREATE TABLE IF NOT EXISTS "public"."amenities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "amenity_type" "text" NOT NULL,
    "lat" double precision NOT NULL,
    "lon" double precision NOT NULL,
    "geog" "extensions"."geography"(Point,4326) GENERATED ALWAYS AS (("extensions"."st_setsrid"("extensions"."st_makepoint"("lon", "lat"), 4326))::"extensions"."geography") STORED,
    "label" "text",
    "source" "text" NOT NULL,
    "source_ref" "text",
    "confidence" smallint DEFAULT 50 NOT NULL,
    "verified_at" timestamp with time zone,
    "imported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "raw" "jsonb",
    CONSTRAINT "amenities_confidence_range" CHECK ((("confidence" >= 0) AND ("confidence" <= 100))),
    CONSTRAINT "amenities_lat_range" CHECK ((("lat" >= ('-90'::integer)::double precision) AND ("lat" <= (90)::double precision))),
