CREATE TABLE IF NOT EXISTS "public"."beach_feedback_calibration_candidates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "beach_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'shadow'::"text" NOT NULL,
    "offset_ft" numeric(4,2) NOT NULL,
    "sample_count" integer NOT NULL,
    "unique_user_count" integer NOT NULL,
    "evidence_window_start" timestamp with time zone,
    "evidence_window_end" timestamp with time zone,
    "residual_direction" "text" NOT NULL,
    "mae_before_ft" numeric(6,3) NOT NULL,
    "mae_after_ft" numeric(6,3) NOT NULL,
    "decision_reason" "text" NOT NULL,
    "evidence_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "shadow_started_at" timestamp with time zone,
    "activated_at" timestamp with time zone,
    "rejected_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "beach_feedback_calibration_candidates_check" CHECK ((("status" <> 'active_temp'::"text") OR (("activated_at" IS NOT NULL) AND ("expires_at" IS NOT NULL) AND ("expires_at" > "activated_at")))),
    CONSTRAINT "beach_feedback_calibration_candidates_mae_after_ft_check" CHECK (("mae_after_ft" >= (0)::numeric)),
    CONSTRAINT "beach_feedback_calibration_candidates_mae_before_ft_check" CHECK (("mae_before_ft" >= (0)::numeric)),
    CONSTRAINT "beach_feedback_calibration_candidates_offset_ft_check" CHECK ((("offset_ft" >= '-0.50'::numeric) AND ("offset_ft" <= 0.50))),
    CONSTRAINT "beach_feedback_calibration_candidates_residual_direction_check" CHECK (("residual_direction" = ANY (ARRAY['forecast_too_high'::"text", 'forecast_too_low'::"text", 'neutral'::"text"]))),
    CONSTRAINT "beach_feedback_calibration_candidates_sample_count_check" CHECK (("sample_count" >= 0)),
    CONSTRAINT "beach_feedback_calibration_candidates_status_check" CHECK (("status" = ANY (ARRAY['shadow'::"text", 'active_temp'::"text", 'expired'::"text", 'rejected'::"text", 'manual_hold'::"text"]))),
    CONSTRAINT "beach_feedback_calibration_candidates_unique_user_count_check" CHECK (("unique_user_count" >= 0))
);


