CREATE TABLE IF NOT EXISTS "public"."community_spot_photos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "uploader_id" "uuid",
    "target_type" "text" NOT NULL,
    "beach_id" "uuid",
    "custom_spot_id" "uuid",
    "visibility" "text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "content_type" "text" DEFAULT 'image/webp'::"text" NOT NULL,
    "width" integer,
    "height" integer,
    "processing_status" "text" DEFAULT 'processing'::"text" NOT NULL,
    "moderation_status" "text" DEFAULT 'visible'::"text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "hidden_reason" "text",
    "removed_at" timestamp with time zone,
    "recoverable_until" timestamp with time zone,
    "idempotency_key" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "community_photo_exactly_one_target" CHECK (((("target_type" = 'beach'::"text") AND ("beach_id" IS NOT NULL) AND ("custom_spot_id" IS NULL)) OR (("target_type" = 'custom_spot'::"text") AND ("beach_id" IS NULL) AND ("custom_spot_id" IS NOT NULL)))),
    CONSTRAINT "community_photo_private_custom_only" CHECK ((("visibility" = 'public'::"text") OR ("target_type" = 'custom_spot'::"text"))),
    CONSTRAINT "community_photo_removal_window" CHECK (((("lifecycle_status" = 'active'::"text") AND ("removed_at" IS NULL) AND ("recoverable_until" IS NULL)) OR (("lifecycle_status" = ANY (ARRAY['removed'::"text", 'purging'::"text"])) AND ("removed_at" IS NOT NULL) AND ("recoverable_until" = ("removed_at" + '30 days'::interval))))),
    CONSTRAINT "community_spot_photos_content_type_check" CHECK (("content_type" = 'image/webp'::"text")),
    CONSTRAINT "community_spot_photos_height_check" CHECK ((("height" IS NULL) OR (("height" >= 1) AND ("height" <= 2400)))),
    CONSTRAINT "community_spot_photos_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['active'::"text", 'removed'::"text", 'purging'::"text"]))),
    CONSTRAINT "community_spot_photos_moderation_status_check" CHECK (("moderation_status" = ANY (ARRAY['visible'::"text", 'hidden'::"text"]))),
    CONSTRAINT "community_spot_photos_processing_status_check" CHECK (("processing_status" = ANY (ARRAY['processing'::"text", 'ready'::"text", 'cleanup'::"text"]))),
    CONSTRAINT "community_spot_photos_target_type_check" CHECK (("target_type" = ANY (ARRAY['beach'::"text", 'custom_spot'::"text"]))),
    CONSTRAINT "community_spot_photos_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'private'::"text"]))),
    CONSTRAINT "community_spot_photos_width_check" CHECK ((("width" IS NULL) OR (("width" >= 1) AND ("width" <= 2400))))
);


