    CONSTRAINT "forecast_alert_deliveries_alert_type_check" CHECK (("alert_type" = ANY (ARRAY['forecast_threshold'::"text", 'daily_digest_email'::"text", 'conditions_alert'::"text", 'session_prompt'::"text", 'reengagement'::"text", 'swell_watch_email'::"text"])))
);


