CREATE OR REPLACE VIEW "public"."growth_app_handoff_v1" WITH ("security_invoker"='true') AS
 WITH "product_activity_events" AS (
         SELECT "ue"."user_id",
            "ue"."created_at"
           FROM "public"."user_events" "ue"
          WHERE (("ue"."user_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."event_type" = ANY (ARRAY['beach_view'::"text", 'forecast_check'::"text", 'forecast_interaction'::"text", 'home_beach_forecast_viewed'::"text", 'home_hero_forecast_viewed'::"text", 'home_viewed'::"text", 'map_interaction'::"text", 'map_marker_tapped'::"text", 'map_viewed'::"text", 'session_log_start'::"text", 'session_log_submit'::"text", 'set_home_beach'::"text", 'tab_view'::"text"])))
        ), "handoff_events" AS (
         SELECT "lower"(("ue"."metadata" ->> 'handoff_id'::"text")) AS "handoff_id",
            "ue"."event_type",
            "ue"."created_at",
            "ue"."user_id",
            "ue"."metadata"
           FROM "public"."user_events" "ue"
          WHERE (("ue"."event_type" = ANY (ARRAY['app_handoff_view'::"text", 'app_handoff_qr_rendered'::"text", 'app_handoff_email_submit'::"text", 'app_handoff_email_sent'::"text", 'app_handoff_email_failed'::"text", 'app_handoff_link_opened'::"text", 'app_handoff_native_open'::"text"])) AND (COALESCE("ue"."bot_flagged", false) = false) AND (COALESCE(("ue"."metadata" ->> 'is_test'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (NULLIF(("ue"."metadata" ->> 'handoff_id'::"text"), ''::"text") ~* '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::"text"))
        ), "handoff_cohorts" AS (
         SELECT "he"."handoff_id",
            "min"("he"."created_at") AS "cohort_anchor",
            "min"("he"."created_at") FILTER (WHERE ("he"."event_type" = 'app_handoff_view'::"text")) AS "first_handoff_view_at",
            "min"("he"."created_at") FILTER (WHERE ("he"."event_type" = 'app_handoff_qr_rendered'::"text")) AS "first_qr_action_at",
            "min"("he"."created_at") FILTER (WHERE ("he"."event_type" = ANY (ARRAY['app_handoff_email_submit'::"text", 'app_handoff_email_sent'::"text"]))) AS "first_email_action_at",
            "min"("he"."created_at") FILTER (WHERE ("he"."event_type" = 'app_handoff_link_opened'::"text")) AS "first_phone_link_open_at",
            "min"("he"."created_at") FILTER (WHERE (("he"."event_type" = 'app_handoff_link_opened'::"text") AND (("he"."metadata" ->> 'destination_type'::"text") = ANY (ARRAY['app_store'::"text", 'android_beta'::"text"])))) AS "first_store_redirect_at",
            "min"("he"."created_at") FILTER (WHERE ("he"."event_type" = 'app_handoff_native_open'::"text")) AS "first_native_open_at",
            ("array_agg"("he"."user_id" ORDER BY "he"."created_at") FILTER (WHERE (("he"."event_type" = 'app_handoff_native_open'::"text") AND ("he"."user_id" IS NOT NULL))))[1] AS "linked_profile_id",
            ("array_agg"(NULLIF(("he"."metadata" ->> 'handoff_channel'::"text"), ''::"text") ORDER BY "he"."created_at") FILTER (WHERE (NULLIF(("he"."metadata" ->> 'handoff_channel'::"text"), ''::"text") IS NOT NULL)))[1] AS "handoff_channel",
            ("array_agg"(NULLIF(("he"."metadata" ->> 'source'::"text"), ''::"text") ORDER BY "he"."created_at") FILTER (WHERE (NULLIF(("he"."metadata" ->> 'source'::"text"), ''::"text") IS NOT NULL)))[1] AS "entrypoint",
            ("array_agg"(NULLIF(("he"."metadata" ->> 'surface'::"text"), ''::"text") ORDER BY "he"."created_at") FILTER (WHERE (NULLIF(("he"."metadata" ->> 'surface'::"text"), ''::"text") IS NOT NULL)))[1] AS "surface",
            ("array_agg"(NULLIF(("he"."metadata" ->> 'placement'::"text"), ''::"text") ORDER BY "he"."created_at") FILTER (WHERE (NULLIF(("he"."metadata" ->> 'placement'::"text"), ''::"text") IS NOT NULL)))[1] AS "placement",
            ("array_agg"(NULLIF(("he"."metadata" ->> 'utm_source'::"text"), ''::"text") ORDER BY "he"."created_at") FILTER (WHERE (NULLIF(("he"."metadata" ->> 'utm_source'::"text"), ''::"text") IS NOT NULL)))[1] AS "utm_source",
            ("array_agg"(NULLIF(("he"."metadata" ->> 'utm_medium'::"text"), ''::"text") ORDER BY "he"."created_at") FILTER (WHERE (NULLIF(("he"."metadata" ->> 'utm_medium'::"text"), ''::"text") IS NOT NULL)))[1] AS "utm_medium",
            ("array_agg"(NULLIF(("he"."metadata" ->> 'utm_campaign'::"text"), ''::"text") ORDER BY "he"."created_at") FILTER (WHERE (NULLIF(("he"."metadata" ->> 'utm_campaign'::"text"), ''::"text") IS NOT NULL)))[1] AS "utm_campaign"
           FROM "handoff_events" "he"
          GROUP BY "he"."handoff_id"
        ), "eligible_handoff_cohorts" AS (
         SELECT "hc"."handoff_id",
            "hc"."cohort_anchor",
            "hc"."first_handoff_view_at",
            "hc"."first_qr_action_at",
            "hc"."first_email_action_at",
            "hc"."first_phone_link_open_at",
            "hc"."first_store_redirect_at",
            "hc"."first_native_open_at",
            "hc"."linked_profile_id",
            "hc"."handoff_channel",
            "hc"."entrypoint",
            "hc"."surface",
            "hc"."placement",
            "hc"."utm_source",
            "hc"."utm_medium",
            "hc"."utm_campaign"
           FROM ("handoff_cohorts" "hc"
             LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "hc"."linked_profile_id")))
          WHERE (("hc"."linked_profile_id" IS NULL) OR (("p"."analytics_is_real_user" = true) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."deleted_at" IS NULL) AND ("p"."id" <> '73040cff-afe9-4fa0-a874-2016203fc015'::"uuid") AND ("p"."id" <> 'c15c2ab3-275c-49d1-ac4f-dcc493db0653'::"uuid")))
        ), "handoff_outcomes" AS (
         SELECT "hc"."handoff_id",
            "hc"."cohort_anchor",
            "hc"."first_handoff_view_at",
            "hc"."first_qr_action_at",
            "hc"."first_email_action_at",
            "hc"."first_phone_link_open_at",
            "hc"."first_store_redirect_at",
            "hc"."first_native_open_at",
            "hc"."linked_profile_id",
            "hc"."handoff_channel",
            "hc"."entrypoint",
            "hc"."surface",
            "hc"."placement",
            "hc"."utm_source",
            "hc"."utm_medium",
            "hc"."utm_campaign",
            "native_activation"."first_native_activation_at",
            "persisted"."first_persisted_session_at",
            "d1"."d1_return_at",
            "d7"."d7_return_at"
           FROM (((("eligible_handoff_cohorts" "hc"
             LEFT JOIN LATERAL ( SELECT "min"("ue"."created_at") AS "first_native_activation_at"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "hc"."linked_profile_id") AND ("hc"."linked_profile_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND (COALESCE(("ue"."metadata" ->> 'is_emulator'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND ("ue"."event_type" = ANY (ARRAY['beach_view'::"text", 'forecast_interaction'::"text", 'home_beach_forecast_viewed'::"text", 'home_hero_forecast_viewed'::"text", 'home_viewed'::"text", 'map_interaction'::"text", 'map_marker_tapped'::"text", 'map_viewed'::"text", 'session_log_start'::"text"])) AND ("ue"."created_at" >= "hc"."cohort_anchor"))) "native_activation" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("s"."created_at") AS "first_persisted_session_at"
                   FROM "public"."sessions" "s"
                  WHERE (("s"."user_id" = "hc"."linked_profile_id") AND ("hc"."linked_profile_id" IS NOT NULL) AND ("s"."status" = 'completed'::"text") AND ("s"."deleted_at" IS NULL) AND ("s"."created_at" >= "hc"."cohort_anchor") AND ("s"."created_at" < ("hc"."cohort_anchor" + '7 days'::interval)))) "persisted" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("pae"."created_at") AS "d1_return_at"
                   FROM "product_activity_events" "pae"
                  WHERE (("pae"."user_id" = "hc"."linked_profile_id") AND ("hc"."linked_profile_id" IS NOT NULL) AND ("pae"."created_at" >= ("hc"."cohort_anchor" + '24:00:00'::interval)) AND ("pae"."created_at" < ("hc"."cohort_anchor" + '48:00:00'::interval)))) "d1" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("pae"."created_at") AS "d7_return_at"
                   FROM "product_activity_events" "pae"
                  WHERE (("pae"."user_id" = "hc"."linked_profile_id") AND ("hc"."linked_profile_id" IS NOT NULL) AND ("pae"."created_at" >= ("hc"."cohort_anchor" + '168:00:00'::interval)) AND ("pae"."created_at" < ("hc"."cohort_anchor" + '192:00:00'::interval)))) "d7" ON (true))
        )
 SELECT "handoff_outcomes"."handoff_id",
    "handoff_outcomes"."linked_profile_id",
    "handoff_outcomes"."cohort_anchor",
        CASE
            WHEN ("handoff_outcomes"."first_native_open_at" IS NOT NULL) THEN 'exact'::"text"
            WHEN ("handoff_outcomes"."first_phone_link_open_at" IS NOT NULL) THEN 'linked'::"text"
            ELSE 'unknown'::"text"
        END AS "evidence_level",
        CASE
            WHEN (COALESCE("handoff_outcomes"."utm_source", "handoff_outcomes"."utm_medium", "handoff_outcomes"."utm_campaign", "handoff_outcomes"."entrypoint") IS NOT NULL) THEN 'captured'::"text"
            ELSE 'missing'::"text"
        END AS "source_capture_status",
        CASE
            WHEN ("handoff_outcomes"."utm_source" IS NOT NULL) THEN "handoff_outcomes"."utm_source"
            WHEN ("handoff_outcomes"."entrypoint" = 'direct'::"text") THEN 'direct'::"text"
            WHEN ("handoff_outcomes"."entrypoint" IS NOT NULL) THEN "handoff_outcomes"."entrypoint"
            ELSE 'unknown'::"text"
        END AS "source_group",
    "handoff_outcomes"."handoff_channel",
    "handoff_outcomes"."entrypoint",
    "handoff_outcomes"."surface",
    "handoff_outcomes"."placement",
    "handoff_outcomes"."utm_source",
    "handoff_outcomes"."utm_medium",
    "handoff_outcomes"."utm_campaign",
    ("now"() >= ("handoff_outcomes"."cohort_anchor" + '24:00:00'::interval)) AS "eligible_24h",
    ("now"() >= ("handoff_outcomes"."cohort_anchor" + '7 days'::interval)) AS "eligible_7d",
    ("now"() >= ("handoff_outcomes"."cohort_anchor" + '48:00:00'::interval)) AS "eligible_d1",
    ("now"() >= ("handoff_outcomes"."cohort_anchor" + '192:00:00'::interval)) AS "eligible_d7",
    "handoff_outcomes"."first_handoff_view_at",
    "handoff_outcomes"."first_qr_action_at",
    "handoff_outcomes"."first_email_action_at",
    "handoff_outcomes"."first_phone_link_open_at",
    "handoff_outcomes"."first_store_redirect_at",
    "handoff_outcomes"."first_native_open_at",
    "handoff_outcomes"."first_native_activation_at",
    "handoff_outcomes"."first_persisted_session_at",
    ("handoff_outcomes"."first_persisted_session_at" IS NOT NULL) AS "persisted_session_within_7d",
        CASE
            WHEN ("now"() >= ("handoff_outcomes"."cohort_anchor" + '48:00:00'::interval)) THEN ("handoff_outcomes"."d1_return_at" IS NOT NULL)
            ELSE NULL::boolean
        END AS "d1_returned",
        CASE
            WHEN ("now"() >= ("handoff_outcomes"."cohort_anchor" + '192:00:00'::interval)) THEN ("handoff_outcomes"."d7_return_at" IS NOT NULL)
            ELSE NULL::boolean
        END AS "d7_returned"
   FROM "handoff_outcomes";


ALTER TABLE "public"."growth_app_handoff_v1" OWNER TO "postgres";


COMMENT ON VIEW "public"."growth_app_handoff_v1" IS 'One row per valid handoff ID; exact only when installed-app open preserves the ID.';



CREATE OR REPLACE VIEW "public"."growth_native_install_activation_v1" WITH ("security_invoker"='true') AS
 WITH "product_activity_events" AS (
         SELECT "ue"."user_id",
            "ue"."created_at"
           FROM "public"."user_events" "ue"
          WHERE (("ue"."user_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND (COALESCE(("ue"."metadata" ->> 'is_emulator'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'is_test'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND ("ue"."event_type" = ANY (ARRAY['beach_view'::"text", 'forecast_check'::"text", 'forecast_interaction'::"text", 'home_beach_forecast_viewed'::"text", 'home_hero_forecast_viewed'::"text", 'home_viewed'::"text", 'map_interaction'::"text", 'map_marker_tapped'::"text", 'map_viewed'::"text", 'session_log_start'::"text", 'session_log_submit'::"text", 'set_home_beach'::"text", 'tab_view'::"text"])))
        ), "native_first_open_candidates" AS (
         SELECT NULLIF(("ue"."metadata" ->> 'native_install_id'::"text"), ''::"text") AS "native_install_id",
            "ue"."user_id" AS "linked_profile_id",
            "ue"."created_at" AS "cohort_anchor",
            COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) AS "platform",
            NULLIF(("ue"."metadata" ->> 'build'::"text"), ''::"text") AS "app_build",
            NULLIF(("ue"."metadata" ->> 'source_group'::"text"), ''::"text") AS "reviewed_source_group",
            NULLIF(("ue"."metadata" ->> 'utm_source'::"text"), ''::"text") AS "utm_source",
            NULLIF(("ue"."metadata" ->> 'utm_medium'::"text"), ''::"text") AS "utm_medium",
            NULLIF(("ue"."metadata" ->> 'utm_campaign'::"text"), ''::"text") AS "utm_campaign",
            NULLIF(("ue"."metadata" ->> 'referrer_domain'::"text"), ''::"text") AS "referrer_domain",
            NULLIF(("ue"."metadata" ->> 'source'::"text"), ''::"text") AS "entrypoint",
            NULLIF(("ue"."metadata" ->> 'handoff_id'::"text"), ''::"text") AS "handoff_id",
            "row_number"() OVER (PARTITION BY NULLIF(("ue"."metadata" ->> 'native_install_id'::"text"), ''::"text") ORDER BY "ue"."created_at", "ue"."id") AS "install_rank"
           FROM "public"."user_events" "ue"
          WHERE (("ue"."event_type" = 'native_app_first_open'::"text") AND (COALESCE("ue"."bot_flagged", false) = false) AND (COALESCE(("ue"."metadata" ->> 'is_emulator'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'is_test'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> '_is_test'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'environment'::"text"), 'production'::"text") <> ALL (ARRAY['test'::"text", 'local'::"text", 'development'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND (NULLIF(("ue"."metadata" ->> 'native_install_id'::"text"), ''::"text") ~* '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::"text"))
        ), "native_installs" AS (
         SELECT "nfc"."native_install_id",
            "nfc"."linked_profile_id",
            "nfc"."cohort_anchor",
            "nfc"."platform",
            "nfc"."app_build",
            "nfc"."reviewed_source_group",
            "nfc"."utm_source",
            "nfc"."utm_medium",
            "nfc"."utm_campaign",
            "nfc"."referrer_domain",
            "nfc"."entrypoint",
            "nfc"."handoff_id",
            "nfc"."install_rank"
           FROM ("native_first_open_candidates" "nfc"
             LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "nfc"."linked_profile_id")))
          WHERE (("nfc"."install_rank" = 1) AND (("nfc"."linked_profile_id" IS NULL) OR (("p"."analytics_is_real_user" = true) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."deleted_at" IS NULL) AND ("p"."id" <> '73040cff-afe9-4fa0-a874-2016203fc015'::"uuid") AND ("p"."id" <> 'c15c2ab3-275c-49d1-ac4f-dcc493db0653'::"uuid"))))
        ), "native_cohorts" AS (
         SELECT "ni"."native_install_id",
            "ni"."linked_profile_id",
            "ni"."cohort_anchor",
            "ni"."platform",
            "ni"."app_build",
            "ni"."reviewed_source_group",
            "ni"."utm_source",
            "ni"."utm_medium",
            "ni"."utm_campaign",
            "ni"."referrer_domain",
            "ni"."entrypoint",
            "ni"."handoff_id",
            "ni"."install_rank",
                CASE
                    WHEN ("ni"."reviewed_source_group" IS NOT NULL) THEN "ni"."reviewed_source_group"
                    WHEN ("ni"."utm_source" IS NOT NULL) THEN "ni"."utm_source"
                    WHEN ("ni"."handoff_id" IS NOT NULL) THEN 'web_handoff'::"text"
                    WHEN ("ni"."referrer_domain" IS NOT NULL) THEN "ni"."referrer_domain"
                    WHEN ("ni"."entrypoint" = 'direct'::"text") THEN 'direct'::"text"
                    ELSE 'unknown'::"text"
                END AS "source_group",
                CASE
                    WHEN ((COALESCE("ni"."reviewed_source_group", "ni"."utm_source", "ni"."utm_medium", "ni"."utm_campaign", "ni"."handoff_id", "ni"."referrer_domain") IS NOT NULL) OR ("ni"."entrypoint" = 'direct'::"text")) THEN 'captured'::"text"
                    ELSE 'missing'::"text"
                END AS "source_capture_status",
            'exact'::"text" AS "evidence_level"
           FROM "native_installs" "ni"
        ), "native_outcomes" AS (
         SELECT "nc"."native_install_id",
            "nc"."linked_profile_id",
            "nc"."cohort_anchor",
            "nc"."platform",
            "nc"."app_build",
            "nc"."reviewed_source_group",
            "nc"."utm_source",
            "nc"."utm_medium",
            "nc"."utm_campaign",
            "nc"."referrer_domain",
            "nc"."entrypoint",
            "nc"."handoff_id",
            "nc"."install_rank",
            "nc"."source_group",
            "nc"."source_capture_status",
            "nc"."evidence_level",
            "auth"."first_auth_at",
            "onboarding"."first_onboarding_completed_at",
            "high_intent"."first_high_intent_native_at",
            "session_start"."first_session_log_start_at",
            "persisted"."first_persisted_session_at",
            "d1"."d1_return_at",
            "d7"."d7_return_at"
           FROM ((((((("native_cohorts" "nc"
             LEFT JOIN LATERAL ( SELECT "min"("ue"."created_at") AS "first_auth_at"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "nc"."linked_profile_id") AND ("nc"."linked_profile_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."event_type" = ANY (ARRAY['signed_in'::"text", 'signup_success'::"text", 'login_success'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND ("ue"."created_at" >= "nc"."cohort_anchor") AND ("ue"."created_at" < ("nc"."cohort_anchor" + '24:00:00'::interval)))) "auth" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("ue"."created_at") AS "first_onboarding_completed_at"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "nc"."linked_profile_id") AND ("nc"."linked_profile_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."event_type" = 'onboarding_completed'::"text") AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND ("ue"."created_at" >= "nc"."cohort_anchor"))) "onboarding" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("ue"."created_at") AS "first_high_intent_native_at"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "nc"."linked_profile_id") AND ("nc"."linked_profile_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND (COALESCE(("ue"."metadata" ->> 'is_emulator'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'is_test'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND ("ue"."event_type" = ANY (ARRAY['beach_view'::"text", 'forecast_interaction'::"text", 'home_beach_forecast_viewed'::"text", 'home_hero_forecast_viewed'::"text", 'home_viewed'::"text", 'map_interaction'::"text", 'map_marker_tapped'::"text", 'map_viewed'::"text", 'session_log_start'::"text"])) AND ("ue"."created_at" >= "nc"."cohort_anchor"))) "high_intent" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("ue"."created_at") AS "first_session_log_start_at"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "nc"."linked_profile_id") AND ("nc"."linked_profile_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."event_type" = 'session_log_start'::"text") AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND ("ue"."created_at" >= "nc"."cohort_anchor"))) "session_start" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("s"."created_at") AS "first_persisted_session_at"
                   FROM "public"."sessions" "s"
                  WHERE (("s"."user_id" = "nc"."linked_profile_id") AND ("nc"."linked_profile_id" IS NOT NULL) AND ("s"."status" = 'completed'::"text") AND ("s"."deleted_at" IS NULL) AND ("s"."created_at" >= "nc"."cohort_anchor") AND ("s"."created_at" < ("nc"."cohort_anchor" + '7 days'::interval)))) "persisted" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("pae"."created_at") AS "d1_return_at"
                   FROM "product_activity_events" "pae"
                  WHERE (("pae"."user_id" = "nc"."linked_profile_id") AND ("nc"."linked_profile_id" IS NOT NULL) AND ("pae"."created_at" >= ("nc"."cohort_anchor" + '24:00:00'::interval)) AND ("pae"."created_at" < ("nc"."cohort_anchor" + '48:00:00'::interval)))) "d1" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("pae"."created_at") AS "d7_return_at"
                   FROM "product_activity_events" "pae"
                  WHERE (("pae"."user_id" = "nc"."linked_profile_id") AND ("nc"."linked_profile_id" IS NOT NULL) AND ("pae"."created_at" >= ("nc"."cohort_anchor" + '168:00:00'::interval)) AND ("pae"."created_at" < ("nc"."cohort_anchor" + '192:00:00'::interval)))) "d7" ON (true))
        )
 SELECT "native_outcomes"."native_install_id",
    "native_outcomes"."linked_profile_id",
    "native_outcomes"."cohort_anchor",
    "native_outcomes"."platform",
    "native_outcomes"."app_build",
    "native_outcomes"."evidence_level",
    "native_outcomes"."source_capture_status",
    "native_outcomes"."source_group",
    "native_outcomes"."entrypoint",
    "native_outcomes"."referrer_domain",
    "native_outcomes"."utm_source",
    "native_outcomes"."utm_medium",
    "native_outcomes"."utm_campaign",
    "native_outcomes"."handoff_id",
    ("now"() >= ("native_outcomes"."cohort_anchor" + '24:00:00'::interval)) AS "eligible_24h",
    ("now"() >= ("native_outcomes"."cohort_anchor" + '7 days'::interval)) AS "eligible_7d",
    ("now"() >= ("native_outcomes"."cohort_anchor" + '48:00:00'::interval)) AS "eligible_d1",
    ("now"() >= ("native_outcomes"."cohort_anchor" + '192:00:00'::interval)) AS "eligible_d7",
    "native_outcomes"."first_auth_at",
    "native_outcomes"."first_onboarding_completed_at",
    "native_outcomes"."first_high_intent_native_at",
    "native_outcomes"."first_session_log_start_at",
    "native_outcomes"."first_persisted_session_at",
    ("native_outcomes"."first_persisted_session_at" IS NOT NULL) AS "persisted_session_within_7d",
        CASE
            WHEN ("now"() >= ("native_outcomes"."cohort_anchor" + '48:00:00'::interval)) THEN ("native_outcomes"."d1_return_at" IS NOT NULL)
            ELSE NULL::boolean
        END AS "d1_returned",
        CASE
            WHEN ("now"() >= ("native_outcomes"."cohort_anchor" + '192:00:00'::interval)) THEN ("native_outcomes"."d7_return_at" IS NOT NULL)
            ELSE NULL::boolean
        END AS "d7_returned"
   FROM "native_outcomes";


ALTER TABLE "public"."growth_native_install_activation_v1" OWNER TO "postgres";


COMMENT ON VIEW "public"."growth_native_install_activation_v1" IS 'One row per real-device native install ID; install-grain activation denominator.';



CREATE OR REPLACE VIEW "public"."growth_web_signup_activation_v1" WITH ("security_invoker"='true') AS
 WITH "product_activity_events" AS (
         SELECT "ue"."user_id",
            "ue"."created_at",
            COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) AS "platform"
           FROM "public"."user_events" "ue"
          WHERE (("ue"."user_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."event_type" = ANY (ARRAY['beach_view'::"text", 'forecast_check'::"text", 'forecast_interaction'::"text", 'home_beach_forecast_viewed'::"text", 'home_hero_forecast_viewed'::"text", 'home_viewed'::"text", 'map_interaction'::"text", 'map_marker_click'::"text", 'map_marker_tapped'::"text", 'map_viewed'::"text", 'session_log_start'::"text", 'session_log_submit'::"text", 'set_home_beach'::"text", 'tab_view'::"text"])))
        ), "web_signup_candidates" AS (
         SELECT "p"."id" AS "profile_id",
            "p"."created_at" AS "cohort_anchor",
            "p"."signup_context",
            ("p"."referral_code" IS NOT NULL) AS "has_partner_referral",
            "signup_event"."created_at" AS "exact_web_signup_at",
            "signup_event"."metadata" AS "signup_event_metadata",
            "row_number"() OVER (PARTITION BY "p"."id" ORDER BY
                CASE
                    WHEN ("signup_event"."created_at" IS NOT NULL) THEN 0
                    ELSE 1
                END, "signup_event"."created_at") AS "evidence_rank"
           FROM ("public"."profiles" "p"
             LEFT JOIN LATERAL ( SELECT "ue"."created_at",
                    "ue"."metadata"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "p"."id") AND ("ue"."event_type" = 'signup_success'::"text") AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."created_at" >= ("p"."created_at" - '24:00:00'::interval)) AND ("ue"."created_at" < ("p"."created_at" + '24:00:00'::interval)) AND (COALESCE(("ue"."metadata" ->> 'signup_surface'::"text"), ("ue"."metadata" ->> 'surface'::"text"), 'web'::"text") = 'web'::"text") AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text"), 'web'::"text") <> ALL (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])))
                  ORDER BY ("abs"(EXTRACT(epoch FROM ("ue"."created_at" - "p"."created_at")))), "ue"."created_at"
                 LIMIT 1) "signup_event" ON (true))
          WHERE (("p"."analytics_is_real_user" = true) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."deleted_at" IS NULL) AND ("p"."id" <> '73040cff-afe9-4fa0-a874-2016203fc015'::"uuid") AND ("p"."id" <> 'c15c2ab3-275c-49d1-ac4f-dcc493db0653'::"uuid") AND ((("p"."signup_context" ->> 'signup_surface'::"text") = 'web'::"text") OR ("signup_event"."created_at" IS NOT NULL)))
        ), "web_signups" AS (
         SELECT "wsc"."profile_id",
            "wsc"."cohort_anchor",
            "wsc"."signup_context",
            "wsc"."has_partner_referral",
            "wsc"."exact_web_signup_at",
            "wsc"."signup_event_metadata",
            "wsc"."evidence_rank",
            COALESCE(NULLIF(("wsc"."signup_context" ->> 'entrypoint'::"text"), ''::"text"), NULLIF(("wsc"."signup_event_metadata" ->> 'entrypoint'::"text"), ''::"text"), NULLIF(("wsc"."signup_event_metadata" ->> 'source'::"text"), ''::"text")) AS "entrypoint",
            COALESCE(NULLIF(("wsc"."signup_context" ->> 'referrer_domain'::"text"), ''::"text"), NULLIF(("wsc"."signup_event_metadata" ->> 'referrer_domain'::"text"), ''::"text")) AS "referrer_domain",
            COALESCE(NULLIF((("wsc"."signup_context" -> 'utm'::"text") ->> 'source'::"text"), ''::"text"), NULLIF(("wsc"."signup_event_metadata" ->> 'utm_source'::"text"), ''::"text")) AS "utm_source",
            COALESCE(NULLIF((("wsc"."signup_context" -> 'utm'::"text") ->> 'medium'::"text"), ''::"text"), NULLIF(("wsc"."signup_event_metadata" ->> 'utm_medium'::"text"), ''::"text")) AS "utm_medium",
            COALESCE(NULLIF((("wsc"."signup_context" -> 'utm'::"text") ->> 'campaign'::"text"), ''::"text"), NULLIF(("wsc"."signup_event_metadata" ->> 'utm_campaign'::"text"), ''::"text")) AS "utm_campaign"
           FROM "web_signup_candidates" "wsc"
          WHERE ("wsc"."evidence_rank" = 1)
        ), "web_cohorts" AS (
         SELECT "ws"."profile_id",
            "ws"."cohort_anchor",
            "ws"."signup_context",
            "ws"."has_partner_referral",
            "ws"."exact_web_signup_at",
            "ws"."signup_event_metadata",
            "ws"."evidence_rank",
            "ws"."entrypoint",
            "ws"."referrer_domain",
            "ws"."utm_source",
            "ws"."utm_medium",
            "ws"."utm_campaign",
                CASE
                    WHEN (("ws"."signup_context" ->> 'source_capture_status'::"text") = ANY (ARRAY['captured'::"text", 'missing'::"text"])) THEN ("ws"."signup_context" ->> 'source_capture_status'::"text")
                    WHEN ((COALESCE("ws"."utm_source", "ws"."utm_medium", "ws"."utm_campaign") IS NOT NULL) OR "ws"."has_partner_referral") THEN 'captured'::"text"
                    WHEN (("ws"."referrer_domain" IS NOT NULL) AND ("ws"."referrer_domain" <> ALL (ARRAY['quiversurf.app'::"text", 'www.quiversurf.app'::"text", 'dev.quiversurf.app'::"text", 'localhost'::"text"]))) THEN 'captured'::"text"
                    ELSE 'missing'::"text"
                END AS "source_capture_status",
                CASE
                    WHEN (NULLIF(("ws"."signup_context" ->> 'source_group'::"text"), ''::"text") IS NOT NULL) THEN ("ws"."signup_context" ->> 'source_group'::"text")
                    WHEN ("ws"."utm_source" IS NOT NULL) THEN "ws"."utm_source"
                    WHEN "ws"."has_partner_referral" THEN 'partner_referral'::"text"
                    WHEN (("ws"."referrer_domain" IS NOT NULL) AND ("ws"."referrer_domain" <> ALL (ARRAY['quiversurf.app'::"text", 'www.quiversurf.app'::"text", 'dev.quiversurf.app'::"text", 'localhost'::"text"]))) THEN "ws"."referrer_domain"
                    WHEN ((("ws"."signup_context" ->> 'referrer'::"text") = 'direct'::"text") OR (("ws"."signup_context" ->> 'source_group'::"text") = 'direct'::"text")) THEN 'direct'::"text"
                    ELSE 'unknown'::"text"
                END AS "source_group",
                CASE
                    WHEN ("ws"."exact_web_signup_at" IS NOT NULL) THEN 'exact'::"text"
                    WHEN (("ws"."signup_context" ->> 'schema_version'::"text") = '2'::"text") THEN 'linked'::"text"
                    ELSE 'unknown'::"text"
                END AS "evidence_level"
           FROM "web_signups" "ws"
        ), "web_outcomes" AS (
         SELECT "wc"."profile_id",
            "wc"."cohort_anchor",
            "wc"."signup_context",
            "wc"."has_partner_referral",
            "wc"."exact_web_signup_at",
            "wc"."signup_event_metadata",
            "wc"."evidence_rank",
            "wc"."entrypoint",
            "wc"."referrer_domain",
            "wc"."utm_source",
            "wc"."utm_medium",
            "wc"."utm_campaign",
            "wc"."source_capture_status",
            "wc"."source_group",
            "wc"."evidence_level",
            "web_activation"."first_web_product_activation_at",
            "handoff"."first_app_handoff_intent_at",
            "native"."first_linked_native_open_at",
            "persisted"."first_persisted_session_at",
            "d1"."d1_return_at",
            "d7"."d7_return_at"
           FROM (((((("web_cohorts" "wc"
             LEFT JOIN LATERAL ( SELECT "min"("pae"."created_at") AS "first_web_product_activation_at"
                   FROM "product_activity_events" "pae"
                  WHERE (("pae"."user_id" = "wc"."profile_id") AND ("pae"."created_at" >= "wc"."cohort_anchor") AND ("pae"."created_at" < ("wc"."cohort_anchor" + '24:00:00'::interval)) AND (COALESCE("pae"."platform", 'web'::"text") <> ALL (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])))) "web_activation" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("ue"."created_at") AS "first_app_handoff_intent_at"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "wc"."profile_id") AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."event_type" = ANY (ARRAY['app_handoff_qr_rendered'::"text", 'app_handoff_email_submit'::"text", 'app_handoff_link_opened'::"text"])) AND ("ue"."created_at" >= "wc"."cohort_anchor") AND ("ue"."created_at" < ("wc"."cohort_anchor" + '24:00:00'::interval)))) "handoff" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("ue"."created_at") AS "first_linked_native_open_at"
                   FROM "public"."user_events" "ue"
                  WHERE (("ue"."user_id" = "wc"."profile_id") AND (COALESCE("ue"."bot_flagged", false) = false) AND ("ue"."event_type" = 'native_app_first_open'::"text") AND (COALESCE(("ue"."metadata" ->> 'is_emulator'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'is_test'::"text"), 'false'::"text") <> ALL (ARRAY['true'::"text", '1'::"text"])) AND (COALESCE(("ue"."metadata" ->> 'platform'::"text"), ("ue"."metadata" ->> '_platform'::"text")) = ANY (ARRAY['ios'::"text", 'android'::"text", 'native-ios'::"text", 'native-android'::"text"])) AND ("ue"."created_at" >= "wc"."cohort_anchor") AND ("ue"."created_at" < ("wc"."cohort_anchor" + '7 days'::interval)))) "native" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("s"."created_at") AS "first_persisted_session_at"
                   FROM "public"."sessions" "s"
                  WHERE (("s"."user_id" = "wc"."profile_id") AND ("s"."status" = 'completed'::"text") AND ("s"."deleted_at" IS NULL) AND ("s"."created_at" >= "wc"."cohort_anchor") AND ("s"."created_at" < ("wc"."cohort_anchor" + '7 days'::interval)))) "persisted" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("pae"."created_at") AS "d1_return_at"
                   FROM "product_activity_events" "pae"
                  WHERE (("pae"."user_id" = "wc"."profile_id") AND ("pae"."created_at" >= ("wc"."cohort_anchor" + '24:00:00'::interval)) AND ("pae"."created_at" < ("wc"."cohort_anchor" + '48:00:00'::interval)))) "d1" ON (true))
             LEFT JOIN LATERAL ( SELECT "min"("pae"."created_at") AS "d7_return_at"
                   FROM "product_activity_events" "pae"
                  WHERE (("pae"."user_id" = "wc"."profile_id") AND ("pae"."created_at" >= ("wc"."cohort_anchor" + '168:00:00'::interval)) AND ("pae"."created_at" < ("wc"."cohort_anchor" + '192:00:00'::interval)))) "d7" ON (true))
        )
 SELECT "web_outcomes"."profile_id",
    "web_outcomes"."cohort_anchor",
    'web_signup'::"text" AS "cohort_type",
    "web_outcomes"."evidence_level",
    "web_outcomes"."source_capture_status",
    "web_outcomes"."source_group",
    "web_outcomes"."entrypoint",
    "web_outcomes"."referrer_domain",
    "web_outcomes"."utm_source",
    "web_outcomes"."utm_medium",
    "web_outcomes"."utm_campaign",
    ("now"() >= ("web_outcomes"."cohort_anchor" + '24:00:00'::interval)) AS "eligible_24h",
    ("now"() >= ("web_outcomes"."cohort_anchor" + '7 days'::interval)) AS "eligible_7d",
    ("now"() >= ("web_outcomes"."cohort_anchor" + '48:00:00'::interval)) AS "eligible_d1",
    ("now"() >= ("web_outcomes"."cohort_anchor" + '192:00:00'::interval)) AS "eligible_d7",
    "web_outcomes"."first_web_product_activation_at",
    "web_outcomes"."first_app_handoff_intent_at",
    "web_outcomes"."first_linked_native_open_at",
    "web_outcomes"."first_persisted_session_at",
    ("web_outcomes"."first_persisted_session_at" IS NOT NULL) AS "persisted_session_within_7d",
        CASE
            WHEN ("now"() >= ("web_outcomes"."cohort_anchor" + '48:00:00'::interval)) THEN ("web_outcomes"."d1_return_at" IS NOT NULL)
            ELSE NULL::boolean
        END AS "d1_returned",
        CASE
            WHEN ("now"() >= ("web_outcomes"."cohort_anchor" + '192:00:00'::interval)) THEN ("web_outcomes"."d7_return_at" IS NOT NULL)
            ELSE NULL::boolean
        END AS "d7_returned"
   FROM "web_outcomes";


