CREATE MATERIALIZED VIEW "public"."observable_beaches" AS
 SELECT DISTINCT "s"."nearest_beach_id" AS "beach_id"
   FROM "public"."ioos_stations" "s"
  WHERE (("s"."active" = true) AND ("s"."has_wave_data" = true) AND ("s"."nearest_beach_id" IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM "public"."ioos_observations" "o"
          WHERE (("o"."station_id" = "s"."station_id") AND ("o"."wave_height_m" IS NOT NULL) AND ("o"."observed_at" > ("now"() - '24:00:00'::interval))))))
UNION
 SELECT DISTINCT "b"."id" AS "beach_id"
   FROM "public"."beaches" "b"
  WHERE (("b"."deleted_at" IS NULL) AND (EXISTS ( SELECT 1
           FROM ("public"."ioos_stations" "s"
             JOIN "public"."beaches" "nb" ON (("nb"."id" = "s"."nearest_beach_id")))
          WHERE (("s"."active" = true) AND ("s"."has_wave_data" = true) AND "extensions"."st_dwithin"("b"."geog", ("s"."coordinates")::"extensions"."geography", (50000)::double precision) AND ("public"."swell_windows_overlap"(("b"."swell_window_min_deg")::numeric, ("b"."swell_window_max_deg")::numeric, ("nb"."swell_window_min_deg")::numeric, ("nb"."swell_window_max_deg")::numeric) >= (30)::numeric) AND (EXISTS ( SELECT 1
                   FROM "public"."ioos_observations" "o"
                  WHERE (("o"."station_id" = "s"."station_id") AND ("o"."wave_height_m" IS NOT NULL) AND ("o"."observed_at" > ("now"() - '48:00:00'::interval)))))))))
UNION
 SELECT DISTINCT "s"."nearest_beach_id" AS "beach_id"
   FROM "public"."ndbc_direct_stations" "s"
  WHERE (("s"."active" = true) AND ("s"."has_wave_data" = true) AND ("s"."nearest_beach_id" IS NOT NULL) AND (("s"."ioos_station_id" IS NULL) OR (NOT (EXISTS ( SELECT 1
           FROM "public"."ioos_stations" "iss"
          WHERE (("iss"."station_id" = "s"."ioos_station_id") AND ("iss"."active" = true)))))) AND (EXISTS ( SELECT 1
           FROM "public"."ndbc_direct_observations" "o"
          WHERE (("o"."station_id" = "s"."station_id") AND ("o"."wave_height_m" IS NOT NULL) AND ("o"."observed_at" > ("now"() - '24:00:00'::interval))))))
UNION
 SELECT DISTINCT "b"."id" AS "beach_id"
   FROM "public"."beaches" "b"
  WHERE (("b"."deleted_at" IS NULL) AND (EXISTS ( SELECT 1
           FROM ("public"."ndbc_direct_stations" "s"
             JOIN "public"."beaches" "nb" ON (("nb"."id" = "s"."nearest_beach_id")))
          WHERE (("s"."active" = true) AND ("s"."has_wave_data" = true) AND (("s"."ioos_station_id" IS NULL) OR (NOT (EXISTS ( SELECT 1
                   FROM "public"."ioos_stations" "iss"
                  WHERE (("iss"."station_id" = "s"."ioos_station_id") AND ("iss"."active" = true)))))) AND "extensions"."st_dwithin"("b"."geog", ("s"."coordinates")::"extensions"."geography", (50000)::double precision) AND ("public"."swell_windows_overlap"(("b"."swell_window_min_deg")::numeric, ("b"."swell_window_max_deg")::numeric, ("nb"."swell_window_min_deg")::numeric, ("nb"."swell_window_max_deg")::numeric) >= (30)::numeric) AND (EXISTS ( SELECT 1
                   FROM "public"."ndbc_direct_observations" "o"
                  WHERE (("o"."station_id" = "s"."station_id") AND ("o"."wave_height_m" IS NOT NULL) AND ("o"."observed_at" > ("now"() - '48:00:00'::interval)))))))))
  WITH NO DATA;


ALTER TABLE "public"."observable_beaches" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."observable_beaches" IS 'Beaches with ground truth observation sources for ML training. Four paths: (A) IOOS direct station mapping (24h recency), (B) IOOS spatial proximity 50km with >= 30 degrees swell overlap (48h recency), (C) NDBC direct station mapping, NDBC-exclusive only (24h recency), (D) NDBC direct spatial proximity 50km with >= 30 degrees swell overlap (48h recency). Expanded Jun 2026 from 25km to 50km for mixed-swell sentinel recovery. Refreshed every 2h by /api/cron/ioos-sync?phase=observations.';



CREATE OR REPLACE VIEW "public"."unified_wave_observations" WITH ("security_invoker"='true') AS
 SELECT 'ioos'::"text" AS "source",
    "o"."station_id",
    "o"."observed_at",
    "o"."wave_height_m",
    "o"."wave_period_s",
    "o"."wave_direction_deg",
    "o"."water_temp_c",
    "s"."latitude",
    "s"."longitude",
    "s"."nearest_beach_id",
    "s"."distance_to_beach_km",
    "s"."source_network"
   FROM ("public"."ioos_observations" "o"
     JOIN "public"."ioos_stations" "s" USING ("station_id"))
  WHERE (("s"."active" = true) AND ("o"."wave_height_m" IS NOT NULL))
UNION ALL
 SELECT 'ndbc_direct'::"text" AS "source",
    "o"."station_id",
    "o"."observed_at",
    "o"."wave_height_m",
    "o"."wave_period_s",
    "o"."wave_direction_deg",
    "o"."water_temp_c",
    "s"."latitude",
    "s"."longitude",
    "s"."nearest_beach_id",
    "s"."distance_to_beach_km",
    'NDBC'::"text" AS "source_network"
   FROM ("public"."ndbc_direct_observations" "o"
     JOIN "public"."ndbc_direct_stations" "s" USING ("station_id"))
  WHERE (("s"."active" = true) AND ("o"."wave_height_m" IS NOT NULL) AND (("s"."ioos_station_id" IS NULL) OR (NOT (EXISTS ( SELECT 1
           FROM "public"."ioos_stations" "iss"
          WHERE (("iss"."station_id" = "s"."ioos_station_id") AND ("iss"."active" = true)))))));


ALTER TABLE "public"."unified_wave_observations" OWNER TO "postgres";


COMMENT ON VIEW "public"."unified_wave_observations" IS 'Unified view of wave observations from IOOS and NDBC direct sources for ML training. NDBC direct observations are only included for stations not actively covered by IOOS (dedup via ioos_station_id cross-reference).';



CREATE MATERIALIZED VIEW "public"."mv_nowcast_anchors" AS
 WITH "resolved" AS (
         SELECT "ob"."beach_id",
            "public"."get_beach_observation_station"("ob"."beach_id") AS "station_id"
           FROM "public"."observable_beaches" "ob"
        )
 SELECT DISTINCT ON ("r"."beach_id") "r"."beach_id",
    "r"."station_id",
    "uwo"."observed_at",
    "uwo"."wave_height_m",
    "uwo"."wave_period_s",
    "uwo"."wave_direction_deg"
   FROM ("resolved" "r"
     JOIN "public"."unified_wave_observations" "uwo" ON (("uwo"."station_id" = "r"."station_id")))
  WHERE (("r"."station_id" IS NOT NULL) AND ("uwo"."observed_at" >= ("now"() - '48:00:00'::interval)) AND ("uwo"."wave_height_m" IS NOT NULL))
  ORDER BY "r"."beach_id", "uwo"."observed_at" DESC
  WITH NO DATA;


ALTER TABLE "public"."mv_nowcast_anchors" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_nowcast_anchors" IS 'Latest buoy anchor per observable beach (<=48h). Backs get_nowcast_anchors() as an indexed read instead of a per-request ~1.9s scan. Refreshed by refresh_observable_beaches().';



