    CONSTRAINT "session_shares_platform_check" CHECK (("platform" = ANY (ARRAY['instagram'::"text", 'tiktok'::"text", 'twitter'::"text", 'facebook'::"text", 'copy'::"text", 'native'::"text", 'other'::"text"]))),
