    "location_type" "text" NOT NULL,
    "beach_id" "uuid",
    "custom_lat" double precision,
    "custom_lon" double precision,
    "general_area" "text",
    "exact_label" "text",
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "audience" "public"."surf_drop_audience" DEFAULT 'mutuals'::"public"."surf_drop_audience" NOT NULL,
    "note" "text",
    "forecast_snapshot" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cancelled_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "surf_drops_custom_lat_range" CHECK ((("custom_lat" IS NULL) OR (("custom_lat" >= ('-90'::integer)::double precision) AND ("custom_lat" <= (90)::double precision)))),
    CONSTRAINT "surf_drops_custom_lon_range" CHECK ((("custom_lon" IS NULL) OR (("custom_lon" >= ('-180'::integer)::double precision) AND ("custom_lon" <= (180)::double precision)))),
    CONSTRAINT "surf_drops_location" CHECK (((("location_type" = 'known_spot'::"text") AND ("beach_id" IS NOT NULL) AND ("custom_lat" IS NULL) AND ("custom_lon" IS NULL)) OR (("location_type" = 'custom_pin'::"text") AND ("beach_id" IS NULL) AND ("custom_lat" IS NOT NULL) AND ("custom_lon" IS NOT NULL)))),
    CONSTRAINT "surf_drops_location_type" CHECK (("location_type" = ANY (ARRAY['known_spot'::"text", 'custom_pin'::"text"]))),
    CONSTRAINT "surf_drops_max_ahead" CHECK (("starts_at" <= ("now"() + '4 days'::interval))),
    CONSTRAINT "surf_drops_min_duration" CHECK (("ends_at" >= ("starts_at" + '00:15:00'::interval))),
    CONSTRAINT "surf_drops_note_length" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 240))),
    CONSTRAINT "surf_drops_slug_format" CHECK (("share_slug" ~ '^[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{10}$'::"text")),
    CONSTRAINT "surf_drops_time_window" CHECK (("ends_at" > "starts_at"))
);


