CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_decisions" (
    "decision_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "beach_id" "uuid" NOT NULL,
    "local_date" "date" NOT NULL,
    "local_timezone" "text" NOT NULL,
    "status" "text" NOT NULL,
    "primary_issue_id" "uuid",
    "baseline_max_face_ft" numeric(8,4),
    "trusted_min_face_ft" numeric(8,4),
    "trusted_max_face_ft" numeric(8,4),
    "signed_gap_ft" numeric(8,4),
    "applied_delta_ft" numeric(8,4) DEFAULT 0 NOT NULL,
    "policy_version" "text" NOT NULL,
    "build_key" "text" NOT NULL,
    "decided_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_decisions_applied_requires_delta_check" CHECK ((("status" = 'applied'::"text") = ("applied_delta_ft" <> (0)::numeric))),
    CONSTRAINT "trusted_forecast_decisions_applied_requires_primary_check" CHECK ((("status" <> ALL (ARRAY['applied'::"text", 'no_adjustment'::"text"])) OR (("primary_issue_id" IS NOT NULL) AND ("trusted_min_face_ft" IS NOT NULL) AND ("trusted_max_face_ft" IS NOT NULL) AND ("baseline_max_face_ft" IS NOT NULL)))),
    CONSTRAINT "trusted_forecast_decisions_delta_band_check" CHECK (("applied_delta_ft" = ANY (ARRAY['-0.5'::numeric, '-0.25'::numeric, (0)::numeric, 0.25, 0.5]))),
    CONSTRAINT "trusted_forecast_decisions_range_check" CHECK (((("trusted_min_face_ft" IS NULL) = ("trusted_max_face_ft" IS NULL)) AND (("trusted_min_face_ft" IS NULL) OR (("trusted_min_face_ft" >= (0)::numeric) AND ("trusted_max_face_ft" <= (60)::numeric) AND ("trusted_min_face_ft" <= "trusted_max_face_ft"))))),
    CONSTRAINT "trusted_forecast_decisions_status_check" CHECK (("status" = ANY (ARRAY['applied'::"text", 'no_adjustment'::"text", 'no_authority'::"text", 'blocked_conflict'::"text"])))
);


