    "finished_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_source_results_counts_check" CHECK ((("issue_count" >= 0) AND ("authority_issue_count" >= 0) AND ("authority_issue_count" <= "issue_count") AND ("degraded_item_count" >= 0) AND (("http_status" IS NULL) OR (("http_status" >= 100) AND ("http_status" <= 599))) AND (("redirect_hops" IS NULL) OR ("redirect_hops" >= 0)) AND (("attempts" IS NULL) OR ("attempts" >= 0)))),
    CONSTRAINT "trusted_forecast_source_results_degraded_check" CHECK (((("degraded_failure_code" IS NULL) AND ("degraded_item_count" = 0)) OR (("degraded_failure_code" IS NOT NULL) AND ("degraded_item_count" > 0) AND ("status" = 'ok'::"text")))),
    CONSTRAINT "trusted_forecast_source_results_failure_code_check" CHECK (
CASE
    WHEN ("status" = ANY (ARRAY['ok'::"text", 'skipped_disabled'::"text"])) THEN ("failure_code" IS NULL)
    ELSE ("failure_code" IS NOT NULL)
END),
    CONSTRAINT "trusted_forecast_source_results_status_check" CHECK (("status" = ANY (ARRAY['ok'::"text", 'no_issues'::"text", 'transport_failed'::"text", 'parser_failed'::"text", 'skipped_disabled'::"text"]))),
    CONSTRAINT "trusted_forecast_source_results_window_check" CHECK (("finished_at" >= "started_at"))
);


