CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_issues" (
    "issue_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_lineage" "text" NOT NULL,
    "source_key" "text" NOT NULL,
    "issued_at" timestamp with time zone NOT NULL,
    "valid_local_date" "date" NOT NULL,
    "valid_timezone" "text" NOT NULL,
    "valid_start_at" timestamp with time zone NOT NULL,
    "valid_end_at" timestamp with time zone NOT NULL,
    "validity_basis" "text" NOT NULL,
    "scope_type" "text" NOT NULL,
    "region_key" "text",
    "beach_id" "uuid",
    "exposure" "text" NOT NULL,
    "day_part" "text" NOT NULL,
    "measurement_basis" "text" NOT NULL,
    "min_face_ft" numeric(8,4),
    "max_face_ft" numeric(8,4),
    "direction_deg" numeric(8,4),
    "period_seconds" numeric(8,4),
    "parser_version" "text" NOT NULL,
    "source_hash" "text" NOT NULL,
    "issue_identity_key" "text" NOT NULL,
    "revision_hash" "text" NOT NULL,
    "supersedes_issue_id" "uuid",
    "authority_eligible" boolean NOT NULL,
    "evidence_class" "text" NOT NULL,
    "ingest_run_id" "uuid",
    "fetched_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_issues_authority_check" CHECK ((("authority_eligible" = false) OR (("min_face_ft" IS NOT NULL) AND ("max_face_ft" IS NOT NULL) AND ("measurement_basis" = 'breaking_face_ft'::"text") AND ("evidence_class" = 'human_face_height_authority'::"text")))),
    CONSTRAINT "trusted_forecast_issues_day_part_check" CHECK (("day_part" = ANY (ARRAY['all_day'::"text", 'day'::"text", 'night'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_direction_check" CHECK ((("direction_deg" IS NULL) OR (("direction_deg" >= (0)::numeric) AND ("direction_deg" < (360)::numeric)))),
    CONSTRAINT "trusted_forecast_issues_evidence_class_check" CHECK (("evidence_class" = ANY (ARRAY['human_face_height_authority'::"text", 'model_buoy_evidence'::"text", 'evidence_only'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_identity_hex_check" CHECK (("issue_identity_key" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "trusted_forecast_issues_measurement_basis_check" CHECK (("measurement_basis" = ANY (ARRAY['breaking_face_ft'::"text", 'unspecified'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_period_check" CHECK ((("period_seconds" IS NULL) OR (("period_seconds" > (0)::numeric) AND ("period_seconds" <= (120)::numeric)))),
    CONSTRAINT "trusted_forecast_issues_range_bounds_check" CHECK (((("min_face_ft" IS NULL) OR (("min_face_ft" >= (0)::numeric) AND ("min_face_ft" <= (60)::numeric))) AND (("max_face_ft" IS NULL) OR (("max_face_ft" >= (0)::numeric) AND ("max_face_ft" <= (60)::numeric))) AND (("min_face_ft" IS NULL) OR ("max_face_ft" IS NULL) OR ("min_face_ft" <= "max_face_ft")))),
    CONSTRAINT "trusted_forecast_issues_range_pairing_check" CHECK ((("min_face_ft" IS NULL) = ("max_face_ft" IS NULL))),
    CONSTRAINT "trusted_forecast_issues_revision_hex_check" CHECK (("revision_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "trusted_forecast_issues_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['spot'::"text", 'regional'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_validity_basis_check" CHECK (("validity_basis" = ANY (ARRAY['stated'::"text", 'derived_publication_day'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_window_check" CHECK (("valid_end_at" > "valid_start_at"))
);


ALTER TABLE "public"."trusted_forecast_issues" OWNER TO "postgres";


COMMENT ON TABLE "public"."trusted_forecast_issues" IS 'Append-only normalized forecaster issue revisions (MFA-02, D-18). region_key carries chart spot slugs when scope_type=spot; exposure is free text across source families.';



COMMENT ON COLUMN "public"."trusted_forecast_issues"."validity_basis" IS 'Whether the source stated the validity window or it was derived from the publication day (stated|derived_publication_day).';



