CREATE OR REPLACE VIEW "public"."v_enhanced_forecast_latest" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "beach_id",
    "near_term"."updated_at",
    "near_term"."data_source"
   FROM ("public"."beaches" "b"
     CROSS JOIN LATERAL ( SELECT "ef"."updated_at",
            "ef"."data_source"
           FROM "public"."enhanced_forecasts" "ef"
          WHERE (("ef"."beach_id" = "b"."id") AND ("ef"."forecast_at" >= "now"()) AND ("ef"."forecast_at" < ("now"() + '72:00:00'::interval)) AND ("ef"."updated_at" IS NOT NULL) AND (NULLIF("btrim"("ef"."wave_height"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("ef"."data_source"), ''::"text") IS NOT NULL))
          ORDER BY
                CASE
                    WHEN ((("ef"."forecast_at" AT TIME ZONE COALESCE(NULLIF("b"."timezone", ''::"text"), 'America/Los_Angeles'::"text")))::"date" = (("now"() AT TIME ZONE COALESCE(NULLIF("b"."timezone", ''::"text"), 'America/Los_Angeles'::"text")))::"date") THEN 0
                    WHEN ((("ef"."forecast_at" AT TIME ZONE COALESCE(NULLIF("b"."timezone", ''::"text"), 'America/Los_Angeles'::"text")))::"date" = ((("now"() AT TIME ZONE COALESCE(NULLIF("b"."timezone", ''::"text"), 'America/Los_Angeles'::"text")))::"date" + 1)) THEN 1
                    ELSE 2
                END, "ef"."forecast_at", "ef"."updated_at" DESC
         LIMIT 1) "near_term");


ALTER TABLE "public"."v_enhanced_forecast_latest" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_marine_forecast_latest" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "beach_id",
    "mf"."created_at",
    "mf"."ts",
    "mf"."source",
    "mf"."is_observed"
   FROM ("public"."beaches" "b"
     CROSS JOIN LATERAL (( SELECT "m"."created_at",
            "m"."ts",
            "m"."source",
            "m"."is_observed"
           FROM "public"."marine_forecasts" "m"
          WHERE (("m"."beach_id" = "b"."id") AND ("m"."is_observed" = true) AND ("m"."created_at" > ("now"() - '06:00:00'::interval)))
          ORDER BY "m"."created_at" DESC
         LIMIT 1)
        UNION ALL
        ( SELECT "m"."created_at",
            "m"."ts",
            "m"."source",
            "m"."is_observed"
           FROM "public"."marine_forecasts" "m"
          WHERE ("m"."beach_id" = "b"."id")
          ORDER BY "m"."created_at" DESC
         LIMIT 1)
 LIMIT 1) "mf");


ALTER TABLE "public"."v_marine_forecast_latest" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_sun_times_latest" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "beach_id",
    "st"."created_at",
    "st"."date",
    "st"."source"
   FROM ("public"."beaches" "b"
     CROSS JOIN LATERAL ( SELECT "s"."created_at",
            "s"."date",
            "s"."source"
           FROM "public"."sun_times" "s"
          WHERE ("s"."beach_id" = "b"."id")
          ORDER BY "s"."created_at" DESC
         LIMIT 1) "st");


ALTER TABLE "public"."v_sun_times_latest" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_tide_forecast_latest" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "beach_id",
    "tf"."created_at",
    "tf"."ts",
    "tf"."source"
   FROM ("public"."beaches" "b"
     CROSS JOIN LATERAL ( SELECT "t"."created_at",
            "t"."ts",
            "t"."source"
           FROM "public"."tide_forecasts" "t"
          WHERE ("t"."beach_id" = "b"."id")
          ORDER BY "t"."created_at" DESC
         LIMIT 1) "tf");


ALTER TABLE "public"."v_tide_forecast_latest" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."weekend_scout_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "weekend_start" "date" NOT NULL,
    "weekend_end" "date" NOT NULL,
    "generated_at" timestamp with time zone NOT NULL,
    "location_captured_at" timestamp with time zone NOT NULL,
    "location_timezone" "text" NOT NULL,
    "max_drive_minutes" integer NOT NULL,
    "qualifying_count" integer NOT NULL,
    "lead_beach_id" "uuid" NOT NULL,
    "lead_beach_name" "text" NOT NULL,
    "lead_window_local" "text" NOT NULL,
    "scorer_version" "text" NOT NULL,
    "contract_version" "text" NOT NULL,
    "rankings" "jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "weekend_scout_snapshots_contract_version_check" CHECK (("contract_version" = 'weekend-scout-v1'::"text")),
    CONSTRAINT "weekend_scout_snapshots_lead_beach_name_check" CHECK (("length"("lead_beach_name") > 0)),
    CONSTRAINT "weekend_scout_snapshots_lead_window_local_check" CHECK (("length"("lead_window_local") > 0)),
    CONSTRAINT "weekend_scout_snapshots_location_timezone_check" CHECK ((("length"("location_timezone") >= 1) AND ("length"("location_timezone") <= 64))),
    CONSTRAINT "weekend_scout_snapshots_max_drive_minutes_check" CHECK ((("max_drive_minutes" >= 1) AND ("max_drive_minutes" <= 300))),
    CONSTRAINT "weekend_scout_snapshots_qualifying_count_check" CHECK ((("qualifying_count" >= 1) AND ("qualifying_count" <= 3))),
    CONSTRAINT "weekend_scout_snapshots_rankings_check" CHECK (("jsonb_typeof"("rankings") = 'array'::"text")),
    CONSTRAINT "weekend_scout_snapshots_scorer_version_check" CHECK (("length"("scorer_version") > 0)),
    CONSTRAINT "weekend_scout_snapshots_two_day_window" CHECK (("weekend_end" = ("weekend_start" + 1)))
);


ALTER TABLE "public"."weekend_scout_snapshots" OWNER TO "postgres";


COMMENT ON TABLE "public"."weekend_scout_snapshots" IS 'Immutable top-three Weekend Scout alert evidence. One snapshot per user and Saturday date.';



